	\end{enumerate}

\begin{enumerate}
		\item Calculer les restes de la division euclidienne de \( 1,4,4^2,4^3 \) par \( 3 \).

		\item Formuler, pour tout \( n\in\Nn \), une hypothèse \( \mathcal{P}(n) \) concernant le reste de la division euclidienne de \( 4^n \) par \( 3 \). Démontrer que \( \mathcal{P}(n) \) est vérifiée pour tout \( n\in\Nn \).

		\item Pour tout \( n\in\Nn \), le nombre \( 16^n+4^n +3 \) est-il divisible par \( 3 \)?
	\end{enumerate}

