		\item Simplifier \( [1,3]\cap[2,4] \) et \( [1,3]\cup[2,4] \).

		\item Pour tout \( n\in\Nn \), on note \( n\Zz \) l'ensemble des entiers relatifs multiples de \( n \) : \( n\Zz = \{np \mid\nolinebreak p\in\Zz\} \). Simplifier \( 2\Zz\cap3\Zz \).
	\end{enumerate}

