\begin{enumerate}
		\item Résoudre dans \( \Cc \) l'équation (1) \( (z-2)/(z-1) = i \). On donnera la solution sous forme algébrique.

		\item Soit \( M,A \), et \( B \) les points d'affixes respectives \( z,1,2 \). On suppose que \( M\neq A \) et que \( M\neq B \). Interpréter géométriquement le module et un argument de \( (z-2)/(z-1) \) et retrouver la solution de l'équation (1).
	\end{enumerate}

Soit \( C \) la courbe d'équation \( x^2-xy+y^2 = 0 \) dans le plan \( P \) rapporté à un repère orthonormé.
	\begin{enumerate}
		\item La courbe \( C \) a-t-elle des points d'intersection avec le rectangle ouvert \( R \) dont les sommets sont :
		\begin{eqnarray*}
			A &=& (-3,2)\\
			B &=& (4,2)\\
			C &=& (4,-1)\\
			D &=& (-3,-1).\\
		\end{eqnarray*}

		\item Même question pour le rectangle fermé \( R' \) de sommets :
		\begin{eqnarray*}
			A' &=& (-1,4)\\
			B' &=& (2,4)\\
			C' &=& (2,1)\\
			D' &=& (-1,1).\\
		\end{eqnarray*}
	\end{enumerate}

\begin{enumerate}
		\item Soit \( A \), \( B \), \( C \) trois points du plan complexe dont les affixes sont respectivement \( a \), \( b \), \( c \). On suppose que \( a+jb+j^2c = 0 \) ; montrer que \( ABC \) est un triangle équilatéral (\( j \) et \( j^2 \) sont les racines cubiques complexes de \( 1 \) --- plus précisément \( j = \frac{-1+i\sqrt3}{2} \)). Réciproque ?

		\item \( ABC \) étant un triangle équilatéral direct du plan complexe, on construit les triangles équilatéraux directs \( BOD \) et \( OCE \), ce qui détermine les points \( D \) et \( E \) (\( O \) est l'origine du plan complexe). Quelle est la nature du quadrilatère \( ADOE \) ? Comparer les triangles \( OBC \), \( DBA \) et \( EAC \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Réciproque : \( a+jb+j^2c = 0 \) ou \( a+j^2b+jc = 0 \) (cela dépend de l'orientation du triangle).

\item \( ADOE \) est un parallélogramme. Les trois triangles \( OBC \), \( DBA \) et \( EAC \) sont directement isométriques, ce qui d'ailleurs se vérifie immédiatement à l'aide de rotations.
\end{enumerate}

exercices.enonce:
Soient \( z,z' \in \Cc \) tels que \( \text{Arg}(z)-\text{Arg}(z') = \frac{\pi}{2} \).
	\begin{enumerate}
		\item Montrer que \( z\overline{z'}+\overline{z}z' = 0 \).

		\item Montrer que \( |z+z'|^2 = |z-z'|^2 = |z|^2+|z'|^2 \).
	\end{enumerate}

\begin{enumerate}
		\item Déterminer l'ensemble des points \( M \) du plan complexe, d'affixe \( z \) tels que : \( \overline{z}(z-1) = z^2(\overline{z}-1) \).

		\item Déterminer l'ensemble des points \( M \) du plan complexe, d'affixe \( z \) tels que les images de \( 1 \), \( z \), \( 1+z^2 \) soient alignées.
	\end{enumerate}

Soit \( s = (1-z)(1-iz) \).
	\begin{enumerate}
		\item Déterminer l'ensemble des images des nombres complexes \( z \) tels que \( s \) soit réel.

		\item Déterminer l'ensemble des images des nombres complexes \( z \) tels que \( s \) soit imaginaire pur.

	\end{enumerate}

\begin{enumerate}
		\item Soit \( A \) un point du plan d'affixe \( \alpha = a+ib \). Déterminer l'ensemble des points \( M \) du plan dont l'affixe \( z \) vérifie \( |z|^2 = \alpha \bar{z} + \bar{\alpha} z \).

		\item Quelles conditions doivent vérifier les points \( M_1 \) et \( M_2 \) d'affixes \( z_1 \) et \( z_2 \) pour que \( \frac{z_1}{z_2} \) soit réel ?

		\item Déterminer les nombres complexes \( z \) tels que les points du plan complexe d'affixes \( z \), \( iz \), \( i \) forment un triangle équilatéral.

		\item Soit \( z = a+ib \), mettre l'expression \( \frac{z-1}{z+1} \) sous forme \( A+iB \), . Déterminer l'ensemble des points du plan complexe d'affixe \( z \) telle que l'argument de \( \frac{z-1}{z+1} \) soit \( \frac{\pi}{2} \).
	\end{enumerate}

\begin{enumerate}
		\item Montrer que toute droite du plan admet pour équation complexe : \( az + \overline{az} = b \) avec \( a \in \Cc^*, b \in \Rr \).

		\item Soient \( a,b,c \in \Cc \), \( a,b \) non tous deux nuls. Discuter la nature de \( E = \{\, z \in \Cc \mid az + b\overline{z} = c \,\} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
