Pour \( n \) naturel non nul, on pose \( S_n = \sum_{}^{}e^{i(\pm a_1\pm...\pm a_n)} \).
\textbullet \( S_1 = e^{ia_1}+e^{-ia_1} = 2\cos a_1 \)
\textbullet Soit \( n\ge1 \). Supposons que \( S_n = 2^n\cos a_1...\cos a_n \) alors

\begin{align*}
S_{n+1} & =\sum_{}^{}e^{i(\pm a_1\pm...\pm a_{n+1})}=e^{ia_{n+1}}\sum_{}^{}e^{i(\pm a_1\pm...\pm a_n)}+e^{-ia_{n+1}}\sum_{}^{}e^{i(\pm a_1\pm...\pm a_n)} \\
& =2\cos(a_{n+1})S_n=2^{n+1}\cos a_1...\cos a_{n+1}.
\end{align*}
On a montré par récurrence que : \( \forall n\ge1,\;S_n = 2^n\cos a_1...\cos a_n \). Ensuite, pour \( n\ge1 \), \( \sum_{}^{}\cos(\pm a_1\pm...\pm a_n) = \Re(S_n) = 2^n\cos a_1...\cos a_n \) (et on obtient aussi \( \sum_{}^{}\sin(\pm a_1\pm...\pm a_n) = \Im(S_n) = 0 \)).

\begin{center}
\shadowbox{ \( \forall n\in\Nn^* \), \( \sum_{}^{}\cos(\pm a_1\pm...\pm a_n) = 2^n\cos a_1...\cos a_n \). }
\end{center}

exercices.enonce:
\begin{enumerate}
		\item Calculer \( \prod_{k = 1}^n\cos\left(\frac{a}{2^k}\right) \) pour \( a \) élément donné de \( ]0,\pi[ \) (penser à \( \sin(2x) = 2\sin x\cos x \)).

		\item Déterminer \( \lim_{n\rightarrow +\infty}\sum_{k = 1}^n\ln\left(\cos(\frac{a}{2^k})\right) \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( n\in\Nn^* \). Puisque \( a \) est dans \( ]0,\pi[ \) alors, pour tout entier naturel non nul \( k \), \( \frac{a}{2^k} \) est dans \( ]0,\pi[ \) et donc \( \sin\frac{a}{2^k}\neq0 \). De plus, puisque \( \sin\left(\frac{a}{2^{k-1}}\right) = \sin\left(2\times\frac{a}{2^k}\right) = 2\sin\left(\frac{a}{2^k}\right)\cos\left(\frac{a}{2^k}\right) \), on a :

\[
\prod_{k = 1}^n\cos\left(\frac{a}{2^k}\right) = \prod_{k = 1}^n\frac{\sin\left(\frac{a}{2^{k-1}}\right)}{2\sin\left(\frac{a}{2^k}\right)} = \frac{1}{2^n}
\frac{\sin(a)\sin\left(\frac{a}{2}\right)\ldots\sin\left(\frac{a}{2^{n-1}}\right)}
{\sin\left(\frac{a}{2}\right)\ldots\sin\left(\frac{a}{2^{n-1}}\right)\sin\left(\frac{a}{2^n}\right)} = \frac{\sin a}{2^n\sin\frac{a}{2^n}}.
\]
\begin{center}
	\shadowbox{ \( \forall a\in]0,\pi[ \), \( \forall n\in\Nn^* \), \( \prod_{k = 1}^n\cos\left(\frac{a}{2^k}\right) = \frac{\sin a}{2^n\sin\frac{a}{2^n}} \). }
\end{center}

\item \( \forall k\in\Nn^*,\;\cos\left(\frac{a}{2^k}\right)>0 \) car \( \frac{a}{2^k} \) est dans \( ]0,\frac{\pi}{2}[ \). Puis

\begin{align*}
	\sum_{k=1}^n\ln\left(\cos(\frac{a}{2^k})\right) & =\ln\left(\prod_{k=1}^n\cos(\frac{a}{2^k})\right)=\ln\left(\frac{\sin a}{2^n\sin\frac{a}{2^n}}\right)=\ln\left(\frac{\sin a}{a}\right)-\ln\left(\frac{\sin\frac{a}{2^n}}{\frac{a}{2^n}}\right).
\end{align*}
Maintenant, \( \lim_{n\rightarrow +\infty}\frac{\sin\frac{a}{2^n}}{\frac{a}{2^n}} = \lim_{x\rightarrow 0}\frac{\sin x}{x} = 1 \) et donc,

\[
\lim_{n\rightarrow +\infty}\sum_{k = 1}^n\ln\left(\cos(\frac{a}{2^k})\right) = \lim_{n\rightarrow +\infty}\left(\ln(\frac{\sin a}{a})-\ln(\frac{\sin\frac{a}{2^n}}{\frac{a}{2^n}})\right) = \ln\left(\frac{\sin a}{a}\right).
\]
\begin{center}
	\shadowbox{ \( \forall a\in]0,\pi[ \), \( \lim_{n\rightarrow +\infty}\sum_{k = 1}^n\ln\left(\cos(\frac{a}{2^k})\right) = \ln\left(\frac{\sin a}{a}\right) \). }
\end{center}
\end{enumerate}

\begin{enumerate}
\item Tout d'abord, d'après la formule de \textsc{Moivre},

\[
\cos(3\theta)+i\sin(3\theta) = (\cos\theta+i\sin\theta)^3 = (\cos^3\theta-3\cos\theta\sin^2\theta) +i(3\cos^2\theta\sin\theta-\sin^3\theta),
\]
et par identification des parties réelles et imaginaires,

\begin{center}
	\shadowbox{ \( \forall\theta\in\Rr,\;\cos(3\theta) = \cos^3\theta-3\cos\theta\sin^2\theta\;\mbox{et}\;\sin(3\theta) = 3\cos^2\theta\sin\theta-\sin^3\theta \). }
\end{center}
Ensuite, \( \tan(3\theta) \) et \( \tan\theta \) existent \( \Leftrightarrow3\theta\notin\frac{\pi}{2}+\pi\Zz \) et \( \theta\notin\frac{\pi}{2}+\pi\Zz\Leftrightarrow3\theta\notin\frac{\pi}{2}+\pi\Zz\Leftrightarrow\theta\notin\frac{\pi}{6}+
\frac{\pi}{3}\Zz \). Soit donc \( \theta\notin\frac{\pi}{6}+\frac{\pi}{3}\Zz \).

\[
\tan(3\theta) = \frac{\sin(3\theta)}{\cos(3\theta)}
= \frac{3\cos^2\theta\sin\theta-\sin^3\theta}{\cos^3\theta-3\cos\theta\sin^2\theta}
= \frac{3\tan\theta-\tan^3\theta}{1-3\tan^2\theta},
\]
après division du numérateur et du dénominateur par le réel non nul \( \cos^3\theta \).

\begin{center}
	\shadowbox{ \( \forall\theta\in\Rr\setminus\left(\frac{\pi}{6}+\frac{\pi}{3}\Zz\right),\;\tan(3\theta) = \frac{3\tan\theta-\tan^3\theta}{1-3\tan^2\theta} \). }\end{center}

\item Soit \( a\neq\pm\frac{1}{\sqrt{3}} \).
\textbf{1ère méthode.} \( a \) est bien sûr racine de l'équation proposée, ce qui permet d'écrire :

\begin{align*}
	\frac{3x-x^3}{1-3x^2}=\frac{3a-a^3}{1-3a^2} & \Leftrightarrow(3x-x^3)(1-3a^2)=(1-3x^2)(3a-a^3)\;(\mbox{car}\;\pm\frac{1}{\sqrt{3}}
	\;\mbox{ne sont pas solution de l'équation})                                                                                       \\
	& \Leftrightarrow(x-a)((3a^2-1)x^2+8ax-a^2+3)=0.
\end{align*}
Le discriminant réduit du trinôme \( (3a^2-1)x^2+8ax-a^2+3 \) vaut :

\[
\Delta' = 16a^2-(3a^2-1)(-a^2+3) = 3a^4+6a^2+3 = (\sqrt{3}(a^2+1))^2>0.
\]
L'équation proposée a donc trois racines réelles :

\begin{center}
	\shadowbox{ \( \mathcal{S} = \left\{a,\frac{4a-\sqrt{3}(a^2+1)}{1-3a^2},\frac{4a+\sqrt{3}(a^2+1)}{1-3a^2}\right\} \). }
\end{center}
\textbf{2ème méthode.} Il existe un unique réel \( \alpha\in\left]-\frac{\pi}{2},\frac{\pi}{2}\right[\setminus\left\{-\frac{\pi}{6},\frac{\pi}{6}\right\} \) tel que \( a = \tan\alpha \). De même, si \( x \) est un réel distinct de \( \pm\frac{1}{\sqrt{3}} \), il existe un unique réel \( \theta\in\left]-\frac{\pi}{2},\frac{\pi}{2}\right[\setminus\left\{-\frac{\pi}{6},\frac{\pi}{6}\right\} \) tel que \( x = \tan\theta \) (à savoir \( \alpha = \arctan a \) et \( \theta = \arctan x \)). Comme \( \pm\frac{1}{\sqrt{3}} \) ne sont pas solution de l'équation proposée, on a :

\begin{align*}
	\frac{3x-x^3}{1-3x^2}=\frac{3a-a^3}{1-3a^2} & \Leftrightarrow\frac{3\tan\theta-\tan^3\theta}{1-3\tan^2\theta}
	=\frac{3\tan\alpha-\tan^3\alpha}{1-3\tan^2\alpha}\Leftrightarrow\tan(3\theta)=\tan(3\alpha)                                           \\
	& \Leftrightarrow3\theta\in3\alpha+\pi\Zz\Leftrightarrow\theta\in\alpha+\frac{\pi}{3}\Zz.
\end{align*}
Ceci refournit les solutions \( x = \tan\alpha = a \), puis

\[
x = \tan\left(\alpha+\frac{\pi}{3}\right) = \frac{\tan\alpha+\tan\frac{\pi}{3}}{1-\tan\alpha\tan\frac{\pi}{3}} = \frac{a+\sqrt{3}}{1 -\sqrt{3}a} = \frac{(a+\sqrt{3})(1+\sqrt{3}a)}{1-3a^2} = \frac{4a+\sqrt{3}(a^2+1)}{1-3a^2},
\]
et \( x = \tan\left(\alpha-\frac{\pi}{3}\right) = \frac{4a-\sqrt{3}(a^2+1)}{1-3a^2} \).

\end{enumerate}

exercices.enonce:
On veut calculer \( S = \tan9^\circ-\tan27^\circ-\tan63^\circ+\tan81^\circ \).\\
	\begin{enumerate}
		\item Calculer \( \tan(5x) \) en fonction de \( \tan x \).

		\item En déduire un polynôme de degré \( 4 \) dont les racines sont \( \tan9^\circ \), \( -\tan27^\circ \), \( -\tan63^\circ \) et \( \tan81^\circ \) puis la valeur de \( S \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Pour \( x\notin\frac{\pi}{10}+\frac{\pi}{5}\Zz \),

\[
\tan(5x) = \frac{\Im((e^{ix})^5)}{\Re((e^{ix})^5)} = \frac{5\cos^4x\sin x-10\cos^2x\sin^3x+\sin^5x}{\cos^5x-10\cos^3x\sin^2x+5\cos x\sin^4x} = \frac{5\tan x-10\tan^3x+\tan^5x}{1-10\tan^2x+5\tan^4x},
\]
après division du numérateur et du dénominateur par le réel non nul \( \cos^5x \).

\begin{center}
	\shadowbox{ \( \forall x\in\Rr\setminus\left(\frac{\pi}{10}+\frac{\pi}{5}\Zz\right),\;\tan(5x) = \frac{5\tan x-10\tan^3x+\tan^5x}{1-10\tan^2x+5\tan^4x} \). }
\end{center}

\item \( 9^\circ \), \( -27^\circ \), \( -63^\circ \) et \( 81^\circ \) vérifient \( \tan(5\times9^\circ) = \tan(5\times(-27^\circ)) = \tan(5\times(-63^\circ)) = \tan(5\times81^\circ) = 1 \). On résoud donc l'équation :

\[
\tan(5x) = 1\Leftrightarrow5x\in\left(\frac{\pi}{4}+\pi\Zz\right)\Leftrightarrow x\in\left(\frac{\pi}{20}+\frac{\pi}{5}\Zz\right).
\]
Les solutions, exprimées en degrés et éléments de \( ]-90^\circ,90^\circ[ \), sont \( -63^\circ \), \( -27^\circ \), \( 9^\circ \), \( 45^\circ \) et \( 81^\circ \). Ainsi, les cinq nombres \( \tan(-63^\circ) \), \( \tan(-27^\circ) \), \( \tan(9^\circ) \), \( \tan(45^\circ) \) et \( \tan(81^\circ) \) sont deux à deux distincts et solutions de l'équation \( \frac{5X-10X^3+X^5}{1-10X^2+5X^4} = 1 \) qui s'écrit encore :

\[
X^5-5X^4-10X^3+10X^2+5X-1 = 0.
\]
Le polynôme \( X^5-5x^4-10X^3+10X^2+5X-1 \) admet déjà \( \tan(45^\circ) = 1 \) pour racine et on a

\[
X^5-5X^4-10X^3+10X^2+5X-1 = (X-1)(X^4-4X^3-14X^2-4X+1).
\]
Les quatre nombres \( \tan(-63^\circ) \), \( \tan(-27^\circ) \), \( \tan(9^\circ) \) et \( \tan(81^\circ) \) sont ainsi les racines du polynôme \( X^4-4X^3-14X^2-4X+1 \). Ce dernier peut donc encore s'écrire \( (X-\tan(9^\circ))(X+\tan(27^\circ))(X+\tan(63^\circ))(X-\tan(81^\circ)) \). L'opposé du coefficient de \( X^3 \) à savoir \( 4 \) vaut donc également \( \tan(9^\circ)-\tan(27^\circ)-\tan(63^\circ)+\tan(81^\circ) \) et on a montré que :

\begin{center}
	\shadowbox{ \( \tan(9^\circ)-\tan(27^\circ)-\tan(63^\circ)+\tan(81^\circ) = 4 \). }
\end{center}
\end{enumerate}

