\begin{enumerate}
		\item Soient \( x,y\in \Nn \), \( y \ge 3 \). Montrer par récurrence sur \( y \) que : \( 3^x \equiv 1 (\mathrm{mod}\, {2^y}) \iff 2^{y-2}\mid x \).

		\item Trouver tous les couples d'entiers \( x,y \in \Nn \) tels que \( 3^x = 2^y + 1 \).
	\end{enumerate}

