		\item Montrer que \( \Zz[i] \) est un anneau commutatif pour les lois usuelles de \( \Cc \).

		\item Déterminer les inversibles de \( \Zz[i] \).
	\end{enumerate}

Sur l'ensemble \( \Rr^2 \), on définit la loi \( \star \) par
	\[
	{(x_1,x_2)\star (y_1,y_2) = (x_1y_1,x_1y_2+x_2y_1).}
	\]
	\begin{enumerate}
		\item
		\begin{enumerate}
			\item Montrer que \( (\Rr^2,+,\star) \) est un anneau commutatif noté \( A \).

			\item Chercher les diviseurs de \( 0 \) de l'anneau \( A \).
		\end{enumerate}

		\item On considère l'application
		\[
		{f:\Rr[X]\to A, P\mapsto (P(0),P'(0)).}
		\]
		\begin{enumerate}
			\item Montrer que \( f \) est un homomorphisme d'anneaux.

			\item \( f \) est-il surjectif ?

			\item Déterminer le noyau de \( f \).
		\end{enumerate}
	\end{enumerate}

On définit \( A = \left\{a+jb:a,b\in \Zz\right\} \) où \( j = \exp(\frac{2i\pi}3) \).
	\begin{enumerate}
		\item Montrer que \( A \) est un sous-anneau de \( \Cc \). On désigne par \( \mathcal{U}(A) \) le groupe des éléments inversibles de \( A \) et enfin, on pose, pour tout \( z\in\Cc \), \( N(z) = {|z|}^2 \).

		\item
		\begin{enumerate}
			\item Montrer que si \( z\in A \) alors \( N(z)\in\Zz \).

			\item Soit \( z\in A \). Montrer que \( z\in \mathcal{U}(A) \) si et seulement si \( N(z) = 1 \).

			\item Soient \( a \) et \( b \) des entiers. Montrer que si \( N(a+jb) = 1 \) alors \( a,b\in\left\{-1,0,1\right\} \).
		\end{enumerate}

		\item Décrire le groupe \( \mathcal{U}(A) \) et en déterminer les éléments d'ordre 3.

		\item Soit \( \Phi: \Qq[X]\to\Cc, P\mapsto P(j) \).
		\begin{enumerate}
			\item Montrer que \( \Phi \) est un homomorphisme d'anneaux.

			\item Déterminer le noyau de \( \Phi \) (on pourra remarquer que \( j^2+j+1 = 0 \)).

			\item Montrer que \( \text{Im\,}\Phi = \left\{a+jb:a,b\in \Qq\right\} \) et que c'est un sous-corps de \( \Cc \).
		\end{enumerate}
	\end{enumerate}

\begin{enumerate}
		\item Montrer que \( \overline{k} \) est inversible dans l'anneau \( \Zz{/}n\Zz \) si et seulement si les entiers \( k \) et \( n \) sont premiers entre eux.

		\item On pose \( n = 10 \) et soit \( G \) le groupe des éléments inversibles de \( %
