\begin{enumerate}
	\item Remarquons d'abord que, par construction, \( t\in]-\frac{\pi}{2},\frac{\pi}{2}[ \), \( t \) est donc dans le domaine de définition de la fonction \( \tan \). En prenant la tangente de l'égalité \( t = \arctan(\sh x) \) on obtient directement \( \tan t = \tan\big(\arctan(\sh x)\big) = \sh x \).

	\item Ensuite, \( \frac{1}{\cos^2t} = 1+\tan^2 t = 1 + \tan^2\big(\arctan(\sh x)\big) = 1+\sh^2x = \ch^2x \). Or la fonction \( \ch \) ne prend que des valeurs positives, et \( t\in]-\frac{\pi}{2},\frac{\pi}{2}[ \) donc \( \cos t>0 \). Ainsi \( \frac{1}{\cos t} = \ch x \).

	\item Enfin, \( \sin t = \tan t \cdot \cos t = \sh x \cdot \frac{1}{\ch x} = \tanh x \).
\end{enumerate}

\item Puisque \( t\in]-\frac{\pi}{2},\frac{\pi}{2}[ \), on a \( 0<\frac{t}{2}+\frac{\pi}{4}<\frac{\pi}{2} \), donc \( \tan\left(\frac{t}{2}+\frac{\pi}{4}\right) \) est bien défini et strictement positif. Ainsi \( y = \ln \left(\tan\left(\frac{t}{2}+\frac{\pi}{4}\right)\right) \) est bien défini.

Ensuite :
\begin{eqnarray*}
	\sh y &=& \frac{e^y-e^{-y}}{2}\\
	&=& \tfrac{1}{2}\tan\left(\tfrac{t}{2}+\tfrac{\pi}{4}\right)-
	\tfrac{1}{2}\frac{1}{\tan\left(\frac{t}{2}+\frac{\pi}{4}\right)}\\
	&=&\frac{\sin^2\left(\frac{t}{2}+\frac{\pi}{4}\right)-
		\cos^2\left(\frac{t}{2}+\frac{\pi}{4}\right)}{2\cos\left(\frac{t}{2}+\frac{\pi}{4}\right)\sin\left(\frac{t}{2}+\frac{\pi}{4}\right)}\\
	&=&\frac{-\cos\left(t+\frac{\pi}{2}\right)}{\sin\left(t+\frac{\pi}{2}\right)}
\end{eqnarray*}
car \( \sin(2u) = 2\cos u\sin u \) et \( \cos(2u) = \cos^2u-\sin^2u \).

Enfin, puisque \( \cos\left(t+\frac{\pi}{2}\right) = -\sin t \) et \( \sin\left(t+\frac{\pi}{2}\right) = \cos t \), on a \( \sh y = \frac{\sin t}{\cos t} = \tan t = \sh x \). Puisque la fonction \( \sh \) est bijective de \( \Rr \) dans \( \Rr \), on en déduit \( y = x \). Conclusion : \( x = y = \ln \big(\tan\big(\frac{t}{2}+\frac{\pi}{4}\big)\big) \).
\end{enumerate}

\begin{enumerate}
\item Soit \( f(x) = \ln(1+x)-x+x^2/2 \) alors \( f'(x) = \frac{1}{1+x}
-1+x = \frac{x^2}{1+x} >0 \). Donc \( f \) est strictement croissante sur \( [0,+\infty[ \) et comme \( f(0) = 0 \) alors \( f(x) > f(0) = 0 \) pour \( x>0 \). Ce qui donne l'inégalité recherchée.

\item De même avec \( g(x) = e^x-x-1 \), \( g'(x) = e^x-1 \). Sur \( [0,+\infty[ \) \( g'(x) \ge 0 \) et \( g \) est croissante sur \( ]-\infty,0] \), \( g'(x)\le 0 \) et \( g \) est décroissante. Comme \( g(0) = 0 \) alors pour tout \( x\in\Rr \) \( g(x)\ge 0 \).
\end{enumerate}

\
\begin{center}
\shadowbox{ \( \begin{array}{ccc}
		\ch(a+b) = \ch a\ch b+\sh a\sh b                      & \mbox{et} & \ch(a-b) = \ch a\ch b-\sh a\sh b,                      \\
		\sh(a+b) = \sh a\ch b+\ch a\sh b                      & \mbox{et} & \sh(a-b) = \sh a\ch b-\sh b\ch a                       \\
		\tanh(a+b) = \frac{\tanh a+\tanh b}{1+\tanh a\tanh b} & \mbox{et} & \tanh(a-b) = \frac{\tanh a-\tanh b}{1-\tanh a\tanh b}.
	\end{array} \) }
	\end{center}
	Deux démonstrations :

	\[
	\ch a\ch b+\sh a\sh b = \frac{1}{4}((e^a+e^{-a})(e^b+e^{-b})+(e^a-e^{-a})(e^b-e^{-b})) =
	\frac{1}{2}(e^{a+b}+e^{-a-b}) = \ch(a+b).
	\]
	\[
	\tanh(a+b) = \frac{\sh(a+b)}{\ch(a+b)} = \frac{\sh a\ch b+\sh b\ch a}{\ch a\ch b+\sh a\sh b} = \frac{\tanh a+\tanh b}{1+\tanh a\tanh b}
	\]
	après division du numérateur et du dénominateur par le nombre non nul \( \ch a\ch b \). En appliquant à \( a = b = x \), on obtient : 

	\begin{center}
\shadowbox{ \( \forall x\in\Rr,\;\ch(2x) = \ch^2x+sh^2x = 2ch^2x-1 = 2sh^2x+1,\;\sh(2x) = 2\sh x\ch x\;\mbox{et}\;
	\tanh(2x) = \frac{2\tanh x}{1+\tanh^2x} \). }
	\end{center}
	En additionnant entre elles les formules d'addition, on obtient les formules de linéarisation :

	\[
	\ch a\ch b = \frac{1}{2}(\ch(a+b)+\ch(a-b)),\;\sh a\sh b = \frac{1}{2}(\ch(a+b)-\ch(a-b))\;\mbox{et}\;\sh a\ch b = \frac{1}{2}(\sh(a+b)+\sh(a-b)),
	\]
	et en particulier

	\[
	\ch^2x = \frac{\ch(2x)+1}{2}\;\mbox{et}\;\sh^2x = \frac{\ch(2x)-1}{2}.
	\]

exercices.enonce:
\begin{enumerate}
		\item Montrer que pour tout réel \( x \) non nul, on a : \( \tanh x = \frac{2}{\tanh(2x)}-\frac{1}{\tanh x} \).

		\item En déduire la valeur de \( u_n = 2^0\tanh(2^0x)+2^1\tanh(2^1x)+ \cdots +2^n\tanh(2^nx) \) pour \( n \) entier naturel non nul et \( x \) réel non nul donnés puis calculer la limite de \( (u_n) \).
	\end{enumerate}

exercices.correction:
On a vu au \ref{exo:suprou3} que pour tout réel \( x \), \( \tanh(2x) = \frac{2\tanh x}{1+\tanh^2x} \) ce qui s'écrit pour \( x \) non nul : \( \frac{1+\tanh^2x}{\tanh x} = \frac{2}{\tanh(2x)} \) ou encore \( \tanh x+\frac{1}{\tanh x} = \frac{2}{\tanh(2x)} \) ou finalement

\begin{center}
\shadowbox{ \( \forall x\in\Rr^*,\;\tanh x = \frac{2}{\tanh(2x)}-\frac{1}{\tanh x} \). }
\end{center}
Soient \( n \) un entier naturel non nul et \( x \) un réel non nul. D'après ce qui précède,

\[
u_n = \sum_{k = 0}^n2^k\tanh(2^kx) = \sum_{k = 0}^n\left(\frac{2^{k+1}}{\tanh(2^{k+1}x)}-\frac{2^k}{\tanh(2^kx)}\right) = \sum_{k = 1}^{n+1}\frac{2^k}{\tanh(2^kx)}-\sum_{k = 0}^n\frac{2^k}{\tanh(2^kx)} = \frac{2^{n+1}}{\tanh(2^{n+1}x)}
-\frac{1}{\tanh x}.
\]
Ensuite, pour \( x>0 \), \( \tanh(2^{n+1}x) \) tend vers \( 1 \) quand \( n \) tend vers l'infini. Donc \( u_n \) tend vers \( +\infty \) quand \( n \) tend vers \( +\infty \) si \( x>0 \) et vers \( -\infty \) quand \( n \) tend vers \( +\infty \) si \( x<0 \).

Par définition des fonctions \( \ch \) et \( \sh \), on a
\begin{eqnarray*}
2\ch^2(x)-\sh(2x)&=&2\left(\frac{e^x+e^{-x}}{2}\right)^2-\frac{e^{2x}-e^{-2x}}{2}\\
&=&\frac{e^{2x}+2+e^{-2x}}{2}+\frac{e^{-2x}-e^{2x}}{2}\\
&=&1+e^{-2x}
\end{eqnarray*}

Et en utilisant les deux relations \( \ln(ab) = \ln a + \ln b \) et \( \ln(e^x) = x \) on calcule :
\begin{eqnarray*}
x-\ln(\ch x)-\ln 2 &=& x-\ln\left(\frac{e^x+e^{-x}}{2}\right)-\ln 2\\
&=& x-\ln(e^x+e^{-x}) + \ln 2 - \ln 2\\
&=& x-\ln\big(e^x(1+e^{-2x})\big)\\
&=& x-\ln(e^x)-\ln(1+e^{-2x})\\
&=& x-x-\ln(1+e^{-2x})\\
&=& -\ln(1+e^{-2x})\\
\end{eqnarray*}
d'où
\[
\frac{2\ch^2(x)-\sh(2x)}{x-\ln(\ch x)-\ln 2} = -\frac{1+e^{-2x}}{\ln(1+e^{-2x})}
\]
C'est une expression de la forme \( -\frac{u}{\ln u} \) avec \( u = 1+e^{-2x} \) :
\begin{itemize}
\item si \( x\to +\infty \), alors \( u\to 1^+ \), \( \frac{1}{\ln u} \to +\infty \) donc \( -\frac{u}{\ln u}\to -\infty \) ;

\item si \( x\to -\infty \), alors \( u\to +\infty \) donc d'après les relations de croissances comparées, \( -\frac{u}{\ln u}\to -\infty \).
\end{itemize}

