exercices.correction:
\begin{enumerate}
\item Soit \( x\in\Rr \). Alors, \( E(x)\le x<E(x)+1 \) puis \( E(x)+1\le x+1<(E(x)+1)+1 \). Comme \( E(x)+1\in\Zz \), on a bien \( E(x+1) = E(x)+1 \).

\item Soient \( (x,y)\in\Rr^2 \). On a \( E(x)+E(y)\le x+y \). Ainsi, \( E(x)+E(y) \) est un entier relatif inférieur ou égal à \( x+y \). Comme \( E(x+y) \) est le plus grand entier relatif inférieur ou égal à \( x+y \), on a donc \( E(x)+E(y)\le E(x+y) \).

Améliorons. \( E(x)\le x<E(x)+1 \) et \( E(y)\le y<E(y)+1 \) fournit \( E(x)+E(y)\le x+y<E(x)+E(y)+2 \) et donc \( E(x+y) \) vaut, suivant le cas, \( E(x)+E(y) \) ou \( E(x)+E(y)+1 \) (et est dans tous les cas supérieur ou égal à \( E(x)+E(y) \)).

\item Soit \( (x,y)\in\Rr^2 \). Posons \( k = E(x) \) et \( l = E(y) \).
\begin{itemize}
	\item[\textbf{1er cas.}] Si \( x\in[k,k+\frac{1}{2}[ \) et \( y\in[l,l+\frac{1}{2}[ \), alors \( x+y\in[k+l,k+l+1[ \) et donc \( E(x+y) = k+l \), puis \( E(x)+E(y)+E(x+y) = k+l+k+l = 2k+2l \). D'autre part, \( 2x\in[2k,2k+1[ \) et \( 2y\in[2l,2l+1[ \). Par suite, \( E(2x)+E(2y) = 2k+2l \). Dans ce cas, \( E(x)+E(y)+E(x+y) = E(2x)+E(2y) \).

	\item[\textbf{2ème cas.}] Si \( x\in[k+\frac{1}{2},k+1[ \) et \( y\in[l,l+\frac{1}{2}[ \), alors \( x+y\in[k+l+\frac{1}{2},k+l+\frac{3}{2}[ \) et donc \( E(x+y) = k+l \) ou \( k+l+1 \),puis \( E(x)+E(y)+E(x+y) = 2k+2l \) ou \( 2k+2l+1 \). D'autre part, \( 2x\in[2k+1,2k+2[ \) et \( 2y\in[2l,2l+1[ \). Par suite, \( E(2x)+E(2y) = 2k+2l+1 \). Dans ce cas, \( E(x)+E(y)+E(x+y)\le E(2x)+E(2y) \).

	\item[\textbf{3ème cas.}] Si \( x\in[k,k+\frac{1}{2}[ \) et \( y\in[l+\frac{1}{2},l+1[ \), on a de même \( E(x)+E(y)+E(x+y)\le E(2x)+E(2y) \).

	\item[\textbf{4ème cas.}] Si \( x\in[k+\frac{1}{2},k+1[ \) et \( y\in[l+\frac{1}{2},l+1[ \), on a \( E(x)+E(y)+E(x+y) = 2k+2l+2 = E(2x)+E(2y) \).
\end{itemize}
Finalement, on a dans tous les cas \( E(x)+E(y)+E(x+y)\le E(2x)+E(2y) \).
\end{enumerate}

\( p \) est déterminé par l'encadrement : \( 10^p\le n<10^{p+1} \) qui s'écrit encore \( p\le\frac{\ln n}{\ln 10}<p+1 \). Par suite,
\begin{center}
\shadowbox{ \( p = E(\mbox{log}_{10}(n)) \). }
\end{center}

\begin{center}
\shadowbox{ Le nombre de chiffres d'un entier \( n \) en base \( 10 \) est donc \( E(\mbox{log}_{10}(n))+1 \). }
\end{center}

Soient \( n\in\Nn^* \) et \( x\in\Rr \).

\begin{align*}
E(x)\le x<E(x)+1 & \Rightarrow nE(x)\le nx<nE(x)+n\Rightarrow nE(x)\le E(nx)<nE(x)+n
\Rightarrow E(x)\le\frac{E(nx)}{n}<E(x)+1                                            \\
& \Rightarrow E(\frac{E(nx)}{n})=E(x).
\end{align*}

Pour \( n = 1 \), \( \sum_{k = 0}^{2n-1}\frac{(-1)^k}{k+1} = 1-\frac{1}{2} = \frac{1}{2} \) et \( \sum_{k = n+1}^{2n}\frac{1}{k} = \frac{1}{2} \). L'identité proposée est donc vraie pour \( n = 1 \).

Soit \( n\ge1 \). Supposons que \( \sum_{k = 0}^{2n-1}\frac{(-1)^k}{k+1} = \sum_{k = n+1}^{2n}\frac{1}{k} \).

On a alors

\begin{align*}
\sum_{k=0}^{2(n+1)-1}\frac{(-1)^k}{k+1} & =\sum_{k=0}^{2n-1}\frac{(-1)^k}{k+1}+\frac{1}{2n+1}-\frac{1}{2n+2}
=\sum_{k=n+1}^{2n}\frac{1}{k}+\frac{1}{2n+1}-\frac{1}{2(n+1)}                                                \\
& =\frac{1}{n+1}+\sum_{k=n+2}^{2n+1}\frac{1}{k}+\frac{1}{2(n+1)}
=\sum_{k=n+2}^{2n+1}\frac{1}{k}+\frac{1}{2n+2}=\sum_{k=n+2}^{2(n+1)}\frac{1}{k}
\end{align*}
On a montré par récurrence que \( \forall n\ge1,\;\sum_{k = 0}^{2n-1}\frac{(-1)^k}{k+1} = \sum_{k = n+1}^{2n}\frac{1}{k} \) (identité de \textsc{Catalan}).

exercices.enonce:
Soient \( a_1 \),..., \( a_n \), \( b_1 \),..., \( b_n \) des nombres réels.
	\begin{enumerate}
		\item En considérant la fonction \( f : x\mapsto\sum_{k = 1}^n(a_k+xb_k)^2 \), montrer que \( |\sum_{k = 1}^na_kb_k|\le\sqrt{\sum_{k = 1}^na_k^2}\sqrt{\sum_{k = 1}^nb_k^2} \) (inégalité de \textsc{Cauchy}-\textsc{Schwarz}).

		\item En déduire l'inégalité de \textsc{Minkowski} : \( \sqrt{\sum_{k = 1}^n(a_k+b_k)^2}\le\sqrt{\sum_{k = 1}^na_k^2}+\sqrt{\sum_{k = 1}^nb_k^2} \).

		(l'inégalité de \textsc{Cauchy}-\textsc{Schwarz} affirme que le produit scalaire de deux vecteurs est inférieur ou égal au produit de leurs normes et l'inégalité de \textsc{Minkowski} est l'inégalité triangulaire).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Si les \( b_k \) sont tous nuls, l'inégalité est claire. Sinon, pour \( x \) réel, posons

\begin{center}
	\( f(x) = \sum_{k = 1}^n(a_k+xb_k)^2 = \left(\sum_{k = 1}^nb_k^2\right)x^2+2\left(\sum_{k = 1}^na_kb_k\right)x+\sum_{k = 1}^na_k^2 \).
\end{center}
\( f \) est un trinôme du second degré de signe constant sur \( \Rr \). Son discriminant réduit est donc négatif ou nul ce qui fournit :

\[
0\ge\Delta' = \left(\sum_{k = 1}^na_kb_k\right)^2-\left(\sum_{k = 1}^na_k^2\right)\left(\sum_{k = 1}^nb_k^2\right),
\]
ou encore \( \left|\sum_{k = 1}^na_kb_k\right|\le\sqrt{\sum_{k = 1}^na_k^2}\sqrt{\sum_{k = 1}^nb_k^2} \), qui est l'inégalité de \textsc{Cauchy}-\textsc{Schwarz}.

\item

\begin{align*}
	\sum_{k=1}^n(a_k+b_k)^2 & =\sum_{k=1}^na_k^2+2\sum_{k=1}^na_kb_k+\sum_{k=1}^nb_k^2
	\le\sum_{k=1}^na_k^2+2\left|\sum_{k=1}^na_kb_k\right|+\sum_{k=1}^nb_k^2                                            \\
	& \le\sum_{k=1}^na_k^2+2\sqrt{\sum_{k=1}^na_k^2}\sqrt{\sum_{k=1}^nb_k^2}+\sum_{k=1}^nb_k^2
	\quad(\mbox{\textsc{Cauchy}-\textsc{Schwarz}})                                                                     \\
	& =\left(\sqrt{\sum_{k=1}^na_k^2}+\sqrt{\sum_{k=1}^nb_k^2}\right)^2
\end{align*}
et donc, \( \sqrt{\sum_{k = 1}^n(a_k+b_k)^2}\le\sqrt{\sum_{k = 1}^na_k^2}+\sqrt{\sum_{k = 1}^nb_k^2} \), qui est l'inégalité de \textsc{Minkowski}.

\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Montrer que les sous groupes du groupe \( (\Rr,+) \) sont soit de la forme \( a\Zz \), \( a \) réel donné, soit denses dans \( \Rr \).

		Indication : pour \( G \) sous-groupe donné de \( (\Rr,+) \), non réduit à \( \{0\} \), considérer \( a = \inf (G\cap]0;+\infty[) \) puis envisager les deux cas \( a = 0 \) et \( a>0 \).

		(Definition : \( G \) est dense dans \( \Rr \) si et seulement si : \( (\forall x\in\Rr,\;\forall\varepsilon>0,\;\exists y\in G/\;|y-x|<\varepsilon) \).

		\item Application 1. Montrer que \( \{a+b\sqrt{2},\;(a,b)\in\Zz^2\} \) est dense dans \( \Rr \).

		\item Application 2 (groupe des périodes d'une fonction).
		\begin{enumerate}
			\item Soit \( f \) une fonction définie sur \( \Rr \) à valeurs dans \( \Rr \). Montrer que l'ensemble des périodes de \( f \) est un sous groupe de \( (\Rr,+) \) (ce sous-groupe est réduit à \( \{0\} \) si \( f \) n'est pas périodique).

			\item Montrer qu'une fonction continue sur \( \Rr \) qui admet \( 1 \) et \( \sqrt{2} \) pour périodes, est constante sur \( \Rr \).
		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( G \) un sous groupe non nul de \( (\Rr,+) \) (\( \{0\} = 0.\Zz \) est du type voulu). Il existe dans \( G \) un réel non nul \( x_0 \). Puisque \( G \) est un sous groupe de \( (\Rr,+) \), le réel \( -x_0 \) est aussi dans \( G \) et l'un des deux réels \( x_0 \) ou \( -x_0 \) est strictement positif. Soit alors \( A = G\cap]0,+\infty[ \). D'après ce qui précède, \( A \) est une partie non vide et minorée (par \( 0 \)) de \( \Rr \). \( A \) admet donc une borne inférieure que l'on note \( a \).

\textbf{1er cas.} Si \( a = 0 \), montrons dans ce cas que \( G \) est dense dans \( \Rr \) (c'est par exemple le cas de \( (\Qq,+) \)). Soient \( x \) un réel et \( \varepsilon \) un réel strictement positif. Puisque \( \mbox{inf }A = \mbox{inf}(G\cap]0,+\infty[) = 0 \), il existe dans \( G \) un élément \( g \) tel que \( 0<g<\varepsilon \). Puis il existe un entier relatif \( n \) tel que \( ng\le x-\varepsilon<(n+1)g \) à savoir \( n = E\left(\frac{x-\varepsilon}{g}\right) \). Soit \( y = (n+1)g \). D'une part, \( y \) est dans \( G \) (si \( n+1 = 0 \), \( (n+1)g = 0\in G \), si \( n+1>0 \), \( (n+1)g = g+g+...+g\in G \) et si \( n+1<0 \), \( (n+1)g = -(-(n+1)g)\in G \)) et d'autre part

\[
x-\varepsilon<(n+1)g = ng+g<x-\varepsilon+\varepsilon = x.
\]
On a montré que \( \forall x\in\Rr,\;\forall\varepsilon>0,\;\exists y\in G/\;x-\varepsilon<y<x \) et donc
\begin{center}
	\shadowbox{ si \( G\neq\{0\} \) et si \( \text{inf}\left(G\cap]0,+\infty[\right) = 0 \), \( G \) est dense dans \( \Rr \). }
\end{center}
\textbf{2ème cas.} Si \( a>0 \), montrons dans ce cas que \( G = a\Zz \). Pour cela, montrons tout d'abord que \( a \) est dans \( G \). Mais si \( a \) n'est pas élément de \( G \), par définition de \( a \), il existe un réel \( x \) dans \( G\cap]a,2a[ \) puis il existe un réel \( y \) dans \( G\cap]a,x[ \). Le réel \( x-y \) est alors dans \( G\cap]0,a[ \) ce qui est impossible. Donc \( a \) est élément de \( G \). Montrons alors que \( G = a\Zz \). Puisque \( a \) est dans \( G \), \( G \) contient encore \( a+a = 2a \), puis \( a+a+a = 3a \) et plus généralement tous les \( na \), \( n\in\Nn^* \). Puisque \( G \) contient aussi les opposés de ces nombres et également \( 0 = 0\times a \), \( G \) contient finalement tous les \( na \), \( n\in\Zz \). On a ainsi montré que \( a\Zz\subset G \). Réciproquement, soit \( x \) un élément de \( G \) et \( n = E\left(\frac{x}{a}\right)(\in\Zz) \). Alors, \( n\le\frac{x}{a}<n+1 \) puis \( 0\le x-na<a \). Or, \( x \) est dans \( G \) et \( na \) est dans \( G \). Donc, \( x-na \) est dans \( G\cap[0,a[ = \{0\} \), puis \( x = na\in a\Zz \). On a ainsi montré l'inclusion contraire et donc \( G = a\Zz \).

\begin{center}
	\shadowbox{ si \( \text{inf}\left(G\cap]0,+\infty[\right) = a>0 \), \( G = a\Zz \). }
\end{center}

\item Soit \( G = \{a+b\sqrt{2},\;(a,b)\in\Zz^2\} \). On vérifie aisément que \( G \) est un sous-groupe de \( (\Rr,+) \). Maintenant, la formule du binôme de \textsc{Newton} montre que, pour chaque entier naturel \( n \),

\begin{center}
	\( (\sqrt{2}-1)^n\in G\cap]0,+\infty[ \).
\end{center}
Or, \( 0<\sqrt{2}-1<1 \) et donc \( \lim_{n\rightarrow +\infty}(\sqrt{2}-1)^n = 0 \). Ceci montre que \( \mbox{inf}(G\cap]0;+\infty[) = 0 \) et donc que \( G \) est dense dans \( \Rr \).

\item
\begin{enumerate}
	\item Soit \( f \) une application de \( \Rr \) dans \( \Rr \) et \( G_f = \{T\in\Rr/\;\forall x\in\Rr,\;f(x+T) = f(x)\} \). \( 0 \) est élément de \( G_f \) (et c'est même le seul élément de \( G_f \) si \( f \) n'est pas périodique) et donc \( G\neq\varnothing \). De plus, si \( T \) et \( T' \) sont deux éléments de \( G \) alors, pour \( x \) réel donné :

	\[
	f(x+(T-T')) = f((x-T')+T) = f(x-T') = f(x-T'+T') = f(x),
	\]
	et \( T-T' \) est encore un élément de \( G \). On a montré que

	\begin{center}
		\shadowbox{ \( G_f \) est un sous groupe de \( (\Rr,+) \). }
	\end{center}

	\item Soit \( f \) une application de \( \Rr \) dans \( \Rr \) admettant \( 1 \) et \( \sqrt{2} \) pour périodes. \( G_f \) contient encore tous les nombres de la forme \( a+b\sqrt{2},\;(a,b)\in\Zz^2 \) et est donc dense dans \( \Rr \). Montrons que si de plus \( f \) est continue sur \( \Rr \), \( f \) est constante. Soit \( x \) un réel quelconque. On va montrer que \( f(x) = f(0) \). Remarque préliminaire : soit \( T \) une période strictement positive de \( f \). Il existe un entier relatif \( p \) tel que \( pT\le x<(p+1)T \) à savoir \( p = E\left(\frac{x}{T}\right) \). On a alors \( f(x) = f(x-pT) \) avec \( 0\le x-pT<T \). Soit alors \( n\in\Nn^* \). Puisque \( G_f \) est dense dans \( \Rr \), il existe dans \( G_f \) un réel \( T_n \) tel que \( 0<T_n<\frac{1}{n} \) (ce qui implique que \( \lim_{n\rightarrow +\infty}T_n = 0 \)). Mais alors, puisque \( 0<x-E\left(\frac{x}{T_n}\right)T_n<T_n \), on a aussi \( \lim_{n\rightarrow +\infty}x-E\left(\frac{x}{T_n}\right)T_n = 0 \). Maintenant, la suite \( \left(f\left(x-E\left(\frac{x}{T_n}\right)T_n\right)\right)_{n\in\Nn^*} \) est constante égale à \( f(x) \)) et donc convergente vers \( f(x) \). On en déduit que

	\begin{align*}
		f(x) & =\lim_{n\rightarrow +\infty}f\left(x-E\left(\frac{x}{T_n}\right)T_n\right)= f\left(\lim_{n\rightarrow +\infty}\left(x-E\left(\frac{x}{T_n}\right)T_n\right)\right)\quad(\mbox{par continuité de}\;f\;\text{en}\;0) \\
		& =f(0)
	\end{align*}
	ce qu'il fallait démontrer.
\end{enumerate}
\end{enumerate}

Soient \( x \) un réel et \( \varepsilon \) un réel strictement positif. On a \( \sqrt[3]{x}<\sqrt[3]{x+\varepsilon} \). Puisque \( \Qq \) est dense dans \( \Rr \), il existe un rationnel \( r \) tel que \( \sqrt[3]{x}<r<\sqrt[3]{x+\varepsilon} \) et donc tel que \( x<r^3<x+\varepsilon \), par stricte croissance de la fonction \( t\mapsto t^3 \) sur \( \Rr \). On a montré que

\begin{center}
\shadowbox{ \( \{r^3,\;r\in\Qq\} \) est dense dans \( \Rr \). }
\end{center}

exercices.indication:
\begin{enumerate}
\item Rappelez-vous que la partie entière de \( x \) est le plus grand entier, inférieur ou égal à \( x \). Mais il est ici préférable de donner la définition de \( E(x) \) en disant que \( E(x) \in \Zz \) et que \( x \) vérifie un certain encadrement...

\item Encadrer \( E(kx) \), pour \( k = 1,\ldots,n \).

\item Rappelez-vous d'abord de la formule \( 1+2+\cdots+n \) puis utilisez le fameux théorème des gendarmes.

