\end{enumerate}

exercices.enonce:
Soit \( u_n = 1 + \frac1{\sqrt2} + \dots + \frac1{\sqrt n} \).

	\begin{enumerate}
		\item Chercher \( \lim_{n\to\infty} (u_{2n}-u_n) \), puis \( \lim_{n\to\infty} u_n \).

		\item Comparer \( \frac 1{2\sqrt k} \), \( \sqrt{k+1} - \sqrt k \), et \( \sqrt k - \sqrt{k-1} \). En déduire que la suite \( \bigl(u_n - 2\sqrt n\bigr) \) est convergente.

	\end{enumerate}

\begin{enumerate}
		\item On pose \( u_n = \frac 1{0!} + \frac 1{1!} + \dots + \frac 1{n!} \).
		\begin{enumerate}
			\item Montrer que la suite \( (u_n) \) est convergente.

			\item Calculer le nombre \( e = \lim_{n\to\infty}u_n \) à \( 10^{-7} \) près.
		\end{enumerate}

		\item On note \( v_n = \left(1+\frac1n\right)^{1/n} \).
		\begin{enumerate}
			\item Développer \( v_n \) et montrer que \( v_n \le e \).

			\item On fixe \( p \in \Nn \) et \( \varepsilon > 0 \). Montrer que pour \( n \) suffisamment grand, \( v_n \ge \sum_{k = 0}^p \frac 1{k!}
			- \varepsilon \).

			\item Que pouvez-vous en déduire ?
		\end{enumerate}
	\end{enumerate}

On pose \( u_n = \frac{1\times 3\times 5 \times \dots \times (2n-1)}
	{2\times 4\times 6 \times \dots \times (2n)} \).

	\begin{enumerate}
		\item Exprimer \( u_n \) à l'aide de factorielles.

		\item Montrer que la suite \( (u_n) \) est convergente.

		\item Soit \( v_n = (n+1)u_n^2 \). Montrer que la suite \( (v_n) \) converge. Que pouvez-vous en déduire pour \( \lim_{n\to\infty}u_n \) ?

		\item On note \( \alpha = \lim_{n\to\infty}v_n \). En étudiant la suite \( (n u_n^2) \), montrer que \( \alpha > 0 \).

	\end{enumerate}

