exercices.enonce:
Soit \( (u_n) \) une suite réelle. On pose \( v_n = \frac{u_1 + \dots + u_n}n \).

	\begin{enumerate}
		\item Montrer que si \( u_n \xrightarrow[n\to\infty]{} 0 \), alors \( v_n \xrightarrow[n\to\infty]{} 0 \).

		\item Montrer que si \( u_n \xrightarrow[n\to\infty]{} \ell \), alors \( v_n \xrightarrow[n\to\infty]{} \ell \). (\( \ell \in \overline\Rr \))

		\item Donner un exemple où \( (v_n) \) converge mais \( (u_n) \) diverge.

	\end{enumerate}

\begin{enumerate}
		\item Soit \( (b_n) \) une suite réelle strictement croissante tendant vers \( +\infty \), et \( (a_n) \) une suite réelle telle que :\par \( \frac{a_n-a_{n-1}}{b_n-b_{n-1}} \xrightarrow[n\to\infty]{} \ell \in \Rr \). Montrer que \( \frac{a_n}{b_n} \xrightarrow[n\to\infty]{} \ell \).

		\item Application : Quelle est la limite de \( \frac{1^k + 2^k + \dots + n^k}{n^{k+1}} \) \( (k \in \Nn) \) ?
	\end{enumerate}

Soit \( x \in \Rr^* \) et \( (r_n) \) une suite de rationnels convergeant vers \( x \). On écrit \( r_n = \frac{p_n}{q_n} \) avec \( p_n\in\Zz \), \( q_n\in\Nn^* \).

	\begin{enumerate}
		\item Montrer que si l'une des suites \( (p_n) \), \( (q_n) \) est bornée, alors l'autre l'est aussi, et \( x \in \Qq \).

		\item En déduire que si \( x \in \Rr\setminus \Qq \), alors \( |p_n| \xrightarrow[n\to\infty]{} +\infty \) et \( q_n \xrightarrow[n\to\infty]{} +\infty \).
	\end{enumerate}

Pour \( n \in \Nn^* \), on note \( S(n) \) la somme des chiffres de l'écriture décimale de \( n \).

	\begin{enumerate}
		\item Encadrer \( S(n+1) \) en fonction de \( S(n) \). En déduire que la suite \( \left(\frac{S(n+1)}{S(n)}\right) \) est bornée.

		\item Chercher \( \inf\left\{\frac{S(n+1)}{S(n)} \text{ tq } n \in \Nn^*\right\} \), et \( \sup\left\{\frac{S(n+1)}{S(n)} \text{ tq } n \in \Nn^*\right\} \).

		\item La suite \( \left(\frac{S(n+1)}{S(n)}\right) \) est-elle convergente ?
	\end{enumerate}

