exercices.enonce:
On note \( x_n = (\sqrt3 + 1)^{2n+1} \), \( y_n = (\sqrt3 - 1)^{2n+1} \), et \( z_n = [x_n] \).
	\begin{enumerate}
		\item Montrer que \( z_n = x_n - y_n \).

		\item En déduire que \( 2^{n+1} \) divise \( z_n \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item L'équation caractéristique est \( 4z^2-4z-3 = 0 \). Ses solutions sont \( -\frac{1}{2} \) et \( \frac{3}{2} \). Les suites cherchées sont les suites de la forme \( (u_n) = \left(\lambda\left(-\frac{1}{2}\right)^n+\mu\left(\frac{3}{2}\right)^n\right) \) où \( \lambda \) et \( \mu \) sont deux réels (ou deux complexes si on cherche toutes les suites complexes). Si \( u_0 \) et \( u_1 \) sont les deux premiers termes de la suite \( u \), \( \lambda \) et \( \mu \) sont les solutions du système \( \left\{
\begin{array}{l}
	\lambda+\mu = u_0 \\
	-\frac{\lambda}{2}+\frac{3\mu}{2} = u_1
\end{array}
\right. \) et donc \( \lambda = \frac{1}{4}(3u_0-2u_1) \) et \( \mu = \frac{1}{4}(u_0+2u_1) \).

\begin{center}
	\shadowbox{ \( \forall n\in\Nn,\;u_n = \frac{1}{4}(3u_0-2u_1)\left(-\frac{1}{2}\right)^n+\frac{1}{4}(u_0+2u_1)\left(\frac{3}{2}\right)^n \). }
\end{center}

\item Clairement \( u_{2n} = \frac{1}{4^n}u_0 \) et \( u_{2n+1} = \frac{1}{4^n}u_1 \) et donc \( u_n = \frac{1}{2}\left(\frac{1}{2^n}(1+(-1)^n)u_0+2\times\frac{1}{2^n}(1-(-1)^n)u_1\right) \).

\begin{center}
	\shadowbox{ \( \forall n\in\Nn \), \( u_n = \frac{1}{2^{n+1}}\left((1+(-1)^n)u_0+2(1-(-1)^n)u_1\right) \). }
\end{center}

\item Les solutions de l'équation homogène associée sont les suites de la forme \( \lambda\left(-\frac{1}{2}\right)^n+\mu\left(\frac{3}{2}\right)^n \). Une solution particulière de l'équation proposée est une constante \( a \) telle que \( 4a = 4a+3a+12 \) et donc \( a = -4 \). Les solutions de l'équation proposée sont donc les suites de la forme \( \left(-4+\lambda\left(-\frac{1}{2}\right)^n+\mu\left(\frac{3}{2}\right)^n\right) \) où \( \lambda \) et \( \mu \) sont les solutions du système \( \left\{
\begin{array}{l}
	\lambda+\mu = 4+u_0 \\
	-\frac{\lambda}{2}+\frac{3\mu}{2} = 4+u_1
\end{array}
\right. \) et donc \( \lambda = \frac{1}{4}(4+3u_0-2u_1) \) et \( \mu = \frac{1}{4}(12+u_0+2u_1) \).

\begin{center}
	\shadowbox{ \( \forall n\in\Nn,\;u_n = -4+\frac{1}{4}(4+3u_0-2u_1)\left(-\frac{1}{2}\right)^n+\frac{1}{4}(12+u_0+2u_1)\left(\frac{3}{2}\right)^n \). }
\end{center}

\item La suite \( v = \frac{1}{u} \) est solution de la récurrence \( 2v_{n+2} = v_{n+1}-v_n \) et donc, \( (v_n) \) est de la forme \( \left(\lambda\left(\frac{1+i\sqrt{7}}{4}\right)^n+\mu\left(\frac{1-i\sqrt{7}}{4}\right)^n\right) \) et donc \( u_n = \frac{1}{\lambda\left(\frac{1+i\sqrt{7}}{4}\right)^n+\mu\left(\frac{1-i\sqrt{7}}{4}\right)^n} \).

\item Les solutions de l'équation homogène associée sont les suites de la forme \( (\lambda+\mu2^n) \). \( 1 \) est racine simple de l'équation caractéristique et donc il existe une solution particulière de l'équation proposée de la forme \( u_n = an^4+bn^3+cn^2+dn \). Pour \( n\ge2 \), on a

\begin{align*}
	u_n-3u_{n-1}+2u_{n-2} & =(an^4+bn^3+cn^2+dn)-3(a(n-1)^4+b(n-1)^3+c(n-1)^2+d(n-1)) \\
	& \;+2(a(n-2)^4+b(n-2)^3+c(n-2)^2+d(n-2))                   \\
	& = a(n^4-3(n-1)^4+2(n-2)^4)+b(n^3-3(n-1)^3+2(n-2)^3)       \\
	& \;+c(n^2-3(n-1)^2+2(n-2)^2)+d(n-3(n-1)+2(n-2))            \\
	& = a(-4n^3+30n^2-52n+29)+b(-3n^2+15n-13)+c(-2n+5)+d(-1)    \\
	& =n^3(-4a)+n^2(30a-3b)+n(-52a+15b-2c)+29a-13b+5c-d.
\end{align*}

\begin{align*}
	u\;\mbox{est solution} & \Leftrightarrow-4a=1\;\mbox{et}\;30a-3b=0\;\mbox{et}\;-52a+15b-2c=0\;\mbox{et}\;29a-13b+5c-d=0 \\
	& \Leftrightarrow a=-\frac{1}{4},\;b=-\frac{5}{2},\;c=-\frac{49}{4},\;d=-36.
\end{align*}
Les suites cherchées sont les suites de la forme \( \left(-\frac{1}{4}(n^3+10n^2+49n+144)+\lambda+\mu2^n\right) \).

\item Pour tout complexe \( z \), \( z^3-6z^2+11z-6 = (z-1)(z-2)(z-3) \) et les suites solutions sont les suites de la forme \( (\alpha+\beta2^n+\gamma3^n) \).

\item Pour tout complexe \( z \), \( z^4-2z^3+2z^2-2z+1 = (z^2+1)^2-2z(z^2+1) = (z-1)^2(z^2+1) \). Les solutions de l'équation homogène associée sont les suites de la forme \( \alpha+\beta n+\gamma i^n+\delta(-i)^n \). \( 1 \) est racine double de l'équation caractéristique et donc l'équation proposée admet une solution particulière de la forme \( u_n = an^7+bn^6+cn^5+dn^4+en^3+fn^2 \). Pour tout entier naturel \( n \), on a

\begin{align*}
	u_{n+4}-2u_{n+3} & +2u_{n+2}-2u_{n+1}+u_n=a((n+4)^7-2(n+3)^7+2(n+2)^7-2(n+1)^7+n^7)       \\
	& +b((n+4)^6-2(n+3)^6+2(n+2)^6-2(n+1)^6+n^6)                             \\
	& +c((n+4)^5-2(n+3)^5+2(n+2)^5-2(n+1)^5+n^5)                             \\
	& +d((n+4)^4-2(n+3)^4+2(n+2)^4-2(n+1)^4+n^4)                             \\
	& +e((n+4)^3-2(n+3)^3+2(n+2)^3-2(n+1)^3+n^3)                             \\
	& +f((n+4)^2-2(n+3)^2+2(n+2)^2-2(n+1)^2+n^2)                             \\
	& =a(84n^5+840n^4+4340n^3+12600n^2+19348n+12264)                         \\
	& +b(60n^4+480n^3+1860n^2+3600n+2764)                                    \\
	& +c(40n^3+240n^2+620n+600)+d(24n^2+96n+124)+e(12n+24)+4f                \\
	& =n^5(84a)+n^4(840a+60b)+n^3(4340a+480b+40c)+n^2(12600a+1860b+240c+24d) \\
	& +n(19348a+3600b+620c+96d+12e)+(12264a+2764b+600c+124d+24e+4f)
\end{align*}
\( u \) est solution si et seulement si \( 84a = 1 \) et donc \( a = \frac{1}{84} \), puis \( 840a+60b = 0 \) et donc \( b = -\frac{1}{6} \), puis \( 4340a+480b+40c = 0 \) et donc \( c = \frac{17}{24} \), puis \( 12600a+1860b+240c+24d = 0 \) et donc \( d = -\frac{5}{12} \) puis \( 19348a+3600b+620c+96d+12e = 0 \) et donc \( e = -\frac{59}{24} \) puis \( 12264a+2764b+600c+124d+24e+4f = 0 \) et donc \( f = \frac{1}{12} \). La solution générale de l'équation avec second membre est donc :

\[
\forall n\in\Nn,\;u_n = \frac{1}{168}(2n^7-28n^6+119n^5-70n^4-413n^3+14n^2)+\alpha+\beta n+\gamma i^n+\delta(-i)^n,\; (\alpha,\beta,\gamma,\delta)\in\Cc^4.
\]
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item (*) Calculer \( \prod_{k = 1}^n(1+\frac{1}{k}) \), \( n\in\Nn^* \).

		\item (***) Calculer \( \prod_{k = 1}^n\cos\frac{a}{2^k} \), \( a\in]0,\pi[ \), \( n\in\Nn^* \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( n\in\Nn^* \).

\begin{align*}
	\prod_{k=1}^n(1+\frac{1}{k}) & =\prod_{k=1}^n\frac{k+1}{k}=\frac{\prod_{k=1}^n(k+1)}{\prod_{k=1}^nk}=\frac{(n+1)!}
	{n!}=n+1
\end{align*}

\item Soit \( a\in]0,\pi[ \) et \( n\in\Nn^* \). Alors, pour tout naturel non nul \( k \), on a \( 0<\frac{a}{2^k}\le\frac{a}{2}<\frac{\pi}{2} \) et donc \( \sin\frac{a}{2^k}\neq0 \).

On sait alors que pour tout réel \( x \), \( \sin(2x) = 2\sin x\cos x \). Par suite, pour tout naturel \( k \),

\[
\sin(2.\frac{a}{2^k}) = 2\sin\frac{2^k}\cos\frac{a}{2^k}\quad\mbox{et donc}\quad
\cos\frac{a}{2^k} = \frac{\sin(a/2^{k-1})}{2\sin(a/2^k)}.
\]
Mais alors,

\begin{align*}
	\prod_{k=1}^n\cos\frac{a}{2^k} & =\prod_{k=1}^n\frac{\sin(a/2^{k-1})}{2\sin(a/2^k)}=\frac{1}{2^n}\frac{\prod_{k=1}^n\sin(a/2^{k-1})}{\prod_{k=1}^n\sin(a/2^k)}
	=\frac{1}{2^n}\frac{\prod_{k=0}^{n-1}
		\sin(a/2^k)}{\prod_{k=1}^n\sin(a/2^k)}
	=\frac{\sin a}{2^n\sin(a/2^n)}.
\end{align*}
\end{enumerate}

Pour \( n\in\Nn^* \), \( (1+\frac{1}{n})^n = \sum_{k = 0}^n\frac{C_n^k}{n^k} \). Pour \( k\in\{0,...,n\} \), posons \( u_k = \frac{C_n^k}{n^k} \) puis \( v_k = \frac{u_{k+1}}{u_k} \). Pour \( k\in\{1,...,n-1\} \), on a alors

\begin{align*}
v_k & =\frac{C_n^{k+1}.n^k}{C_n^k.n^{k+1}}=\frac{1}{n}.\frac{n!k!(n-k)!}{n!(k+1)!(n-k-1)!}=\frac{n-k}{n(k+1)}
=\frac{(n+1)-(k+1)}{n(k+1)}=-\frac{1}{n}+\frac{n+1}{n(k+1)}                                                   \\
& \le-\frac{1}{n}+\frac{n+1}{2n}\;(\mbox{car}\;k\ge1)                                                     \\
& =\frac{1}{2}-\frac{1}{2n}<\frac{1}{2}
\end{align*}

Ainsi, pour \( k\in\{1,...,n-1\} \), \( u_{k+1}\le\frac{1}{2}u_k \) et donc, immédiatement par récurrence,

\[
u_k\le\frac{1}{2^{k-1}}u_1 = \frac{1}{2^{k-1}}\frac{n}{n} = \frac{1}{2^{k-1}}.
\]
En tenant compte de \( u_0 = 1 \), on a alors pour \( n\in\Nn^* \),

\[
(1+\frac{1}{n})^n = \sum_{k = 0}^nu_k\le1+\sum_{k = 1}^n\frac{1}{2^{k-1}} = 1+\frac{1-\frac{1}{2^n}}{1-\frac{1}{2}}
= 1+2(1-\frac{1}{2^n}) = 3-\frac{1}{2^{n-1}}<3.
\]

exercices.enonce:
Soient \( (u_n)_{n\in\Nn} \) une suite réelle et \( (v_n)_{n\in\Nn} \) la suite définie par : \( \forall n\in\Nn,\;v_n = \frac{u_0+u_1+...+u_n}{n+1} \).

	\begin{enumerate}
		\item Montrer que si la suite \( (u_n)_{n\in\Nn} \) converge vers un réel \( \ell \), la suite \( (v_n)_{n\in\Nn} \) converge et a pour limite \( \ell \). Réciproque ?

		\item Montrer que si la suite \( (u_n)_{n\in\Nn} \) est bornée, la suite \( (v_n)_{n\in\Nn} \) est bornée. Réciproque ?

		\item Montrer que si la suite \( (u_n)_{n\in\Nn} \) est croissante alors la suite \( (v_n)_{n\in\Nn} \) l'est aussi.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( \varepsilon>0 \). Il existe un rang \( n_0 \) tel que, si \( n\ge n_0 \) alors \( |u_n-\ell|<\frac{\varepsilon}{2} \). Soit \( n \) un entier naturel strictement supérieur à \( n_0 \).

\begin{align*}
	|v_n-\ell| & =\left|\frac{1}{n+1}\sum_{k=0}^nu_k-\ell\right|=\left|\frac{1}{n+1}\sum_{k=0}^n(u_k-\ell)\right|                                                                                       \\
	& \le\frac{1}{n+1}\sum_{k=0}^n|u_k-\ell|=\frac{1}{n+1}\sum_{k=0}^{n_0}|u_k-\ell|+\frac{1}{n+1}\sum_{k=n_0+1}^n|u_k-\ell|                                                                 \\
	& \le\frac{1}{n+1}\sum_{k=0}^{n_0}|u_k-\ell|+\frac{1}{n+1}\sum_{k=n_0+1}^n\frac{\varepsilon}{2}\le\frac{1}{n+1}\sum_{k=0}^{n_0}|u_k-\ell|+\frac{1}{n+1}\sum_{k=0}^n\frac{\varepsilon}{2} \\
	& =\frac{1}{n+1}\sum_{k=0}^{n_0}|u_k-\ell|+\frac{\varepsilon}{2}
\end{align*}
Maintenant, \( \sum_{k = 0}^{n_0}|u_k-\ell| \) est une expression constante quand \( n \) varie et donc, \( \lim_{n\rightarrow +\infty}\frac{1}{n+1}\sum_{k = 0}^{n_0}|u_k-\ell| = 0 \). Par suite, il existe un entier \( n_1\ge n_0 \) tel que pour \( n\ge n_1 \), \( \frac{1}{n+1}\sum_{k = 0}^{n_0}|u_k-\ell|<\frac{\varepsilon}{2} \). Pour \( n\ge n_1 \), on a alors \( |v_n-\ell|<\frac{\varepsilon}{2}+\frac{\varepsilon}{2} = \varepsilon \). On a montré que \( \forall\varepsilon>0,\;\exists n_1\in\Nn/\;(\forall n\in\Nn)(n\ge n_1\Rightarrow|v_n-\ell|<\varepsilon) \). La suite \( (v_n) \) est donc convergente et \( \lim_{n\rightarrow +\infty}v_n = \ell \).

\begin{center}
	\shadowbox{ Si la suite \( u \) converge vers \( \ell \) alors la suite \( v \) converge vers \( \ell \). }
\end{center}
La réciproque est fausse. Pour \( n \) dans \( \Nn \), posons \( u_n = (-1)^n \). La suite \( (u_n) \) est divergente. D'autre part, pour \( n \) dans \( \Nn \), \( \sum_{k = 0}^n(-1)^k \) vaut \( 0 \) ou \( 1 \) suivant la parité de \( n \) et donc, dans tous les cas, \( |v_n|\le\frac{1}{n+1} \). Par suite, la suite \( (v_n) \) converge et \( \lim_{n\rightarrow +\infty}v_n = 0 \).

\item Si \( u \) est bornée, il existe un réel \( M \) tel que, pour tout naturel \( n \), \( |u_n|\le M \). Pour \( n \) entier naturel donné, on a alors

\[
|v_n|\le\frac{1}{n+1}\sum_{k = 0}^n|u_k|\le\frac{1}{n+1}\sum_{k = 0}^nM = \frac{1}{n+1}(n+1)M = M.
\]
La suite \( v \) est donc bornée.

\begin{center}
	\shadowbox{ Si la suite \( u \) est bornée alors la suite \( v \) est bornée. }
\end{center}
La réciproque est fausse. Soit \( u \) la suite définie par : \( \forall n\in\Nn,\;u_n = (-1)^nE\left(\frac{n}{2}\right) = \left\{
\begin{array}{l}
	p\;\mbox{si}\;n = 2p,\;p\in\Nn \\
	-p\;\mbox{si}\;n = 2p+1,\;p\in\Nn
\end{array}
\right. \). \( u \) n'est pas bornée car la suite extraite \( (u_{2p}) \) tend vers \( +\infty \) quand \( p \) tend vers \( +\infty \). Mais, si \( n \) est impair, \( v_n = 0 \), et si \( n \) est pair, \( v_n = \frac{1}{n+1}\times u_n = \frac{n}{2(n+1)} \), et dans tous les cas \( |v_n|\le\frac{1}{n+1}\frac{n}{2}\le\frac{1}{n+1}\frac{n+1}{2} = \frac{1}{2} \) et la suite \( v \) est bornée.

\item Si \( u \) est croissante, pour \( n \) entier naturel donné on a :

\begin{align*}
	v_{n+1}-v_n & =\frac{1}{n+2}\sum_{k=0}^{n+1}u_k-\frac{1}{n+1}\sum_{k=0}^nu_k=\frac{1}{(n+1)(n+2)}\left((n+1)\sum_{k=0}^{n+1}u_k-(n+2)\sum_{k=0}^nu_k\right) \\
	& =\frac{1}{(n+1)(n+2)}\left((n+1)u_{n+1}-\sum_{k=0}^nu_k\right)=\frac{1}{(n+1)(n+2)}\sum_{k=0}^n(u_{n+1}-u_k)\ge0.
\end{align*}
La suite \( v \) est donc croissante.

\begin{center}
	\shadowbox{ Si la suite \( u \) est croissante alors la suite \( v \) est croissante. }
\end{center}
\end{enumerate}

exercices.indication:
\begin{enumerate}
\item On pourra utiliser la variante de l'inégalité triangulaire \( |x-y|\ge \big| |x|-|y| \big| \).

\item Utiliser la première question pour montrer que \( |f-g| \) est continue.
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item On a pour tout \( x,y\in\Rr \) \( |x-y|\ge \big| |x|-|y|\big| \) (c'est la deuxième formulation de l'inégalité triangulaire). Donc pour tout \( x\in I \) :\( \big| |f(x)|-|f(a)| \big| \le |f(x)-f(a)| \). L'implication annoncée résulte alors immédiatement de la définition de l'assertion \( \lim_{x\to a} f(x) = f(a) \).

\item Si \( f,g \) sont continues alors \( \alpha f+\beta g \) est continue sur \( I \), pour tout \( \alpha,\beta\in\Rr \). Donc les fonctions \( f+g \) et \( f-g \) sont continues sur \( I \). L'implication de \( 1 \). prouve alors que \( |f-g| \) est continue sur \( I \), et finalement on peut conclure :\\
La fonction \( \sup (f,g) = \frac{1}{2}(f+g+|f-g|) \) est continue sur \( I \).
\end{enumerate}

exercices.enonce:
Soit \( f \) une fonction de \( \lbrack a,b \rbrack \) dans \( \lbrack a,b\rbrack \) telle que pour tout \( x \) et \( x' \) (\( x\neq x' \)) de \( \lbrack a,b \rbrack \) on ait : \( \ \ \vert f(x)-f(x')\vert<\vert x-x'\vert \).
	\begin{enumerate}
		\item Montrer que \( f \) est continue sur \( \lbrack a,b\rbrack \).

		\item Montrer que l'équation \( f(x) = x \) admet une et une seule solution
		\mbox{dans \( \lbrack a,b\rbrack \).}
		(On pourra introduire la fonction: \( x\mapsto g(x) = f(x)-x \).)
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f \) une fonction continue sur \( ]a,b[ \) telle que \( f(]a,b[)\subset [a,b] \). Montrer, par considération de \( \phi(x) = f(x)-x \), qu'il existe \( c \) dans \( [a,b] \) tel que \( f(c) = c \).

		\item Soit \( f \) une fonction continue sur \( [0,1] \) telle que \( f(0) = f(1) \). Montrer qu'il existe \( c \) dans \( [0,\frac{1}{2}] \) tel que \( f(c) = f(c+\frac{1}{2}) \).

		\item Un mobile parcourt, à vitesse continue, une distance \( d \) en une unité de temps. Montrer qu'il existe un intervalle d'une demi-unité de temps pendant lequel il parcourt une distance \( \frac{d}{2} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( g(a) = f(\frac{a+b}{2})-f(a) \) et \( g(\frac{a+b}{2}) = f(b) - f(\frac{a+b}{2}) \). Comme \( f(a) = f(b) \) alors nous obtenons que \( g(a) = -g(\frac{a+b}{2}) \). Donc ou bien \( g(a) \le 0 \) et \( g(\frac{a+b}{2}) \ge 0 \) ou bien \( g(a) \ge 0 \) et \( g(\frac{a+b}{2}) \le 0 \). D'après le théorème des valeurs intermédiaires, \( g \) s'annule en \( c \) pour un \( c \) entre \( a \) et \( \frac{a+b}{2} \).

\item Notons \( t \) le temps (en heure) et \( d(t) \) la distance parcourue (en km) entre les instants \( 0 \) et \( t \). Nous supposons que la fonction \( t \mapsto d(t) \) est continue. Soit \( f(t) = d(t) - 4t \). Alors \( f(0) = 0 \) et par hypothèse \( f(1) = 0 \). Appliquons la question précédente avec \( a = 0 \), \( b = 1 \). Il existe \( c\in [0,\frac 12] \) tel que \( g(c) = 0 \), c'est-à-dire \( f(c+\frac12) = f(c) \). Donc \( d(c+\frac 12)-d(c) = 4(c+\frac12)-4c = 2 \). Donc entre \( c \) et \( c+\frac 12 \), (soit 1/2 heure), la personne parcourt exactement \( 2 \) km.
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \rightarrow \Rr^{+} \) continue telle que \( f (0) = 1 \), \( \lim\limits_{ -\infty}f = 0 \) et \( \lim\limits_{ + \infty}f = 0 \).
	\begin{enumerate}
		\item Montrer qu'il existe \( a>0 \) tel que si \( \left|x\right|>a \) alors \( f (x) \le \frac 12 \).

		\item Montrer que \( f \) est bornée et possède un maximum.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( x\in[0,1] \) et \( y = f(x) \in [0,1] \). Alors \( f(y) = y \) car \( f(f(x)) = f(x) \). Donc \( E_f \not= \varnothing \). Nous venons de montrer que \( I = f([0,1]) \) est inclus dans \( E_f \).

\item Montrons réciproquement que \( E_f \) est inclus dans \( I \). Soit \( x\in[0,1] \) tel que \( f(x) = x \) alors \( x \in I = f([0,1]) \) (car \( x = f(x) \) !). Ainsi \( E_f = I = f([0,1]) \). Mais l'image de l'intervalle \( [0,1] \) par la fonction continue \( f \) est un intervalle donc \( E_f \) est un intervalle.

\item La réciproque est vraie : une fonction continue pour laquelle \( E_f = f([0,1]) \) vérifie aussi \( f\circ f = f \). En effet pour \( x \in [0,1] \) et \( y = f(x) \) alors \( y \in f([0,1]) \) donc \( y \in E_f \). Donc \( f(y) = y \), autrement dit \( f(f(x)) = f(x) \).

Les fonctions continues qui vérifient \( f \circ = f \) sont donc exactement les fonctions continues telles que \( E_f = f([0,1]) \). Pour une telle fonction si l'on note \( [a,b] = E_f \) alors \( f \) est définie sur \( [0,a] \) par n'importe qu'elle fonction continue prenant ses valeurs entre \( a \) et \( b \), et valant \( a \) en \( a \) : \( f([0,a]) \subset [a,b] \) et \( f(a) = a \). Elle est ensuite définie par l'identité sur \( [a,b] \) : pour tout \( x\in [a,b] \), \( f(x) = x \). Et enfin sur \( [b,1] \) elle est définie par n'importe quelle fonction continue prenant ses valeurs entre \( a \) et \( b \), et valant \( b \) en \( b \) : \( f([b,1]) \subset [a,b] \) et \( f(b) = b \).
\end{enumerate}

exercices.enonce:
Soit \( (f,g)\in C([0,1],[0,1])^2 \), tel que : \( fg = gf \). On veut montrer que \( f-g \) s'annule par deux méthodes :
	\begin{itemize}
		\item par l'absurde, utiliser le fait que \( (f-g)([0,1]) \) est un segment ne contenant pas 0.

		\item par l'absurde, en examinant, si \( f-g>0 \) par exemple, \( \min\{x\in [0,1]|f(x) = x\} \).
	\end{itemize}
	Le résultat subsiste-t-il si l'on remplace \( [0,1] \) par \( \Rr \) ?

exercices.indication:
\begin{enumerate}
\item On pourra montrer que \( \sup_{a\le x \le b} f(x) \) est un majorant de \( f \) sur \( ]a,b[ \).

\item Dans le cas \( x_0 = a \), par exemple, on pourra considérer la suite de réels \( a_n = a+1/n \) et étudier la suite \( (f(a_n)) \).
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \to \Rr \) et \( T > 0 \). On suppose que \( f \) est \( T \)-périodique c.-à-d. : \( \forall\ x \in \Rr,\ f(x+T) = f(x) \).

	\begin{enumerate}
		\item Si \( f \) possède une limite en \( +\infty \), montrer que \( f \) est constante.

		\item Si \( f \) est continue non constante, montrer que \( f \) a une plus petite période.

		\item Si \( f \) est continue, montrer que \( f \) est bornée et atteint ses bornes.
	\end{enumerate}

Soit \( f : {[0,+\infty[} \to \Rr \) une fonction continue ayant une limite finie en \( +\infty \).

	\begin{enumerate}
		\item Montrer que \( f \) est bornée.

		\item Montrer que \( f \) admet un maximum ou un minimum absolu, mais pas nécessairement les deux.

		\item Montrer que \( f \) est uniformément continue.
	\end{enumerate}

Pour \( x \in [0,1[ \), on note \( x = \sum_{k = 1}^\infty \frac{x_k}{10^k} \) le développement décimal propre de \( x \).

	\begin{enumerate}
		\item Soit \( f : [0,1[ \to [0,1[ \) définie par : \( f(x) = \sum_{k = 1}^\infty \frac{x_{k+1}}{10^k} \). Montrer que \( f \) est continue par morceaux.

		\item Soit \( g : [0,1[ \to [0,1[ \) définie par : \( g(x) = \sum_{k = 1}^\infty \left( \frac{x_{2k}}{10^{2k-1}} +
		\frac{x_{2k-1}}{10^{2k}} \right) \). Déterminer les points où \( g \) est continue.
	\end{enumerate}

\begin{enumerate}
		\item Soient \( {f,g} : \Rr \to \Rr \) continues telles que : \( \forall\ x \in \Qq,\ f(x) < g(x) \).
		\begin{enumerate}
			\item Montrer que \( f \le g \).

			\item Montrer qu'on n'a pas nécessairement : \( \forall\ x \in \Rr,\ f(x) < g(x) \).
		\end{enumerate}

		\item Soit \( f : \Rr \to \Rr \) continue dont la restriction à \( \Qq \) est strictement croissante. Montrer que \( f \) est strictement croissante.

	\end{enumerate}

\begin{enumerate}
		\item Soit \( f : [0,1] \to [0,1] \) continue. Montrer qu'il existe \( x \in [0,1] \) tel que \( f(x) = x \).

		\item Soient \( {f,g} : [0,1] \to [0,1] \) continues telles que \( f\circ g = g\circ f \). Montrer qu'il existe \( x \in [0,1] \) tel que \( f(x) = g(x) \) (on pourra s'intéresser aux points fixes de \( f \)).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( f(x)-x \) change de signe entre \( 0 \) et \( 1 \).

\item Sinon \( f-g \) est de signe constant, par exemple positif. Si \( a \) est le plus grand point fixe de \( f \) alors \( g(a)>a \) et \( g(a) \) est aussi point fixe de \( f \), absurde.
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \to \Rr \). On dit que \( f \) vérifie la propriété des valeurs intermédiaires si :
	\[
	\forall\ a,b\in\Rr \text{ avec } a < b, \forall\ y \text{ compris entre }
	f(a) \text{ et } f(b),\ \exists\ x \in [a,b] \text{ tq } f(x) = y.
	\]
	\begin{enumerate}
		\item Montrer que si \( f \) vérifie la propriété des valeurs intermédiaires et est injective, alors elle est continue.

		\item Trouver une fonction discontinue ayant la propriété des valeurs intermédiaires.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( a\in\Rr \) tel que \( f \) est discontinue en \( a \). Il existe une suite \( a_n \) telle que \( a_n \to a \) et \( |f(a_n)-f(a)| \ge \varepsilon \). Alors \( f(a)\pm\varepsilon \) a une infinité d'antécédents.

\item
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \to \Rr \) telle que : \( \forall\ x,y \in \Rr,\ f(x+y) = f(x) + f(y) \). On pose \( a = f(1) \).

	\begin{enumerate}
		\item Montrer que : \( \forall\ x\in\Qq \), \( f(x) = ax \).

		\item On suppose \( f \) continue. Montrer que : \( \forall\ x \in \Rr \), \( f(x) = ax \).

		\item On suppose que \( f \) est bornée au voisinage de 0. Montrer que : \( \forall\ x \in \Rr \), \( f(x) = ax \).
	\end{enumerate}

\
	\begin{enumerate}
		\item Existe-t-il toujours \( \varphi \) lipschitzienne telle que \( \varphi\le f \) où \( f : {\Rr^n} \to \Rr \) est une application continue donnée ?

		\item Soit \( k>0 \). Trouver une CNS sur \( f \) pour qu'il existe \( \varphi : {\Rr^n}\to \Rr \) \( k \)-lipschitzienne minorant \( f \).

		\item On suppose cette CNS vérifiée pour \( k_0>0 \). Montrer que si \( k\ge k_0 \) alors il existe \( \varphi_k \), \( k \)-lipschitzienne minorant \( f \) et maximale pour l'ordre usuel des fonctions.

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Non. Si \( \varphi \) est lipschitzienne alors \( \varphi(x) = O(\|x\|) \) lorsque \( \|x\| \) tend vers l'infini, donc toute fonction \( f \) à décroissance suffisament rapide vers \( -\infty \) n'est pas minorable par une fonction lipschitzienne. Contre-exemple explicite : \( f(x) = -\|x\|^2 \).

\item CNS : \( x \mapsto f(x)+k\|x\| \) est minorée.

\item On pose \( \varphi(x) = \sup\{g(x),\ g\ k \)-lipschitzienne minorant \( f\} \). Il suffit de vérifier que \( \varphi \) est \( k \)-lipschitzienne, ce sera alors la plus grande fonction \( k \)-lipschitzienne minorant \( f \). Soient \( x,y\in\Rr^n \), \( \varepsilon>0 \) et \( g_x,g_y \) des fonctions \( k \)-lipschitziennes minorant \( f \) telles que \( g_y(x)\le\varphi(x)\le g_x(x)+\varepsilon \) et \( g_x(y)\le\varphi(y)\le g_y(y)+\varepsilon \). On a :
\begin{align*}
	\varphi(y) & \le g_y(y)+\varepsilon\le g_y(x)+k\|x-y\|+\varepsilon\le\varphi(x)+k\|x-y\|+\varepsilon, \\
	\varphi(y) & \ge g_x(y)\ge g_x(x)-k\|x-y\|\ge\varphi(x)-k\|x-y\|-\varepsilon.
\end{align*}
Donc \( |\varphi(x)-\varphi(y)|\le k\|x-y\|+\varepsilon \) et on fait tendre \( \varepsilon \) vers \( 0^+ \).
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Soit la fonction réelle définie par \( f(x) = 1 \) si \( x\in\Qq \) et \( f(x) = 0 \) sinon. Montrer que \( f \) n'admet pas de limite en tout point de \( \Rr \).

		\item Soit la fonction réelle définie par \( f(x) = x \) si \( x\in\Qq \) et \( f(x) = 1-x \) sinon. En quels points de \( \Rr \) \( f \) est‑elle continue ?
	\end{enumerate}

On admet que pour tout \( x\in \Rr, \vert \sin x \vert \le \vert x\vert \).
	\begin{enumerate}
		\item Montrer que \( x\mapsto \sin x \) est continue en \( 0 \) puis sur \( \Rr \) tout entier.

		\item En déduire que \( x\mapsto \cos x \) est continue sur \( \Rr \).
	\end{enumerate}

Étudier la continuité sur \( \Rr \) des fonctions suivantes :
	\begin{enumerate}
		\item \( f_1(x) = x^2 \cos \frac{1}{x} \mbox{ si } x\not=0, \mbox{ et }
		f_1(0) = 0 \) ;

		\item \( f_2(x) = \sin x\sin \frac{1}{x} \mbox{ si } x\not=0, \mbox{ et } f_2(0) = 0 \) ;

		\item \( f_3(x) = x E(x) \) ;

		\item \( f_4(x) = E(x) \sin(\pi x) \).
	\end{enumerate}

Étudier la continuité sur \( \Rr \) des fonctions suivantes :
	\begin{enumerate}
		\item \( f(x) = E(x)\sin(x) \),

		\item \( g(x) = E(x)\sin(\pi x) \).
	\end{enumerate}

Étudier la continuité de
	\begin{enumerate}
		\item \( f (x) = x + \sqrt{x-\text{E} (x)} \).

		\item \( g (x) = \text{E} (x) + \sqrt{x-\text{E} (x)} \).
	\end{enumerate}

Soit \( f : [0,1]\longrightarrow \Rr \) définie par \( f(0) = 0 \), \( f(x) = 1/2-x \) si \( x\in ]0,1/2[ \), \( f(1/2) = 1/2 \), \( f(x) = 3/2-x \) si \( x\in ]1/2,1[ \) et \( f(1) = 1 \).
	\begin{enumerate}
		\item Tracer le graphe de \( f \). Étudier sa continuité.\\

		\item Démontrer que \( f \) est une bijection de \( [0,1] \) sur \( [0,1] \).\\

		\item Démontrer que pour tout \( x\in [0,1] \), on a \( f(x) = \frac{1}{2}-x+\frac{1}{2}E(2x)-\frac{1}{2}E(1-2x) \).
	\end{enumerate}

Étudier la continuité des fonctions suivantes :
	\begin{enumerate}
		\item \( f_1(x) = x^2\cos \frac{1}{x} \text{\ \ si }x\not=0 \qquad f_1(0) = 0 \) ;

		\item \( f_2(x) = \sin x\sin \frac{1}{x} \text{\ \ si }x\not=0 \qquad f_2(0) = 0 \) ;

		\item \( f_3(x) = xE(x) \text{ sur } \Rr \) ;

		\item \( f_4(x) = \left[ x-E(x)\right]^2 \text{\ \ et\ \ } f_5(x) = E(x)+f_4(x) \).
	\end{enumerate}

\begin{enumerate}
		\item Démontrer que \( \displaystyle{ \lim_{x\rightarrow 0}\frac{\sqrt{1+x}-\sqrt{1-x}}{ x} = 1} \).

		\item Soient \( m,n \) des entiers positifs. Étudier \( \displaystyle{\lim_{x\rightarrow 0}\frac{\sqrt{1+x^m}-
				\sqrt{1-x^m}}{ x^n}} \).

		\item Démontrer que \( \displaystyle{ \lim_{x\rightarrow 0}\frac{1}{x}(\sqrt{1+x+x^2}-1) = \frac{1}{2}} \).
	\end{enumerate}

\begin{enumerate}
		\item Montrer que toute fonction périodique et non constante n'admet pas de limite en \( +\infty \).

		\item Montrer que toute fonction croissante et majorée admet une limite finie en \( +\infty \).
	\end{enumerate}

exercices.indication:
\begin{enumerate}
\item Raisonner par l'absurde.

\item Montrer que la limite est la borne supérieure de l'ensemble des valeurs atteintes \( f(\Rr) \).
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Rappeler que pour tout nombre réel \( \epsilon > 0 \) il existe un entier \( n \) tel que:
		\begin{eqnarray*}
			\frac 1{2n\pi} &<& \epsilon\\
			\frac 1{(2n+1)\pi} &<& \epsilon.\\
		\end{eqnarray*}

		\item Montrer que pour tout nombre réel \( l \), et pour tout \( \epsilon > 0 \), il existe \( x \in ]-\epsilon,\epsilon[ \) tel que:
		\[
		|\sin \frac 1x -l | > \frac 12.
		\]

		\item En déduire que la fonction \( x \mapsto \sin \frac 1x \) n'a pas de limite lorsque \( x \) tend vers \( 0 \).

		\item Montrer que la fonction définie par \( f(x) = x \sin(\frac 1x) \) pour \( x \not= 0 \) et \( f(0) = 0 \) est continue sur \( \Rr \).
	\end{enumerate}

Calculer :
	\[
	\lim\limits_{x\rightarrow \infty }\ln (1+e^{-x})^{\frac{1}{x}
	},\lim\limits_{x\rightarrow 0}\frac{x}{2+\sin \frac{1}{x}}
	,\lim\limits_{x\rightarrow 0^{+}}x^{\frac{1}{\ln (e^x-1)}}.
	\]

Calculer :
	\[
	\lim\limits_{x\rightarrow 0}\frac{x}{2+\sin \frac{1}{x}}
	,\ \ \lim\limits_{x\rightarrow +\infty }(\ln (1+e^{-x}))^{\frac{1}{x}}
	,\ \ \lim\limits_{x\rightarrow 0^{+}}x^{\frac{1}{\ln (e^x-1)}}.
	\]

exercices.indication:
Réponses : \( 0,\frac{1}{e},e \).
\begin{enumerate}
\item Borner \( \sin\frac{1}{x} \).

\item Utiliser que \( \ln(1+t) = t \cdot \mu(t) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(t) \to 1 \) lorsque \( t\to 0 \).

\item Utiliser que \( e^t-1 = t \cdot \mu(t) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(t) \to 1 \) lorsque \( t\to 0 \).
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Comme \( -1 \le \sin \frac 1x \le +1 \) alors \( 1 \le 2 + \sin \frac 1x \le +3 \). Donc pour \( x>0 \), nous obtenons \( \frac x3 \le \frac{x}{2+\sin \frac{1}{x}} \le x \). On obtient une inégalité similaire pour \( x<0 \). Cela implique \( \lim\limits_{x\rightarrow 0}\frac{x}{2+\sin \frac{1}{x}} = 0 \).

\item Sachant que \( \frac{\ln (1+t)}{t} \to 1 \) lorsque \( t \to 0 \), on peut le reformuler ainsi \( \ln(1+t) = t \cdot \mu(t) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(t) \to 1 \) lorsque \( t\to 0 \). Donc \( \ln (1+e^{-x}) = e^{-x} \mu(e^{-x}) \). Maintenant

\begin{align*}
	(\ln (1+e^{-x}))^{\frac{1}{x}}
	& = \exp \left(\frac{1}{x} \ln\left( \ln (1+e^{-x}) \right) \right)      \\
	& = \exp \left(\frac{1}{x} \ln \left( e^{-x} \mu(e^{-x}) \right) \right) \\
	& = \exp \left(\frac{1}{x} \left( -x + \ln \mu(e^{-x}) \right) \right)   \\
	& = \exp \left( -1 + \frac{\ln \mu(e^{-x})}{x} \right)
\end{align*}
\( \mu(e^{-x}) \to 1 \) donc \( \ln\mu(e^{-x}) \to 0 \), donc \( \frac{\ln \mu(e^{-x})}{x} \to 0 \) lorsque \( x \to +\infty \).

Bilan : la limite est \( \exp(-1) = \frac{1}{e} \).

\item

\item Sachant \( \frac{e^x - 1}{x} \to 1 \) lorsque \( x\to 0 \), on reformule ceci en \( e^x-1 = x \cdot \mu(x) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(x) \to 1 \) lorsque \( x\to 0 \). Cela donne \( \ln (e^x-1) = \ln (x \cdot \mu(x)) = \ln x + \ln \mu(x) \).
\begin{align*}
	x^{\frac{1}{\ln (e^x-1)}}
	& = \exp\left( \frac{1}{\ln (e^x-1)} \ln x \right)            \\
	& = \exp\left( \frac{1}{\ln x + \ln \mu(x)} \ln x \right)     \\
	& = \exp\left( \frac{1}{1 + \frac{\ln \mu(x)}{\ln x}} \right)
\end{align*}
Maintenant \( \mu(x) \to 1 \) donc \( \ln \mu(x) \to 0 \), et \( \ln x \to - \infty \) lorsque \( x \to 0 \). Donc \( \frac{\ln \mu(x)}{\ln x} \to 0 \). Cela donne
\[
\lim\limits_{x\rightarrow 0^{+}}x^{\frac{1}{\ln (e^x-1)}} = \lim\limits_{x\rightarrow 0^{+}} \exp\left( \frac{1}{1 + \frac{\ln \mu(x)}{\ln x}} \right) = \exp\left(1\right) = e.
\]
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \to \Rr \) continue telle que \( f(x+1) - f(x) \to a \in \overline\Rr \) lorsque \( x\to+\infty \).

	\begin{enumerate}
		\item Montrer que \( \frac{f(n)}n \to a \) lorsque \( n\to\infty \).

		\item Montrer que \( \frac{f(x)}x \to a \) lorsque \( x\to\infty \).
	\end{enumerate}

exercices.correction:
Pour \( x>0 \), \( (x^x)^x = e^{x\ln(x^x)} = e^{x^2\ln x} \) et \( x^{(x^x)} = e^{x^x\ln x} \). Par suite,

\[
\forall x>0,\;\frac{(x^x)^x}{x^{(x^x)}} = \text{exp}(\ln x(x^2-x^x)).
\]
Or, \( x^2-x^x = -x^x(1-x^{2-x}) = -e^{x\ln x}(1-e^{(2-x)\ln x}) \). Quand \( x \) tend vers \( +\infty \), \( (2-x)\ln x \) tend vers \( -\infty \). Donc, \( 1-e^{(2-x)\ln x} \) tend vers \( 1 \) puis \( x^2-x^x \) tend vers \( -\infty \). Mais alors, \( \ln x(x^2-x^x) \) tend vers \( -\infty \), puis \( \frac{(x^x)^x}{x^{(x^x)}} = \mbox{exp}(\ln x(x^2-x^x)) \) tend vers \( 0 \).

\begin{center}
\shadowbox{ \( \lim_{x\rightarrow +\infty}\frac{(x^x)^x}{x^{(x^x)}} = 0 \). }
\end{center}

Soit \( x\in\Rr \). Montrons par récurrence que : \( \forall n\in\Nn,\;|\sin(nx)|\le n|\sin x| \).
\begin{itemize}
\item[-] C'est clair pour \( n = 0 \).

\item[-] Soit \( n\ge0 \). Supposons que \( |\sin(nx)|\le n|\sin x| \). Alors,

\begin{align*}
	|\sin(n+1)x| & =|\sin nx\cos x+\cos nx\sin x|\le|\sin nx|.|\cos x|+|\cos nx|.|\sin x| \\
	& \le|\sin nx|+|\sin x|                                                  \\
	& \le n|\sin x|+|\sin x|\quad(\mbox{par hypothèse de récurrence})        \\
	& =(n+1)|\sin x|
\end{align*}

\end{itemize}

On a montré par récurrence que \shadowbox{\( \forall n\in\Nn,\forall x\in\Rr,\;|\sin(nx)|\le n|\sin x| \)}.

exercices.enonce:
Soit \( f \) une application de \( [0,1] \) dans \( \Rr \), continue sur \( [0,1] \) et vérifiant \( f(0) = f(1) \).
	\begin{enumerate}
		\item Soit \( n \) un entier naturel non nul et soit \( a = \frac{1}{n} \). Montrer que l'équation \( f(x+a) = f(x) \) admet au moins une solution.

		\item Montrer (en fournissant une fonction précise) que, si \( a \) est un réel de \( ]0,1[ \) qui n'est pas de la forme précédente, il est possible que l'équation \( f(x+a) = f(x) \) n'ait pas de solution.

		\item Application. Un cycliste parcourt 20 km en une heure.
		\begin{enumerate}
			\item Montrer qu'il existe au moins un intervalle de temps de durée d'une demi-heure pendant lequel il a parcouru 10 km.

			\item Montrer qu'il existe au moins un intervalle de temps de durée 3 min pendant lequel il a parcouru 1 km.

			\item Montrer qu'il n'existe pas nécessairement un intervalle de temps de durée 45 min pendant lequel il a parcouru 15 km.
		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Selon que \( n \equiv 0 \pmod 4, 1 \pmod 4, 2 \pmod 4 , 3\pmod 4 \) alors \( f^{(n)}(x) \) vaut respectivement \( \sin x \), \( \cos x \), \( -\sin x \), \( -\cos x \).

\item La dérivée de \( \sin^2 x \) est \( 2\sin x \cos x = \sin 2x \). Et donc les dérivées suivantes seront : \( 2\cos 2x, -4\sin 2x, -8\cos 2x, 16\sin 2x \),... Et selon que \( n \equiv 1 \pmod 4, 2 \pmod 4 , 3\pmod 4, 0 \pmod 4 \), alors \( g^{(n)}(x) \) vaut respectivement \( 2^{n-1}\sin 2x \), \( 2^{n-1}\cos 2x \), \( -2^{n-1}\sin 2x \), \( -2^{n-1}\cos 2x \).

\item \( \sin(x)^3+\cos(x)^3 = -\frac14\sin(3x)+\frac34\sin(x)+\frac14\cos(3x)+\frac34\cos(x) \) et on dérive...
\end{enumerate}

exercices.enonce:
Calculer les dérivées des fonctions :
	\begin{enumerate}
		\item \( x \mapsto \sqrt{1+x^2 \sin^2 x},\qquad x \mapsto \frac{\exp(1/x)+1} {\exp(1/x)-1} \).

		\item \( x \mapsto \log (\frac{1+\sin(x)} {1-\sin(x)}),\qquad x \mapsto (x(x-2))^{1/3} \).
	\end{enumerate}

Soit \( f \) une fonction dérivable sur \( \Rr \).
	\begin{enumerate}
		\item Calculer la dérivée de \( x\mapsto \hbox{sin} (f(x)^2) \) et de \( x \mapsto \hbox{sin} (f(x^2)) \).

		\item On suppose \( f(x)\not=0 \) pour tout \( x\in \Rr \). Calculer la dérivée de \( x\mapsto \hbox{log}(\vert f(x)\vert ) \).
	\end{enumerate}

Prolonger par continuité en \( 0 \) et étudier la dérivabilité de
	\begin{enumerate}
		\item \( f (x) = \sqrt{x} \ln x \).

		\item \( g (x) = \dfrac{e^x-1}{\sqrt x} \).
	\end{enumerate}

Soit \( f :  \Rr \rightarrow \Rr   \quad 
	\begin{cases}
		x \mapsto e^x \text{ si }x<0 \\
		x \mapsto ax^2 + bx + c \text{ sinon}
	\end{cases} \) 

	Déterminer \( a, b, c \) pour que \( f \) soit \( C^2 \) (et \( C^3 \) ?).

Étudier la continuité, la dérivabilité, la continuité de la dérivée pour les applications suivantes :
	\begin{enumerate}
		\item \( \displaystyle { f :x \mapsto \hbox{sin }(\frac{1}{x}) } \) si \( x\not= 0 \) et \( f(0) = 0 \).

		\item \( \displaystyle { g :x \mapsto x \hbox{sin }(\frac{1}{x}) } \) si \( x\not= 0 \) et \( g(0) = 0 \).

		\item \( \displaystyle { h :x \mapsto x^2 \hbox{sin }(\frac{1}{x}) } \) si \( x\not= 0 \) et \( h(0) = 0 \).
	\end{enumerate}

Soit \( f:\Rr_+\rightarrow \Rr_+^* \) une fonction bornée et deux fois dérivable et telle qu'il existe \( \alpha > 0 \) tel que, pour tout \( x\in \Rr_+ \), on ait \( \alpha f(x)\le f''(x) \).
	\begin{enumerate}
		\item
		\begin{enumerate}
			\item Montrer que \( f' \) a une limite en \( +\infty \). Quelle est la valeur de cette limite ?

			\item Montrer que \( f \) est décroissante et que \( \displaystyle{ \lim_{+\infty} f(x) = 0} \).
		\end{enumerate}

		\item
		\begin{enumerate}
			\item Soit \( g :x\mapsto \alpha f^2(x)-(f'(x))^2 \). Montrer que \( g \) est croissante et a pour limite \( 0 \) en \( \infty \).

			\item En posant \( f(x) = h(x)\exp (-\sqrt{\alpha}x) \), montrer que, pour tout \( x\in \Rr_+,\; f(x)\le f(0)\exp (-\sqrt{\alpha}x) \).
		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Par l'absurde on suppose qu'il y a (au moins) quatre racines distinctes pour \( P_n(X) = X^n+aX+b \). Notons les \( x_1 <x_2<x_3<x_4 \). Par le théorème de Rolle appliqué trois fois (entre \( x_1 \) et \( x_2 \), entre \( x_2 \) et \( x_3 \),...) il existe \( x'_1<x'_2<x'_3 \) des racines de \( P'_n \). On applique deux fois le théorème de Rolle entre \( x'_1 \) et \( x'_2 \) et entre \( x'_2 \) et \( x'_3 \). On obtient deux racines distinctes pour \( P''_n \). Or \( P''_n = n(n-1)X^{n-2} \) ne peut avoir que \( 0 \) comme racine. Donc nous avons obtenu une contradiction.

\item \emph{Autre méthode :}
Le résultat est évident si \( n\le 3 \). On suppose donc \( n\ge 3 \). Soit \( P_n \) l'application \( X\mapsto X^n+aX+b \) de \( \Rr \) dans lui-même. Alors \( P'_n(X) = nX^{n-1}+a \) s'annule en au plus deux valeurs. Donc \( P_n \) est successivement croissante-décroissante-croissante ou bien décroissante-croissante-décroissante. Et donc \( P_n \) s'annule au plus trois fois.
\end{enumerate}

exercices.enonce:
Appliquer la formule des accroissements finis à la fonction
	\[
	f(x) = a+bx+ce^{\alpha x}
	\]
	(où \( a,b,c,\alpha \) sont réels, et \( c \) et \( \alpha \) sont non nuls) sur l'intervalle \( [0,X] \).
	\begin{enumerate}
		\item Calculer ``\( \theta \)'' en fonction de \( X \).

		\item En déduire que
		\[
		x\mapsto \frac{1}{\alpha x}\ln \frac{e^{\alpha x}-1}{\alpha x}
		\]
		est bornée sur \( \Rr \).
	\end{enumerate}

exercices.indication:
\begin{enumerate}
\item Utiliser le théorème des accroissements finis avec la fonction \( t \mapsto \ln t \)

\item Montrer d'abord que \( f'' \) est négative. Se servir du théorème des valeurs intermédiaires pour \( f' \).
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( g(t) = \ln t \). Appliquons le théorème des accroissements finis sur \( [x,y] \). Il existe \( c \in ]x,y[ \), \( g(y)-g(x) = g'(c)(y-x) \). Soit \( \ln y - \ln x = \frac 1c (y-x) \). Donc \( \frac{\ln y - \ln x}{y-x} = \frac 1c \). Or \( x <c<y \) donc \( \frac 1y < \frac 1c < \frac 1x \). Ce qui donne les inégalités recherchées.

\item \( f'(\alpha) = \frac{x-y}{\alpha x + (1-\alpha)y} - \ln x + \ln y \). Et \( f''(\alpha) = -\frac{(x-y)^2}{(\alpha x + (1-\alpha)y)^2} \). Comme \( f'' \) est négative alors \( f' \) est décroissante sur \( [0,1] \). Or \( f'(0) = \frac{x-y - y(\ln x - \ln y)}{y} >0 \) d'après la première question et de même \( f'(1) < 0 \). Par le théorème des valeurs intermédiaires, il existe \( c \in [0,1] \) tel que \( f'(c) = 0 \). Maintenant \( f' \) est positive sur \( [0,c] \) et négative sur \( [c,1] \). Donc \( f \) est croissante sur \( [0,c] \) et décroissante sur \( [c,1] \). Or \( f(0) = 0 \) et \( f(1) = 0 \) donc pour tout \( x\in[0,1] \), \( f(x) \ge 0 \). Cela prouve l'inégalité demandée.

\item Géométriquement nous avons prouvé que la fonction \( \ln \) est concave, c'est‑à‑dire que la corde (le segment qui va de \( (x,\ln x) \) à \( (y,\ln y) \)) est sous la courbe d'équation \( y = \ln x \).
\end{enumerate}

Pour simplifier nous supposons \( x>0 \).
\begin{enumerate}
\item Appliquer le théorème des accroissements finis ne va pas être suffisant. En effet, soit \( f(x) = e^x-1-x \). Alors il existe \( c \in ]0,x[ \) tel que \( f(x)-f(0) = f'(c)(x-0) \). Alors \( e^x-1-x = (e^c-1)x \). Soit maintenant \( g(x) = e^x-1 \) alors, par le théorème des accroissements finis sur \( [0,c] \) il existe \( d \in ]0,c[ \) tel que \( g(c)-g(0) = g'(d)(c-0) \), soit \( e^c-1 = e^dc \). Donc \( e^x-1-x = f(x) = (e^c-1)x = e^dcx \). Comme \( d \le c \le x \), alors \( e^x-1-x \le e^xx^2 \).

Cela donne une inégalité, mais il manque un facteur \( 1/2 \).

\item Nous allons obtenir l'inégalité par application du théorème de Rolle. Soit maintenant \( f(t) = e^t-1-t-k\frac{t^2}{2} \). Nous avons \( f(0) = 0 \), \( x>0 \) étant fixé, nous choisissons \( k \) tel que \( f(x) = 0 \), (un tel \( k \) existe car \( e^x-1-x >0 \) et \( x^2>0 \)). Comme \( f(0) = 0 = f(x) \) alors par Rolle il existe \( c \in ]0,x[ \) tel que \( f'(c) = 0 \). Mais \( f'(t) = e^t-1-kt \), donc \( f'(0) = 0 \). Maintenant \( f'(0) = 0 = f'(c) \) donc il existe (par Rolle toujours !) \( d \in ]0,c[ \) tel que \( f''(d) = 0 \). Or \( f''(t) = e^t-k \), donc \( f''(d) = 0 \) donne \( k = e^d \). Ainsi \( f(x) = 0 \) devient \( e^x-1-x = e^d \frac{x^2}{2} \). Comme \( d\le x \) alors \( e^x-1-x \le e^x \frac{x^2}{2} \).
\end{enumerate}

exercices.enonce:
Pour \( n \) entier naturel non nul donné, on pose \( L_n = ((X^2-1)^n)^{(n)} \).
	\begin{enumerate}
		\item Déterminer le degré et le coefficient dominant de \( L_n \).

		\item En étudiant le polynôme \( A_n = (X^2-1)^n \), montrer que \( L_n \) admet \( n \) racines réelles simples et toutes dans \( ]-1;1[ \).
	\end{enumerate}

Soient \( f \) et \( g \) deux fonctions continues sur \( [a,b] \) et dérivables sur \( ]a,b[ \).

	Soit \( \begin{array}[t]{cccc}
		\Delta : & [a,b] & \rightarrow & \Rr    \\
		& x     & \mapsto     & \left|
		\begin{array}{ccc}
			f(a) & f(b) & f(x) \\
			g(a) & g(b) & g(x) \\
			1    & 1    & 1
		\end{array}
		\right|
	\end{array} \).

	\begin{enumerate}
		\item Montrer que \( \Delta \) est continue sur \( [a,b] \), dérivable sur \( ]a,b[ \) et calculer sa dérivée.

		\item En déduire qu'il existe \( c \) dans \( ]a,b[ \) tel que \( (g(b)-g(a))f'(c) = (f(b)-f(a))g'(c) \).
	\end{enumerate}

Soit \( f \) une fonction continue de \( [0,1] \) à valeurs dans \( \Rr \). Pour chaque \( n \in \Nn \), on note \( g_n \) la fonction \( \displaystyle{ x\mapsto f(x+\frac{1}{n})-f(x)} \).
	\begin{enumerate}
		\item On suppose \( g_n(x)>0 \) pour tout \( \displaystyle{ x\in [0,1-\frac{1}{n}[} \). Montrer que \( f(1)>f(0) \).

		\item On suppose désormais que \( f(0) = f(1) \). Montrer que, pour chaque \( n \in \Nn \), la fonction \( g_n \) s'annule en au moins un point de l'intervalle \( \displaystyle{ [0,1-\frac{1}{n}]} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Pour tout \( n \ge 2 \) on a : \( P_n(0) = -1 \) et \( P_n(1) = 3 \). Comme l'application \( X\mapsto P_n(X) \) est continue, elle s'annule en (au moins) un point de l'intervalle \( \rbrack 0, 1 \lbrack \). Comme par ailleurs, pour tout \( X \) positif, \( P'_n(X) = nX^{n-1}+(n-1)X^{n-2}+2X+1 \) est strictement positif, l'application \( X\mapsto P_n(X) \) est strictement croissante sur \( \Rr_+ \) et s'annule en au plus un point de \( \Rr_+ \). En conséquence \( P_n \) a une unique racine positive \( \lambda_n \) qui de plus satisfait l'inégalité \( 0<\lambda_n<1 \).

\item Pour tout \( X\in \rbrack 0, 1 \lbrack , P_n(X)-P_{n-1}(X) = X^n-X^{n-2}<0 \). En particulier \( P_n(\lambda_{n-1})<0 \) donc \( \lambda_n>\lambda_{n-1} \). La suite \( (\lambda_n)_{n\ge 3} \) est donc croissante et majorée (cf 1.) : elle est convergente.

\item Pour tout \( n \ge 3 \) on a : \( \lambda_n^n+\lambda_n^{n-1} = -\lambda_n^2-\lambda_n+1 \). Or \( \displaystyle{ P_n\Bigl( \frac{3}{4}\Bigr) >\Bigl( \frac{3}{4}\Bigr)^2+\frac{3}{4}-1>0} \) donc la suite \( (\lambda_n^n+\lambda_n^{n-1})_{n \ge 3} \) satisfait les inégalités \( 0<\lambda_n^n+\lambda_n^{n-1}<\displaystyle{ \Bigl(
	\frac{3}{4}\Bigr)^n+\Bigl(\frac{3}{4} \Bigr)^{n+1}} \) et converge vers \( 0 \). Il en va de même de la suite \( (-\lambda_n^2-\lambda_n+1)_{n\ge 2} \). En passant à la limite, on obtient l'égalité : \( \ell^2+\ell -1 = 0 \). La seule solution positive de cette équation étant \( \displaystyle{\frac{ -1+\sqrt{5} }{ 2}} \), on a l'égalité : \( \ell = \displaystyle{ \frac{ -1+\sqrt{5}}{ 2}} \).
	\end{enumerate}

	\bigskip
	\noindent \textbf{Remarques}
	\begin{enumerate}
\item L'inégalité \( 0<\lambda_n <1 \) (pour tout \( n\ge 2 \)) n'implique pas que \( (\lambda_n^n )_{n\ge 2} \) converge vers \( 0 \). Par exemple la suite \( (v_n)_{n \ge 1} \) définie par \( v_n = \displaystyle {(1 -\frac{1}{n})^n} \) converge vers \( \displaystyle{\frac{1}{e}} \).

\item La propriété \( \displaystyle{\lim_{n\rightarrow \infty} \frac{1}{n+k}\epsilon \Bigl( \frac{1}{n+k} \Bigr) } = 0 \) n'implique pas que \( \displaystyle{\lim_{n\rightarrow \infty} \sum_{\scriptstyle k = 0}^{\scriptstyle n}\frac{1}{n+k}\epsilon \Bigl( \frac{1}{n+k} \Bigr) } = 0 \). Par exemple... \( \displaystyle{\lim_{n\rightarrow \infty} \sum_{\scriptstyle k = 0}^{\scriptstyle n}\frac{1}{n+k}} = \hbox{log }(2) \).
\end{enumerate}

exercices.enonce:
Soit \( f \) une fonction d'un intervalle \( I \) à valeurs dans \( \Rr \) dérivable sur \( I \). Montrer que les propriétés suivantes sont équivalentes :
	\begin{enumerate}
		\item \( f \) est strictement croissante sur \( I \).

		\item \( f' \) est positive ou nulle sur \( I \) et \( \{ x\in I ; f'(x)>0\} \) est dense dans \( I \).
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f \) une application de \( \Rr \) dans \( \Rr \) dérivable en \( 0 \). Montrer qu'il existe une application \( \epsilon \) de \( \Rr \) dans lui-même telle que \( \forall x\in \Rr : f(x) = f(0)+ xf'(0)+x \epsilon (x) \) et \( \displaystyle{\lim_{x\rightarrow 0} \epsilon (x) = 0 } \). Donner une interprétation géométrique de ce résultat.

		\item En déduire les limites des suites \( (u_n)_{n \ge 1} \) et \( (v_n)_{n\ge 1} \) définies en posant, pour tout \( n \in \Nn^* \): \( \displaystyle{u_n = (n^3+1)^{\frac{1}{3}}-n} \) et \( \displaystyle{v_n = (1+\frac{\alpha}{n})^{\frac{1}{n}}} \).

		\item Construire un exemple de suite \( (w_n)_{n \ge 1} \) avec, \( w_n<1 \) pour tout \( n \ge 1 \) et telle que \( \displaystyle{ \lim_{n\rightarrow \infty }w_n = 1} \). (On pourra s'inspirer de l'exemple de \( (v_n)_{n\ge 1} \) ci-dessus.)
	\end{enumerate}

\begin{enumerate}
		\item Montrer que pour tout \( x>0 \) on a : \( \displaystyle{\frac{1}{x+1}<\hbox{log}(x+1) -\hbox{log}(x)<\frac{1}{x}} \).

		\item En déduire que pour tout entier \( n\ge 1 : \) \( \displaystyle {
			\hbox{log}(n+1)< 1+ \frac{1}{2}+\cdots +\frac{1}{n}<1+\hbox{log}(n)} \).

		\item Posons \( \displaystyle{u_n = 1+ \frac{1}{2}+\cdots +\frac{1}{n}-\hbox{log}(n)} \) Montrer que la suite \( (u_n)_{n \in \Nn} \) est décroissante et convergente.
	\end{enumerate}

Soit \( I \) un intervalle ouvert contenant \( 0 \) et \( 1 \) et \( f: I \rightarrow \Rr \) une fonction dérivable. On pose \( p = f(1)-f(0) \).

	\begin{enumerate}
		\item Soit \( g :[0,1]\rightarrow \Rr \) la fonction définie par \( g(0) = f'(0) \) et \( g(x) = \dfrac{f(x)-f(0)}{x} \) sinon. Montrer que si \( u \) est un réel compris entre \( f'(0) \) et \( p \) alors il existe \( a\in [0,1] \) tel que \( u = f'(a) \).

		\item Soit \( h :[0,1]\rightarrow \Rr \) la fonction définie par \( h(1) = f'(1) \) et \( h(x) = \dfrac{f(x)-f(1)}{x-1} \) sinon. Montrer que si \( v \) est un réel compris entre \( f'(1) \) et \( p \) alors il existe \( b\in [0,1] \) tel que \( v = f'(b) \).

		\item Soit \( w \) un réel compris entre \( f'(0) \) et \( f'(1) \). Montrer qu'il existe \( c\in [0,1] \) tel que \( w = f'(c) \).
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f : {\Rr^+} \to \Rr \) convexe et bornée. Montrer que \( f \) est décroissante.

		\item Soit \( f : \Rr \to \Rr \) convexe et bornée. Montrer que \( f \) est constante.

	\end{enumerate}

Soit \( f : \Rr \to \Rr \) deux fois dérivable telle que : \( f \ge 0 \), \( f' \ge 0 \), \( f'' \ge 0 \).

	\begin{enumerate}
		\item Étudier l'existence des limites (dans \( \overline\Rr\ \),) en \( +\infty \) de \( f(x) \), \( f'(x) \), \( \frac{f(x)}x \).

		\item Même question pour les limites en \( -\infty \) de \( f(x) \), \( f'(x) \), et \( xf'(x) \).

	\end{enumerate}

