		\[
		\forall\ x \in \Rr,\ \exists\ \theta_p \in {]-p,p[} \text{ tq }
		\Delta_h^pf(x) = f^{(p)}(x) + \frac{ph^2}{24} f^{(p+2)}\left( x + \frac{\theta_p h}{2}\right).
		\]
	\end{enumerate}

