	\begin{align*}
		\frac{1}{(x^2-1)^5} &= \frac{1}{32(x-1)^5} - \frac{5}{64(x-1)^4} + \frac{15}{128(x-1)^3} - \frac{35}{256(x-1)^2} + \frac{35}{256(x-1)} \\
		&\quad - \frac{35}{256(x+1)} - \frac{35}{256(x+1)^2} - \frac{15}{128(x+1)^3} - \frac{15}{64(x+1)^4} - \frac{1}{32(x+1)^5} \\
		\frac{(x^2+1)^2}{(x-1)^6} &= \frac{4}{(x-1)^6} + \frac{8}{(x-1)^5} + \frac{8}{(x-1)^4} + \frac{4}{(x-1)^3} + \frac{1}{(x-1)^2} \\
		\frac{x^3+x+1}{x^4(x-1)^3} &= -\frac{1}{x^4} - \frac{4}{x^3} - \frac{9}{x^2} - \frac{17}{x} + \frac{3}{(x-1)^3} - \frac{8}{(x-1)^2} + \frac{17}{x-1} \\
		\frac{(x^2-x+1)^2}{x^2(x-1)^2} &= 1 + \frac{1}{x^2} + \frac{1}{(x-1)^2} \\
		\frac{x^2}{(x^2-1)^2} &= \frac{1}{4(x-1)^2} + \frac{1}{4(x-1)} + \frac{1}{4(x+1)^2} + \frac{1}{4(x+1)}
	\end{align*}

	\bigskip

	\textbf{Du type \( x^2+1 \)}

	\begin{align*}
		\frac{x^2}{(x^2+1)^2} &= \frac{-1}{(x^2+1)^2} + \frac{1}{x^2+1} \\
		\frac{x}{(x^4-1)^2} &= \frac{1}{16(x-1)^2} - \frac{1}{8(x-1)} - \frac{1}{16(x+1)^2} - \frac{1}{8(x+1)} + \frac{x}{4(x^2+1)^2} + \frac{x}{4(x^2+1)} \\
		\frac{x}{(x-1)(x^2+1)^2} &= \frac{1}{4(x-1)} + \frac{1-x}{2(x^2+1)^2} - \frac{x+1}{4(x^2+1)} \\
		\frac{x^6}{(x^2+1)^2(x+1)^2} &= 1 + \frac{1}{4(x+1)^2} - \frac{1}{x+1} + \frac{x}{2(x^2+1)^2} - \frac{x+1/4}{x^2+1} \\
		\frac{x^6}{(x^2+1)(x-1)^3} &= x + 3 + \frac{x-1}{4(x^2+1)} + \frac{1}{2(x-1)^3} + \frac{5}{2(x-1)^2} + \frac{19}{4(x-1)}
	\end{align*}

	\bigskip

	\textbf{Du type \( x^2+x+1 \)}

	\begin{align*}
		\frac{x}{x^4+x^2+1} &= \frac{1}{2(x^2-x+1)} - \frac{1}{2(x^2+x+1)} \\
		\frac{x^4+1}{x^4+x^2+1} &= 1 + \frac{x}{2(x^2+x+1)} - \frac{x}{2(x^2-x+1)} \\
		\frac{x^4+1}{x^2(x^2+x+1)^2} &= \frac{1}{x^2} - \frac{2}{x} - \frac{1}{(x^2+x+1)^2} + \frac{2x+2}{x^2+x+1} \\
		\frac{3x^5-5x^4+4x^2-11x+1}{(x^2+x+1)^6} &= -\frac{23x+6}{(x^2+x+1)^6} + \frac{13x+18}{(x^2+x+1)^5} + \frac{3x-11}{(x^2+x+1)^4}
	\end{align*}

	\bigskip

	\textbf{Autres éléments de 2ème espèce}

	\begin{align*}
		\frac{x^8}{x^6-1} &= x^2 + \frac{1}{6} \left( \frac{1}{x-1} - \frac{1}{x+1} + \frac{2x+1}{x^2+x+1} - \frac{2x-1}{x^2-x+1} \right) \\
		\frac{1}{x^4+1} &= \frac{1}{2\sqrt{2}} \left( \frac{x+\sqrt{2}}{x^2+x\sqrt{2}+1} - \frac{x-\sqrt{2}}{x^2-x\sqrt{2}+1} \right) \\
		\frac{x}{x^4+1} &= \frac{1}{2\sqrt{2}} \left( \frac{1}{x^2-x\sqrt{2}+1} - \frac{1}{x^2+x\sqrt{2}+1} \right) \\
		\frac{1}{x^5+1} &= \frac{1}{5(x+1)} - \frac{1}{5} \left( \frac{\omega x-2}{x^2-\omega x+1} + \frac{\omega'x-2}{x^2-\omega'x+1} \right),\quad \omega = \frac{1+\sqrt{5}}{2} ,\omega' = \frac{1-\sqrt{5}}{2}
	\end{align*}

	\bigskip

	\textbf{Racines de l'unité}

	\begin{align*}
		\frac{x^n+1}{x^n-1} &= 1 + 2\sum_{k=0}^{n-1} \frac{\omega^k}{n(x-\omega^k)} ,\quad \omega = e^{2i\pi/n} \\
		\frac{1}{x^n-1} &= \sum_{\substack{k=1 \\ 2k \ne n}}^{n-1} \frac{2x\cos\alpha_k-2}{n(x^2-2x\cos\alpha_k+1)} + \frac{1}{n(x-1)} 
		\begin{cases} 
			- \frac{1}{n(x+1)} & \text{si } n \text{ est pair} \\
			0 & \text{sinon}
		\end{cases}, \quad \alpha_k = \frac{2k\pi}{n} \\
		\sum_{k=0}^{n-1} \frac{1}{x-\omega^k} &= \frac{nx^{n-1}}{x^n-1} ,\quad \omega = e^{2i\pi/n} \\
		\sum_{k=0}^{n-1} \frac{1}{(x-\omega^k)^2} &= \frac{nx^{2n-2}+n(n-1)x^{n-2}}{(x^n-1)^2} ,\quad \omega = e^{2i\pi/n} \quad (\text{dérivée})
	\end{align*}

	\bigskip

	\textbf{Polynômes de Tchebychev}

	\begin{align*}
		\frac{1}{\cos(n\arccos x)} &= \frac{1}{n} \sum_{k=0}^{n-1} \frac{(-1)^k\sin\beta_k}{x-\cos\beta_k} ,\quad \beta_k = \frac{(2k+1)\pi}{2n} \\
		\tan(n\arctan x) &= \frac{1}{n} \sum_{\substack{k=0 \\ 2k\ne n-1}}^{n-1} \frac{1}{\cos^2\beta_k(\tan\beta_k-x)} 
		+ \begin{cases} 
			\frac{x}{n} & \text{si } n \text{ est impair} \\
			0 & \text{sinon}
		\end{cases},\quad \beta_k = \frac{(2k+1)\pi}{2n}
	\end{align*}

	\bigskip

	\textbf{Divers}

	\begin{align*}
		\frac{x^{2n}}{(x^2+1)^n} &= \sum_{k=0}^n \frac{(-1)^k\binom{n}{k}}{(x^2+1)^k} \\
		\frac{1}{(x^2-1)^n} &= \sum_{k=0}^{n-1} \frac{\Gamma_n^k}{2^{n+k}} \left( \frac{(-1)^k}{(x-1)^{n-k}} + \frac{(-1)^n}{(x+1)^{n-k}} \right) \\
		\frac{1}{(x^2+1)^n} &= \sum_{k=0}^{n-1} \frac{(-1)^n\Gamma_n^k}{2^{n+k}} \left( \frac{i^{k+n}}{(x-i)^{n-k}} + \frac{(-i)^{k+n}}{(x+i)^{n-k}} \right) \\
		\frac{n!}{(x+1)(x+2)\dots(x+n)} &= \sum_{k=1}^n \frac{(-1)^{k-1}k\binom{n}{k}}{x+k} \\
		\frac{x^2}{x^4-2x^2\cos\alpha+1} &= \frac{1}{4\cos(\alpha/2)} \left(\frac{x}{x^2-2x\cos(\alpha/2)+1} - \frac{x}{x^2+2x\cos(\alpha/2)+1} \right), \quad \alpha\not\equiv 0 \pmod{\pi}
	\end{align*}

