exercices.correction:
Soit \( u = (x,y,z,t) = xe_1+ye_2+ze_3+te_4\in\Rr^4 \). Alors,

\begin{align*}
f(u) & =xf(e_1)+yf(e_2)+zf(e_3)+tf(e_4)=x(2e_1+e_3)+y(-e_2+e_4)+z(e_1+2e_3)+t(e_2-e_4) \\
& =(2x+z)e_1+(-y+t)e_2+(x+2z)e_3+(y-t)e_4.
\end{align*}
Par suite,

\[
u\in\mbox{Ker }f\Leftrightarrow
\left\{
\begin{array}{l}
2x+z = 0 \\
-y+t = 0 \\
x+2z = 0 \\
y-t = 0
\end{array}
\right.\Leftrightarrow
\left\{
\begin{array}{l}
x = z = 0 \\
y = t
\end{array}
\right..
\]
Donc, \( \mbox{Ker }f = \{(0,y,0,y),\;y\in\Rr\} = \mbox{Vect}((0,1,0,1)) \).

\begin{center}
\shadowbox{ \( \mbox{Ker }f = \mbox{Vect}((0,1,0,1)) \). }
\end{center}

Soit \( u' = (x',y',z',t')\in\Rr^4 \).

\begin{align*}
u'= (x',y',z',t')\in\mbox{Im }f & \Leftrightarrow\exists(x,y,z,t)\in\Rr^4/\;\left\{
\begin{array}{l}
	2x+z=x' \\
	-y+t=y' \\
	x+2z=z' \\
	y-t=t'
\end{array}
\right.\Leftrightarrow\exists(x,y,z,t)\in\Rr^4/\;\left\{
\begin{array}{l}
	x=\frac{1}{3}(2x'-z')  \\
	z=\frac{1}{3}(-x'+2z') \\
	t=y+y'                 \\
	y'+t'=0
\end{array}
\right.                                                                             \\
& \Leftrightarrow y'=-t'
\end{align*}
(si \( y'\neq-t' \), le système ci-dessus, d'inconnues \( x \), \( y \), \( z \) et \( t \), n'a pas de solution et si \( y' = -t' \), le système ci-dessus admet au moins une solution comme par exemple \( (x,y,z,t) = \left(\frac{1}{3}(2x'-z'),0,\frac{1}{3}(-x'+2z'),y')\right) \). Donc, \( \mbox{Im }f = \{(x,y,z,t)\in\Rr^4/\;y+t = 0\} = \{(x,y,z,-y)/(x,y,z)\in\Rr^3\} = \{xe_1+y(e_2-e_4)+ze_3,\;(x,y,z)\in\Rr^4\} = \mbox{Vect}(e_1,e_2-e_4,e_3) \).

\begin{center}
\shadowbox{ \( \mbox{Im }f==\{(x,y,z,-y)/(x,y,z)\in\Rr^3\} = \mbox{Vect}(e_1,e_2-e_4,e_3) \). }
\end{center}

\textbf{Autre solution} pour la détermination de \( \mbox{Im }f \). \( \mbox{Im }f = \mbox{Vect}(f(e_1),f(e_2),f(e_3),f(e_4)) = \mbox{Vect}(2e_1+e_3,-e_2+e_4,e_1+2e_3,e_2-e_4) = \mbox{Vect}(2e_1+e_3,e_1+2e_3,e_2-e_4) \). Mais d'autre part, d'après le théorème du rang, \( \mbox{dim }(\mbox{Im }f) = 4-1 = 3 \). Donc, \( (2e_1+e_3,e_1+2e_3,e_2-e_4) \) est une base de \( \mbox{Im }f \).

Par définition, \( \mbox{rg }(u+v) = \mbox{dim }\left(\mbox{Im }(u+v)\right) \).

\begin{center}
\( \mbox{Im }(u+v) = \{u(x)+v(x),\;x\in E\}\subset\{u(x)+v(y),\;(x,y)\in E^2\} = \mbox{Im }u+\mbox{Im }v \).
\end{center}
Donc,

\begin{align*}
rg(u+v) & =\mbox{dim }\left(\mbox{Im }(u+v)\right)                                                                                          \\
& \le\mbox{dim }(\mbox{Im }u+\mbox{Im }v)=\mbox{dim }(\mbox{Im }u)+\mbox{dim }(\mbox{Im }v)-\mbox{dim }(\mbox{Im }u\cap\mbox{ Im}v) \\
& \le\mbox{dim }(\mbox{Im }u)+\mbox{dim }(\mbox{Im }v)=\mbox{rg }u+\mbox{rg }v.
\end{align*}
On a montré que :

\begin{center}
\shadowbox{ \( \forall(u,v)\in(\mathcal{L}(E,F))^2,\;\mbox{rg }(u+v)\le\mbox{rg }u+\mbox{rg }v \). }
\end{center}
Ensuite,
\[
\mbox{rg }u = \mbox{rg }(u+v-v)\le\mbox{rg }(u+v)+\mbox{rg }(-v) = \mbox{rg }(u+v)+\mbox{rg }v,
\]
(il est clair que \( \mbox{Im }(-v) = \mbox{Im }v) \) et donc \( \mbox{rg }u-\mbox{rg }v\le\mbox{rg }(u+v) \). En échangeant les rôles de \( u \) et \( v \), on a aussi \( \mbox{rg }v-\mbox{rg }u = \mbox{rg }(u+v) \) et finalement

\begin{center}
\shadowbox{ \( \forall(u,v)\in(\mathcal{L}(E,F))^2,\;|\mbox{rg }u-\mbox{rg }v|\le\mbox{rg }(u+v) \). }
\end{center}

exercices.enonce:
Soient \( \Kk \) un sous-corps de \( \Cc \) et \( E \) un \( \Kk \)-espace vectoriel de dimension finie \( n \).
	\begin{enumerate}
		\item Montrer que, pour tout endomorphisme \( f \) de \( \Rr^2 \), on a :

		\begin{center}
			\( (\mbox{Ker}f = \mbox{Im}f)\Leftrightarrow(f^2 = 0\;\mbox{et}\;n = 2\;\mbox{rg} f)\Leftrightarrow(f^2 = 0\;\mbox{et}\;
			\exists g\in\mathcal{L}(E)/\;f\circ g+g\circ f = Id_E) \).
		\end{center}

		\item On suppose \( \mbox{Ker}f = \mbox{Im}f \). Montrer qu'il existe une base \( (u_1,...,u_p,v_1,...,v_p) \) de \( E \) telle que :

		\begin{center}
			\( \forall i\in\{1,...,p\},\;f(u_i) = 0\;\mbox{et}\;f(v_i) = u_i \).
		\end{center}
	\end{enumerate}

\label{exo:suprou10}
	Soient \( \Kk \) un sous-corps de \( \Cc \), \( E \) un \( \Kk \)-espace vectoriel de dimension finie \( n \) et \( f \) un endomorphisme de \( E \) non injectif. Pour \( k \) entier naturel donné, on pose \( N_k = \mbox{Ker}f^k \) et \( I_k = \mbox{Im}f^k \) (avec la convention \( f^0 = Id_E \)).
	\begin{enumerate}
		\item Montrer que : \( \forall k\in\Nn,\;(N_k\subset N_{k+1}\;\mbox{et}\;I_{k+1}\subset I_k) \).

		\item
		\begin{enumerate}
			\item Montrer que : \( (\forall k\in\Nn,\;(N_k = N_{k+1}\Rightarrow N_{k+1} = N_{k+2}) \).

			\item Montrer que : \( \exists p\in\Nn/\;\forall k\in\Nn,\;(k<p\Rightarrow N_k\neq N_{k+1}\;\mbox{et}\;k\ge p\Rightarrow N_k = N_{k+1}) \).

			\item Montrer que \( p\le n \).
		\end{enumerate}

		\item Montrer que si \( k<p \), \( I_k \neq I_{k+1} \) et si \( k\ge p \), \( I_k = I_{k+1} \).

		\item Montrer que \( E = I_p\oplus N_p \) et que \( f \) induit un automorphisme de \( I_p \).

		\item Soit \( d_k = \mbox{dim}I_k \). Montrer que la suite \( (d_k-d_{k+1})_{k\in\Nn} \) est décroissante (en d'autres termes la suite des images itérées \( I_k \) décroît de moins en moins vite).
	\end{enumerate}

Soient \( E \) un espace vectoriel non nul de dimension finie et \( f \) un endomorphisme de \( E \).

	Montrer que :
	\begin{enumerate}
		\item \( (f\;\text{non injective})\Leftrightarrow(f = 0\;\text{ou}\;f\;\text{diviseur de zéro à gauche}) \).

		\item \( (f\;\text{non surjective})\Leftrightarrow(f = 0\;\text{ou}\;f\;\text{diviseur de zéro à droite}) \).
	\end{enumerate}

Soient \( E \) un espace vectoriel et \( f \) un endomorphisme de \( E \). Pour \( k\in\Nn \), on pose \( N_k = \text{Ker}(f^k) \) et \( I_k = \text{Im}(f^k) \) puis \( N = \displaystyle\bigcup_{k\in\Nn}N_k \) et \( I = \displaystyle\bigcap_{k\in\Nn}I_k \). (\( N \) est le nilespace de \( f \) et \( I \) le c\oe ur de \( f \))

	\begin{enumerate}
		\item

		\begin{enumerate}
			\item Montrer que les suites \( (N_k)_{k\in\Nn} \) et \( (I_k)_{k\in\Nn} \) sont respectivement croissante et décroissante pour l'inclusion.

			\item Montrer que \( N \) et \( I \) sont stables par \( f \).

			\item Montrer que \( \forall k\in\Nn \), \( (N_k = N_{k+1})\Rightarrow(N_{k+1} = N_{k+2}) \).
		\end{enumerate}

		\item On suppose de plus que \( \text{dim}E = n \) entier naturel non nul.
		\begin{enumerate}
			\item Soit \( A = \{k\in\Nn/\;N_k = N_{k+1}\} \) et \( B = \{k\in\Nn/\;I_k = I_{k+1}\} \). Montrer qu'il existe un entier \( p\le n \) tel que \( A = B = \{k\in\Nn/\;k\ge p\} \).

			\item Montrer que \( E = N_p\oplus I_p \).

			\item Montrer que \( f_{/N} \) est nilpotent et que \( f_{/I}\in GL(I) \).
		\end{enumerate}

		\item Trouver des exemples où
		\begin{enumerate}
			\item \( A \) est vide et \( B \) est non vide,

			\item \( A \) est non vide et \( B \) est vide,

			\item (****) \( A \) et \( B \) sont vides.
		\end{enumerate}

		\item Pour \( k\in\Nn \), on pose \( d_k = \text{dim}(I_k) \). Montrer que la suite \( (d_k-d_{k+1})_{k\in\Nn} \) est décroissante.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item
\begin{enumerate}
	\item Soient \( k\in\Nn \) et \( x\in E \). \( x\in N_k\Rightarrow f^k(x) = 0\Rightarrow f(f^k(x)) = 0\Rightarrow x\in N_{k+1} \).

	\begin{center}
		\shadowbox{ \( \forall k\in\Nn \), \( N_k\subset N_{k+1} \). }
	\end{center}

	Soient \( k\in\Nn \) et \( y\in I_{k+1}\Rightarrow\exists x\in E/\;y = f^{k+1}(x)\Rightarrow\exists x\in E/\;y = f^k(f(x))\Rightarrow y\in I_k \).

	\begin{center}
		\shadowbox{ \( \forall k\in\Nn \), \( I_{k+1}\subset I_k \). }
	\end{center}

	\item Soit \( x\in N \). Il existe un entier \( k \) tel que \( x \) est dans \( N_k \) ou encore tel que \( f^k(x) = 0 \). Mais alors \( f^k(f(x)) = f(f^k(x)) = 0 \) et \( f(x) \) est dans \( N_k \) et donc dans \( N \). Ainsi, \( N \) est stable par \( f \).

	Soit \( y\in I \). Alors, pour tout naturel \( k \), il existe \( x_k\in E \) tel que \( y = f^k(x_k) \). Mais alors, pour tout entier \( k \), \( f(y) = f(f^k(x_k)) = f^k(f(x)) \) est dans \( I_k \), et donc \( f(y) \) est dans \( I \). \( I \) est stable par \( f \).

	\item Si \( N_k = N_{k+1} \), on a déjà \( N_{k+1}\subset N_{k+2} \). Montrons que \( N_{k+2}\subset N_{k+1} \).

	Soit \( x\in N_{k+2} \). Alors \( f^{k+1}(f(x)) = 0 \) et donc \( f(x)\in N_{k+1} = N_k \). Donc, \( f^k(f(x)) = 0 \) ou encore \( x \) est dans \( N_{k+1} \). On a montré que

	\begin{center}
		\shadowbox{ \( \forall k\in\Nn \), \( [(N_k = N_{k+1})\Rightarrow (N_{k+1} = N_{k+2})] \). }
	\end{center}
\end{enumerate}

\item
\begin{enumerate}
	\item Notons tout d'abord que, pour tout entier naturel \( k \), \( N_k\subset N_{k+1} \) et \( I_{k+1}\subset I_k \). Si de plus, on est en dimension finie, alors d'après le théorème du rang,

	\begin{center}
		\( N_k = N_{k+1}\Leftrightarrow I_{k+1} = I_k\Leftrightarrow\text{dim}N_k = \text{dim}N_{k+1} \).
	\end{center}

	Donc \( A = B \) (éventuellement \(  = \varnothing \)).

	La suite des noyaux itérés ne peut être strictement croissante pour l'inclusion car alors la suite des dimensions de ces noyaux serait une suite strictement croissante d'entiers naturels, vérifiant par une récurrence facile \( \text{dim}N_k\ge k \) pour tout naturel \( k \), et en particulier \( \text{dim}N_{n+1} >\text{dim}E \) ce qui est exclu.

	Donc il existe un entier \( k \) tel que \( N_k = N_{k+1} \). Soit \( p \) le plus petit de ces entiers \( k \).

	Par définition de \( p \), \( N_k \) est strictement inclus dans \( N_{k+1} \) pour \( k<p \), puis \( N_p = N_{p+1} \) et d'après 1)c) pour tout entier naturel \( k \) supérieur ou égal à \( p \) on a \( N_k = N_p \) (par récurrence sur \( k\ge p \)). Donc \( A = \{p,p+1,p+2,...\} \).

	Enfin, \( \text{dim}(N_0)<\text{dim}(N_1)<...<\text{dim}(N_p) \) et donc \( \text{dim}(N_p)\ge p \) ce qui impose \( p\le n \).

	\item On a déjà \( \text{dim}N_p +\text{dim}I_p = \text{dim}E \). Il reste à vérifier que \( I_p\cap N_p = \{0\} \).

	Soit \( x \) un élément de \( I_p\cap N_p \). Donc \( f^p(x) = 0 \) et il existe \( y\in E \) tel que \( x = f^p(y) \). Mais alors \( f^{2p}(y) = 0 \) et \( y \) est dans \( N_{2p} = N_p \) (car \( 2p\ge p \)) ou encore \( x = f^p(y) = 0 \).

	\begin{center}
		\shadowbox{ \( E = I_p\oplus N_p \). }
	\end{center}

	\item Ici \( N = N_p = \text{Ker}f^p \) et \( I = I_p = \text{Im}f^p \).

	Soit \( f' = f_{/N} \). D'après 1)b), \( f' \) est un endomorphisme de \( N \) puis immédiatement \( f'^p = 0 \). Donc \( f_{/N} \) est nilpotent.

	Soit \( f'' = f_{/I} \) . \( f'' \) est d'après 1)b) un endomorphisme de \( I \). Pour montrer que \( f'' \) est un automorphisme de \( I \), il suffit de vérifier que \( \text{Ker}f'' = \{0\} \). Mais \( \text{Ker}f''\subset\text{Ker}f\subset N \) et aussi \( \text{Ker}f''\subset I \). Donc \( \text{Ker}f''\subset N\cap I = \{0\} \). Donc \( f_{/I}\in\mathcal{GL}(I) \).
\end{enumerate}

\item Il faut bien sûr chercher les exemples en dimension infinie.

\begin{enumerate}
	\item Soit \( f \) de \( \Rr[X] \) dans lui-même qui à un polynôme \( P \) associe sa dérivée \( P' \). On vérifie aisément que \( \forall k \in\Nn \), \( N_k = \Rr_k[X] \) et donc la suite des noyaux itérés est strictement croissante. La suite des \( I_k \) est par contre constante : \( \forall k\in\Nn \), \( I_k = \Rr[X] \). Dans ce cas, \( A \) est vide et \( B = \Nn \).

	\item A un polynôme \( P \), on associe le polynôme \( XP \). Les \( N_k \) sont tous nuls et pour \( k\in\Nn \) donné, \( I_k \) est constitué des polynômes de valuation supérieure ou égale à \( k \) ou encore \( I_k = X^k\Rr[X] \). Dans ce cas, \( A = \Nn \) et \( B = \varnothing \).

	\item Soit \( f \) l'endomorphisme de \( \Rr[X] \) qui à Xn associe Xn+1 si \( n \) n'est pas une puissance de \( 2 \) et \( 0 \) si \( n \) est une puissance de \( 2 \) (\( f(1) = X \), \( f(X) = 0 \), \( f(X^2) = 0 \), \( f(X^3) = X^4 \), \( f(X^4) = 0 \), ...)

	Soit \( k \) un entier naturel.

	\begin{center}
		\( f^{2^k-1}(X^{2^k+1}) = X^{2^k+1+2^k-1} = X^{2^{k+1}}\neq0 \) et \( f^{2^k}(X^{2^k+1}) = f(X^{2^{k+1}}) = 0 \).
	\end{center}

	Donc, pour tout entier naturel \( k \), \( N_{2^k-1} \) est strictement inclus dans \( N_k \). \( A \) est vide.

	Ensuite, \( X^{2^{k+1}}\in I_{2^k-1} \) mais \( X^{2^{k+1}}\notin I_{2^k} \). En effet, si \( l\ge 2^{k+1} +1 \), \( f^{2^k}(X^l) \) est ou bien nul ou bien de degré supérieur ou égal à \( 2^k+2^{k+1}+1>2^{k+1} \) et si \( l\le 2^{k+1} \), \( f^{2^k}(X^l) = 0 \) car entre \( l \) et \( 2^k+l-1 \), il y a une puissance de \( 2 \) (il y a \( 2^k \) nombres entre \( l \) et \( 2^k+l-1 \), ensuite \( 2^k+l-1 < 2^k+2^{k+1} = 3\times2^k <2^{k+2} \) et enfin l'écart entre deux puissances de \( 2 \) inférieures à \( 2^{k+1} \) vaut au maximum \( 2^{k+1}-2^k = 2^k \)) . Donc, \( I_{2^k} \) contient le polynôme nul ou des polynômes de degré strictement supérieur à \( 2^{k+1} \) et ne contient donc pas \( X^{2^{k+1}} \). Finalement, pour tout entier naturel \( k \), \( I_{2^k} \) est strictement inclus dans \( I_{2^k-1} \) et \( B \) est vide.

\end{enumerate}

\item Pour \( k \) entier naturel donné, on note \( f_k \) la restriction de \( f \) à \( I_k \). D'après le théorème du rang, on a

\begin{center}
	\( \text{dim}I_k = \text{dim}\text{Ker}f_k+\text{dim}\text{Im}f_k \) avec \( \text{Im}f_k = f(I_k) = I_{k+1} \).
\end{center}

Donc, pour tout entier naturel \( k \), \( d_k -d_{k+1} = \text{dim}\text{Ker}f_k \).

Or, pour tout entier naturel \( k \), \( \text{Ker}f_{k+1} = \text{Ker}f\cap I_{k+1}\subset\text{Ker}f\cap I_k = \text{Ker}f_k \) et donc \( d_{k+1}-d_{k+2} = \text{dim}\text{Ker}f_{k+1}\le\text{dim}\text{Ker}f_k = d_k-d_{k+1} \).

Finalement, pour tout entier naturel \( k \), \( d_{k+1}-d_{k+2}\le d_k-d_{k+1} \) et la suite des images itérées décroît de moins en moins vite.
\end{enumerate}

exercices.enonce:
Soient \( E \) et \( F \) deux \( \Kk \)-espaces vectoriels et \( f \) une application linéaire de \( E \) vers \( F \).

	\begin{enumerate}
		\item Montrer que \( \left[\left(\forall g\in\mathcal{L}(F,E),\;f\circ g\circ f = 0\Rightarrow g = 0\right)\Rightarrow f\;\text{bijective}\right] \).

		\item On pose \( \text{dim}E = p \), \( \text{dim}F = n \) et \( \text{rg}f = r \). Calculer la dimension de \( \{g\in\mathcal{L}(F,E)/\;f\circ g\circ f = 0\} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Si \( N = \text{Ker}f\neq\{0\} \), considérons \( g \) non nul tel que \( \text{Im}g\neq\{0\} \) et \( \text{Im}g\subset\text{Ker}f \).

Pour un tel \( g \), \( f\circ g = 0 \) puis \( f\circ g\circ f = 0 \) et donc \( g = 0 \) par hypothèse, contredisant \( g \) non nulle. Donc \( \text{Ker}f = \{0\} \).

Si \( \text{Im}f\neq F \), on choisit \( g \) nulle sur \( \text{Im}f \) et non nulle sur un supplémentaire de \( \text{Im}f \) (dont l'existence est admise en dimension infinie). Alors, \( g\circ f = 0 \) puis \( f\circ g\circ f = 0 \) et donc \( g = 0 \) contredisant \( g \) non nulle. Donc \( \text{Im}f = F \).

Finalement, \( f \) est bien un isomorphisme de \( E \) sur \( F \).

\item Soit \( A = \{g\in\mathcal{L}(F,E)/\;f\circ g\circ f = 0\} \). Tout d'abord \( A \) est bien un sous-espace vectoriel de \( \mathcal{L}(F,E) \) car contient l'application nulle et est stable par combinaison linéaire (ou bien \( A \) est le noyau de l'application linéaire de \( \mathcal{L}(F,E) \) dans \( \mathcal{L}(E,F) \) qui à \( g \) associe \( f\circ g\circ f \)).

Soit \( J \) un supplémentaire de \( I = \text{Im}f \) dans \( F \). Un élément \( g \) de \( \mathcal{L}(F,E) \) est entièrement déterminé par ses restrictions à \( I \) et \( J \).

\begin{center}
	\( f\circ g\circ f = 0\Leftrightarrow(f\circ g)_{/I} = 0\;\text{et}\;g_{/J}\;\text{est quelconque}\Leftrightarrow g(I)\subset N \).
\end{center}

Pour être le plus méticuleux possible, on peut alors considérer l'application \( G \) de \( \mathcal{L}(I,N)\times\mathcal{L}(J,E) \) dans \( \mathcal{L}(F,E) \) qui à un couple \( (g_1,g_2) \) associe l'unique application linéaire \( g \) de \( F \) dans \( E \) telle que \( g_{/I} = g_1 \) et \( g_{/J} = g_2 \). \( G \) est linéaire et injective d'image \( A \). Donc

\begin{center}
	\( \text{dim}A = \text{dim}\mathcal{L}(I,N)\times\text{dim}\mathcal{L}(J,E) = \text{dim}\mathcal{L}(I,N) + \text{dim}\mathcal{L}(J,E) = r(p - r) + (n - r)p = pn - r^2 \).
\end{center}
\end{enumerate}

exercices.enonce:
Soit \( E = \Kk_n[X] \). \( u \) est l'endomorphisme de \( E \) défini par : \( \forall P\in E,\; u(P) = P(X+1)-P(X) \).

	\begin{enumerate}
		\item Déterminer \( \text{Ker}u \) et \( \text{Im}u \).

		\item Déterminer explicitement une base dans laquelle la matrice de \( u \) est \( \left(
		\begin{array}{ccccc}
			0      & 1      & 0      & \ldots & 0      \\
			\vdots & \ddots & \ddots & \ddots & \vdots \\
			&        &        & \ddots & 0      \\
			\vdots &        &        & \ddots & 1      \\
			0      & \ldots &        & \ldots & 0
		\end{array}
		\right) \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( u \) est dans L(E) car \( u \) est linéaire et si \( P \) est un polynôme de degré au plus \( n \) alors \( u(P) \) est un polynôme de degré au plus \( n \).

\textbullet Les polynômes constants sont dans \( \text{Ker}u \). Réciproquement , soit \( P \)un élément de \( \text{Ker}u \) puis \( Q = P - P(0) \).

Par hypothèse, \( P(0) = P(1) = P(2) = . \).. et donc \( 0 \), \( 1 \), \( 2 \), ... sont des racines de \( Q \). Puisque le polynôme \( Q \) admet une infinité de racines, \( Q \) est nul et donc \( P = P(0) \) et \( P\in\Kk_0[X] \). Ainsi, \( \text{Ker}u = \Kk_0[X] \).

\textbullet Mais alors, d'après le théorème du rang, \( \text{rg}u = (n+1)-1 = n \). D'autre part, si \( P \) est dans \( \Kk_n[X] \), \( P(X+1)-P \) est dans \( \Kk_{n-1}[X] \) (si on pose \( P = a_nX^n+\ldots \), le coefficient de \( X^n \) dans \( u(P) \) est \( a_n-a_n = 0 \)).

En résumé, \( \text{Im}u\subset\Kk_{n-1}[X] \) et \( \text{dim}\text{Im}u = \text{dim}\Kk_{n-1}[X]<+\infty \) et donc \( \text{Im}u = \Rr_{n-1}[X] \).

\begin{center}
	\shadowbox{ \( \text{Ker}u = \Kk_0[X] \) et \( \text{Im}u = \Kk_{n-1}[X] \). }
\end{center}

\item On part de \( P_0 = 1 \) et aussi de \( P_1 = X \) qui vérifient bien \( u(P_0) = 0 \) et \( u(P_1) = P_0 \).

Trouvons \( P_2 = aX^2 + bX \) tel que \( u(P_2) = P_1 \) (il est clair que si \( \text{deg}(P)\ge1 \), \( \text{deg}(u(P)) = \text{deg}(P)-1 \) et d'autre part, les constantes sont inutiles car \( \text{Ker}u = \Kk_0[X] \)).

\begin{center}
	\( u(P_2) = P_1\Leftrightarrow a(X+1)^2 +b(X+1) - aX^2 - bX = X\Leftrightarrow (2a-1)X +a+b = 0\Leftrightarrow a = \frac{1}{2}\;\text{et}\;b = -a \).
\end{center}

On prend \( P_2 = \frac{1}{2}(X^2-X) = \frac{1}{2}X(X-1) \).

Trouvons \( P_3 = aX^3 + bX^2+cX \) tel que \( u(P_3) = P_2 \).

\begin{align*}\ensuremath u(P_3) =P_2 & \Leftrightarrow a(X+1)^3 +b(X+1)^2+c(X+1) - aX^3 - bX^2-cX =\frac{1}{2}X^2-\frac{1}{2}X \\
	& \Leftrightarrow \left(3a-\frac{1}{2}\right)X^2+\left(3a+2b-\frac{1}{2}\right)X+a+b+c=0  \\
	& \Leftrightarrow a =\frac{1}{6}\;\text{et}\;b =-\frac{1}{2}\;\text{et}\;c=\frac{1}{3}.
\end{align*}

On prend \( P_3 = \frac{1}{6}(X^3-3X^2+2X) = \frac{1}{6}X(X-1)(X-2) \).

Essayons, pour \( 1\le k\le n \), \( P_k = \frac{1}{k!}\prod_{i = 0}^{k-1}(X-i) \). Pour \( 1\le k\le n-1 \),

\begin{align*}\ensuremath u(P_{k+1}) & =\frac{1}{(k+1)!}\prod_{i=0}^k(X+1-i)-\frac{1}{(k+1)!}\prod_{i=0}^k(X-i)=\frac{1}{(k+1)!}((X+1)-(X-k))\prod_{i=0}^{k-1}(X-i) \\
	& =\frac{1}{k!}\prod_{i=0}^{k-1}(X-i)=P_k.
\end{align*}

Enfin, les \( P_k \), \( 0\le k\le n \), constituent une famille de \( n+1 = \text{dim}\Kk_n[X] \) polynômes de degrés échelonnés de \( \Kk_n[X] \) et donc la famille \( (P_k)_{0\le k\le n} \) est une base de \( \Kk_n[X] \). Dans cette base, la matrice de \( u \) a la forme désirée.
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Soit \( E \) un espace vectoriel de dimension \( n \). Un {\em hyperplan} de \( E \) est un sous-espace vectoriel de dimension \( n-1 \). Montrer que l'intersection de deux hyperplans de \( E \) a une dimension supérieure ou égale à \( n-2 \). Montrer que, pour tout \( p\le n \), l'intersection de \( p \) hyperplans a une dimension supérieure ou égale à \( n-p \).

		\item Montrer que, pour tout \( n\in \Nn \) et pour tout \( y\in \Rr \), l'application \( e_y \) de \( \Rr_n[X] \) à valeurs dans \( \Rr \) définie en posant \( e_y(P(X)) = P(y) \) ( i.e. l'application \( e_y \) est l'évaluation en \( y \)) est linéaire. Calculer la dimension de son noyau.

		\item Même question avec l'application \( e'_y \) de \( \Rr_n[X] \) à valeurs dans \( \Rr \) définie en posant \( e'_y(P(X)) = P'(y) \) (en désignant par \( P' \) le polynôme dérivé de \( P \)).

		\item Démontrer, à l'aide de ces deux résultats, qu'il existe dans \( \Rr_6[X] \) un polynôme \( P \) non nul et ayant les propriétés suivantes : \( P(0) = P(1) = P(2) = 0 \) et \( P'(4) = P'(5) = P'(6) = 0 \).
	\end{enumerate}

\( E \) est un \( \Rr \)-espace vectoriel, \( F \) et \( G \) deux sous-espaces supplémentaires de \( E \): \( E = F\bigoplus G \). On pose \( s(u) = u_F-u_G \) où \( u = u_F+u_G \) est la décomposition (unique) obtenue grâce à \( E = F\bigoplus G \). \( s \) est la symétrie par rapport à \( F \) de direction \( G \).
	\begin{enumerate}
		\item Montrer que \( s\in L(E) \), que \( u\in F\Leftrightarrow s(u) = u,u\in G\Leftrightarrow s(u) = -u \), donner \( \mathrm{Ker}(s) \) et calculer \( s^2 \).

		\item Réciproquement si \( f\in L(E) \) vérifie \( f^2 = id_E \). On pose \( p = \frac{f+id_E}{2} \). Calculer \( f(u) \) en fonction de \( p(u) \) et \( u \). Vérifier que \( p \) est un projecteur, calculer son noyau et son image. Montrer que \( f \) est la symétrie par rapport à \( F = \{u\in E|f(u) = u\} \) de direction \( G = \{u\in E|f(u) = -u\} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item La seule fonction qui est à la fois paire et impaire est la fonction nulle : \( P\cap I = \{0\} \). Montrons qu'une fonction \( f:\Rr \longrightarrow \Rr \) se décompose en une fonction paire et une fonction impaire. En effet :
\[
f(x) = \frac{f(x)+f(-x)}{2}+\frac{f(x)-f(-x)}{2}.
\]
La fonction \( x \mapsto \frac{f(x)+f(-x)}{2} \) est paire (le vérifier !), la fonction \( x \mapsto \frac{f(x)-f(-x)}{2} \) est impaire. Donc \( P+I = E \). Bilan : \( E = P\oplus I \).

\item Le projecteur sur \( P \) de direction \( I \) est l'application \( \pi : E \longrightarrow E \) qui à \( f \) associe la fonction \( x \mapsto \frac{f(x)+f(-x)}{2} \), c'est-à-dire à \( f \) on associe la partie paire de \( f \). Nous avons bien
\begin{itemize}
	\item \( \pi(f)\in P \). Par définition de \( \pi \), \( \pi(f) \) est bien une fonction paire.

	\item \( \pi \circ \pi = \pi \). Si \( g \) est une fonction paire alors \( \pi(g) = g \). Appliquons ceci avec \( g = \pi(f) \) (qui est bien une fonction paire) donc \( \pi(\pi(f)) = \pi(f) \).

	\item \( \ker \pi = I \). Si \( \pi(f) = 0 \) alors cela signifie exactement que la fonction \( x \mapsto \frac{f(x)+f(-x)}{2} \) est la fonction nulle. Donc pour tout \( x \) : \( \frac{f(x)+f(-x)}{2} = 0 \) donc \( f(x) = -f(-x) \) ; cela implique que \( f \) est une fonction impaire. Réciproquement si \( f\in I \) est une fonction impaire, sa partie paire est nulle donc \( f\in \ker \pi \).
\end{itemize}

\end{enumerate}

exercices.enonce:
Soient \( E,F \) deux espaces vectoriels et \( f : E \to F \) linéaire.

	\begin{enumerate}
		\item Montrer que \( f \) est injective si et seulement si \( f \) transforme toute famille libre de \( E \) en une famille libre de \( F \).

		\item Montrer que \( f \) est surjective si et seulement s'il existe une famille génératrice de \( E \) transformée par \( f \) en une famille génératrice de \( F \).
	\end{enumerate}

Soit \( \sigma \in S_n \) (groupe symétrique) et \( {f_\sigma} : { K^n} \to { K^n}, {(x_1,\dots x_n)} \mapsto {(x_{\sigma(1)},\dots,x_{\sigma(n)})} \)

	On munit \( K^n \) de la structure d'algèbre pour les opérations composante par composante.

	\begin{enumerate}
		\item Montrer que \( f_{\sigma} \) est un automorphisme d'algèbre.

		\item Soit \( \varphi \) un automorphisme d'algèbre de \( K^n \).
		\begin{enumerate}
			\item Montrer que la base canonique de \( K^n \) est invariante par \( \varphi \) (étudier \( \varphi(e_i^2) \) et \( \varphi(e_i\times e_j) \)).

			\item En déduire qu'il existe \( \sigma \in S_n \) tel que \( \varphi = f_\sigma \).
		\end{enumerate}

		\item Montrer que \( \{0\} \), \( K(1,\dots, 1) \), \( \{(x_1,\dots,x_n) \text{ tq } x_1 + \dots + x_n = 0 \} \) et \( K^n \) sont les seuls sous‑espaces stables par tous les endomorphismes \( f_\sigma \).
	\end{enumerate}

Soient \( E \) un espace vectoriel de dimension finie et \( f \in \mathcal{L}(E) \).

	\begin{enumerate}
		\item Montrer qu'il existe un projecteur \( p\in \mathcal{L}(E) \) et un isomorphisme \( g\in GL(E) \) tels que \( f = g\circ p \).

		\item Montrer qu'il existe un projecteur \( p\in \mathcal{L}(E) \) et un isomorphisme \( g\in GL(E) \) tels que \( f = p\circ g \).
	\end{enumerate}

Soit \( E \) un \( K\)-espace vectoriel de dimension finie. Le centre de \( \mathcal{L}(E) \) est : \( Z = \{f \in \mathcal{L}(E) \text{ tq } \forall\ g \in \mathcal{L}(E),\ f\circ g = g\circ f\} \).

	\begin{enumerate}
		\item Soit \( f \in \mathcal{L}(E) \) et \( \vec x \in E \). Si \( (\vec x,f(\vec x)) \) est libre, montrer qu'il existe \( g \in \mathcal{L}(E) \) telle que \( g(\vec x) = \vec x \) et \( g\circ f(\vec x) = -f(\vec x) \).

		\item En déduire que \( Z \) est l'ensemble des homothéties.

