exercices.indication:
\begin{enumerate}
\item Calculer \( (1-3^{-1})\sum_{n \ge 0} (n+1)3^{-n} \).
\end{enumerate}

exercices.correction:
\begin{enumerate}

\item Posons \( S_n = \sum_{k = 0}^n (k+1)3^{-k} \). L'idée est de calculer la somme de \( (1-3^{-1})S_n \). On a ainsi:
\begin{eqnarray*}
	(1-3^{-1})S_n & = & (1-3^{-1})\sum_{k=0}^n (k+1)3^{-k} \\
	& = & \sum_{k=0}^n (k+1)3^{-k}-\sum_{k=0}^n (k+1)3^{-(k+1)} \\
	& = & \sum_{k=0}^n k 3^{-k} + \sum_{k=0}^n 3^{-k} - \sum_{k=0}^n (k+1)3^{-(k+1)}
	{}\end{eqnarray*}
En réindexant les sommes, on obtient:
\begin{eqnarray*}
	(1-3^{-1})S_n & = & \sum_{k=1}^n k3^{-k} + \sum_{k=0}^n \left(\frac{1}{3}\right)^k - \sum_{k=1}^n k3^{-k} - (n+1)3^{-(n+1)}\\
	& = & \sum_{k=0}^n \frac{1}{3^k} - \frac{n+1}{3^{n+1}}
	= \cfrac{1 - \left(\frac{1}{3}\right)^{n+1}}{\frac{2}{3}}
	- \underbrace{\frac{n+1}{3^{n+1}}}_{\to 0}
\end{eqnarray*}
somme des termes d'une suite géométrique de raison \( \frac{1}{3} \in ]-1,1[ \). Et donc,
\[
\lim_{n \to +\infty} \left(1-\frac{1}{3}\right)S_n = \cfrac{3}{2}
\]
d'où
\[
\sum_{k = 0}^{+\infty}(k+1)3^{-k} = \frac{9}{4} \, \cdotp
\]
Remarque: On reconnaît la série géométrique dérivée première de raison \( \frac{1}{3} \).

\item Posons \( \displaystyle u_n = \frac{n}{n^4+n^2+1} \) et cherchons à la décomposer en éléments simples.
\begin{eqnarray*}
	n^4 + n^2 + 1 &=& (n^4 + 2n^2 + 1) - n^2 = (n^2 + 1)^2 - n^2
	\\
	&=& (n^2 + n + 1)(n^2 - n + 1) {}\end{eqnarray*}
d'où \( u_n = \frac{n}{(n^2+n+1)(n^2-n+1)} \) . Trouvons maintenant \( A \) et \( B \in \Rr \) tels que \( u_n = \frac{A}{n^2+n+1} + \frac{B}{n^2-n+1} \), soit tels que \( A(n^2-n+1) + B(n^2+n+1) = n \), ce qui équivaut à \( (A+B)n^2 + (B-A)n + (A+B) = n \). Par identification, on a:
\[
\left\{
\begin{array}{r c l}
	A+B = 0 \\
	B-A = 1 \\
	A+B = 0
\end{array}
\right.
\iff \left\{
\begin{array}{r c l}
	A & = & -\frac{1}{2} \\
	&   &              \\
	B & = & \frac{1}{2}
\end{array}
\right.
\]
D'où:
\[
u_n = \frac{n}{n^4+n^2+1} = \frac{1}{2} \left( \frac{1}{n^2-n+1} - \frac{1}{n^2+n+1} \right )
\]
\[
\sum_{n = 0}^N u_n = \sum_{n = 0}^N \frac{1}{2} \left( \frac{1}{n^2-n+1} - \frac{1}{n^2+n+1} \right) = \frac{1}{2} \left(\sum_{n = 0}^N \frac{1}{n^2-n+1} - \sum_{n = 0}^N \frac{1}{n^2+n+1} \right)
\]
Or \( n^2+n+1 = (n+1)^2 - (n+1) + 1 \). En réindexant la deuxième somme:
\begin{eqnarray*}
	\sum_{n=0}^N u_n & = & \frac{1}{2} \left(\sum_{n = 0}^N \frac{1}{n^2-n+1} - \sum_{n = 1}^{N+1} \frac{1}{n^2-n+1} \right) \\
	& = & \frac{1}{2} \left( 1 - \frac{1}{(N+1)^2 - (N+1) + 1} \right) \quad \text{par télescopage.}
	{}\end{eqnarray*}
La série est donc convergente et la somme vaut
\[
\sum_{n = 0}^{+\infty} \frac{n}{n^4+n^2+1} = \frac{1}{2} \,.
\]

\item Décomposons \( \displaystyle v_n = \frac{2n-1}{n^3-4n} \) en éléments simples. Comme
\[
n^3-4n = n(n^2-4) = n (n-2) (n + 2),
\]
cherchons \( \alpha \), \( \beta \) et \( \gamma \in \Rr \) tels que:
\[
v_n = \frac{\alpha}{n} + \frac{\beta}{n+2} + \frac{\gamma}{n-2} .
\]
Soit
\begin{eqnarray*}
	2n-1 & = & \alpha(n-2)(n+2) + \beta n(n-2) + \gamma n(n+2)\\
	& = & (\alpha+\beta+\gamma) n^2 + (2\gamma-2\beta)n - 4\alpha {}\end{eqnarray*}
Par identification:
\[
\left\{
\begin{array}{r c l}
	\alpha + \beta + \gamma = 0 \\
	2(\gamma - \beta) = 2       \\
	-4 \alpha = - 1
\end{array}
\right.
\Longleftrightarrow \left\{
\begin{array}{r c l}
	\alpha              & = & \frac{1}{4} \\
	\gamma              & = & 1 + \beta   \\
	\alpha + 2\beta + 1 & = & 0
\end{array}
\right.
\Longleftrightarrow \left\{
\begin{array}{r c l}
	\alpha & = & \frac{1}{4}   \\
	\beta  & = & - \frac{5}{8} \\
	\gamma & = & \frac{3}{8}
\end{array}
\right.
\]
D'où
\[
\frac{2n-1}{n^3-4n} = \frac{1}{4n} - \frac{5}{8(n+2)} + \frac{3}{8(n-2)}
\]
et
\begin{eqnarray*}
	\sum_{n = 3}^N v_n & = & \sum_{n = 3}^N \left(\frac{1}{4n} - \frac{5}{8(n+2)} + \frac{3}{8(n-2)}\right) \\
	& = & \sum_{n = 3}^N\frac{1}{4n} - \sum_{n = 3}^N \frac{5}{8(n+2)} + \sum_{n = 3}^N \frac{3}{8(n-2)} \,. {}\end{eqnarray*}
Soit en réindexant les 2 dernières sommes:
\[
\sum_{n = 3}^N v_n = \frac{1}{8} \left[2 \sum_{n = 3}^N \frac{1}{n} - 5 \sum_{n = 5}^{N+2} \frac{1}{n} + 3 \sum_{n = 1}^{N-2} \frac{1}{n} \right]
\]
Puis, par télescopage,
\[
\sum_{n = 3}^N v_n = \frac{1}{8} \left(\frac{89}{12} - \frac{3}{N-1} - \frac{3}{N} - \frac{5}{N+1} - \frac{5}{N+2}\right) \xrightarrow[n \to +\infty]{} \frac{1}{8}\frac{89}{12}
\, .
\]
Donc, la série converge et \( \displaystyle \sum_{n = 3}^{+\infty} \frac{2n-1}{n^3-4n} = \frac{89}{96} \).

\end{enumerate}

\medskip

(\emph{Corrigé d'Antoine Poulain})

Montrons par récurrence que \( \forall n\ge1,\;\sum_{k = 1}^n\frac{1}{k(k+1)(k+2)} = \frac{n(n+3)}{4(n+1)(n+2)} \).
\textbullet Pour \( n = 1 \), \( \sum_{k = 1}^1\frac{1}{k(k+1)(k+2)} = \frac{1}{6} = \frac{1\times(1+3)}{4\times(1+1)(1+2)} \) et la formule proposée est vraie pour \( n = 1 \). Soit \( n\ge1 \). Supposons que \( \sum_{k = 1}^n\frac{1}{k(k+1)(k+2)} = \frac{n(n+3)}{4(n+1)(n+2)} \) et montrons que \( \sum_{k = 1}^{n+1}\frac{1}{k(k+1)(k+2)} = \frac{(n+1)(n+4)}{4(n+2)(n+3)} \).

\begin{align*}
\sum_{k=1}^{n+1}\frac{1}{k(k+1)(k+2)} & =\sum_{k=1}^n\frac{1}{k(k+1)(k+2)}+\frac{1}{(n+1)(n+2)(n+3)}                                \\
& =\frac{n(n+3)}{4(n+1)(n+2)}+\frac{1}{(n+1)(n+2)(n+3)}\;(\mbox{par hypothèse de récurrence}) \\
& =\frac{n(n+3)^2+4}{4(n+1)(n+2)(n+3)}=\frac{n^3+6n^2+9n+4}{4(n+1)(n+2)(n+3)}                 \\
& =\frac{(n+1)(n^2+5n+4)}{4(n+1)(n+2)(n+3)}=\frac{(n+1)(n+4)}{4(n+2)(n+3)}
\end{align*}
On a montré par récurrence que :
\begin{center}
\shadowbox{ \( \forall n\ge1,\;\sum_{k = 1}^n\frac{1}{k(k+1)(k+2)} = \frac{n(n+3)}{4(n+1)(n+2)} \). }
\end{center}
Démonstration directe. Pour \( k\ge1 \),

\[
\frac{1}{k(k+1)(k+2)} = \frac{1}{2}\frac{(k+2)-k}{k(k+1)(k+2)} = \frac{1}{2}\left(\frac{1}{k(k+1)}-\frac{1}{(k+1)(k+2)}\right),
\]
et donc,

\begin{align*}
\sum_{k=1}^n\frac{1}{k(k+1)(k+2)} & =\frac{1}{2}(\sum_{k=1}^n\frac{1}{k(k+1)}-\sum_{k=1}^n\frac{1}{(k+1)(k+2)}) =\frac{1}{2}(\sum_{k=1}^n\frac{1}{k(k+1)}-\sum_{k=2}^{n+1}\frac{1}{k(k+1)}) \\
& =\frac{1}{2}\left(\frac{1}{2}-\frac{1}{(n+1)(n+2)}\right)=\frac{n^2+3n}{4(n+1)(n+2)}
=\frac{n(n+3)}{4(n+1)(n+2)}
\end{align*}

exercices.enonce:
\begin{enumerate}
		\item Montrer par récurrence que, pour tout naturel non nul \( n \), \( \sum_{k = 1}^nk = \frac{n(n+1)}{2} \). En calculant la différence \( (k+1)^2-k^2 \), trouver une démonstration directe de ce résultat.\rule[-1mm]{0mm}{0mm}

		\item Calculer de même les sommes \( \sum_{k = 1}^nk^2 \), \( \sum_{k = 1}^nk^3 \) et \( \sum_{k = 1}^nk^4 \) (et mémoriser les résultats).

		\item On pose \( S_p = \sum_{k = 1}^nk^p \). Déterminer une relation de récurrence permettant de calculer les \( S_p \) de proche en proche.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Montrons par récurrence que : \( \forall n\ge1,\;\sum_{k = 1}^nk = \frac{n(n+1)}{2} \). Pour \( n = 1 \), \( \sum_{k = 1}^1k = 1 = \frac{1\times(1+1)}{2} \). Soit \( n\ge1 \). Supposons que \( \sum_{k = 1}^nk = \frac{n(n+1)}{2} \) et montrons que \( \sum_{k = 1}^{n+1}k = \frac{(n+1)(n+2)}{2} \).

\begin{align*}
	\sum_{k=1}^{n+1}k & =\sum_{k=1}^nk+(n+1) =\frac{n(n+1)}{2}+(n+1)\;(\mbox{par hypothèse de récurrence}) \\
	& =(n+1)(\frac{n}{2}+1)=\frac{(n+1)(n+2)}{2}
\end{align*}
On a montré par récurrence que :
\begin{center}
	\shadowbox{ \( \forall n\ge1,\;\sum_{k = 1}^nk = \frac{n(n+1)}{2} \). }
\end{center}
On peut donner plusieurs démonstrations directes.

\begin{itemize}
	\item[\textbf{1ère demonstration.}] Pour \( k\ge1 \), \( (k+1)^2-k^2 = 2k+1 \) et donc \( \sum_{k = 1}^n((k+1)^2-k^2) = 2\sum_{k = 1}^nk+\sum_{k = 1}^n1 \) ce qui s'écrit \( (n+1)^2-1 = 2\sum_{k = 1}^nk+n \) ou encore \( 2\sum_{k = 1}^nk = n^2+n \) ou enfin \( \sum_{k = 1}^nk = \frac{n(n+1)}{2} \).

	\item[\textbf{2ème demonstration.}] On écrit

	\[
	\begin{array}{ccccccccccccc}
		1 & + & 2     & + & 3     & + & \ldots & + & (n-1) & + & n & = & S \\
		n & + & (n-1) & + & (n-2) & + & \ldots & + & 2     & + & 1 & = & S
	\end{array}
	\]
	et en additionnant (verticalement), on obtient \( 2S = (n+1)+(n+1)+\ldots+(n+1) = n(n+1) \) d'où le résultat. La même démonstration s'écrit avec le symbole sigma : 

	\[
	2S = \sum_{k = 1}^nk+\sum_{k = 1}^n(n+1-k) = \sum_{k = 1}^n(k+n+1-k) = \sum_{k = 1}^n(n+1) = n(n+1).
	\]

	\item[\textbf{3ème demonstration.}] On compte le nombre de points d'un rectangle ayant \( n \) points de large et \( n+1 \) points de long. Il y en a \( n(n+1) \). Ce rectangle se décompose en deux triangles isocèles contenant chacun \( 1+2+...+n \) points. D'où le résultat.

	\[
	\begin{array}{ccccccccc}
		{*}    &        & {*} & {*}    & \ldots &        &     & \ldots & {*}    \\
		{*}    & {*}    &     & \ddots &        &        &     &        & \vdots \\
		{*}    & {*}    & {*} &        &        &        &     &        &        \\
		\vdots &        &     & \ddots &        & \ddots &     &        & \vdots \\
		&        &     &        &        &        & {*} & {*}    & {*}    \\
		\vdots &        &     &        &        & \ddots &     & {*}    & {*}    \\
		*      & \ldots &     &        & \ldots & {*}    & {*} &        & {*}
	\end{array}
	\]

	\item[\textbf{4ème démonstration.}] Dans le triangle de \textsc{Pascal}, on sait que pour \( n \) et \( p \) entiers naturels donnés,

	\begin{center}
		\( C_n^p+C_n^{p+1} = C_{n+1}^{p+1} \).
	\end{center}
	Donc, pour \( n\ge2 \) (le résultat est clair pour \( n = 1 \)),

	\[
	1+2+...+n = 1+\sum_{k = 2}^nC_k^1 = 1+\sum_{k = 2}^n\left(C_{k+1}^2-C_k^2\right) = 1+(C_{n+1}^2-1) = \frac{n(n+1)}{2}.
	\]
\end{itemize}

\item Pour \( k\ge1 \), \( (k+1)^3-k^3 = 3k^2+3k+1 \). Donc, pour \( n\ge1 \):

\[
3\sum_{k = 1}^nk^2+3\sum_{k = 1}^nk+\sum_{k = 1}^n1 = \sum_{k = 1}^n((k+1)^3-k^3) = (n+1)^3-1.
\]
D'où,

\[
\sum_{k = 1}^nk^2 = \frac{1}{3}\left((n+1)^3-1-3\frac{n(n+1)}{2}-n\right) = \frac{1}{6}(2(n+1)^3-3n(n+1)-2(n+1)) =
\frac{1}{6}(n+1)(2n^2+n),
\]
et donc
\begin{center}
	\shadowbox{ \( \forall n\ge1,\;\sum_{k = 1}^nk^2 = \frac{n(n+1)(2n+1)}{6} \). }
\end{center}
Pour \( k\ge1 \), \( (k+1)^4-k^4 = 4k^3+6k^2+4k+1 \). Donc, pour \( n\ge1 \), on a

\[
4\sum_{k = 1}^nk^3+6\sum_{k = 1}^nk^2+4\sum_{k = 1}^nk+\sum_{k = 1}^n1 = \sum_{k = 1}^n((k+1)^4-k^4) = (n+1)^4-1.
\]
D'où :

\begin{align*}
	\sum_{k=1}^nk^3 & =\frac{1}{4}((n+1)^4-1-n(n+1)(2n+1)-2n(n+1)-n)=\frac{1}{4}((n+1)^4-(n+1)(n(2n+1)+2n+1)     \\
	& =\frac{1}{4}((n+1)^4-(n+1)^2(2n+1))=\frac{(n+1)^2((n+1)^2-(2n+1))}{4}=\frac{n^2(n+1)^2}{4}
\end{align*}
\begin{center}
	\shadowbox{ \( \forall n\ge1,\;\sum_{k = 1}^nk^3 = \frac{n^2(n+1)^2}{4} = \left(
		\sum_{k = 1}^nk\right)^2 \). }
\end{center}
Pour \( k\ge1 \), \( (k+1)^5-k^5 = 5k^4+10k^3+10k^2+5k+1 \). Donc, pour \( n\ge1 \),

\[
5\sum_{k = 1}^nk^4+10\sum_{k = 1}^nk^3+10\sum_{k = 1}^nk^2+5\sum_{k = 1}^nk+\sum_{k = 1}^n1 = \sum_{k = 1}^n((k+1)^5-k^5) = (n+1)^5-1.
\]
D'où :

\begin{align*}
	\sum_{k=1}^nk^4 & =\frac{1}{5}((n+1)^5-1-\frac{5}{2}n^2(n+1)^2-\frac{5}{3}n(n+1)(2n+1)-\frac{5}{2}n(n+1)-n) \\
	& =\frac{1}{30}(6(n+1)^5-15n^2(n+1)^2-10n(n+1)(2n+1)-15n(n+1)-6(n+1))                       \\
	& =\frac{1}{30}(n+1)(6n^4+9n^3+n^2-n)=\frac{n(n+1)(6n^3+9n^2+n-1)}{30}
\end{align*}

Finalement,
\begin{center}
	\shadowbox{ \( \begin{array}{c}
			\forall n\in\Nn^*,\;\sum_{k = 1}^nk = \frac{n(n+1)}{2}                                        \\
			\forall n\in\Nn^*,\;\sum_{k = 1}^nk^2 = \frac{n(n+1)(2n+1)}{6}                                \\
			\forall n\in\Nn^*,\;\sum_{k = 1}^nk^3 = \frac{n^2(n+1)^2}{4} = \left(\sum_{k = 1}^nk\right)^2 \\
			\forall n\in\Nn^*,\;\sum_{k = 1}^nk^4 = \frac{n(n+1)(6n^3+9n^2+n-1)}{30}.
		\end{array} \) }
\end{center}

\item Soit \( p \) un entier naturel. Pour \( k\ge1 \),

\[
(k+1)^{p+1}-k^{p+1} = \sum_{j = 0}^pC_{p+1}^jk^j.
\]
Donc, pour \( n\ge1 \):

\[
\sum_{j = 0}^pC_{p+1}^j(\sum_{k = 1}^nk^j) = \sum_{k = 1}^n(\sum_{j = 0}^pC_{p+1}^jk^j) = \sum_{k = 1}^n((k+1)^{p+1}-k^{p+1}) = ( n+1)^{p+1}-1.
\]
D'où la formule de récurrence :

\begin{center}
	\shadowbox{\( \forall p\in\Nn,\;\forall n\in\Nn^*,\sum_{j = 0}^pC_{p+1}^jS_j = (n+1)^{p+1}-1 \).}
\end{center}
\end{enumerate}

