\]
\begin{itemize}
	\item[\textbf{- 1er cas.}] Si \( \theta\notin2\pi\Zz \), alors \( e^{i\theta}\neq1 \). Par suite,

	\[
	C_n+iS_n = \frac{1-e^{i(n+1)\theta}}{1-e^{i\theta}} = e^{i\theta(n+1-1)/2}\frac{-2i\sin\frac{(n+1)\theta}{2}}{-2i\sin
		\frac{\theta}{2}} = e^{in\theta/2}\frac{\sin\frac{(n+1)\theta}{2}}{\sin
		\frac{\theta}{2}}.
	\]
	Par suite,

	\[
	C_n = \Re(C_n+iS_n) = \frac{\cos\frac{n\theta}{2}\sin\frac{(n+1)\theta}{2}}{\sin\frac{\theta}{2}}\;\mbox{et}\;S_n = \Im(C_n+iS_n) = \frac{\sin\frac{n\theta}{2}\sin\frac{(n+1)\theta}{2}}{\sin\frac{\theta}{2}}.
	\]

	\item[\textbf{- 2ème cas.}] Si \( \theta\in2\pi\Zz \), on a immédiatement \( C_n = n+1 \) et \( S_n = 0 \).
\end{itemize}

Finalement,
\begin{center}
	\shadowbox{ \( \forall n\in\Nn,\;\sum_{k = 0}^n\cos(k\theta) = \left\{
		\begin{array}{l}
			\frac{\cos\frac{n\theta}{2}\sin\frac{(n+1)\theta}{2}}{\sin\frac{\theta}{2}}\;\mbox{si}\;\theta\notin2\pi\Zz \\
			n+1\;\mbox{si}\;\theta\in2\pi\Zz
		\end{array}
		\right.
		\;\text{et}\;\sum_{k = 0}^n\sin(k\theta) = \left\{
		\begin{array}{l}
			\frac{\sin\frac{n\theta}{2}\sin\frac{(n+1)\theta}{2}}{\sin\frac{\theta}{2}}\;\mbox{si}\;\theta\notin2\pi\Zz \\
			0\;\mbox{si}\;\theta\in2\pi\Zz
		\end{array}
		\right. \). }
\end{center}

\item Soient \( x\in[0,1] \) et \( n\in\Nn^* \). Puisque \( -x\neq1 \), on a

\begin{align*}
	S_n'(x) & =\sum_{k=1}^n(-1)^{k-1}x^{k-1}=\sum_{k=0}^{n-1}(-x)^k=\frac{1-(-x)^n}{1-(-x)}=\frac{1}{1+x}(1-(-x)^n).
\end{align*}

Par suite,

\[
S_n(x) = S_n(0)+\int_0^xS_n'(t)\;dt = \int_0^x\frac{1-(-t)^n}{1+t}\;dt = \int_0^x\frac{1}{1+t}\;dt-
\int_0^x\frac{(-t)^n}{1+t}\;dt = \ln(1+x)-\int_0^x\frac{(-t)^n}{1+t}\;dt.
\]
Mais alors,

\[
|S_n(x)-\ln(1+x)| = \left|\int_0^x\frac{(-t)^n}{1+t}\;dt\right|\le\int_0^x
\left|\frac{(-t)^n}{1+t}\right|\;dt = \int_0^x\frac{t^n}{1+t}\;dt
\le\int_0^xt^ndt = \frac{x^{n+1}}{n+1}\le\frac{1}{n+1}.
\]
Comme \( \frac{1}{n+1} \) tend vers \( 0 \) quand \( n \) tend vers \( +\infty \), on en déduit que
\begin{center}
	\shadowbox{ \( \forall x\in[0,1],\;\lim_{n\rightarrow +\infty}\sum_{k = 1}^n(-1)^{k-1}x^{k-1} = \ln(1+x) \). }
\end{center}
En particulier,
\begin{center}
	\shadowbox{\( \ln2 = \lim_{n\rightarrow +\infty}(1-\frac{1}{2}+\frac{1}{3}-...+\frac{(-1)^{n-1}}{n}) \)}.
\end{center}

\item

\begin{enumerate}
	\item Soit \( n\in\Nn \). \( u_{n+1}-3 = 2u_n-6 = 2(u_n-3) \). La suite \( (u_n-3)_{n\in\Nn} \) est donc une suite géométrique, de raion \( q = 2 \) et de premier terme \( u_0-3 = -2 \). On en déduit que, pour \( n \) enteir naturel donné, \( u_n-3 = -2.2^n \). Donc,

	\[
	\forall n\in\Nn,\;u_n = 3-2^{n+1}.
	\]

	\item Soit \( n\in\Nn \).

	\[
	\sum_{k = 0}^nu_k = \sum_{k = 0}^n3-2\sum_{k = 0}^n2^k = 3(n+1)-2\frac{2^{n+1}-1}{2-1} = -2^{n+2}+3n+5.
	\]
\end{enumerate}
\end{enumerate}

exercices.enonce:
\label{ex:rou1ter}
	Nature de la série de terme général

	\begin{center}
