\end{enumerate}

\
\begin{enumerate}
\item Soit \( t>0 \):
\[
\left\{\begin{array}{l}
	x(\frac{1}{t}) = \frac{1}{t}\ln(\frac{1}{t}) = -y(t) \\
	\                                                    \\
	y(\frac{1}{t}) = t\ln(\frac{1}{t}) = -x(t)
\end{array}\right.
\]
et par conséquent, le point \( M(\frac{1}{t}) \) est le symétrique de \( M(t) \) par rapport à la droite d'équation \( y = -x \).
\fbox{On restreint l'étude à l'intervalle \( ]0;1] \)}, puis on obtiendra l'intégralité de la courbe par symétrie par rapport à la seconde bissectrice.

\item Les fonctions \( x \) et \( y \) sont de classe \( \mathcal{C}^1 \) sur \( ]0;1] \).
\begin{itemize}
	\item Tableau de variations conjointes\\
	Pour \( t\in]0;1] \):
	\[
	\begin{array}{lcl}
		x(t) = t\ln t                        & \  & y(t) = \frac{\ln t}{t}      \\
		x'(t) = 1+\ln t                      & \  & y'(t) = \frac{1-\ln t}{t^2} \\
		x'(t)>0\Longleftrightarrow t>1/e     & \  & y'(t)>0                     \\
		x'(t) = 0\Longleftrightarrow t = 1/e & \  & y'(t)\not=0
	\end{array}
	\]
	puisque \( \frac{1}{e}<1<e \). On obtient donc le tableau suivant:
	\[
	\begin{array}{c|lcccr}
		t  & 0       & \        & 1/e  & \        & 1 \\\hline x'(t)&-\infty &-&0&+&1 \\\hline
		\  & 0       & \        &      &          & 0 \\
		x  & \       & \searrow & \    & \nearrow &   \\
		\  &         &          & -1/e & \        &   \\\hline
		\  &         & \        &      &          & 0 \\
		& \       &          & \    & \nearrow &   \\
		& \       &          & -e   &          &   \\
		y  & \       & \nearrow & \    & \        &   \\
		\  & -\infty &          &      & \        &   \\\hline y'(t)&+\infty & + &2e^2 & +&1
	\end{array}
	\]
	Il n'y a pas de point singulier.

	\item Étude des branches infinies\\
	Comme \( x(t)\xrightarrow[t\to 0^+]{}0 \) et \( y(t)\xrightarrow[t\to 0^+]{}-\infty \), l'axe des ordonnées est asymptote à \( \mathcal{C} \).
\end{itemize}
\end{enumerate}

