exercices.correction:
\begin{enumerate}
\item L'astroïde complète est obtenue quand \( t \) décrit \( [-\pi,\pi] \) et pour des raisons de symétrie, \( L = 4\int_0^{\pi}{2}\left\|\overrightarrow{\frac{dM}{dt}}\right\| dt \). Or \( \overrightarrow{\frac{dM}{dt}} = \left(\begin{array}{c}
	-3a\sin t\cos^2t \\
	3a\cos t\sin^2t
\end{array}
\right) = 3a\sin t\cos t\left(\begin{array}{c}
	-\cos t \\
	\sin t
\end{array}
\right) \) et donc \( \left\|\overrightarrow{\frac{dM}{dt}}\right\| = 3a|\sin t\cos t| = \frac{3a}{2}|\sin(2t)| \) puis

\begin{center}
	\( L = 4\int_0^{\pi/2}\left\|\overrightarrow{\frac{dM}{dt}}\right\| dt = 6a\int_0^{\pi/2}\sin(2t)\;dt = 6a\left[-\frac{\cos(2t)}{2}\right]_0^{\pi/2} = 6a \).
\end{center}

\begin{center}
	\shadowbox{ \( L = 6a \). }
\end{center}

\item \( \overrightarrow{\frac{dM}{dt}} = \left(\begin{array}{c}
	R(1-\cos t) \\
	R\sin t
\end{array}
\right) = 2R\sin\left(\frac{t}{2}\right)\sin t\cos t\left(\begin{array}{c}
	\sin(t/2) \\
	\cos(t/2)
\end{array}
\right) \) et donc \( \left\|\overrightarrow{\frac{dM}{dt}}\right\| = 2R\left|\sin\left(\frac{t}{2}\right)\right| \) puis

\begin{center}
	\( L = \int_0^{2\pi}\left\|\overrightarrow{\frac{dM}{dt}}\right\| dt = 2R\int_0^{2\pi}\sin\left(\frac{t}{2}\right)\;dt = 4R\left[-\cos\left(\frac{t}{2}\right)\right]_0^{2\pi} = 8R \).
\end{center}

\begin{center}
	\shadowbox{ \( L = 8R \). }
\end{center}

\item Une représentation paramétrique de \( \Gamma \) est \( \left\{
\begin{array}{l}
	x = t \\
	y = \frac{t^2}{2p}
\end{array}
\right. \), \( 0\le t\le a \) et donc

\begin{align*}\ensuremath L & =\int_0^a\sqrt{(x'(t))^2+(y'(t))^2}\;dt=\int_0^a\sqrt{1+\frac{t^2}{p^2}}\;dt=p\int_0^{a/p}\sqrt{u^2+1}\;du                                                         \\
	& =p\left(\left[u\sqrt{u^2+1}\right]_0^{a/p}-\int_0^{a/p}\frac{u^2}{\sqrt{u^2+1}}\;du\right)=a\sqrt{1+\frac{a^2}{p^2}}-p\int_0^{a/p}\frac{u^2+1-1}{\sqrt{u^2+1}}\;du \\
	& =a\sqrt{1+\frac{a^2}{p^2}}-L+p\Argsh\left(\frac{a}{p}\right),
\end{align*}
et donc

\begin{center}
	\shadowbox{ \( L = \frac{1}{2}\left(a\sqrt{1+\frac{a^2}{p^2}}+p\Argsh\left(\frac{a}{p}\right)\right) \). }
\end{center}

\item La cardioïde complète est obtenue quand \( \theta \) décrit \( [-\pi,\pi] \).

\begin{center}
	\( \overrightarrow{\frac{dM}{d\theta}} = a\left((-\sin\theta)\overrightarrow{u}_\theta+(1+\cos\theta)\overrightarrow{v}_\theta\right) = 2a\cos\left(\frac{\theta}{2}\right)\left(-\sin\left(\frac{\theta}{2}\right)\overrightarrow{u}_\theta+\cos\left(\frac{\theta}{2}\right)\overrightarrow{v}_\theta\right) \).
\end{center}
Comme le vecteur \( -\sin\left(\frac{\theta}{2}\right)\overrightarrow{u}_\theta+\cos\left(\frac{\theta}{2}\right)\overrightarrow{v}_\theta \) est unitaire, \( \left\|\overrightarrow{\frac{dM}{d\theta}}\right\| = \left|2a\cos\left(\frac{\theta}{2}\right)\right| \) puis

\begin{center}
	\( L = \int_{-\pi}^{\pi}\left|2a\cos\left(\frac{\theta}{2}\right)\right|dt = 4a\int_0^{\pi}\cos\left(\frac{\theta}{2}\right)dt = 8a\left[\sin\left(\frac{\theta}{2}\right)\right]_0^{\pi} = 8a \).
\end{center}

\begin{center}
	\shadowbox{ \( L = 8a \). }
\end{center}
\end{enumerate}

\( \mathcal{C} \) est le support de l'arc paramétré \( t\mapsto\left(
\begin{array}{c}
t \\
\ln t
\end{array}
\right) \), \( t>0 \).

\begin{center}
\( \overrightarrow{\frac{dM}{dt}} = \left(\begin{array}{c}
	1 \\
	1/t
\end{array}
\right) = \sqrt{1+\frac{1}{t^2}}\left(\begin{array}{c}
	1/\sqrt{1+\frac{1}{t^2}} \\
	1/\left(t\sqrt{1+\frac{1}{t^2}}\right)
\end{array}
\right) = \frac{\sqrt{1+t^2}}{t}\left(
\begin{array}{c}
	\frac{t}{\sqrt{1+t^2}} \\
	\frac{1}{\sqrt{1+t^2}}
\end{array}
\right) \).
\end{center}
Donc, \( \frac{ds}{dt} = \frac{\sqrt{1+t^2}}{t} \) et on peut prendre \( \alpha(t) = \arcsin\left(\frac{1}{\sqrt{1+t^2}}\right) \) puis

\begin{center}
\( \frac{d\alpha}{dt} = -\frac{t}{(t^2+1)^{3/2}}\frac{1}{\sqrt{1-\frac{1}{1+t^2}}} = -\frac{1}{t^2+1} \),
\end{center}
et finalement

\begin{center}
\( R(t) = \frac{ds/dt}{d\alpha/dt} = -\frac{1}{t}(t^2+1)^{3/2} \).
\end{center}
Pour \( t>0 \), posons \( f(t) = |R(t)| = \frac{1}{t}(t^2+1)^{3/2} \). \( f \) est dérivable sur \( ]0,+\infty[ \) et pour \( t>0 \),

\begin{center}
\( f'(t) = -\frac{1}{t^2}(t^2+1)^{3/2}+3(t^2+1)^{1/2} = \frac{\sqrt{t^2+1}}{t^2}(-(t^2+1)+3t^2) = \frac{\sqrt{t^2+1}}{t^2}(2t^2-1) \).
\end{center}
\( f \) admet un minimum en \( t = \frac{1}{\sqrt{2}} \) égal à \( \sqrt{2}\left(\frac{1}{2}+1\right)^{3/2} = \frac{3\sqrt{3}}{2} \).

\begin{center}
\shadowbox{ Le rayon de courbure minimum est \( \frac{3\sqrt{3}}{2} \) et est le rayon de courbure en \( M\left(\frac{1}{\sqrt{2}}\right) \), \( -\frac{\pi}{2}<t<\frac{\pi}{2} \). }
\end{center}

