\begin{align*}\ensuremath r(u) & =(\cos\theta)u+(1-\cos\theta)\left(u|k\right)k+(\sin\theta)k\wedge u=\frac{1}{2}u +\frac{1}{4}(u|(e_1+e_2))(e_1+e_2)+\frac{\sqrt{6}}{4}(e_1+e_2)\wedge u \\
& \text{\og}=\text{\fg}\;\frac{1}{2}\left(
\begin{array}{c}
