exercices.correction:
\begin{enumerate}
\item Pour \( x\in]-1,1[ \) et \( n \) entier naturel non nul, posons \( f_n(x) = \frac{x^n\sin(nx)}{n} \).

Soit \( x\in]-1,1[ \). Pour \( n \) entier naturel non nul, \( |f_n(x)|\le|x|^n \). Or, la série géométrique de terme général \( |x|^n \), \( n\ge1 \), est convergente et donc la série numérique de terme général \( f_n(x) \) est absolument convergente et en particulier convergente. On en déduit que \( f(x) \) existe.

\begin{center}
	\shadowbox{ \( f \) est définie sur \( ]-1,1[ \). }
\end{center}

Soit \( a\in]0,1[ \). Chaque \( f_n \), \( n\ge1 \), est de classe \( C^1 \) sur \( [-a,a] \) et pour \( x\in[-a,a] \),

\begin{center}
	\( f_n'(x) = x^{n-1}\sin(nx)+x^n\cos(nx) \).
\end{center}

Pour \( x\in[-a,a] \) et \( n\in\Nn^* \),

\begin{center}
	\( |f_n'(x)|\le a^{n-1}+a^n\le2a^{n-1} \).
\end{center}

Puisque la série numérique de terme général \( 2a^{n-1} \), \( n\ge1 \), converge, la série de fonctions de terme général \( f_n' \), \( n\ge1 \), est normalement et donc uniformément sur \( [-a,a] \).

En résumé,

\textbullet la série de fonctions de terme général \( f_n \), \( n\ge1 \), converge simplement vers \( f \) sur \( [-a,a] \),

\textbullet chaque fonction \( f_n \), \( n\ge1 \), est de classe \( C^1 \) sur \( [-a,a] \),

\textbullet la série de fonctions de terme général \( f_n' \) converge uniformément sur \( [-a,a] \).

D'après un corollaire du théorème de dérivation terme à terme, \( f \) est de classe \( C^1 \) sur \( [-a,a] \) pour tout réel \( a \) de \( ]0,1[ \) et donc sur \( ]-1,1[ \) et sa dérivée s'obtient par dérivation terme à terme.

\begin{center}
	\shadowbox{ \( f \) est de classe \( C^1 \) sur \( ]-1,1[ \) et \( \forall x\in]-1,1[ \), \( f'(x) = \sum_{n = 1}^{+\infty}(x^{n-1}\sin(nx)+x^n\cos(nx)) \). }
\end{center}

\item Ainsi, pour \( x\in]-1,1[ \)

\begin{align*}\ensuremath f'(x) & =\sum_{n=1}^{+\infty}(x^{n-1}\sin(nx)+x^n\cos(nx))=\text{Im}\left(\sum_{n=1}^{+\infty}x^{n-1}e^{inx}\right)+\text{Re}\left(\sum_{n=1}^{+\infty}x^ne^{inx}\right)                                                                  \\
	& =\text{Im}\left(\frac{e^{ix}}{1-xe^{ix}}\right)+\text{Re}\left(\frac{xe^{ix}}{1-xe^{ix}}\right)=\text{Im}\left(\frac{e^{ix}(1-xe^{-ix})}{x^2-2x\cos x+1}\right) +\text{Re}\left(\frac{xe^{ix}(1-xe^{-ix})}{x^2-2x\cos x+1}\right) \\
	& =\frac{\sin x+x\cos x-x^2}{x^2-2x\cos x+1} .
\end{align*}

Mais, pour \( x\in]-1,1[ \),

\begin{center}
	\( \left(\frac{x\sin x}{1-x\cos x}\right)' = \frac{(\sin x+x\cos x)(1-x\cos x)-x\sin x(-\cos x+x\sin x)}{(1-x\cos x)^2} = \frac{\sin x+x\cos x-x^2}{(1-x\cos x)^2} \).
\end{center}

et donc

\begin{align*}\ensuremath
	\left(\arctan\left(\frac{x\sin x}{1-x\cos x}\right)\right)' & =\frac{\sin x+x\cos x-x^2}{(1-x\cos x)^2}\times\frac{1}{1+\left(\frac{x\sin x}{1-x\cos x}\right)^2}=\frac{\sin x+x\cos x-x^2}{(1-x\cos x)^2+x^2\sin^2x} \\
	& =\frac{\sin x+x\cos x-x^2}{x^2-2x\cos x+1}= f'(x).
\end{align*}

Finalement, pour \( x\in]-1,1[ \),

\begin{center}
	\( f(x) = f(0)+\int_0^xf'(t)\;dt = 0+\arctan\left(\frac{x\sin x}{1-x\cos x}\right)-\arctan(0) = \arctan\left(\frac{x\sin x}{1-x\cos x}\right) \).
\end{center}

\begin{center}
	\shadowbox{ \( \forall x\in]-1,1[ \), \( \sum_{n = 1}^{+\infty}\frac{x^n\sin(nx)}{n} = \arctan\left(\frac{x\sin x}{1-x\cos x}\right) \). }
\end{center}
\end{enumerate}

exercices.enonce:
Soit \( f(x) = \sum_{n = 1}^{+\infty}\frac{(-1)^{n-1}}{\ln(nx)} \).

	\begin{enumerate}
		\item Domaine de définition de \( f \). On étudie ensuite \( f \) sur \( ]1,+\infty[ \).

		\item Continuité de \( f \) et limites de \( f \) en \( 1 \) et \( +\infty \).

		\item Montrer que \( f \) est de classe \( C^1 \) sur \( ]1,+\infty[ \) et dresser son tableau de variation.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Pour \( n \) entier naturel non nul, on note \( f_n \) la fonction \( x\mapsto\frac{(-1)^n}{\ln(nx)} \). Pour tout réel \( x \), \( f(x) \) existe si et seulement si chaque \( f_n(x) \), \( n\in\Nn^* \), existe et la série numérique de terme général \( f_n(x) \), \( n\in\Nn^* \), converge.

Pour \( n\in\Nn^* \) et \( x\in\Rr \), \( f_n(x) \) existe si et seulement si \( x>0 \) et \( x\neq \frac{1}{n} \).

Soit donc \( x\in D = ]0,+\infty[\setminus\left\{\frac{1}{p},\;p\in\Nn^*\right\} \).

Pour \( n>\frac{1}{x} \), on a \( \ln(nx)>0 \). On en déduit que la suite \( \left(\frac{1}{\ln(nx)}\right)_{n\in\Nn^*} \) est positive et décroissante à partir d'un certain et tend vers \( 0 \) quand \( n \) tend vers \( +\infty \). Ainsi, la série numérique de terme général \( f_n(x) \) converge en vertu du critère spécial aux séries alternées et donc \( f(x) \) existe.

\begin{center}
	\shadowbox{ Le domaine de définition de \( f \) est \( D = ]0,+\infty[\setminus\left\{\frac{1}{n},\;n\in\Nn^*\right\} \). }
\end{center}

\item \textbf{Limite de \( f \) en \( +\infty \).}
Soit \( x > 1 \). Donc \( f(x) \) existe. Pour tout entier naturel non nul \( n \), \( \ln(nx) > 0 \). On en déduit que la suite \( \left(\frac{1}{\ln(nx)}\right)_{n\in\Nn^*} \) est décroissante. On sait alors que la valeur absolue de \( f(x) \) est majorée par la valeur absolue du premier terme de la série. Ainsi

\begin{center}
	\( \forall x>1 \), \( |f(x)|\le\left|\frac{(-1)^0}{\ln(x)}\right| = \frac{1}{\ln x} \),
\end{center}

et en particulier

\begin{center}
	\shadowbox{ \( \lim_{x \rightarrow +\infty}f(x) = 0 \). }
\end{center}

On peut noter de plus que pour \( x>1 \), \( f(x) \) est du signe du premier terme de la série à savoir \( \frac{1}{\ln(x)} \) et donc \( \forall x\in]1,+\infty[ \), \( f(x) > 0 \).

\textbf{Convergence uniforme sur\( ]1,+\infty[ \).} D'après une majoration classique du reste à l'ordre \( n \) alternée d'une série alternée, pour \( x > 1 \) et \( n \) naturel non nul,

\begin{center}
	\( |R_n(x)| = \left|\sum_{k = n+1}^{+\infty}\frac{(-1)^{k-1}}{\ln(kx)}\right|\le\left|\frac{(-1)^n}{\ln((n+1)x)}\right| = \frac{1}{\ln((n+1)x}\le\frac{1}{n+1} \).
\end{center}

Donc, pour tout entier naturel non nul, \( \underset{x\in]1,+\infty[}{\text{sup}}|R_n(x)|\le\frac{1}{\ln(n+1)} \) et donc \( \lim_{n \rightarrow +\infty}\underset{x\in]1,+\infty[}{\text{sup}}|R_n(x)| = 0 \). La série de fonctions de terme général \( f_n \) converge uniformément vers sa somme sur \( ]1,+\infty[ \).

\textbf{Continuité sur \( ]1,+\infty[ \).} Chaque fonction \( f_n \), \( n\in\Nn^* \) est continue sur \( ]1,+\infty[ \) et donc \( f \) est donc continue sur \( ]1,+\infty[ \) en tant que limite uniforme sur \( ]1,+\infty[ \) d'une suite de fonctions continues sur \( ]1,+\infty[ \).

\begin{center}
	\shadowbox{ \( f \) est continue sur \( ]1,+\infty[ \). }
\end{center}

\textbf{Limite en \( 1 \) à droite.} Soit \( n\ge2 \). Quand \( x \) tend vers \( 1 \) par valeurs supérieures, \( f_n(x) \) tend vers \( \ell_n = \frac{(-1)^{n-1}}{\ln(n)} \). Puisque la série de fonctions de terme général \( f_n \), \( n\ge2 \), converge uniformément vers sa somme sur \( ]1,+\infty[ \), le théorème d'interversion des limites permet d'affirmer que la série numérique de terme général \( \ell_n \), \( n\ge2 \) converge et que la fonction \( x\mapsto f(x) -\frac{1}{\ln(x)} = \sum_{n = 2}^{+\infty}f_n(x) \) tend vers le réel \( \sum_{n = 2}^{+\infty}\frac{(-1)^{n-1}}{\ln(n)} \) quand \( x \) tend vers \( 1 \) par valeurs supérieures ou encore

\begin{center}
	\shadowbox{ \( f(x)\underset{x\rightarrow1^+}{ = }\frac{1}{\ln x}+O(1) \) et en particulier, \( \displaystyle\lim_{\substack{x\rightarrow1\\
				x>1}}f(x) = +\infty \). }
\end{center}

\item La série de fonctions de terme général \( f_n \), \( n\ge1 \), converge simplement vers la fonction \( f \) sur \( ]1,+\infty[ \). De plus chaque fonction \( f_n \) est de classe \( C^1 \) sur \( ]1,+\infty[ \) et pour \( n\in\Nn^* \) et \( x>1 \),

\begin{center}
	\( f_n'(x) = \frac{(-1)^n}{x\ln^2(nx)} \).
\end{center}

Il reste à vérifier la convergence uniforme de la série de fonctions de terme général \( f_n' \) sur \( ]1,+\infty[ \).

Soit \( x > 1 \). La série de terme général \( f_n'(x) \) est alternée car son terme général est alterné en signe et sa valeur absolue à savoir \( \frac{1}{x\ln^2(nx)} \) tend vers zéro quand \( n \) tend vers \( +\infty \) en décroissant. Donc, d'après une majoration classique du reste à l'ordre \( n \) d'une série alternée,

\begin{center}
	\( |R_n(x)| = \left|\sum_{k = n+1}^{+\infty}\frac{(-1)^k}{x\ln^2(kx)}\right|\le\left|\frac{(-1)^{n+1}}{x\ln^2((n+1)x)}\right| = \frac{1}{x\ln^2((n+1)x)}\le\frac{1}{\ln^2(n+1)} \).
\end{center}

Par suite, \( \underset{x\in]1,+\infty[}{\text{sup}}|R_n(x)|\le\frac{1}{\ln^2(n+1)} \) et donc \( \lim_{n \rightarrow +\infty}\underset{x\in]1,+\infty[}{\text{sup}}|R_n(x)| = 0 \). Ainsi, la série de fonctions de terme général \( f_n' \), \( n\ge1 \), converge uniformément sur \( ]1,+\infty[ \).

En résumé,

\textbullet la série de fonctions de terme général \( f_n \), \( n\ge1 \), converge simplement vers \( f \) sur \( ]1,+\infty[ \),

\textbullet chaque fonction \( f_n \), \( n\ge1 \), est de classe \( C^1 \) sur \( ]1,+\infty[ \),

\textbullet la série de fonctions de terme général \( f_n' \) converge uniformément sur \( ]1,+\infty[ \).

D'après un corollaire du théorème de dérivation terme à terme, \( f \) est de classe \( C^1 \) sur \( ]1,+\infty[ \) et sa dérivée s'obtient par dérivation terme à terme.

\begin{center}
	\shadowbox{ \( f \) est de classe \( C^1 \) sur \( ]1,+\infty[ \) et \( \forall x>1 \), \( f'(x) = \sum_{n = 1}^{+\infty}\frac{(-1)^n}{x\ln^2(nx)} \). }
\end{center}

Pour \( x >1 \), puisque la série de somme \( f'(x) \) est alternée, \( f'(x) \) est du signe du premier terme de la somme à savoir \( -\frac{1}{x\ln^2x} \). Par suite, \( \forall x\in]-1,1[ \), \( f'(x)\le0 \) et \( f \) est donc strictement décroissante sur \( ]1,+\infty[ \).

\begin{center}
	\shadowbox{ La fonction \( f \) est décroissante sur \( ]1,+\infty[ \). }
\end{center}
\end{enumerate}

exercices.enonce:
Pour \( n\in\Nn^* \), soit \( f_n(t) = (-1)^n\ln\left(1+\frac{t^2}{n(1+t^2)}\right) \).

	\begin{enumerate}
		\item Étudier la convergence simple et uniforme de la série de terme général \( f_n \) puis la continuité de la somme \( f \).

		\item Montrer que \( \lim_{t \rightarrow +\infty}f(t) = \ln\left(\frac{2}{\pi}\right) \) à l'aide de la formule de \textsc{Stirling}.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \textbf{Convergence simple.} Soit \( t\in\Rr \). Pour tout entier naturel non nul \( n \), \( 1+\frac{t^2}{n(1+t^2)}\ge1>0 \) et donc \( f_n(t) \) existe. Ensuite, \( \ln\left(1+\frac{t^2}{n(1+t^2)}\right)>0 \) et donc la suite numérique \( (f_n(t))_{n\in\Nn^*} \) est alternée en signe. De plus, \( |f_n(t)| = \ln\left(1+\frac{t^2}{n(1+t^2)}\right) \) et la suite \( (|f_n(t)|)_{n\in\Nn^*} \) tend vers \( 0 \) en décroissant.

On en déduit que la série de terme général \( f_n(t) \), \( n\ge1 \), converge en vertu du critère spécial aux séries alternées.

\begin{center}
	\shadowbox{ La série de fonctions de terme général \( f_n \), \( n\ge1 \), converge simplement sur \( \Rr \). }
\end{center}

On pose alors \( f = \sum_{n = 1}^{+\infty}f_n \).

\textbf{Convergence uniforme.} Soit \( n\in\Nn^* \). D'après une majoration classique du reste à l'ordre \( n \) d'une série alternée, pour tout réel \( t \) on a

\begin{align*}\ensuremath |R_n(t)| & =\left|\sum_{k=n+1}^{+\infty}f_k(t)\right|\le|f_{n+1}(t)|=\ln\left(1+\frac{t^2}{(n+1)(1+t^2)}\right)=\ln\left(1+\frac{t^2+1-1}{(n+1)(1+t^2)}\right)=\ln\left(1+\frac{1}{n+1}-\frac{1}{(n+1)(1+t^2)}\right) \\
	& \le\ln\left(1+\frac{1}{n+1}\right),
\end{align*}

et donc, \( \forall n\in\Nn^* \), \( \underset{t\in\Rr}{\text{sup}}|R_n(t)|\le\ln\left(1+\frac{1}{n+1}\right) \). Comme \( \lim_{n \rightarrow +\infty}\ln\left(1+\frac{1}{n+1}\right) = 0 \), on a encore \( \lim_{n \rightarrow +\infty}\underset{t\in\Rr}{\text{sup}}|R_n(t)| = 0 \) et on a montré que

\begin{center}
	\shadowbox{ La série de fonctions de terme général \( f_n \), \( n\ge1 \), converge uniformément vers \( f \) sur \( \Rr \). }
\end{center}

\textbf{Continuité.} Puisque chaque fonction \( f_n \), \( n\ge1 \), est continue sur \( \Rr \), la fonction \( f \) est continue sur \( \Rr \) en tant que limite uniforme sur \( \Rr \) d'une suite de fonctions continues sur \( \Rr \).

\begin{center}
	\shadowbox{ \( f \) est continue sur \( \Rr \). }
\end{center}

\item D'après le théorème d'interversion des limites, \( f \) a une limite réelle en \( +\infty \) et

\begin{center}
	\( \lim_{t \rightarrow +\infty}f(t) = \sum_{n = 1}^{+\infty}\lim_{t \rightarrow +\infty}f_n(t) = \sum_{n = 1}^{+\infty}(-1)^n\ln\left(1+\frac{1}{n}\right) = \ln\left(\frac{2}{\pi}\right) \) (voir l'exercice \ref{ex:rou4}, 5)).
\end{center}

\begin{center}
	\shadowbox{ \( \lim_{t \rightarrow +\infty}f_n(t) = \ln\left(\frac{2}{\pi}\right) \). }
\end{center}
\end{enumerate}

exercices.enonce:
Pour \( n\in\Nn^* \), on pose \( f_n(x) = \left\{\begin{array}{l}
		\left(1-\frac{x^2}{n}\right)^n\;\text{si}\;x\in[0,\sqrt{n}] \\
		\rule{0mm}{5mm}0\;\text{si}\;x>\sqrt{n}
	\end{array}
	\right. \).

	\begin{enumerate}
		\item Montrer que la suite \( (f_n)_{n\in\Nn^*} \) converge simplement sur \( \Rr^+ \) vers la fonction \( f : x\mapsto e^{-x^2} \).

		\item À l'aide de la suite \( (f_n)_{n\in\Nn^*} \), calculer l'intégrale de \textsc{Gauss} \( \int_0^{+\infty}e^{-x^2}\;dx \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( x\in[0,+\infty[ \). Pour \( n> x^2 \), \( f_n(x) = \text{exp}\left(n\ln\left(1-\frac{x^2}{n}\right)\right) \) et donc \( f_n(x)\underset{n\rightarrow+\infty}{ = }\text{exp}(-x^2+o(1)) \). Donc la suite \( (f_n)_{n\in\Nn^*} \) converge simplement sur \( \Rr^+ \) vers la fonction \( f : x\mapsto e^{-x^2} \).

\item Chaque fonction \( f_n \), \( n\in\Nn^* \), est continue par morceaux sur \( [0,+\infty[ \) et nulle au voisinage de \( +\infty \). Donc chaque fonction \( f_n \), \( n\in\Nn^* \), est intégrable sur \( [0,+\infty[ \).

La fonction \( f \) est continue sur \( [0,+\infty[ \) et négligeable devant \( \frac{1}{x^2} \) quand \( x \) tend vers \( +\infty \). Donc la fonction \( f \) est intégrable sur \( [0,+\infty[ \).

Soit \( n\in\Nn^* \). Par convexité de la fonction exponentielle, \( \forall u\in\Rr \), \( 1+u\le e^u \). Par suite, \( \forall x\in\left[0,\sqrt{n}\right] \), \( 0\le1-\frac{x^2}{n}\le e^{-x^2/n} \) puis par croissance de la fonction \( t\mapsto t^n \) sur \( \Rr^+ \), \( 0\le f_n(x) = \left(1-\frac{x^2}{n}\right)^n\le e^{-x^2} = f(x) \). D'autre part, pour \( x>\sqrt{n} \), \( f_n(x) = 0\le f(x) \). Finalement

\begin{center}. \( \forall n\in\Nn^* \), \( \forall x\in[0,+\infty[ \), \( |f_n(x)|\le f(x) \).
\end{center}

En résumé,

\textbullet chaque fonction \( f_n \), \( n\in\Nn^* \), est continue par morceaux et intégrable sur \( [0,+\infty[ \),

\textbullet la suite de fonctions \( (f_n) \) converge simplement vers la fonction \( f \) sur \( [0,+\infty[ \) et la fonction \( f \) est continue sur \( [0,+\infty[ \).

\textbullet \( \forall n\in\Nn^* \), \( |f_n|\le f \), la fonction \( f \) étant intégrable sur \( [0,+\infty[ \).

D'après le théorème de convergence dominée, la suite \( \left(\int_0^{+\infty}f_n(x)\;dx\right)_{n\in\Nn^*} \) converge vers \( \int_0^{+\infty}f(x)\;dx \). Ainsi,

\begin{center}
	\( \int_0^{+\infty}e^{-x^2}\;dx = \lim_{n \rightarrow +\infty}\int_0^{\sqrt{n}}\left(1-\frac{x^2}{n}\right)^n\;dx \).
\end{center}

Soit \( n\in\Nn^* \). En posant \( t = \arccos\left(\frac{x}{\sqrt{n}}\right) \) et donc \( \frac{x^2}{n} = \cos^2t \) et \( dx = -\sqrt{n}\sin t\;dt \), on obtient

\begin{center}
	\( \int_0^{\sqrt{n}}\left(1-\frac{x^2}{n}\right)^n\;dx = \int_{\pi/2}^0(1-\cos^2t)^n\times(-\sqrt{n}\sin t)\;dt = \sqrt{n}\int_0^{\pi/2}\sin^{2n+1}t\;dt = \sqrt{n}W_{2n+1} \),
\end{center}

où \( W_n \) est la \( n \)-ème intégrale de \textsc{Wallis}. Classiquement, \( W_n\underset{n\rightarrow+\infty}{\sim}\sqrt{\frac{\pi}{2n}} \) (voir Exercices Maths Sup) et donc

\begin{center}
	\( \frac{W_{2n+1}}{\sqrt{n}}\underset{n\rightarrow+\infty}{\sim}\sqrt{n}\sqrt{\frac{\pi}{2(2n+1)}}\underset{n\rightarrow+\infty}{\sim}\frac{\sqrt{\pi}}{2} \).
\end{center}

On a montré que

\begin{center}
	\shadowbox{ \( \int_0^{+\infty}e^{-x^2}\;dx = \frac{\sqrt{\pi}}{2} \). }
\end{center}
\end{enumerate}

Pour \( x\in]0,1] \), \( x^{-x} = e^{-x\ln(x)} \) et donc \( \lim_{x \rightarrow 0^+}x^{-x} = 1 \). Donc si on pose \( \forall x\in[0,1] \), \( f(x) = \left\{
\begin{array}{l}
x^{-x}\;\text{si}\;x\in]0,1] \\
1\;\text{si}\;x = 0
\end{array}
\right. \), \( f \) est une fonction continue sur le segment \( [0,1] \) et donc intégrable sur le segment \( [0,1] \).

Pour \( x\in]0,1] \), \( x^{-x} = e^{-x\ln(x)} = \sum_{n = 0}^{+\infty}\frac{(-x\ln(x))^n}{n!} \). Posons alors \( \forall x\in[0,1] \), \( f_0(x) = 1 \) puis \( \forall n\in\Nn^* \), \( \forall x\in[0,1] \), \( f_n(x) = \left\{
\begin{array}{l}
\frac{(-x\ln(x))^n}{n!}\;\text{si}\;x\in]0,1] \\
\rule{0mm}{4mm}0\;\text{si}\;x = 0
\end{array}
\right. \). La fonction \( f_0 \) est continue sur \( [0,1] \) et pour \( n\in\Nn^* \), puisque \( -x\ln(x)\underset{x\rightarrow0^+}{\rightarrow}0 \), la fonction \( f_n \) est continue sur \( [0,1] \). En résumé, chaque fonction \( f_n \), \( n\in\Nn \), est continue sur \( [0,1] \). De plus,

\begin{center}
\( \forall x\in[0,1] \), \( f(x) = \sum_{n = 0}^{+\infty}f_n(x) \).
\end{center}

Vérifions alors que la série de fonctions de terme général \( f_n \) converge normalement et donc uniformément vers \( f \) sur le segment \( [0,1] \). Pour \( x\in[0,1] \), posons \( g(x) = \left\{
\begin{array}{l}
-x\ln x\;\text{si}\;x\in]0,1] \\
0\;\text{si}\;x = 0
\end{array}
\right. \). La fonction \( g \) est continue sur le segment \( [0,1] \) et admet donc un maximum \( M \) sur ce segment. Pour \( x\in[0,1] \), on a \( 0\le g(x)\le M \) (on peut montrer que \( M = g\left(\frac{1}{e}\right) = \frac{1}{e} \)). Mais alors \( \forall n\in\Nn \), \( \forall x\in]0,1] \), \( |f_n(x)| = \frac{(g(x))^n}{n!}\le\frac{M^n}{n!} \) ce qui reste vrai pour \( x = 0 \). Comme la série numérique de terme général \( \frac{M^n}{n!} \) converge, on a montré que la série de fonctions de terme général \( f_n \) converge normalement et donc uniformément vers \( f \) sur le segment \( [0,1] \).

D'après le théorème d'intégration terme à terme sur un segment, la série numérique de terme général \( \int_0^1f_n(x)\;dx \), converge et

\begin{center}
\( \int_0^1f(x)\;dx = \sum_{n = 0}^{+\infty}\int_0^1f_n(x)\;dx \)\quad\( (*) \).
\end{center}

Pour \( n\in\Nn \), posons \( I_n = \int_0^1f_n(x)\;dx \). Soit \( n\in\Nn \). En posant \( u = -\ln(x) \) puis \( v = (n+1)u \), on obtient

\begin{align*}\ensuremath I_n & =\frac{1}{n!}\int_0^1(-x\ln x)^n\;dx=\frac{1}{n!}\int_{+\infty}^0(ue^{-u})^n\times(-e^{-u}\;du)=\frac{1}{n!}\int_0^{+\infty}u^ne^{-(n+1)u}\;du \\
& =\frac{1}{n!(n+1)^{n+1}}\int_0^{+\infty}v^ne^{-v}\;dv=\frac{\Gamma(n+1)}{n!(n+1)^{n+1}}=\frac{1}{(n+1)^{n+1}}.
\end{align*}

L'égalité \( (*) \) s'écrit alors \( \int_0^1x^{-x}\;dx = \sum_{n = 0}^{+\infty}\frac{1}{(n+1)^{n+1}} = \sum_{n = 1}^{+\infty}\frac{1}{n^n} \).

\textbf{Remarque.} Pour calculer \( I_n = \int_0^1\frac{(-x\ln x)^n}{n!}\;dx \), on peut aussi s'intéresser plus généralement à \( J_{n,p} = \int_0^1\frac{x^n(-\ln x)^p}{n!}\;dx \) que l'on calcule par récurrence grâce à une intégration par parties.

Le travail qui précède permet encore d'écrire

\begin{center}
\( \int_0^1x^x\;dx = \sum_{n = 0}^{+\infty}\int_0^1\frac{(x\ln x)^n}{n!}\;dx = \sum_{n = 1}^{+\infty}\frac{(-1)^n}{n^n} \).
\end{center}

\begin{center}
\shadowbox{ \( \int_0^1x^{-x}\;dx = \sum_{n = 1}^{+\infty}\frac{1}{n^n} \) et \( \int_0^1x^x\;dx = \sum_{n = 1}^{+\infty}\frac{(-1)^n}{n^n} \). }
\end{center}

Pour \( x>0 \), posons \( f(x) = \frac{x^2}{e^x-1} \). \( f \) est continue sur \( ]0,+\infty[ \).

Ensuite, pour tout réel strictement positif \( x \), on a \( 0<e^{-x}<1 \) et donc

\begin{center}
\( \frac{x^2}{e^x-1} = \frac{x^2e^{-x}}{1-e^{-x}} = x^2e^{-x}\sum_{n = 0}^{+\infty}e^{-nx} = \sum_{n = 0}^{+\infty}x^2e^{-(n+1)x} = \sum_{n = 1}^{+\infty}x^2e^{-nx} \).
\end{center}

Pour \( n\in\Nn^* \) et \( x>0 \), posons \( f_n(x) = x^2e^{-nx} \). Chaque fonction \( f_n \), \( n\in\Nn^* \), est continue et intégrable sur \( [0,+\infty[ \) car négligeable devant \( \frac{1}{x^2} \) quand \( x \) tend vers \( +\infty \). En particulier, chaque fonction \( f_n \), \( n\in\Nn^* \), est intégrable sur \( ]0,+\infty[ \). De plus, pour \( n\in\Nn^* \),

\begin{center}
\( \int_0^{+\infty}|f_n(x)|\;dx = \int_0^{+\infty}x^2e^{-nx}\;dx = \frac{1}{n^3}\int_0^{+\infty}u^2e^{-u}\;du = \frac{\Gamma(3)}{n^3} = \frac{2}{n^3} \),
\end{center}

qui est le terme général d'une série numérique convergente.

En résumé,

\textbullet chaque fonction \( f_n \), \( n\in\Nn^* \), est continue et intégrable sur \( ]0,+\infty[ \),

\textbullet la série de fonctions de terme général \( f_n \), \( n\in\Nn^* \), converge simplement vers la fonction \( f \) sur \( ]0,+\infty[ \) et la fonction \( f \)

est continue sur \( ]0,+\infty[ \).

\textbullet \( \sum_{n = 1}^{+\infty}\int_0^{+\infty}|f_n(x)|\;dx<+\infty \).

D'après un théorème d'intégration terme à terme, \( f \) est intégrable sur \( ]0,+\infty[ \), la série numérique de terme général \( \int_0^1f_n(x)\;dx \), \( n\in\Nn^* \), converge et

\begin{center}
\( \int_0^{+\infty}f(x)\;dx = \sum_{n = 1}^{+\infty}\int_0^{+\infty}f_n(x)\;dx = \sum_{n = 1}^{+\infty}\frac{2}{n^3} \).
\end{center}

On a montré que

\begin{center}
\shadowbox{ \( \int_0^{+\infty}\frac{x^2}{e^x-1}\;dx = 2\sum_{n = 1}^{+\infty}\frac{1}{n^3} \). }
\end{center}

C'est presque le même exercice que l'exercice \ref{ex:rou3bis}. Pour tout réel \( x>0 \),

\begin{center}
\( \frac{x}{\sh x} = \frac{2xe^{-x}}{1-e^{-2x}} = 2xe^{-x}\sum_{n = 0}^{+\infty}e^{-2nx} = \sum_{n = 0}^{+\infty}2xe^{-(2n+1)x} \),
\end{center}

puis avec la même démarche que dans l'exercice précédent

\begin{align*}\ensuremath
\int_0^{+\infty}\frac{x}{\sh x}\;dx & =\sum_{n=0}^{+\infty}\int_0^{+\infty}2xe^{-(2n+1)x}\;dx=\sum_{n=0}^{+\infty}\frac{2}{(2n+1)^2}\int_0^{+\infty}ue^{-u}\;du=\sum_{n=0}^{+\infty}\frac{2\Gamma(2)}{(2n+1)^2}                 \\
& =2\sum_{n=0}^{+\infty}\frac{1}{(2n+1)^2}=2\left(\sum_{n=1}^{+\infty}\frac{1}{n^2}-\sum_{n=1}^{+\infty}\frac{1}{(2n)^2}\right)=2\left(1-\frac{1}{4}\right)\frac{\pi^2}{6}=\frac{\pi^2}{4}.
\end{align*}

\begin{center}
\shadowbox{ \( \int_0^{+\infty}\frac{x}{\sh x}\;dx = \frac{\pi^2}{4} \). }
\end{center}

Ici, le plus simple est peut-être de ne pas utiliser de théorème d'intégration terme à terme. La fonction \( f : x\mapsto\frac{\ln x}{1+x^2} \) est continue sur \( ]0,1] \). De plus, quand \( x \) tend vers \( 0 \), \( f(x)\underset{x\rightarrow0^+}{\sim}\ln x\underset{x\rightarrow0^+}{ = }o\left(\frac{1}{\sqrt{x}}\right) \). On en déduit que \( f \) est intégrable sur \( ]0,1] \).

Soit \( n\in\Nn \).

\begin{center}
\( \frac{\ln x}{1+x^2} = \sum_{k = 0}^n(-1)^kx^{2k}\ln x+\frac{(-1)^{n+1}x^{2n+2}\ln x}{1+x^2} \).
\end{center}

Maintenant, chacune des fonctions \( f_k : x\mapsto(-1)^kx^{2k}\ln x \), \( 0\le k\le n \), est intégrable sur \( ]0,1] \) car continue sur \( ]0,1] \) et négligeable devant \( \frac{1}{\sqrt{x}} \) quand \( x \) tend vers \( 0 \). On en déduit encore que la fonction \( g_n : x\mapsto\frac{(-1)^{n+1}x^{2n+2}\ln x}{1+x^2} \) est intégrable sur \( ]0,1] \) car \( g_n = f-\sum_{k = 0}^nf_k \). On a donc

\begin{center}
\( \forall n\in\Nn \), \( \int_0^1\frac{\ln x}{1+x^2}\;dx = \sum_{k = 0}^n(-1)^k\int_0^1x^{2k}\ln x\;dx+\int_0^1\frac{(-1)^{n+1}x^{2n+2}\ln x}{1+x^2}\;dx \).
\end{center}

La fonction \( h : x\mapsto\frac{x\ln x}{1+x^2}\;dx \) est continue sur \( ]0,1] \) et prolongeable par continuité en \( 0 \). On en déduit que la fonction \( h \) est bornée sur \( ]0,1] \). Soit \( M \) un majorant de la fonction \( |h| \) sur \( ]0,1] \). Pour tout entier naturel \( n \), on a alors

\begin{center}
\( \left|\int_0^1\frac{(-1)^{n+1}x^{2n+2}\ln x}{1+x^2}\;dx\right|\le \int_0^1x^{2n}\left|\frac{x\ln x}{1+x^2}\right|\;dx\le M\int_0^1x^{2n}\;dx = \frac{M}{2n+1} \).
\end{center}

En particulier, \( \lim_{n \rightarrow +\infty}\int_0^1\frac{(-1)^{n+1}x^{2n+2}\ln x}{1+x^2}\;dx = 0 \). Ceci montre que la série numérique de terme général \( (-1)^k\int_0^1x^{2k}\ln x\;dx \), \( k\in\Nn \), converge et que

\begin{center}
\( \int_0^1\frac{\ln x}{1+x^2}\;dx = \sum_{k = 0}^{+\infty}(-1)^k\int_0^1x^{2k}\ln x\;dx \).
\end{center}

Soient \( n\in\Nn \) et \( \varepsilon\in]0,1[ \). Les deux fonctions \( x\mapsto\frac{x^{2n+1}}{2n+1} \) et \( x\mapsto\ln x \) sont de classe \( C^1 \) sur le segment \( [\varepsilon,1] \). On peut donc effectuer une intégration par parties et on obtient

\begin{center}
\( \int_{\varepsilon}^1x^{2n}\ln x\;dx = \left[\frac{x^{2n+1}}{2n+1}\ln x\right]_\varepsilon^1-\frac{1}{2n+1}\int_{\varepsilon}^1x^{2n}\;dx = -\frac{\varepsilon^{2n+1}}{2n+1}\ln \varepsilon-\frac{1}{(2n+1)^2}(1-\varepsilon^{2n+1}) \).
\end{center}

Quand \( \varepsilon \) tend vers \( 0 \), on obtient \( \int_0^1x^{2n}\ln x\;dx = -\frac{1}{(2n+1)^2} \). Par suite,

\begin{center}
\( \int_0^1\frac{\ln x}{1+x^2}\;dx = -\sum_{n = 0}^{+\infty}\frac{(-1)^n}{2n+1} = -\frac{\pi}{4} \).
\end{center}

Vérifions maintenant l'intégrabilité de la fonction \( f \) sur \( ]0,+\infty[ \). La fonction \( f \) est continue sur \( ]0,+\infty[ \) et on sait déjà que \( f \) est intégrable sur \( ]0,1] \). De plus, \( x^{3/2}f(x)\underset{x\rightarrow+\infty}{\sim}\frac{\ln x}{\sqrt{x}}\underset{x\rightarrow+\infty}{\rightarrow}0 \) et donc \( f(x)\underset{x\rightarrow+\infty}{ = }o\left(\frac{1}{x^{3/2}}\right) \). Ceci montre que la fonction \( f \) est intégrable sur \( [1,+\infty[ \) et finalement sur \( ]0,+\infty[ \).

Pour calculer \( I = \int_0^{+\infty}\frac{\ln x}{1+x^2}\;dx \), la méthode précédente ne marche plus du tout car pour \( x>1 \), \( x^n \) tend vers \( +\infty \) quand \( n \) tend vers \( +\infty \). C'est une toute autre idée qui permet d'aller au bout. On pose \( u = \frac{1}{x} \) et on obtient

\begin{center}
\( I = \int_0^{+\infty}\frac{\ln x}{1+x^2}\;dx = \int_{+\infty}^0\frac{\ln\left(\frac{1}{u}\right)}{1+\frac{1}{u^2}}\times\frac{-du}{u^2} = -\int_0^{+\infty}\frac{\ln u}{1+u^2}\;du = -I \),
\end{center}

et donc \( I = 0 \).

\begin{center}
\shadowbox{ \( \int_0^1\frac{\ln x}{1+x^2}\;dx = -\frac{\pi}{4} \) et \( \int_0^{+\infty}\frac{\ln x}{1+x^2}\;dx = 0 \). }
\end{center}

exercices.enonce:
\begin{enumerate}
		\item Montrer que pour \( x \) réel de \( [0,1[ \), \( -\ln(1-x) = \sum_{n = 1}^{+\infty}\frac{x^n}{n} \).

		\item Montrer que \( \int_0^1\frac{\ln(t)\ln(1-t)}{t}\;dt = \sum_{n = 1}^{+\infty}\frac{1}{n^3} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( x\in[0,1[ \). Pour tout réel \( t \) de \( [0,x] \), on a \( \frac{1}{1-t} = \sum_{n = 0}^{+\infty}t^n \). Maintenant, pour tout réel \( t\in[0,x] \) et tout entier naturel \( n \), on a \( |t|^n\le x^n \). Puisque la série numérique de terme général \( x^n \) converge, on en déduit que la série de fonctions de terme général \( t\mapsto t^n \) converge normalement et donc uniformément sur le segment \( [0,x] \). D'après le théorème d'intégration terme à terme sur un segment, on peut affirmer que

\begin{center}
	\( -\ln(1-x) = \int_0^x\frac{1}{1-t}\;dt = \sum_{n = 0}^{+\infty}\int_0^xt^n\;dt = \sum_{n = 0}^{+\infty}\frac{x^{n+1}}{n+1} = \sum_{n = 1}^{+\infty}\frac{x^n}{n} \).
\end{center}

\begin{center}
	\shadowbox{ \( \forall t \in[0,1[ \), \( -\ln(1-t) = \sum_{n = 1}^{+\infty}\frac{t^n}{n} \). }
\end{center}

\item Par suite, pour \( t\in]0,1[ \),

\begin{center}
	\( \frac{\ln(t)\ln(1-t)}{t} = -\sum_{n = 1}^{+\infty}\frac{t^{n-1}\ln t}{n} \).
\end{center}

Pour \( t\in]0,1[ \), posons \( f(t) = \frac{\ln(t)\ln(1-t)}{t} \) puis pour \( t\in]0,1] \) et \( n\in\Nn^* \), posons \( f_n(t) = -\frac{t^{n-1}\ln t}{n} \).

Soit \( n\in\Nn^* \). La fonction \( f_n \) est continue sur \( ]0,1] \) et négligeable devant \( \frac{1}{\sqrt{t}} \) quand \( t \) tend vers \( 0 \). La fonction \( f_n \) est donc intégrable sur \( ]0,1] \). En particulier, la fonction \( f_n \) est donc intégrable sur \( ]0,1[ \). Calculons alors \( \int_0^1f_n(t)\;dt \).

Soit \( a\in]0,1[ \). Les deux fonctions \( t\mapsto\frac{t^n}{n} \) et \( t\mapsto-\ln t \) sont de classe \( C^1 \) sur le segment \( [a,1] \). On peut donc effectuer une intégration par parties et on obtient

\begin{center}
	\( \int_a^1t^{n-1}(-\ln t)\;dt = \left[-\frac{t^n\ln t}{n}\right]_a^1+\frac{1}{n}\int_a^1t^{n-1}\;dt = \frac{a^n\ln a}{n}+\frac{1}{n^2}(1-a^n) \).
\end{center}

Quand \( a \) tend vers \( 0 \), on obtient \( \int_0^1-t^{n-1}\ln t\;dt = \frac{1}{n^2} \) et donc \( \int_0^1f_n(t)\;dt = \frac{1}{n^3} \). Puisque la fonction \( f_n \) est positive sur \( ]0,1[ \), on a encore \( \int_0^1|f_n(t)|\;dt = \frac{1}{n^3} \). On en déduit que la série numérique de terme général \( \int_0^1|f_n(t)|\;dt \) converge.

En résumé,

\textbullet chaque fonction \( f_n \) est continue par morceaux et intégrable sur \( ]0,1[ \),

\textbullet la séries de fonctions de terme général \( f_n \), \( n\in\Nn^* \), converge simplement vers la fonction \( f \) sur \( ]0,1[ \) et la fonction \( f \)

est continue sur \( ]0,1[ \),

\textbullet \( \sum_{n = 1}^{+\infty}\int_0^1|f_n(t)|\;dt<+\infty \).

D'après un théorème d'intégration terme à terme,

\begin{center}
	\( \int_0^1\frac{\ln(t)\ln(1-t)}{t}\;dt = \sum_{n = 1}^{+\infty}\int_0^1\frac{-t^{n-1}\ln t}{n}\;dt = \sum_{n = 1}^{+\infty}\frac{1}{n^3} \).
\end{center}

\begin{center}
	\shadowbox{ \( \int_0^1\frac{\ln(t)\ln(1-t)}{t}\;dt = \sum_{n = 1}^{+\infty}\frac{1}{n^3} \). }
\end{center}
\end{enumerate}

\textbf{Existence de l'intégrale.} Soit \( x\in\Rr \). La fonction \( f : t\mapsto\frac{\cos(xt)}{\ch t} \) est continue sur \( [0,+\infty[ \). De plus, pour tout réel positif \( t \), \( |f(t)|\le\frac{1}{\ch t} \) et donc \( |f(t)|\underset{t\rightarrow+\infty}{\sim}\frac{2}{e^t}\underset{t\rightarrow+\infty}{ = }o\left(\frac{1}{t^2}\right) \). On en déduit que la fonction \( f \) est intégrable sur \( [0,+\infty[ \).

\begin{center}
Pour tout réel \( x \), \( \int_0^{+\infty}\frac{\cos(xt)}{\ch t}\;dt \) existe.
\end{center}

\textbf{Convergence de la série.} Soit \( x\in\Rr \). Pour \( n\in\Nn \), posons \( u_n(x) = \frac{2n+1}{(2n+1)^2+x^2} \). Pour \( n\in\Nn \),

\begin{align*}\ensuremath u_n(x)-u_{n+1}(x) & =\frac{2n+1}{(2n+1)^2+x^2}-\frac{2n+3}{(2n+3)^2+x^2}=\frac{(2n+1)((2n+3)^2+x^2)-(2n+3)((2n+1)^2+x^2)}{((2n+1)^2+x^2)((2n+3)^2+x^2)} \\
& =\frac{2(2n+1)(2n+3)-2x^2}{((2n+1)^2+x^2)((2n+3)^2+x^2)}.
\end{align*}

Puisque le numérateur de cette dernière expression tend vers \( +\infty \) quand \( n \) tend vers \( +\infty \), cette expression est positive pour \( n \) grand. On en déduit que la suite \( (u_n(x)) \) décroît à partir d'un certain rang. D'autre part, \( \lim_{n \rightarrow +\infty}u_n(x) = 0 \).

On en déduit que la série de terme général \( (-1)^nu_n(x) \) converge en vertu du critère spécial aux séries alternées.

\begin{center}
Pour tout réel \( x \), la série de terme général \( (-1)^n\frac{2n+1}{(2n+1)^2+x^2} \) converge.
\end{center}

\textbf{Egalité de l'intégrale et de la somme de la série.} Soit \( n\in\Nn \). Pour \( t\in]0,+\infty[ \), on a \( e^{-t}\in]0,1[ \) et donc

\begin{align*}\ensuremath
\frac{\cos(xt)}{\ch t} & =\frac{2\cos(xt)e^{-t}}{1+e^{-2t}}=2\cos(xt)e^{-t}\sum_{k=0}^n(-1)^ke^{-2kt}+(-1)^{n+1}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}} \\
& =2\sum_{k=0}^n(-1)^k\cos(xt)e^{-(2k+1)t}+(-1)^{n+1}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}}.
\end{align*}

Maintenant, pour chaque \( k\in\Nn \), la fonction \( t\mapsto\cos(xt)e^{-(2k+1)t} \) est intégrable sur \( [0,+\infty[ \) car continue sur \( [0,+\infty[ \) et négligeable devant \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \). On en déduit encore que la fonction \( t\mapsto (-1)^{n+1}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}} \) est intégrable sur \( [0,+\infty[ \) puis que

\begin{center}
\( \forall n\in\Nn \), \( \int_0^{+\infty}\frac{\cos(xt)}{\ch t}\;dt = 2\sum_{k = 0}^n(-1)^k\int_0^{+\infty}\cos(xt)e^{-(2k+1)t}\;dt+(-1)^{n+1}\int_0^{+\infty}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}}\;dt \).
\end{center}

Ensuite, \( \left|\int_0^{+\infty}(-1)^{n+1}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}}\;dt\right|\le\int_0^{+\infty}e^{-(2n+3)t}\;dt = \frac{1}{2n+3} \), et donc \( \lim_{n \rightarrow +\infty}(-1)^{n+1}\frac{\cos(xt)e^{-(2n+3)t}}{1+e^{-2t}}\;dt = 0 \) puis

\begin{center}
\( \int_0^{+\infty}\frac{\cos(xt)}{\ch t}\;dt = 2\sum_{n = 0}^{+\infty}(-1)^n\int_0^{+\infty}\cos(xt)e^{-(2n+1)t}\;dt \).
\end{center}

Soit \( n\in\Nn \).

\begin{align*}\ensuremath
\int_0^{+\infty}\cos(xt)e^{-(2n+1)t}\;dt & =\text{Re}\left(\int_0^{+\infty}e^{ixt}e^{-(2n+1)t}\;dt\right)=\text{Re}\left(\int_0^{+\infty}e^{(-(2n+1)+ix)t}\;dt\right)                                                                 \\
& =\text{Re}\left(\left[\frac{e^{(-(2n+1)+ix)t}}{-(2n+1)+ix}\right]_0^{+\infty}\right)=\text{Re}\left(\frac{1}{(2n+1)-ix}\left(1-\lim_{t \rightarrow +\infty}e^{(-(2n+1)+ix)t}\right)\right) \\
& =\text{Re}\left(\frac{1}{(2n+1)-ix}\right)\;(\text{car}\;\left|e^{(-(2n+1)+ix)t}\right|=e^{-(2n+1)t}\underset{n\rightarrow+\infty}{\rightarrow}0)                                          \\
& =\text{Re}\left(\frac{2n+1+ix}{(2n+1)^2+x^2}\right)=\frac{2n+1}{(2n+1)^2+x^2}.
\end{align*}

On a enfin montré que

\begin{center}
\shadowbox{ \( \int_0^{+\infty}\frac{\cos(xt)}{\ch t}\;dt = 2\sum_{n = 0}^{+\infty}(-1)^n\frac{2n+1}{(2n+1)^2+x^2} \). }
\end{center}

exercices.enonce:
Déterminer \( \lim_{n \rightarrow +\infty}\left(
	\begin{array}{cc}
		1           & - \frac{a}{n} \\
		\frac{a}{n} & 1
	\end{array}
	\right)^n \) (\( a \) réel strictement positif donné).

exercices.correction:
Soit \( a\in\Rr \). Pour \( n\in\Nn^* \), on pose \( A_n = \left(
\begin{array}{cc}
1           & - \frac{a}{n} \\
\frac{a}{n} & 1
\end{array}
\right) \).

Soit \( n\in\Nn^* \). On peut écrire \( A_n = \sqrt{1+ \frac{a^2}{n^2}}\left(
\begin{array}{cc}
\frac{1}{\sqrt{1+ \frac{a^2}{n^2}}}   & - \frac{a/n}{\sqrt{1+ \frac{a^2}{n^2}}} \\
\frac{a/n}{\sqrt{1+ \frac{a^2}{n^2}}} & \frac{1}{\sqrt{1+ \frac{a^2}{n^2}}}
\end{array}
\right) \). Les sommes des carrés des deux nombres \( \frac{1}{\sqrt{1+ \frac{a^2}{n^2}}} \) et \( \frac{a/n}{\sqrt{1+ \frac{a^2}{n^2}}} \) est égale à \( 1 \). Donc il existe un réel \( \theta_n\in]-\pi,\pi] \) tel que \( \cos(\theta_n) = \frac{1}{\sqrt{1+ \frac{a^2}{n^2}}} \) et \( \sin(\theta_n) = \frac{a/n}{\sqrt{1+ \frac{a^2}{n^2}}} \). De plus, \( \cos(\theta_n)>0 \) et \( \sin(\theta_n)>0 \) et donc on peut prendre

\begin{center}
\( \theta_n = \arctan\left( \frac{a}{n}\right)\in\left]0, \frac{\pi}{2}\right[ \).
\end{center}

Pour \( n\in\Nn^* \), on a alors

\begin{center}
\( A_n^n = \left(\sqrt{1+ \frac{a^2}{n^2}}\right)^n\left(
\begin{array}{cc}
	\cos(\theta_n) & -\sin(\theta_n) \\
	\sin(\theta_n) & \cos(\theta_n)
\end{array}
\right)^n = \left(1+ \frac{a^2}{n^2}\right)^{n/2}\left(
\begin{array}{cc}
	\cos(n\theta_n) & -\sin(n\theta_n) \\
	\sin(n\theta_n) & \cos(n\theta_n)
\end{array}
\right) \).
\end{center}

Maintenant, \( \left(1+ \frac{a^2}{n^2}\right)^{n/2} = \text{exp}\left( \frac{n}{2}\ln\left(1+ \frac{a^2}{n^2}\right)\right)\underset{n\rightarrow+\infty}{ = }\text{exp}\left( \frac{a^2}{2n}+o\left( \frac{1}{n}\right)\right)\underset{n\rightarrow+\infty}{ = }1+o(1) \).

D'autre part, \( n\theta_n = n\arctan\left( \frac{a}{n}\right)\underset{n\rightarrow+\infty}{ = }n\times \frac{a}{n} = a \). Donc

\begin{center}
\( \lim_{n \rightarrow +\infty}A_n^n = 1.\left(
\begin{array}{cc}
	\cos(a) & -\sin(a) \\
	\sin(a) & \cos(a)
\end{array}
\right) = \left(
\begin{array}{cc}
	\cos(a) & -\sin(a) \\
	\sin(a) & \cos(a)
\end{array}
\right) \).
\end{center}

\begin{center}
\shadowbox{ \( \forall a>0 \), \( \lim_{n \rightarrow +\infty}\left(
	\begin{array}{cc}
		1           & - \frac{a}{n} \\
		\frac{a}{n} & 1
	\end{array}
	\right)^n = \left(
	\begin{array}{cc}
		\cos(a) & -\sin(a) \\
		\sin(a) & \cos(a)
	\end{array}
	\right) \). }
	\end{center}

exercices.enonce:
Soit \( A = \left(
	\begin{array}{cc}
		4/3 & -5/6 \\
		5/3 & -7/6
	\end{array}
	\right) \). Convergence et somme de la série de terme général \( A^n \), \( n\in\Nn \).

exercices.correction:
\( \chi_A = \left|
\begin{array}{cc}
4/3-X & -5/6   \\
5/3   & -7/6-X
\end{array}
\right| = X^2- \frac{1}{6}X- \frac{1}{6} = \left(X- \frac{1}{2}\right)\left(X+ \frac{1}{3}\right) \). Par suite, \( A = PDP^{-1} \) où \( D = \text{diag}\left( \frac{1}{2},- \frac{1}{3}\right) \), \( P = \left(
\begin{array}{cc}
1 & 1 \\
1 & 2
\end{array}
\right) \) et donc \( P^{-1} = \left(
\begin{array}{cc}
2  & -1 \\
-1 & 1
\end{array}
\right) \).

Soit \( n\in\Nn \).

\begin{center}
\( \sum_{k = 0}^nA^k = P\left(\sum_{k = 0}^nD^k\right)P^{-1} = P\;\text{diag}\left(\sum_{k = 0}^n\left( \frac{1}{2}\right)^k,\sum_{k = 0}^n\left(- \frac{1}{3}\right)^k\right)P^{-1} \).
\end{center}

Puisque \( \frac{1}{2} \) et \( - \frac{1}{3} \) sont dans \( ]-1,1[ \), les séries numériques de termes généraux respectifs \( \left( \frac{1}{2}\right)^k \) et \( \left(- \frac{1}{3}\right)^k \) convergent. Il en est de même de la série de terme général \( D^k \). Maintenant, l'application \( M\mapsto PMP^{-1} \), converge est continue car linéaire sur un espace de dimension finie et on en déduit que la série de terme général \( A^k \) converge. De plus,

\begin{align*}\ensuremath
\sum_{n=0}^{+\infty}A^n & =\sum_{n=0}^{+\infty}PD^nP^{-1}=P\left(\sum_{n=0}^{+\infty}D^n\right)P^{-1}\;(\text{par continuité de l'application}\;M\mapsto PMP^{-1})                                                                                \\
& =P\;\text{diag}\left(\sum_{n=0}^{+\infty}\left( \frac{1}{2}\right)^n,\sum_{n=0}^{+\infty}\left(- \frac{1}{3}\right)^n\right)P^{-1}=P\;\text{diag}\left( \frac{1}{1- \frac{1}{2}}, \frac{1}{1+ \frac{1}{3}}\right)P^{-1} \\
& =\left(
\begin{array}{cc}
	1 & 1 \\
	1 & 2
\end{array}
\right)\left(
\begin{array}{cc}
	2 & 0           \\
	0 & \frac{3}{4}
\end{array}
\right)\left(
\begin{array}{cc}
	2  & -1 \\
	-1 & 1
\end{array}
\right)=\left(
\begin{array}{cc}
	\rule[-4mm]{0mm}{0mm}2 & \frac{3}{4} \\
	2                      & \frac{3}{2}
\end{array}
\right)\left(
\begin{array}{cc}
	2  & -1 \\
	-1 & 1
\end{array}
\right)=\left(
\begin{array}{cc}
	\rule[-4mm]{0mm}{0mm} \frac{13}{4} & - \frac{5}{4} \\
	\frac{5}{2}                        & - \frac{1}{2}
\end{array}
\right).
\end{align*}

\begin{center}
\shadowbox{ \( \sum_{n = 0}^{+\infty}A^n = \left(
	\begin{array}{cc}
		\rule[-4mm]{0mm}{0mm} \frac{13}{4} & - \frac{5}{4} \\
		\frac{5}{2}                        & - \frac{1}{2}
	\end{array}
	\right) \). }
	\end{center}

	\textbf{Remarque.} D'après l'exercice suivant, la matrice obtenue est \( (I-A)^{-1} \).

Soit \( A\in\mathcal{M}_p(\Cc) \) telle que \( \|A\|<1 \). Pour tout entier naturel \( n \), on a \( \|A^n\|\le\|A\|^n \). Puisque \( \|A\|<1 \), la série numérique de terme général \( \|A\|^n \), \( n\in\Nn \), converge. Il en est de même de la série de terme général \( \|A^n\| \) et donc la série de terme général \( A^n \), \( n\in\Nn \), converge absolument. Puisque \( \mathcal{M}_p(\Cc) \) est complet en tant que \( \Cc \) espace de dimension finie, on en déduit que la série de terme général \( A^n \), \( n\in\Nn \), converge. De plus,

	\begin{align*}\ensuremath (I-A)\sum_{n=0}^{+\infty}A^n & =(I-A)\lim_{n \rightarrow +\infty}\left(\sum_{k=0}^nA^k\right)=\lim_{n \rightarrow +\infty}\left((I-A)\sum_{k=0}^nA^k\right)\;(\text{par continuité de l'application}\;M\mapsto(I-A)M) \\
& =\lim_{n \rightarrow +\infty}(I-A^{n+1})=I\;(\lim_{n \rightarrow +\infty}A^{n+1}=0\;\text{car}\;\forall n\in\Nn,\;\|A^{n+1}\|\le\|A\|^{n+1}).
\end{align*}

Ainsi, la matrice \( I-A \) est inversible à droite et donc inversible et de plus, \( (I-A)^{-1} = \sum_{n = 0}^{+\infty}A^n \). On en déduit encore

\begin{center}
\( \|(I-A)^{-1}-(I+A)\| = \left\|\sum_{n = 2}^{+\infty}A^n\right\|\le\sum_{n = 2}^{+\infty}\|A\|^n = \frac{\|A\|^2}{1-\|A\|} \).
\end{center}

