\right)                                                                                                                                                                                                            \\
& + \frac{1}{4}\left(\ln\left(1+ \frac{t}{2}\right)+ \frac{2t}{2-t}+3\ln\left(1- \frac{t}{2}\right)\right)\left(
\begin{array}{ccc}
