		\item Soit \( D = \{(x,y)\in\Rr^2,\ |x|<1\} \) et \( F(x,y) = \sum_{n = 1}^{+\infty} a_n(y)x^n \). Montrer que \( F \), \( \frac{\partial F}{\partial x} \) et \( \frac{\partial F}{\partial y} \) existent en tout point de \( D \).
	\end{enumerate}

Soit \( (f_n) \) une suite de fonctions \( [a,b]\to[c,d] \) continues, bijectives, strictement croissantes, convergeant simplement vers une fonction \( f \) : \( [a,b]\to[c,d] \) elle aussi continue, bijective strictement croissante.

	\begin{enumerate}
		\item Montrer qu'il y a convergence uniforme (deuxième théorème de Dini, considérer une subdivision de \( [a,b] \)).

		\item Montrer que les fonctions réciproques \( f_n^{-1} \) convergent simplement vers une fonction \( g \) et que \( g = f^{-1} \).

		\item Montrer que \( (f_n^{-1}) \) converge uniformément vers \( f^{-1} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item

\item soit \( y\in{[c,d]} \) et \( x_n = f_n^{-1}(y) \). La suite \( (x_n) \) admet au plus une valeur d'adhérence, \( x = f^{-1}(y) \).

\item
\end{enumerate}

\begin{enumerate}
\item Il y a convergence normale sur tout intervalle \( [a,+\infty[ \) avec \( a>0 \). Il n'y a pas convergence normale au voisinage de \( 0 \) car \( \sup\Bigl\{\frac{xe^{-nx}}{\ln n},\ x\ge 0\Bigr\} = \frac1{en\ln n} \) atteint pour \( x = \frac1n \) et \( \sum\frac1{n\ln n} \) diverge (série de Bertrand). Par contre il y a convergence uniforme sur \( [0,+\infty[ \) car
\[
0\le \sum_{k = n}^\infty f_k(x) \le \frac1{\ln n}\sum_{k = n}^\infty xe^{-kx}
= \frac{xe^{-nx}}{\ln n(1-e^{-x})} \le \frac{\sup\{t/(1-e^{-t}),\ t\ge 0\}}{\ln n}.
\]

\item

\item Lorsque \( x\to0^+ \), \( \frac{S(x)-S(0)}x = \sum_{n = 2}^\infty\frac{e^{-nx}}{\ln n}
\to \sum_{n = 2}^\infty\frac1{\ln n} = +\infty \) par convergence monotone.

\item
\end{enumerate}

exercices.enonce:
Soit \( S(t) = \sum_{n = 1}^\infty \frac{t^n}{1-t^n} \).

	\begin{enumerate}
		\item Pour quelles valeurs de \( t \), \( S \) est-elle définie ? Est-elle continue ?

		\item Montrer qu'au voisinage de \( 1^- \) on a \( S(t) = -\frac{\ln(1-t)}{1-t} + O\Bigl(\frac1{1-t}\Bigr) \). On pourra développer \( \ln(1-t) \) en série entière.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( -1<t<1 \).

\item Pour \( 0\le t<1 \) et \( n\ge 2 \) on a :
\begin{align*}
	(1-t)\frac{t^n}{1-t^n}
	& = \frac{t^n}{1+t+\dots+t^{n-1}}                                                                \\
	& = \frac{t^n}{n} + \frac{t^n((1-t) + (1-t^2) + \dots + (1-t^{n-1}))}{n(1+t+\dots+t^{n-1})}      \\
	& = \frac{t^n}{n} + \frac{(t^n-t^{n+1})((n-1) + (n-2)t + \dots + t^{n-2})}{n(1+t+\dots+t^{n-1})}
\end{align*}
d'où \( 0 \le (1-t)\frac{t^n}{1-t^n} - \frac{t^n}{n} \le \frac{n-1}{n}(t^n-t^{n+1}) \le t^n-t^{n+1} \) (vrai aussi si \( n = 1 \)) et en sommant :
\[
0\le (1-t)S(t) + \ln(1-t) \le 1.
\]
\end{enumerate}

exercices.enonce:
On pose \( \phi (x) = d(x,\Zz) = \inf\{ |x-n| \text{ tel que } n\in\Zz\} \).
	\begin{enumerate}
		\item Montrer que \( f \) : \( \Rr\ni x \mapsto \sum_{n = 0}^{+\infty} (\frac34)^n\phi (4^nx) \) est définie et continue.

		\item Montrer que \( \phi \) est lipschitzienne. Que peut-on en déduire pour \( f \)?

		\item Montrer que \( f \) n'est dérivable en aucun point.

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item La série converge normalement et \( \phi \) est continue.

\item \( \phi \) est \( 1 \)-lipschitzienne, mais on ne peut rien en déduire pour \( f \):

pour \( N \) fixé et \( 0<h\le \frac1{2.4^N} \), on a \( |f(h)-f(0)| = f(h) \ge \sum_{n = 1}^N3^nh = \frac{3^{N+1}-3}2h \) donc \( f \) n'est pas lipschitzienne au voisinage de \( 0 \).

\item D'après ce qui précède, le taux d'accroissement de \( f \) en \( 0 \) est arbitrairement grand, donc \( f \) n'est pas dérivable en \( 0 \). On montre de même que \( f \) n'est pas dérivable en \( x\in\Rr \).
\end{enumerate}

exercices.enonce:
Soit \( f : \Rr \to \Rr \) continue et \( 2\pi \)-périodique. Pour \( n\in\Nn^* \), on pose \( F_n(x) = \frac{1}{n} \int_{t = 0}^nf(x+t)f(t)\,d t \).

	\begin{enumerate}
		\item Montrer que la suite \( (F_n) \) converge vers une fonction \( F \) que l'on précisera.

		\item Nature de la convergence ?

		\item Prouver \( \|F\|_{\infty} = |F(0)| \).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( k = \lfloor n/2\pi\rfloor \). On a \( F_n(x) = \frac{2k\pi}n \int_{t = 0}^{2\pi}f(x+t)f(t)\,d t + \frac1n \int_{t = 2k\pi}^nf(x+t)f(t)\,d t
\to \int_{t = 0}^{2\pi}f(x+t)f(t)\,d t \) lorsque \( n\to\infty \).

\item Uniforme.

\item Cauchy-Schwarz.
\end{enumerate}

exercices.enonce:
On pose pour \( x\in\Rr \): \( f(x) = \sum_{n = 1}^\infty \frac{(-1)^{n-1}}{\sqrt{n^2+x^2}} \).

	\begin{enumerate}
		\item Déterminer \( \lim_{x\to\infty}f(x) \).

		\item Chercher un équivalent de \( f(x) \) en \( +\infty \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item CSA : \( 0\le f(x)\le \frac1{\sqrt{1+x^2}} \) donc \( f(x)\to 0 \) lorsque \( x\to+\infty \).

\item {\( xf(x) \)}
\(  = \sum_{p = 0}^\infty \frac{x}{\sqrt{(2p+1)^2+x^2}} - \frac{x}{\sqrt{(2p+2)^2+x^2}} \)\par \(  = \sum_{p = 0}^\infty \int_{t = 2p+1}^{2p+2}\frac{xt}{(t^2+x^2)^{3/2}}\,d t \)\par \(  = \sum_{p = 0}^\infty \int_{u = (2p+1)/x}^{(2p+2)/x}\frac{u}{(u^2+1)^{3/2}}\,d u \).\par

On a \( \int_{u = 0}^\infty\frac u{(u^2+1)^{3/2}}\,d u = 1 = a + b \) avec :

\( a = \sum_{p = 0}^\infty \int_{u = (2p)/x}^{(2p+1)/x}\frac{u}{(u^2+1)^{3/2}}\,d u \) et \( b = \sum_{p = 0}^\infty \int_{u = (2p+1)/x}^{(2p+2)/x}\frac{u}{(u^2+1)^{3/2}}\,d u = xf(x) \).

\( h \) : \( u \mapsto\frac{u}{(u^2+1)^{3/2}} \) est croissante sur \( [0,\sqrt{\frac12}] \) et décroissante sur \( [\sqrt{\frac12},+\infty[ \) donc \( |a-b| \le \frac{3\|h\|_\infty}x \), et \( xf(x)\to \frac12 \) lorsque \( x\to+\infty \).
\end{enumerate}

exercices.enonce:
On note \( R \) l'ensemble des fractions rationnelles continues sur \( [0,1] \) et pour \( m,n\in\Nn \):

	\( R_{m,n} = \{f\in R\text{ tel que }\exists\ P,Q\in\Rr[X]\text{ tels que }\deg(P)\le m,\ \deg(Q)\le n\text{ et }f = P/Q\} \).

	\begin{enumerate}
		\item \( R \) est-il un espace vectoriel ? Si oui en trouver une base. Même question pour \( R_{m,n} \).

		\item Soient \( m,n \) fixés. On note \( d = \inf\{\|g-f\|,\ f\in R_{m,n}\} \) où \( g \) désigne une fonction continue de \( [0,1] \) dans \( \Rr \) et \( {\|h\| = \sup\{|h(x)|,\ x\in[0,1]\}} \). Montrer qu'il existe \( r_0\in R_{m,n} \) tel que \( \|g-r_0\| = d \).

	\end{enumerate}

\begin{enumerate}
		\item Soit \( (f_n) \) une suite de fonctions de classe \( \mathcal{C}^1 \) sur \( [a,b] \) telle que \( (f_n') \) converge uniformément vers \( g \) et il existe \( x_1 \) tel que \( (f_n(x_1)) \) converge. Montrer que \( (f_n) \) converge uniformément sur \( [a,b] \) vers \( f \) telle que \( f' = g \).

		\item Soit \( (f_n) \) une suite de fonctions de classe \( \mathcal{C}^p \) sur \( [a,b] \) telle que \( (f_n^{(p)}) \) converge uniformément vers \( g \) et il existe \( x_1,\dots,x_p \) distincts tels que \( (f_n(x_i)) \) converge. Montrer que \( (f_n) \) converge uniformément sur \( [a,b] \) vers \( f \) telle que \( f^{(p)} = g \).
	\end{enumerate}

exercices.correction:
Soit \( x>0 \). Pour \( n\in\Nn^* \), \( n^2e^{-x\sqrt{n}} = e^{-x\sqrt{n}+2\ln n}\underset{n\rightarrow+\infty}{ = }o(1) \) d'après un théorème de croissances comparées. On en déduit que \( e^{-x\sqrt{n}}\underset{n\rightarrow+\infty}{ = }o\left(\frac{1}{n^2}\right) \) et donc que la série de terme général \( e^{-x\sqrt{n}} \) converge. Ainsi, \( f \) est bien définie sur \( ]0,+\infty[ \).

Soit \( x\in]0,+\infty[ \). La fonction \( t\mapsto e^{-x\sqrt{t}} \) est décroissante sur \( [0,+\infty[ \). Donc, \( \forall k\in\Nn \), \( \int_k^{k+1}e^{-x\sqrt{t}}\;dt\le e^{-x\sqrt{k}} \) et \( \forall k\in\Nn^* \), \( e^{-x\sqrt{k}}\le\int_{k-1}^ke^{-x\sqrt{t}}\;dt \). En sommant ces inégalités, on obtient

\begin{center}
\( \forall x\in]0,+\infty[ \), \( \int_0^{+\infty}e^{-x\sqrt{t}}\;dt\le f(x)\le1+\int_0^{+\infty}e^{-x\sqrt{t}}\;dt \)\quad\( (*) \).
\end{center}

Soit \( x\in]0,+\infty[ \). En posant \( u = x\sqrt{t} \) et donc \( t = \frac{u^2}{x^2} \) puis \( dt = \frac{2u}{x^2}\;du \), on obtient

\begin{center}
\( \int_0^{+\infty}e^{-x\sqrt{t}}\;dt = \frac{2}{x^2}\int_0^{+\infty}ue^{-u}\;du = \frac{2}{x^2}\times\Gamma(2) = \frac{2}{x^2} \).
\end{center}

L'encadrement \( (*) \) s'écrit alors

\begin{center}
\( \forall x\in]0,+\infty[ \), \( \frac{2}{x^2}\le f(x)\le1+\frac{2}{x^2} \).
\end{center}

Comme \( \displaystyle\lim_{\substack{x\rightarrow0\\
	x>0}}\frac{2}{x^2} = +\infty \), on a montré que

	\begin{center}
\shadowbox{ \( \sum_{n = 0}^{+\infty}e^{-x\sqrt{n}}\underset{x\rightarrow0,\;x>0}{\sim}\frac{2}{x^2} \). }
\end{center}

Soit \( x\in]-1,1[ \). Pour \( n\in\Nn^* \), \( \left|x^{n^2}\right| = |x|^{n^2}\le|x|^n \). Puisque la série numérique de terme général \( |x|^n \) converge, on en déduit que la série de terme général \( x^{n^2} \) est absolument convergente et en particulier convergente. Donc, \( f \) est bien définie sur \( ]-1,1[ \).

Soit \( x\in]0,1[ \). La fonction \( t\mapsto x^{t^2} = e^{t^2\ln x} \) est décroissante sur \( [0,+\infty[ \). Donc, \( \forall k\in\Nn^* \), \( \int_k^{k+1}x^{t^2}\;dt\le x^{k^2}\le\int_{k-1}^kx^{t^2}\;dt \). En sommant ces inégalités, on obtient

\begin{center}
\( \forall x\in]0,1[ \), \( \int_1^{+\infty}x^{t^2}\;dt\le f(x)\le\int_0^{+\infty}x^{t^2}\;dt \)\quad\( (*) \).
\end{center}

Soit \( x\in]0,1[ \). En posant \( u = t\sqrt{-\ln x} \), on obtient

\begin{center}
\( \int_0^{+\infty}x^{t^2}\;dt = \int_0^{+\infty}e^{t^2\ln x}\;dt = \int_0^{+\infty}e^{-(t\sqrt{-\ln x})^2}\;dt = \frac{1}{\sqrt{-\ln x}}\int_0^{+\infty}e^{-u^2}\;du = \frac{\sqrt{\pi}}{2\sqrt{-\ln x}} \).
\end{center}

L'encadrement \( (*) \) s'écrit alors

\begin{center}
\( \forall x\in]0,1[ \), \( \frac{\sqrt{\pi}}{2\sqrt{-\ln x}}-\int_0^1x^{t^2}\;dt\le f(x)\le\frac{\sqrt{\pi}}{2\sqrt{-\ln x}} \).
\end{center}

Comme \( \displaystyle\lim_{\substack{x\rightarrow1\\
	x<1}}\frac{\sqrt{\pi}}{2\sqrt{-\ln x}} = +\infty \), on a montré que

	\begin{center}
\shadowbox{ \( \sum_{n = 1}^{+\infty}x^{n^2}\underset{x\rightarrow1,\;x<1}{\sim}\frac{\sqrt{\pi}}{2\sqrt{-\ln x}} \). }
\end{center}

exercices.enonce:
On considère les suites \( (a_n) \) et \( (b_n) \) définies par : \( a_n = \frac{\cos(n\pi/3)}{n^{1/3}} \), \( b_n = \sin(a_n) \).
	\smallskip
	\begin{enumerate}
		\item Déterminer les rayons de convergence des séries \( \sum a_nx^n \) et \( \sum b_nx^n \).

		\item Déterminer la nature de \( \sum a_nx^n \) et \( \sum b_nx^n \) en fonction de \( x \).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( (a_n) \) est bornée et \( (na_n) \) ne l'est pas, donc \( R_a = 1 \). \( |b_n|\sim|a_n| \) donc \( R_b = 1 \).

\item Il y a doute seulement pour \( x = \pm 1 \). Le critère de convergence d'Abel (hors programme) s'applique, \( \sum a_nx^n \) converge si \( x = \pm1 \). \( b_n = a_n -\frac16a_n^3 + O(n^{-5/3}) \) et le critère d'Abel s'applique aussi à \( \sum a_n^3x^n \) (linéariser le \( \cos^3 \)), il y a aussi convergence pour \( x = \pm 1 \).

Résolution conforme au programme : regrouper par paquets de six termes.
\end{enumerate}

exercices.enonce:
Soit \( \sum a_nz^n \) une série entière de rayon de convergence \( R > 0 \). Déterminer les rayons de convergence des séries :

	\begin{enumerate}
		\item \( \sum a_n^2 z^n \).

		\item \( \sum \frac{a_n}{n!} z^n \).

		\item \( \sum \frac{n!\,a_n}{n^n}z^n \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( R' = R^2 \).

\item \( R' = \infty \).

\item \( R' = eR \).
\end{enumerate}

exercices.enonce:
Soit \( a(z) = \sum_{n = 0}^\infty a_nz^n \) une série entière de rayon de convergence infini et \( \rho > 0 \).

	On définit la série entière \( b(z) = \sum_{n = 0}^\infty b_nz^n \) de sorte que \( (z-\rho)b(z) = a(z) \) en cas de convergence de \( b(z) \).

	\begin{enumerate}
		\item Prouver l'existence et l'unicité des coefficients \( b_n \).

		\item Quel est le rayon de convergence de \( b(z) \) ?

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Série produit de \( a(z) \) et \( \frac1{z-\rho} \Rightarrow b_n = \sum_{k = 0}^\infty a_{k+n+1}\rho^k \).

\item Si \( a(\rho) \ne 0 \) : \( b(z) \) converge pour \( |z|<\rho \) et tend vers l'infini pour \( z\to\rho^- \Rightarrow R = \rho \).\par Si \( a(\rho) = 0 \) : \( \forall\ r > \rho \), \( |a_p| \le \frac M{r^p} \Rightarrow |b_n| \le \frac M{r^n(r-\rho)} \Rightarrow R = \infty \).
\end{enumerate}

exercices.enonce:
Pour \( n\in\Nn \) et \( x\in\Rr \) on pose \( u_n(x) = \Bigl(\frac{x(1-x)}2\Bigr)^{4^n} \).

	\begin{enumerate}
		\item Déterminer le domaine de convergence de la série \( \sum_{n = 0}^\infty u_n(x) \).

		\item On développe \( u_n(x) \) par la formule du binôme : \( u_n(x) = \sum_{4^n\le k \le 2 \cdot 4^n}a_kx^k \). Montrer que le rayon de convergence de la série entière \( \sum_{k\ge 1} a_kx^k \) est égal à \( 1 \) (en convenant que les \( a_k \) non définis valent zéro).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( ]-1,2[ \).

\item Pour \( 0\le k\le 4^n \), on a \( |a_k| \le C_{4^n}^{4^n/2}\Bigm/2^{4^n} \) (atteint pour \( k = 4^n/2 \)).
Donc \(a_n\to0\) lorsque \(n\to\infty\) et si \(x>2\), alors
\(a_{3\cdot4^n/2}x^{3\cdot4^n/2}\not\to0\) lorsque \(n\to\infty\).

\end{enumerate}

\begin{enumerate}
\item Soit \( z\neq0 \). Pour \( n >e^{1/|z|} \), on a \( |z|\ln n > 1 \) et donc la suite \( ((\ln n)^nz^n) \) ne tend pas vers 0 quand \( n \) tend vers \( +\infty \). Ainsi, pour tout nombre complexe non nul \( z \), la série proposée diverge grossièrement.

\begin{center}
	\shadowbox{ \( R = 0 \). }
\end{center}

\item Soit \( z\neq0 \). Pour \( n >\frac{1}{|z|^2} \), on a \( |z|\sqrt{n}> 1 \) et donc la suite \( ((\sqrt{n})^nz^n) \) ne tend pas vers 0 quand \( n \) tend vers \( +\infty \). Pour tout nombre complexe non nul \( z \), la série proposée diverge grossièrement.

\begin{center}
	\shadowbox{ \( R = 0 \). }
\end{center}

\item D'après la formule de \textsc{Stirling}

\begin{center}
	\( (\ln(n!))^2\underset{n\rightarrow+\infty}{\sim}\ln^2\left(\left(\frac{n}{e}\right)^n\sqrt{2\pi n}\right) = \left(\left(n+\frac{1}{2}\right)\ln n -n +\ln(\sqrt{2\pi)}\right)^2\underset{n\rightarrow+\infty}{\sim}n^2\ln^2n \).
\end{center}

La série entière proposée a même rayon de convergence que la série entière associée à la suite \( (n^2\ln^2n) \). Comme \( \lim_{n \rightarrow +\infty}\frac{(n+1)^2\ln^2(n+1)}{n^2\ln^2n} = 1 \), la règle de d'\textsc{Alembert} permet d'affirmer que

\begin{center}
	\shadowbox{ \( R = 1 \). }
\end{center}

\item

\begin{center}
	\( n^4\ln\left(\frac{1}{2}\left(\ch\frac{1}{n}+\cos\frac{1}{n}\right)\right))\underset{n\rightarrow+\infty}{ = }n^4\ln\left(1+\frac{1}{24n^4}+o\left(\frac{1}{n^4}\right)\right)\underset{n\rightarrow+\infty}{ = }\frac{1}{24}+o(1) \).
\end{center}

Donc \( \left(\frac{1}{2}\left(\ch\frac{1}{n}+\cos\frac{1}{n}\right)\right)^{n^4}\underset{n\rightarrow+\infty}{\sim}e^{1/24} \) et

\begin{center}
	\shadowbox{ \( R = 1 \). }
\end{center}

\item Pour \( n\in\Nn^* \), posons \( a_n = \frac{C_{2n+2}^{n+1}}{(n+1)^{n+1}} \).

\begin{align*}\ensuremath
	\frac{a_{n+1}}{a_n} & =\frac{(2n+2)!}{(2n)!}\times\frac{n!^2}{(n+1)!^2}\times\frac{n^n}{(n+1)^{n+1}}=\frac{(2n+2)(2n+1)n^n}{(n+1)^2(n+1)^{n+1}}=\frac{1}{n+1}\times\frac{4n+2}{n+1}\times\left(1+\frac{1}{n}\right)^{-n} \\
	& \underset{n\rightarrow+\infty}{\sim}\frac{4}{ne}.
\end{align*}

et donc \( \lim_{n \rightarrow +\infty}\left|\frac{a_{n+1}}{a_n}\right| = 0 \). D'après la règle de d'\textsc{Alembert},

\begin{center}
	\shadowbox{ \( R = +\infty \). }
\end{center}

\item On a vu que \( \ln(n!)\underset{n\rightarrow+\infty}{\sim}n\ln n \). Donc la série entière proposée a même rayon de convergence que la série entière associée à la suite \( \left(\frac{(n\ln n)^a}{n!^b}\right) \). Puis

\begin{center}
	\( \frac{((n+1)\ln(n+1))^a/(n+1)!^b}{(n\ln n)^a/n!^b}\underset{n\rightarrow+\infty}{\sim}\frac{1}{n^b} \)
\end{center}

et donc, d'après la règle de d'\textsc{Alembert}

\begin{center}
	\shadowbox{ si \( b >0 \), \( R = +\infty \), si \( b = 0 \), \( R = 1 \) et si \( b < 0 \), \( R = 0 \). }
\end{center}

\item Si \( a = 0 \), \( R = +\infty \). On suppose \( a\neq0 \).

\textbullet Si \( b> 1 \), \( \frac{a^n}{1+b^n}\underset{n\rightarrow+\infty}{\sim}\left(\frac{a}{b}\right)^n \) et donc \( R = \frac{b}{a} \).

\textbullet Si \( b = 1 \), \( \frac{a^n}{1+b^n} = \frac{a^n}{2} \) et \( R = a \).

\textbullet Si \( 0\le b< 1 \), \( \frac{a^n}{1+b^n}\underset{n\rightarrow+\infty}{\sim}a^n \) et \( R = a \).

Dans tous les cas

\begin{center}
	\shadowbox{ \( R = \frac{\text{Max}(1,b)}{a} \) si \( a>0 \) et \( R = +\infty \) si \( a = 0 \). }
\end{center}
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Déterminer le rayon de convergence de la série \( \sum 2^{2n}z^{2n} \).

		\item Déterminer la limite de \( \frac{2^{2(n+1)}}{2^{2n}} \).
	\end{enumerate}

Soit \( \sum a_n z^n \) et \( \sum b_nz^n \) deux séries entières de rayon de convergence respectifs \( R_1 \) et \( R_2 \).
	\begin{enumerate}
		\item Montrer que le rayon de convergence de \( \sum(a_n+b_n)z^n \) est supérieur à \( \min(R_1,R_2) \) avec égalité si \( R_2\not=R_1 \).

		\item Montrer que le rayon de convergence de \( \sum(a_nb_n)z^n \) est supérieur à \( R_1R_2 \).
	\end{enumerate}

\begin{enumerate}
		\item Montrer l'existence de \( f(z) = \sum_{k = 1}^{\infty} kz^k \) pour \( z\in\Cc \), \( |z|<1 \).

		\item Soit \( A\in\mathcal{M}_n(\Cc) \). Montrer que \( \sum_{k = 1}^{\infty} kA^k \) converge si et seulement si les valeurs propres de \( A \) sont de module strictement inférieur à \( 1 \).

		\item La somme \( S = \sum_{k = 1}^\infty kA^k \) est-elle inversible ?

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item

\item S'il existe \( \lambda\in\mathrm{Sp}(A) \) tel que \( |\lambda|\ge 1 \) et si \( x \) est un vecteur propre associé alors \( kA^kx = k\lambda^kx\not\rightarrow0 \) donc la série diverge.

Si toutes les valeurs propres de \( A \) sont de module \( <1 \), comme \( kA^k = \sum_\lambda \lambda^kP_\lambda(k) \) où les \( P_\lambda \) sont des polynômes à coefficients matriciels, la série converge absolument.

\item \( S = \sum_{k = 0}^\infty (k+1)A^{k+1} = AS + \sum_{k = 0}^\infty A^{k+1} = AS + A(I-A)^{-1} \) donc \( S = A(I-A)^{-2} \) est inversible ssi \( A \) l'est.
\end{enumerate}

exercices.enonce:
\smallskip Soit \( A = \left(\begin{smallmatrix}1&1&1 \\1&1&0 \\1&0&0 \\\end{smallmatrix}\right)\in\mathcal{M}_3(\Rr) \).
	\begin{enumerate}
		\item Montrer que \( A \) est diagonalisable et admet trois valeurs propres réelles dont on précisera les parties entières.

		\item On pose \( t_n = \mathrm{tr}(A^n) \). Exprimer \( t_n \) en fonction de \( t_{n-1},t_{n-2},t_{n-3} \).

		\item Déterminer le rayon de convergence de la série entière \( \sum_{n = 0}^\infty t_nz^n \) et calculer sa somme.

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( \chi_A(\lambda) = -\lambda^3 + 2\lambda^2 + \lambda - 1 \). \( \chi_A(-1)>0 \), \( \chi_A(0) < 0 \), \( \chi_A(1)>0 \), \( \chi_A(2)>0 \), \( \chi_A(3)<0 \) donc \( \chi_A \) admet une racine dans chacun des intervalles \( ]-1,0[ \), \( ]0,1[ \) et \( ]2,3[ \).

\item Cayley-Hamilton : \( t_n = 2t_{n-1}+t_{n-2}-t_{n-3} \).

\item Soient \( -1<\alpha<0<\beta<1<2<\gamma<3 \) les valeurs propres de \( A \). On a \( t_nz^n = (\alpha z)^n + (\beta z)^n + (\gamma z)^n \) donc la série \( \sum_{n = 0}^\infty t_nz^n \) converge si et seulement si \( |\gamma z|<1 \) et vaut :
\[
\frac1{1-\alpha z} + \frac1{1-\beta z} + \frac 1{1-\gamma z}
= \frac1z\frac{\chi'}{\chi}\Bigl(\frac1z\Bigr) = \frac{-z^2-4z+3}{z^3-z^2-2z+1}.
\]
\end{enumerate}

exercices.enonce:
Calculer les sommes suivantes dans leur intervalle ouvert de convergence après avoir déterminé le rayon de convergence de la série proposée.

	\begin{center}
