exercices.correction:
\begin{enumerate}
\item Pour \( |x| < \frac1q \) : \( \ln f(x) = \sum_{n = 1}^\infty \ln(1-q^nx) = -\sum_{n = 1}^\infty\sum_{k = 1}^\infty \frac{q^{kn}x^k}k = -\sum_{k = 1}^\infty \frac{q^kx^k}{k(1-q^k)} \),\par \( f = e^{\ln f} \) est DSE par composition.

\item \( a_n = \frac{q^{n(n+1)/2}}{(q-1)\dots(q^n-1)} \), \( R = \infty \).
\end{enumerate}

\begin{enumerate}
\item Pour \( x\ne 0 \) la série comporte un nombre fini de termes non nuls au voisinage de \( x \), donc est \( \mathcal{C}^\infty \) au voisinage de \( x \). On a \( |f^{(k)}(x)| = \Bigl|\sum_{n = 0}^\infty a_n\lambda_n^{k-n}\varphi_n^{(k)}(\lambda_nx)\Bigr|
\le\sum_{n = 0}^\infty |a_n|\lambda_n^{k-n}M_n
\le \text{cste}(k) + \sum_{n = k+1}^\infty|a_n|M_n/\lambda_n \) en supposant \( \lambda_n\ge 1 \) pour \( n\ge k \), donc \( f^{(k)} \) est bornée sur \( \Rr \). Ceci implique que \( f \) est \( \mathcal{C}^\infty \) en \( 0 \) et on a le développemment limité : \( f(x) = \sum_{n = 0}^k a_nx^n + o(x^k) \) car \( \phi \equiv 1 \) au voisinage de \( 0 \) donc \( f^{(k)}(0) = k!\,a_k \).

\item \( \psi(x) = \exp\Bigl(\frac1{(1-x)(x-2)}\Bigr) \) sur \( ]1,2[ \), \( \psi(x) = 0 \) ailleurs.
\end{enumerate}

