\item \( \Im(f) \) est de signe constant sur le connexe \( D\cap \Omega^+ \) et \( f(z)\sim z \) au voisinage de \( 0 \).

\item Intégrer terme à terme.

\item \( \Im (f(re^{i\theta})) \sin\theta \ge 0 \) par la question {2.}.
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Développer en série entière \( f \) : \( z \mapsto z(1-z)^{-2} \). Montrer que \( f \) est injective sur \( \mathring D(0,1) \).

		\item Soit \( f(z) = z+\sum_{n = 2}^{+\infty} a_nz^n \) la somme d'une série entière de rayon de convergence au moins \( 1 \) à coefficients réels. On suppose \( f \) injective sur \( \mathring D(0,1) \) et on veut prouver : \( \forall\ n\ge 1, |a_n|\le n \).
		\begin{enumerate}
			\item Montrer pour \( |z|<1 \) que \( f(z)\in\Rr\Leftrightarrow z\in\Rr \) et en déduire : \( \Im(z)\ge 0 \Rightarrow \Im(f(z))\ge 0 \).

			\item Pour \( 0<r<1 \) calculer \( \int_{t = 0}^{\pi }\Im(f(re^{it}))\sin nt\,d t \). En déduire \( |a_n|r^n\le n|a_1|r \) et conclure.

		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( \frac z{(1-z)^2} = \sum_{n = 1}^\infty nz^n \) (\( R = 1 \)).

Pour \( z,t\in \mathring D(0,1) \) on a \( \frac{z}{(1-z)^2} - \frac{t}{(1-t)^2} = \frac{(z-t)(1-zt)}{(1-z)^2(1-t)^2} \), quantité nulle si et seulement si \( z = t \), d'où l'injectivité de \( z \mapsto\frac z{(1-z)^2} \).

\item
\begin{enumerate}
	\item \( f(z)\in\Rr \Leftrightarrow f(z) = \overline{f(z)} = f(\overline z) \Leftrightarrow z = \overline z \Leftrightarrow z\in\Rr \).

	Par injectivité, on en déduit que \( \Im(f(z)) \) garde un signe constant sur chaque demi-disque limité par \( ]-1,1[ \), et comme \( f(z) = z + o_{z\to0}(z) \), ce signe est celui de \( \Im z \).

	\item \( \int_{t = 0}^{\pi }\Im(f(re^{it}))\sin nt\,d t = \frac{\pi a_nr^n}2 \).

	On a \( |\sin(nt)|\le n\sin(t) \) pour \( 0\le t\le\pi \) par récurrence, donc \( \frac{\pi |a_n|r^n}2\le n \int_{t = 0}^{\pi }\Im(f(re^{it}))\sin t\,d t = \frac{n\pi a_1r}2 \). On en déduit \( |a_n|r^n\le n|a_1|r \) et on conclut \( |a_n|\le n \) en faisant tendre \( r \) vers \( 1 \).
\end{enumerate}
\end{enumerate}

Soit \( R > 0 \). Notons \( D_R \) le disque fermé de centre \( 0 \) et de rayon \( R \). Soient \( z\in D_R \) et \( n \) un entier naturel.

\begin{center}
\( |P_n(z)| = \left|e^z - (e^z-P_n(z))\right|\ge|e^z|-|e^z-P_n(z)|\ge e^{-R}-|e^z-P_n(z)| \).
\end{center}

On sait que la suite de polynômes \( (P_n)_{n\in\Nn} \) converge uniformément vers la fonction exponentielle sur \( D_R \).Donc il existe un entier \( n_0 \) tel que pour tout \( z\in D_R \) et tout entier \( n\ge n_0 \), \( \left|e^z-P_n(z)\right|\le\frac{1}{2}e^{-R} \). Pour \( n\ge n_0 \) et \( z\in D_R \), \( \left|P_n(z)\right|\ge\frac{1}{2}e^{-R}>0 \) et \( P_n \) ne s'annule pas dans \( D_R \).

exercices.enonce:
Soit \( \sum_{n = 0}^{+\infty}a_nz^n \) une série entière de rayon \( R > 0 \) et telle que \( a_0 = 1 \) (ou plus généralement \( a_0\neq 0 \)).

	\begin{enumerate}
		\item Montrer qu'il existe une et une seule suite \( (b_n)_{n\in\Nn} \) telle que \( \forall n\in\Nn \), \( \sum_{k = 0}^na_kb_{n-k} = \delta_{0,n} \).

		\item Montrer que la série entière \( \sum_{n = 0}^{+\infty}b_nz^n \) a un rayon strictement positif.
	\end{enumerate}

Soient \( (a_n)_{n\in\Nn} \) et \( (b_n)_{n\in\Nn} \) deux suites de réels strictement positifs telles que la suite \( \left(\frac{a_n}{b_n}\right)_{n\in\Nn} \) ait une limite réelle \( k \). (En particulier \( a_n\underset{n\rightarrow+\infty}{ = }o(b_n) \) si \( k = 0 \) et \( a_n\underset{n\rightarrow+\infty}{\sim}b_n \) si \( k = 1 \)). On suppose de plus que la série entière associée à la suite \( (a_n)_{n\in\Nn} \) a un rayon de convergence égal à \( 1 \) et que la série de terme général \( a_n \) diverge.

	\begin{enumerate}
		\item Montrer que \( \lim_{x \rightarrow 1}\frac{\sum_{n = 0}^{+\infty}a_nx^n}{\sum_{n = 0}^{+\infty}b_nx^n} = k \).

		\item \textbf{Applications.}
		\begin{enumerate}
			\item Équivalent simple quand \( x \) tend vers \( 1 \) de \( \sum_{n = 1}^{+\infty}\ln nx^n \).

			\item Déterminer \( \lim_{x \rightarrow 1}(1-x)^p\sum_{n = 0}^{+\infty}n^{p-1}x^n \) où \( p \) est un entier naturel non nul donné.
		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soient \( A \) et \( B \) les sommes des séries entières associées aux suites \( a \) et \( b \) sur \( ]-1,1[ \). La fonction \( B \) est strictement positive sur \( ]0,1[ \) et en particulier ne s'annule pas sur \( ]0,1[ \).

\textbullet La suite \( a \) est positive donc la fonction \( A \) est croissante sur \( [0,1[ \) et admet ainsi une limite réelle ou infinie quand \( x \) tend vers \( 1 \) par valeurs inférieures. De plus, pour \( N \) entier naturel donné et \( x\in[0,1[ \), on a \( \sum_{n = 0}^{+\infty}a_nx^n\ge\sum_{n = 0}^Na_nx^n \) et donc

\begin{center}
	\( \forall N\in\Nn \), \( \displaystyle\lim_{\substack{x\rightarrow1,\;x<1}}A(x)\ge\displaystyle\lim_{\substack{x\rightarrow1,\;x<1}}\sum_{n = 0}^Na_nx^n = \sum_{n = 0}^Na_n \).
\end{center}

Puisque la série de terme général positif \( a_n \) diverge, quand \( N \) tend tend vers \( +\infty \), on obtient \( \displaystyle\lim_{\substack{x\rightarrow1,\;x<1}}A(x)\ge+\infty \) et donc \( \displaystyle\lim_{\substack{x\rightarrow1,\;x<1}}A(x) = +\infty \). Il en est de même pour \( B \) car la série de terme général \( b_n \) diverge quelque soit la valeur de \( k \).

\textbullet On veut alors montrer que \( A-k B\underset{x\rightarrow1^-}{ = }o(B) \).

Soit \( \varepsilon> 0 \). Par hypothèse, \( a_n-kb_n\underset{n\rightarrow+\infty}o(b_n) \) et donc il existe un entier naturel \( N \) tel que pour \( n\ge N \), \( |a_n-kb_n|\le\frac{\varepsilon}{2} b_n \).

Soit \( x\in[0,1[ \).

\begin{center}
	\( |A(x)-kB(x)|\le \sum_{n = 0}^{+\infty}|a_n-kb_n|x^n\le \sum_{n = 0}^N|a_n-kb_n|x^n+ \frac{\varepsilon}{2}\sum_{n = N+1}^{+\infty}b_nx^n\le\sum_{n = 0}^N|a_n-kb_n|+\frac{\varepsilon}{2}B(x) \).
\end{center}

Maintenant, \( B(x) \) tend vers \( +\infty \) quand \( x \) tend vers \( 1 \) par valeurs inférieures. Donc il existe \( \alpha\in]0,1[ \) tel que pour \( x\in]1-\alpha,1[ \), \( B(x) >\frac{2}{\varepsilon}\sum_{n = 0}^N|a_n-kb_n| \). Pour \( x\in]1-\alpha,1[ \), on a alors \( |A(x)-kB(x)| <\frac{\varepsilon}{2}B(x)+\frac{\varepsilon}{2}B(x) = \varepsilon B(x) \).

On a montré que \( \forall\varepsilon>0 \), \( \exists\alpha\in]0,1[/ \) \( \forall x\in]1-\alpha,1[ \), \( |A(x)-kB(x)|<\varepsilon B(x) \) et donc \( \lim_{x \rightarrow 1^-}\frac{A(x)}{B(x)} = k \).

\item
\begin{enumerate}
	\item La série entière proposée \og vérifie \fg les hypothèses du 1) et de plus , \( \ln n\underset{n\rightarrow+\infty}{\sim}1+\frac{1}{2}+...+\frac{1}{n} \). Donc

	\begin{center}
		\( f(x)\underset{x\rightarrow1^-}{\sim}\sum_{n = 1}^{+\infty}\left(\sum_{k = 1}^n\frac{1}{k}\right)x^n = \left(\sum_{n = 0}^{+\infty}x^n\right)\left(\sum_{n = 1}^{+\infty}\frac{x^n}{n}\right) = \frac{\ln(1-x)}{x-1} \).
	\end{center}

	\begin{center}
		\shadowbox{ \( \sum_{n = 1}^{+\infty}(\ln n) x^n\underset{x\rightarrow1^-}{\sim}\frac{\ln(1-x)}{x-1} \). }
	\end{center}

	\item Soit \( p\ge2 \). \( n^{p-1}\underset{n\rightarrow+\infty}{\sim}(n+1)(n+2)...(n+p-1) \). Comme les deux suites \( (n^{p-1}) \) et \( ((n+1)(n+2)...(n+p-1)) \) vérifient les hypothèses du 1)

	\begin{center}
		\( \sum_{n = 0}^{+\infty}n^{p-1}x^n\underset{x\rightarrow1^-}{\sim}\sum_{n = 0}^{+\infty}(n+p-1)...(n+1)x^n = \left(\sum_{n = 0}^{+\infty}x^n\right)^{(p-1)} = \left(\frac{1}{1-x}\right)^{(p-1)} = \frac{(p-1)!}{(1-x)^p} \).
	\end{center}

	Par suite,

	\begin{center}
		\shadowbox{ \( \lim_{x \rightarrow 1^-}(1-x)^p\sum_{n = 1}^{+\infty}n^{p-1}x^n = (p-1)! \). }
	\end{center}
\end{enumerate}
\end{enumerate}

exercices.enonce:
\label{ex:rou20x}
	\begin{enumerate}
		\item Soit \( E \) un ensemble non vide muni d'une loi interne et \( a_n \) le nombre de parenthésages possibles d'un produit de \( n \) éléments de \( E \) ((\( a_1 = 1 \) conventionnellement), \( a_2 = 1 \), \( a_3 = 2 \), \( a_4 = 5 \), ...). Montrer que pour tout \( n\ge 2 \), \( a_n = \sum_{k = 1}^{n-1}a_ka_{n-k} \).

		\item Soit \( f \) la série entière associée à la suite \( (a_n) \). On suppose momentanément le rayon \( R \) de cette série strictement positif. Montrer que pour tout \( x \) de \( ]-R,R[ \), \( (f(x))^2 -f(x)+ x = 0 \).

		\item Calculer \( R \) et \( f \).

		\item En déduire \( a_n \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soient \( n\ge2 \) puis \( k\in\llbracket1,n-1\rrbracket \). On met une parenthèse autour de \( X_1...X_k \) et une autour de \( X_{k+1}...X_n \). Ensuite, pour chacun des \( a_k \) parenthésages de \( X1...X_k \), il y a \( a_{n-k} \) parenthésages possibles de \( X_{k+1}...X_n \). Finalement, en faisant varier \( k \) de \( 1 \) à \( n-1 \), on a montré que

\begin{center}
	\shadowbox{ \( \forall n\ge2 \), \( a_n = \sum_{k = 1}^{n-1}a_ka_{n-k} \). }
\end{center}

\item On suppose momentanément le rayon \( R \) de la série entière associé à la suite \( (a_n)_{n\in\Nn^*} \) strictement positif. On pose conventionnellement \( a_0 = 0 \). Pour \( x\in]-R,R[ \),

\begin{center}
	\( f^2(x) = \left(\sum_{n = 0}^{+\infty}a_nx^n\right)^2 = \sum_{n = 0}^{+\infty}\left(\sum_{k = 0}^na_ka_{n-k}\right)x^n = \sum_{n = 2}^{+\infty}\left(\sum_{k = 1}^{n-1}a_ka_{n-k}\right)x^n = \sum_{n = 2}^{+\infty}a_nx^n = f(x) - x \),
\end{center}

et donc

\begin{center}
	\shadowbox{ \( \forall x\in]-R,R[ \), \( f^2(x) = f(x) - x \). }
\end{center}

\item Nécessairement, pour tout \( x \) de \( ]-R,R[ \), \( f(x) = \frac{1}{2}(1+\sqrt{1+4x}) \) \( (I) \) ou \( f(x) = \frac{1}{2}(1-\sqrt{1-4x}) \) \( (II) \). Ainsi, pour chaque \( x\in]-R,R[ \), on doit choisir l'une de ces deux expressions. Puisque \( f(0) = 0 \), il faut choisir l'expression \( (II) \) quand \( x = 0 \).

Pour \( x\in\left]-\frac{1}{4},\frac{1}{4}\right[ \), posons \( g(x) = \frac{1}{2}(1-\sqrt{1-4x}) \). \( g \) est développable en série entière sur \( \left]-\frac{1}{4},\frac{1}{4}\right[ \) en vertu de théorèmes généraux. Notons \( (b_n)_{n\in\Nn} \) la suite des coefficients du développement. Puisque \( g(0) = 0 \), on a \( b_0 = 0 = a_0 \) et puisque \( g'(0) = 1 \), on a \( b_1 = 1 = a_1 \). Enfin, la fonction \( g \) vérifie \( \forall x\in\left]-\frac{1}{4},\frac{1}{4}\right[ \), \( g^2(x) = g(x)-x \) et donc \( \forall n\ge2 \), \( b_n = \sum_{k = 1}^{n-1}b_kb_{n-k} \). On en déduit par récurrence que pour tout entier naturel \( n \), \( b_n = a_n \) et donc \( \forall x\in\left]-\frac{1}{4},\frac{1}{4}\right[ \), \( f(x) = g(x) \).

\begin{center}
	\shadowbox{ \( \forall x\in\left]-\frac{1}{4},\frac{1}{4}\right[ \), \( f(x) = \frac{1}{2}(1-\sqrt{1-4x}) \). }
\end{center}

\item Pour connaitre les \( a_n \), il reste à développer la fonction \( g \) en série entière. Pour \( x\in\left]-\frac{1}{4},\frac{1}{4}\right[ \),

\begin{center}
	\( g(x) = \frac{1}{2}(1-(1-4x)^{1/2}) = \frac{1}{2}\left(1-\sum_{n = 0}^{+\infty}C_{1/2}^n(-4x)^n\right) = \sum_{n = 1}^{+\infty}(-1)^{n-1}C_{1/2}^n2^{2n-1}x^n \).
\end{center}

Enfin, pour \( n\in\Nn^* \),

\begin{align*}\ensuremath (-1)^{n-1}C_{1/2}^n2^{2n-1} & =(-1)^{n-1}\frac{\frac{1}{2}\times\left(\frac{1}{2}-1\right)\times\ldots\times\left(\frac{1}{2}-(n-1)\right)}{n!}2^{2n-1}=\frac{2^{n-1}}{n!}\times1\times3\times....\times(2n-3) \\
	& =\frac{2^{n-1}}{n!}\times\frac{1\times2\times3\times....\times(2n-3)\times(2n-2)}{2\times4\times\ldots\times(2n-2)}=\frac{(2n-2)!}{n!(n-1)!}=\frac{C_{2n-2}^{n-1}}{n}.
\end{align*}

Donc

\begin{center}
	\shadowbox{ \( \forall n\in\Nn^* \), \( a_n = \frac{C_{2n-2}^{n-1}}{n} \). }
\end{center}
\end{enumerate}

exercices.enonce:
Sans les calculer, dire si les intégrales suivantes sont convergentes ou divergentes\,:
	\begin{eqnarray*}
		&&\int_0^1 \frac{dt}{\sqrt[3]{t \sqrt{1-t}}}, \\
		&&\int_0^{\pi/2} \tan t\ dt, \\
		&&\int_0^1\frac{dt}{\sqrt{\arcsin t} \ln(1-t)}.
	\end{eqnarray*}

\begin{enumerate}
		\item À l'aide d'une intégration par parties, montrer que \( \int_{t = 0}^{+\infty} \frac{\sin t}t \,d t = \int_{t = 0}^{+\infty} \frac{\sin^2 t}{t^2} \,d t \).

		\item Montrer que \( I_n = \int_{t = 0}^{\pi/2} \frac{\sin^2 nt}{t^2}\,d t \) est comprise entre \( A_n = \int_{t = 0}^{\pi/2} \frac{\sin^2 nt}{\sin^2 t}\,d t \) et \( B_n = \int_{t = 0}^{\pi/2} \cotan^2 t\sin^2 nt\,d t \).

		\item Calculer \( A_n+A_{n+2} - 2A_{n+1} \) et \( A_n-B_n \). En déduire les valeurs de \( A_n \) et \( B_n \) en fonction de \( n \).

		\item Lorsque \( n\to\infty \) montrer que \( \frac{I_n}{n} \to J = \int_{t = 0}^{+\infty} \frac{\sin^2 t}{t^2}\,d t \) et donner la valeur de cette dernière intégrale.

	\end{enumerate}

exercices.correction:
