exercices.enonce:
Soit \( \varphi : {\Rr_n[X]} \to {\Rr^{n+1}}, P \mapsto {(a_0,\dots,a_n)} \) avec \( a_k = \int_{t = 0}^{+\infty} e^{-t}t^kP(t)\,d t \).

	\begin{enumerate}
		\item Justifier l'existence de \( \varphi \).

		\item Montrer que \( \varphi \) est un isomorphisme d'espaces vectoriels.
	\end{enumerate}

Soit \( \gamma \) la constante d'Euler. Montrer que \dots

	\begin{enumerate}
		\item \( \int_{t = 0}^{+\infty} e^{-t}\ln t\,d t = -\gamma \).

		\item \( \int_{t = 0}^1 \frac{1-e^{-t}-e^{-1/t}}t\,d t = \gamma \).

		\item \( \int_{t = 0}^1 \left(\frac 1t + \frac 1{\ln(1-t)}\right)d t = \gamma \).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Intégrations par parties successives,\par
\begin{align*}
	\int_{t=0}^{+\infty} e^{-t}\ln t\,d t & = \int_{t=0}^{+\infty} e^{-t}\frac{t^k}{k!}\left(\ln t - \frac 11 - \frac 12 - \dots - \frac 1k\right)\,d t             \\
	& = \int_{t=0}^{+\infty} e^{-t}\frac{t^k}{k!}\ln(t/k)\,d t + \left(\ln k - \frac 11 - \frac 12 - \dots - \frac 1k\right).
\end{align*}

Soit \( I_k = \int_{t = 0}^{+\infty} e^{-t}\frac{t^k}{k!}\ln(t/k)\,d t \). On pose \( t = ku \):
\begin{align*}I_k & = \frac{k^{k+1}}{k!} \int_{u=0}^{+\infty} (ue^{-u})^k\ln u\,d u                                                \\
	& = \frac{k^{k+1}}{k!} \int_{u=0}^{+\infty} d\left(\frac{(ue^{-u})^{k-1}}{k-1}\right) \frac{u^2e^{-u}\ln u}{1-u} \\
	& = -\frac{k^{k+1}}{k!(k-1)} \int_{u=0}^{+\infty} (ue^{-u})^{k-1} d\left(\frac{u^2e^{-u}\ln u}{1-u}\right).
\end{align*}

Comme \( 0\le ue^{-u}\le e^{-1} \), il reste \( \sqrt k \) au dénominateur multiplié par quelque chose de borné.

\item
\begin{align*}
	\int_{t=0}^1 \frac{1-e^{-t}-e^{-1/t}}t\,d t & = \int_{t=0}^1 \frac{1-e^{-t}}t\,d t - \int_{t=1}^{+\infty}\frac{e^{-t}}t\,d t      \\
	& = \lim_{x\to0^+}\left(-\ln x - \int_{t=x}^{+\infty}\frac{e^{-t}}t\,d t\right)       \\
	& = \lim_{x\to0^+}\left((e^{-x}-1)\ln x - \int_{t=x}^{+\infty}e^{-t}\ln t\,d t\right) \\
	& = - \int_{t=0}^{+\infty} e^{-t}\ln t\,d t.
\end{align*}

\item \( \int_{t = x}^{+\infty}\frac{e^{-t}}t\,d t = (t = -\ln(1-u)) = \int_{u = 1-e^{-x}}^1 \frac{-d u}{\ln(1-u)} \).
\end{enumerate}

exercices.enonce:
Soit \( f : {[a,b[} \to {\Rr^+} \) continue croissante. On pose \( S_n = \frac{b-a}n \sum_{k = 0}^{n-1} f\Bigl(a+k\frac{b-a}n \Bigr) \).

	\begin{enumerate}
		\item Si \( \int_{t = a}^b f(t)\,d t \) converge, montrer que \( S_n \to \int_{t = a}^b f(t)d t \) lorsque \( n\to\infty \).

		\item Si \( \int_{t = a}^b f(t)\,d t \) diverge, montrer que \( S_n \to +\infty \) lorsque \( n\to\infty \).
	\end{enumerate}

Soit \( f : {[0,+\infty[} \to \Rr \) continue décroissante telle que \( \int_{}^{+\infty} f(t)\,d t \) converge.

	\begin{enumerate}
		\item Montrer que la série \( \sum_{k = 0}^\infty f(k) \) converge et encadrer le reste : \( \sum_{k = n}^\infty f(k) \) à l'aide d'intégrales de \( f \).

		\item Application : Pour \( \alpha > 1 \), donner un équivalent pour \( n \to \infty \) de \( \sum_{k = n}^\infty \frac1{k^\alpha} \).

	\end{enumerate}

Soit \( f : {[0,+\infty[} \to {\Rr^+} \) continue telle que \( \int_{t = 0}^{+\infty} tf(t) \,d t \) converge. On pose \( F(x) = \int_{t = x}^{+\infty} f(t)\,d t \).

	\begin{enumerate}
		\item Justifier l'existence de \( F(x) \), et montrer que \( F(x) = o \Bigl({\frac1x }\Bigr) \) pour \( x\to+\infty \).

		\item Montrer que \( \int_{t = 0}^{+\infty} F(t) \,d t = \int_{t = 0}^{+\infty} tf(t) d t \).
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f : ]0, +\infty[ \to \Rr \) une fonction continue telle que \( \lim_{x\to 0^+} f(x) = \ell \) et \( \lim_{x\to +\infty} f(x) = L \).

		Pour \( a > 0 \), établir la convergence et calculer la valeur de \( \int_{t = 0}^{+\infty} \frac{f(at) - f(t)}{t} \,d t \).

		\item Application : Calculer \( \int_{t = 0}^1 \frac{t-1}{\ln t}\, dt \).

	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item \( \int_{t = x}^y \frac{f(at)}t \,d t = \int_{t = ax}^{ay} \frac{f(t)}t \,d t \Rightarrow
\int_{t = x}^y \frac{f(at)-f(t)}t \,d t = \int_{t = ax}^x \frac{f(t)}t \,d t + \int_{t = y}^{ay} \frac{f(t)}t \,d t \).

On obtient \( \int_{t = 0}^{+\infty} \frac{f(at) - f(t)}t \,d t = (L-\ell)\ln a \).

\item \( I = \int_{t = 0}^{+\infty} \frac{e^{-t}-e^{-2t}}t\,d t = \ln 2 \).
\end{enumerate}

