La fonction \( f : x\mapsto\ln(\sin x) \) est continue sur \( \left]0,\frac{\pi}{2}\right] \). De plus, quand \( x \) tend vers \( 0 \), \( \ln(\sin x)\sim\ln x = o\left(\frac{1}{\sqrt{x}}\right) \). Par suite, \( f \) est intégrable sur\( \left]0,\frac{\pi}{2}\right] \).

\begin{enumerate}
\item Soient \( I = \int_0^{\pi/2}\ln(\sin x)\;dx \) et \( J = \int_0^{\pi/2}\ln(\cos x)\;dx \). Le changement de variables \( x = \frac{\pi}{2}-t \) fournit \( J \) existe et \( J = I \). Par suite,

\begin{align*}\ensuremath 2I & = I+J =\int_0^{\pi/2}\ln(\sin x\cos x)\;dx=-\frac{\pi\ln2}{2}+\int_0^{\pi/2}\ln(\sin(2x))\;dx =-\frac{\pi\ln2}{2}+\frac{1}{2}\int_0^{\pi}\ln(\sin u)\;du                                     \\
	& = -\frac{\pi\ln2}{2}+\frac{1}{2}\left(I+\int_{\pi/2}^{\pi}\ln(\sin u)\;du\right) = -\frac{\pi\ln2}{2}+\frac{1}{2}\left(I+\int_{\pi/2}^0\ln(\sin(\pi-t))\;(-dt)\right)=-\frac{\pi\ln2}{2}+ I.
\end{align*}

Par suite, \( I = -\frac{\pi\ln2}{2} \).

\begin{center}
	\shadowbox{ \( \int_0^{\pi/2}\ln(\sin x)\;dx = \int_0^{\pi/2}\ln(\cos x)\;dx = -\frac{\pi\ln2}{2} \). }
\end{center}

\item Pour \( n\ge2 \), posons \( P_n = \prod_{k = 1}^{n-1}\sin\left(\frac{k\pi}{2n}\right) \). Pour \( 1\le k\le n-1 \), on a \( 0<\frac{k\pi}{2n}<\frac{\pi}{2} \) et donc \( P_n > 0 \). D'autre part, \( \sin\left(\frac{(2n-k)\pi}{2n}\right) = \sin\left(\frac{k\pi}{2n}\right) \) et \( \sin\frac{n\pi}{2n} = 1 \). On en déduit que

\begin{center}
	\( P_n^2 = \prod_{k = 1}^{2n-1}\sin\left(\frac{k\pi}{2n}\right) \),
\end{center}

puis

\begin{align*}\ensuremath P_n^2 & =\prod_{k=1}^{2n-1}\frac{e^{ik\pi/(2n)}-e^{-ik\pi/(2n)}}{2i}=\frac{1}{(2i)^{2n-1}}\prod_{k=1}^{2n-1}\left(-e^{-ik\pi/(2n)}\right)\prod_{k=1}^{2n-1}\left(1-e^{2ik\pi/(2n)}\right) \\
	& =\frac{1}{(2i)^{2n-1}}(-1)^{2n-1}(e^{-i\pi/2})^{2n-1}\prod_{k=1}^{2n-1}\left(1-e^{2ik\pi/(2n)}\right)= \frac{1}{2^{2n-1}}\prod_{k=1}^{2n-1}\left(1-e^{2ik\pi/(2n)}\right)
\end{align*}

Maintenant, le polynôme \( Q \) unitaire de degré \( 2n-1 \) dont les racines sont les \( 2n-1 \) racines \( 2n \)-èmes de l'unité distinctes de \( 1 \) est

\begin{center}
	\( \frac{X^{2n}-1}{X-1} = 1+X+X^2+...+X^{2n-1} \)
\end{center}

et donc \( \prod_{k = 1}^{2n-1}\left(1-e^{2ik\pi/(2n)}\right) = Q(1) = 2n \). Finalement,

\begin{center}
	\( \prod_{k = 1}^{n-1}\sin\left(\frac{k\pi}{2n}\right) = P_n = \sqrt{\frac{2n}{2^{2n-1}}} = \frac{\sqrt{n}}{2^{n-1}} \).
\end{center}

Pour \( 0\le k\le n \), posons alors \( x_k = \frac{k\pi}{2n} \) de sorte que \( 0 = x_0 < x_1< ...< x_n = \frac{\pi}{2} \) est une subdivision de \( \left[0,\frac{\pi}{2}\right] \) à pas constant égal à \( \frac{\pi}{2n} \).

Puisque la fonction \( x\mapsto\ln(\sin x) \) est continue et croissante sur \( \left]0,\frac{\pi}{2}\right] \), pour \( 1\le k\le n-1 \), on a \( \frac{\pi}{2n}\ln(\sin(x_k))\le\int_{x_k}^{x_{k+1}}\ln(\sin x)\;dx \) puis en sommant ces inégalités, on obtient

\begin{center}
	\( \frac{\pi}{2n}\ln(P_n)\le\int_{\pi/(2n)}^{\pi/2}\ln(\sin x)\;dx \)
\end{center}

De même, pour \( 0\le k\le n-1 \), \( \int_{x_k}^{x_{k+1}}\ln(\sin x)\;dx\le\frac{\pi}{2n}\ln(\sin(x_{k+1})) \) et en sommant

\begin{center}
	\( \int_0^{\pi/2}\ln(\sin x)\;dx\le\frac{\pi}{2n}\ln(P_n) \).
\end{center}

Finalement, \( \forall n\ge2 \), \( \frac{\pi}{2n}\ln(P_n)+\int_0^{\pi/(2n)}\ln(\sin x)\;dx\le I\le\frac{\pi}{2n}\ln(P_n) \). Mais \( \ln(P_n) = \ln n -(n-1)\ln2 \) et donc \( \frac{\pi}{2n}\ln(P_n) \) tend vers \( -\frac{\pi\ln2}{2} \) quand \( n \) tend vers \( +\infty \) et comme d'autre part, \( \int_0^{\pi/(2n)}\ln(\sin x)\;dx \) tend vers \( 0 \) quand \( n \) tend vers \( +\infty \) (puisque la fonction \( x : \mapsto\ln(\sin x) \) est intégrable sur \( \left]0,\frac{\pi}{2}\right] \)), on a redémontré que \( I = -\frac{\pi\ln2}{2} \).
\end{enumerate}

La fonction \( f : t\mapsto\frac{\ln t}{t-1} \) est continue et positive sur \( ]0,1[ \), négligeable devant \( \frac{1}{\sqrt{t}} \) quand \( t \) tend vers \( 0 \) et prolongeable par continuité en \( 1 \). La fonction \( f \) est donc intégrable sur \( ]0;1[ \).

\textbf{1ère solution.} (à la main, sans utilisation d'un théorème d'intégration terme à terme) Pour \( t\in]0,1[ \) et \( n\in\Nn \),

\begin{center}
\( \frac{\ln t}{t-1} = \frac{-\ln t}{1-t} = -\sum_{k = 0}^nt^k\ln t+\frac{t^{n+1}\ln t}{t-1} \)
\end{center}

Pour \( t\in]0,1] \) et \( n\in\Nn \), posons \( f_n(t) = -t^n\ln t \).

Soit \( n\in\Nn \). Chaque fonction \( f_k \), \( 0\le k\le n \), est continue sur \( ]0,1] \) et négligeable en \( 0 \) devant \( \frac{1}{\sqrt{t}} \). Donc chaque fonction \( f_k \) est intégrable sur \( ]0,1] \) et donc sur \( ]0,1[ \). Mais alors, il en est de même de la fonction \( t\mapsto\frac{t^{n+1}\ln t}{1-t} = \frac{\ln t}{t-1}+\sum_{k = 0}^nt^k\ln t \) et

\begin{center}
\( \int_0^1\frac{\ln t}{t-1}\;dt = -\sum_{k = 0}^n\int_0^1t^k\ln t\;dt+\int_0^1\frac{t^{n+1}\ln t}{t-1}\;dt \)
\end{center}

\textbullet La fonction \( g : t\mapsto\frac{t\ln t}{t-1} \) est continue sur \( ]0,1[ \) et prolongeable par continuité en \( 0 \) et en \( 1 \). Cette fonction est en particulier bornée sur \( ]0,1[ \). Soit \( M \) un majorant de la fonction \( |g| \) sur \( ]0,1[ \). Pour \( n\in\Nn \),

\begin{center}
\( \left|\int_0^1\frac{t^{n+1}\ln t}{t-1}\;dt\right|\le\int_0^1t^n|g(t)|\;dt\le M\int_0^1t^n\;dt = \frac{M}{n+1} \).
\end{center}

Par suite, \( \lim_{n \rightarrow +\infty}\int_0^1\frac{t^{n+1}\ln t}{t-1}\;dt = 0 \). On en déduit que la série de terme général \( -\int_0^1t^k\ln t\;dt \) converge et que

\begin{center}
\( \int_0^1\frac{\ln t}{t-1}\;dt = \sum_{k = 0}^{+\infty}\int_0^1(-t^k\ln t)\;dt \).
\end{center}

\textbullet Soit \( \varepsilon\in]0,1[ \). Pour \( k\in\Nn \), une intégration par parties fournit

\begin{center}
\( \int_{\varepsilon}^1(-t^k\ln t)\;dt = \left[-\frac{t^{k+1}\ln t}{k+1}\right]_\varepsilon^1+\frac{1}{k+1}\int_{\varepsilon}^1t^k\;dt = \frac{\varepsilon^{k+1}\ln \varepsilon}{k+1}+\frac{1-\varepsilon^{k+1}}{(k+1)^2} \).
\end{center}

Quand \( \varepsilon \) tend vers \( 0 \), on obtient \( \int_{\varepsilon}^1(-t^k\ln t)\;dt = \frac{1}{(k+1)^2} \). Finalement,

\begin{center}
\( \int_0^1\frac{\ln t}{t-1}\;dt = \sum_{k = 0}^{+\infty}\frac{1}{(k+1)^2} = \sum_{n = 1}^{+\infty}\frac{1}{n^2} = \frac{\pi^2}{6} \).
\end{center}

\begin{center}
\shadowbox{ \( \int_0^1\frac{\ln t}{t-1}\;dt = \sum_{n = 1}^{+\infty}\frac{1}{n^2} = \frac{\pi^2}{6} \). }
\end{center}

\textbf{2ème solution.} (utilisation d'un théorème d'intégration terme à terme) Chaque fonction \( f_n \) est continue et intégrable sur \( ]0,1[ \) et la série de fonctions de terme général \( f_n \) converge simplement vers la fonction \( f \) sur \( ]0,1[ \) et de plus, la fonction \( f \) est continue sur \( ]0,1[ \). Enfin

\begin{center}
\( \sum_{n = 0}^{+\infty}\int_0^1|f_n(t)|\;dt = \sum_{n = 0}^{+\infty}\frac{1}{(n+1)^2}<+\infty \).
\end{center}

D'après un théorème d'intégration terme à terme, \( \int_0^1f(t)\;dt = \sum_{n = 0}^{+\infty}\int_0^1f_n(t)\;dt = \frac{\pi^2}{6} \).

La fonction \( f : t\mapsto\frac{t-1}{\ln t} \) est continue sur \( ]0,1[ \), prolongeable par continuité en \( 0 \) et \( 1 \) et donc est intégrable sur \( ]0,1[ \).

Soit \( x\in]0,1[ \). Chacune des deux fonctions \( t\mapsto\frac{t}{\ln t} \) et \( t\mapsto\frac{1}{\ln t} \) se prolonge par continuité en \( 0 \) et est ainsi intégrable sur \( ]0,x] \). On peut donc écrire

\begin{center}
\( \int_0^x\frac{t-1}{\ln t}\;dt = \int_0^x\frac{t}{\ln t}\;dt -\int_0^x\frac{1}{\ln t}\;dt \).
\end{center}

Dans la première intégrale, on pose \( u = t^2 \) et on obtient \( \int_0^x\frac{t}{\ln t}\;dt = \int_0^x\frac{2t}{\ln(t^2)}\;dt = \int_0^{x^2}\frac{1}{\ln u}\;du \) et donc

\begin{center}
\( \int_0^x\frac{t-1}{\ln t}\;dt = \int_0^{x^2}\frac{1}{\ln t}\;dt -\int_0^x\frac{1}{\ln t}\;dt = \int_x^{x^2}\frac{1}{\ln t}\;dt \).
\end{center}

On note alors que, puisque \( x\in]0,1[ \), \( x^2 < x \). Pour \( t\in[x^2,x] \), on a \( t\ln t < 0 \) et donc \( \frac{x}{t\ln t}\le\frac{t}{t\ln t} = \frac{1}{\ln t}\le\frac{x^2}\ln t \) puis par croissance de l'intégrale, \( \int_{x^2}^x\frac{x}{t\ln t}\;dt\le\int_{x^2}^x\frac{1}{\ln t}\;dt\le\int_{x^2}^x\frac{x^2}{t\ln t}\;dt \) et donc

\begin{center}
\( x^2\int_x^{x^2}\frac{1}{t\ln t}\;dt\le\int_x^{x^2}\frac{1}{\ln t}\;dtx\le x\int_x^{x^2}\frac{1}{t\ln t}\;dt \)
\end{center}

Maintenant, \( \int_x^{x^2}\frac{1}{t\ln t}\;dt = \ln|\ln(x^2)|-\ln|\ln x| = \ln2 \) et on a montré que, pour tout réel \( x \) de \( ]0,1[ \),

\begin{center}
\( x^2\ln2\le\int_0^x\frac{t-1}{\ln t}\;dt\le x\ln2 \)
\end{center}

Quand \( x \) tend vers \( 1 \), on obtient

\begin{center}
\shadowbox{ \( \int_0^1\frac{t-1}{\ln t}\;dt = \ln2 \). }
\end{center}

\begin{enumerate}
\item La fonction \( t\mapsto e^{-t^2} \) est continue, positive et intégrable sur \( [0,+\infty[ \). De plus, quand \( t \) tend \( +\infty \),

\begin{center}
	\( e^{-t^2}\sim\left(1+\frac{1}{t^2}\right) = \frac{d}{dt}\left(-\frac{1}{2t}e^{-t^2}\right) \).
\end{center}

D'après un théorème de sommation des relations de comparaison, quand \( x \) tend vers \( +\infty \),

\begin{center}
	\( \int_x^{+\infty}e^{-t^2}\;dt\sim\int_x^{+\infty}\left(-\frac{1}{2t}e^{-t^2}\right)'\;dt = \frac{1}{2x}e^{-x^2} \),
\end{center}

et donc

\begin{center}
	\shadowbox{ \( e^{x^2}\int_x^{+\infty}e^{-t^2}\;dt\underset{x\rightarrow+\infty}{\sim}\frac{1}{2x} \). }
\end{center}

\item Pour \( a> 0 \) fixé, \( \int_a^{+\infty}\frac{\cos x}{x}\;dx \) converge (se montre en intégrant par parties (voir exercice \ref{ex:rou3})) puis

\begin{align*}\ensuremath
	\int_a^{+\infty}\frac{\cos x}{x}\;dx & =-\int_1^a\frac{\cos x}{x}\;dx+\int_1^{+\infty}\frac{\cos x}{x}\;dx\underset{a\rightarrow0}{=}-\int_1^a\frac{\cos x}{x}\;dx + O(1)                             \\
	& \underset{a\rightarrow0}{=}-\int_1^a\frac{1}{x}\;dx+\int_1^a\frac{1-\cos x}{x}\;dx+O(1)\underset{a\rightarrow0}{=}-\ln a+\int_1^a\frac{1-\cos x}{x}\;dx+O(1) .
\end{align*}

Maintenant, \( \frac{1-\cos x}{x}\underset{x\rightarrow0}{\sim}\frac{x}{2} \) et en particulier, \( \frac{1-\cos x}{x} \) tend vers \( 0 \) quand \( x \) tend vers \( 0 \). Par suite, la fonction \( x\mapsto\frac{1-\cos x}{x} \) est continue sur \( ]0,1] \) et se prolonge par continuité en \( 0 \). Cette fonction est donc intégrable sur \( ]0,1] \) et en particulier, \( \int_1^a\frac{1-\cos x}{x}\;dx \) a une limite réelle quand \( a \) tend vers \( 0 \). On en déduit que \( \int_a^{+\infty}\frac{\cos x}{x}\;dx\underset{a\rightarrow0}{ = }-\ln a + O(1) \) et finalement

\begin{center}
	\shadowbox{ \( \int_a^{+\infty}\frac{\cos x}{x}\;dx\underset{a\rightarrow0}{\sim}-\ln a \). }
\end{center}

\item Soit \( a>0 \).

\begin{center}
	\( \left|\int_0^1\frac{1}{x^3+a^2}\;dx -\frac{1}{a^2}\right| = \left|\int_0^1\left(\frac{1}{x^3+a^2}-\frac{1}{a^2}\right)\;dx\right| = \int_0^1\frac{x^3}{(x^3+a^2)a^2}\;dx\le\frac{1}{a^4} \)
\end{center}

Donc, \( \int_0^1\frac{1}{x^3+a^2}\;dx\underset{a\rightarrow+\infty}{ = }\frac{1}{a^2}+o\left(\frac{1}{a^2}\right) \) ou encore

\begin{center}
	\shadowbox{ \( \int_0^1\frac{1}{x^3+a^2}\;dx\underset{a\rightarrow+\infty}{\sim}\frac{1}{a^2} \). }
\end{center}
\end{enumerate}

La fonction \( f : x\mapsto\frac{(-1)^{E(x)}}{x} \) est continue par morceaux sur \( [1,+\infty[ \) et donc localement intégrable sur \( [1,+\infty[ \).

Soient \( X \) un réel élément de \( [2,+\infty[ \) et \( n = E(X) \).

\begin{center}
\( \int_1^X\frac{(-1)^{E(x)}}{x}\;dx = \sum_{k = 1}^{n-1}\int_k^{k+1}\frac{(-1)^{E(x)}}{x}\;dx+\int_n^X\frac{(-1)^{E(x)}}{x}\;dx = \sum_{k = 1}^{n-1}(-1)^k\ln\left(1+\frac{1}{k}\right)+\int_n^X\frac{(-1)^{E(x)}}{x}\;dx \).
\end{center}

Or, \( \left|\int_n^X\frac{(-1)^{E(x)}}{x}\;dx\right|\le\frac{X-n}{n}\le\frac{1}{E(X)} \). Cette dernière expression tend vers \( 0 \) quand le réel \( X \) tend vers \( +\infty \) et donc \( \lim_{X \rightarrow +\infty}\int_n^X\frac{(-1)^{E(x)}}{x}\;dx = 0 \).

D'autre part, la suite \( \left((-1)^k\ln\left(1+\frac{1}{k}\right)\right)_{k\ge1} \) est de signe alternée et sa valeur absolue tend vers \( 0 \) en décroissant. La série de terme général \( (-1)^k\ln\left(1+\frac{1}{k}\right) \), \( k\ge1 \), converge en vertu du critère spécial aux séries alternées ou encore, quand le réel \( X \) tend vers \( +\infty \), \( \sum_{k = 1}^{n-1}(-1)^k\ln\left(1+\frac{1}{k}\right) \) a une limite réelle.

Il en est de même de \( \int_1^X\frac{(-1)^{E(x)}}{x}\;dx \) et l'intégrale \( \int_1^{+\infty}\frac{(-1)^{E(x)}}{x}\;dx \) converge. De plus

\begin{center}
\( \int_1^{+\infty}\frac{(-1)^{E(x)}}{x}\;dx = \sum_{n = 1}^{+\infty}(-1)^n\ln\left(1+\frac{1}{n}\right) \).
\end{center}

\textbf{Calcul.} Puisque la série converge, on a \( \sum_{k = 1}^{+\infty}(-1)^k\ln\left(1+\frac{1}{k}\right) = \lim_{n \rightarrow +\infty}\sum_{k = 1}^{2n}(-1)^k\ln\left(1+\frac{1}{k}\right) \). Pour \( n\in\Nn^* \),

\begin{align*}
\sum_{k=1}^{2n}(-1)^k\ln\left(1+\frac{1}{k}\right) & =\sum_{k=1}^n\left(-\ln\left(1+\frac{1}{2k-1}\right)+\ln\left(1+\frac{1}{2k}\right)\right)=\sum_{k=1}^n\ln\left(\frac{(2k-1)(2k+1)}{(2k)^2}\right)                                                    \\
& =\ln\left(\frac{(1\times3\times\ldots\times(2n-1))^2\times(2n+1)}{(2\times4\times\ldots\times(2n))^2}\right) =\ln\left(\frac{1}{2^{4n}}\times\left(\frac{(2n)!}{(n!)^2}\right)^2\times(2n+1)\right) .
\end{align*}

D'après la formule de \textsc{Stirling},

\begin{center}
\( \frac{1}{2^{4n}}\times\left(\frac{(2n)!}{(n!)^2}\right)^2\times(2n+1)\underset{n\rightarrow+\infty}{\sim}\frac{1}{2^{4n}}\times\frac{\left(\frac{2n}{e}\right)^{4n}(\sqrt{4\pi n})^2}{\left(\frac{n}{e}\right)^{4n}(\sqrt{2\pi n})^4}\times(2n) = \frac{2}{\pi} \).
\end{center}

Donc \( \sum_{n = 1}^{+\infty}(-1)^n\ln\left(1+\frac{1}{n}\right) = \ln\left(\frac{2}{\pi}\right) \) et on a montré que

\begin{center}
\shadowbox{ \( \int_1^{+\infty}\frac{(-1)^{E(x)}}{x}\;dx = \sum_{n = 1}^{+\infty}(-1)^n\ln\left(1+\frac{1}{n}\right) = \ln\left(\frac{2}{\pi}\right) \). }
\end{center}

exercices.enonce:
Soit \( f \) définie, continue, positive et décroissante sur \( [1,+\infty[ \), intégrable sur \( [1,+\infty[ \).

	\begin{enumerate}
		\item Montrer que \( xf(x) \) tend vers \( 0 \) quand \( x \) tend vers \( +\infty \).

		\item Existence et calcul de \( \int_1^{+\infty}x(f(x+1)-f(x))dx \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Puisque \( f \) est continue, positive et décroissante sur \( [1,+\infty[ \), pour \( x\ge2 \) on a

\begin{center}
	\( 0\le xf(x) = 2\left(x-\frac{x}{2}\right)f(x)\le2\int_{x/2}^xf(t)\;dt = 2\left(/dint{x/2}{+\infty}f(t)\;dt-\int_x^{+\infty}f(t)\;dt\right) \)
\end{center}

Cette dernière expression tend vers \( 0 \) quand \( x \) tend vers \( +\infty \) car \( f \) est intégrable sur \( [1,+\infty[ \). Donc si \( f \) est continue, positive, décroissante et intégrable sur \( [1,+\infty[ \) alors \( f(x) \underset{x\rightarrow+\infty}{ = }o\left(\frac{1}{x}\right) \).

\item La fonction \( x\mapsto x(f(x) - f(x+1)) \) est continue et positive sur \( [1,+\infty[ \).

Soit \( X\ge 1 \).

\begin{align*}\ensuremath
	\int_1^Xx(f(x) - f(x+1))\;dx & =\int_1^Xxf(x)\;dx -\int_2^{X+1}(x-1)f(x)\;dx =\int_1^Xxf(x)\;dx - \int_2^{X+1}xf(x)\;dx +\int_2^{X+1}f(x)\;dx \\
	& =\int_1^2xf(x)\;dx -\int_X^{X+1}xf(x)\;dx +\int_2^{X+1} f(x)\;dx.
\end{align*}

Maintenant \( 0\le\int_X^{X+1}xf(x)\;dx\le(X+1-X)(X+1)f(X)\le2Xf(X) \). D'après 1), cette dernière expression tend vers \( 0 \) quand \( X \) tend vers \( +\infty \). Donc, quand \( X \) tend vers \( +\infty \), \( \int_1^Xx(f(x) - f(x+1))\;dx \) tend vers \( \int_1^2xf(x)\;dx+\int_2^{+\infty} f(x)\;dx \).

Puisque la fonction \( x\mapsto x(f(x) - f(x+1)) \) est continue et positive sur \( [1,+\infty[ \), on sait que \( x\mapsto x(f(x) - f(x+1)) \) est intégrable sur \( [1,+\infty[ \) si et seulement si la fonction \( X\mapsto\int_1^Xx(f(x) - f(x+1))\;dx \) a une limite réelle quand \( X \) tend vers \( +\infty \). Donc la fonction \( x\mapsto x(f(x) - f(x+1)) \) est intégrable sur \( [1,+\infty[ \) et

\begin{center}
	\shadowbox{ \( \int_1^{+\infty}x(f(x) - f(x+1))\;dx = \int_1^2xf(x)\;dx +\int_2^{+\infty}f(x)\;dx \). }
\end{center}
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item Soit \( f \) de classe \( C^1 \) sur \( \Rr^+ \) à valeurs dans \( \Rr \) telle que l'intégrale \( \int_0^{+\infty}f(x)\;dx \) converge en \( +\infty \). Montrer que \( \int_0^{+\infty}f'(x)\;dx \) converge en \( +\infty \) si et seulement si \( f(x) \) tend vers \( 0 \) quand \( x \) tend vers \( +\infty \).

		\item
		\begin{enumerate}
			\item On suppose que \( f \) est une fonction de classe \( C^2 \) sur \( \Rr^+ \) à valeurs dans \( \Rr \) telle que \( f \) et \( f'' \) admettent des limites réelles quand \( x \) tend vers \( +\infty \). Montrer que \( f' \) tend vers \( 0 \) quand \( x \) tend vers \( +\infty \).

			\item En déduire que si les intégrales \( \int_0^{+\infty}f(x)\;dx \) et \( \int_0^{+\infty}f''(x)\;dx \) convergent alors \( f \) tend vers \( 0 \) quand \( x \) tend vers \( +\infty \).
		\end{enumerate}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Puisque \( f \) est de classe \( C^1 \) sur \( \Rr^+ \), pour \( x\ge0 \), \( \int_0^xf'(t)\;dt = f(x)-f(0) \). Donc l'intégrale \( \int_0^{+\infty}f'(t)\;dt \) converge en \( +\infty \) si et seulement si \( f \) a une limite réelle \( \ell \) quand \( x \) tend vers \( +\infty \).

Si de plus l'intégrale \( \int_0^{+\infty}f(t)\;dt \) converge, il est exclus d'avoir \( \ell\neq0 \) et réciproquement si \( \ell = 0 \) alors \( \int_0^xf'(t)\;dt \) tend vers \( -f(0) \) quand \( x \) tend vers \( +\infty \). Donc l'intégrale \( \int_0^{+\infty}f'(t)\;dt \) converge si et seulement si \( \lim_{x \rightarrow +\infty}f(x) = 0 \).

\item
\begin{enumerate}
	\item Soit \( x\ge0 \). D'après la formule de \textsc{Taylor}-\textsc{Lagrange}, il existe un réel \( \theta_x\in]x,x+1[ \)

	\begin{center}
		\( f(x+1) = f(x) +(x+1-x)f'(x) +\frac{1}{2}f''(\theta_x) \).
	\end{center}

	ce qui s'écrit encore \( f'(x) = f(x+1) -f(x) -\frac{1}{2}f''(\theta_x) \). Quand \( x \) tend vers \( +\infty \), \( f(x+1)-f(x) \) tend vers \( 0 \) et d'autre part, \( \theta_x \) tend vers \( +\infty \). Ainsi, si \( f \) et \( f'' \) ont une limite réelle quand \( x \) tend vers \( +\infty \), \( f' \) a également une limite réelle et de plus \( \lim_{x \rightarrow +\infty}f'(x) = -\frac{1}{2}\lim_{x \rightarrow +\infty}f''(x) \).

	Ensuite, puisque pour \( x\ge0 \), \( \int_0^xf'(t)\;dt = f(x) - f(0) \) et \( \int_0^xf''(t)\;dt = f'(x) - f'(0) \), les intégrales \( \int_0^{+\infty}f'(t)\;dt \) et \( \int_0^{+\infty}f''(t)\;dt \) convergent et d'après 1), \( \lim_{x \rightarrow +\infty}f'(x) = 0 \) (\(  = \lim_{x \rightarrow +\infty}f''(x) \)).

	\item Soit \( F : x\mapsto\int_0^xf(t)\;dt \). \( F \) est de classe \( C^3 \) sur \( \Rr^+ \). De plus, \( F(x) = \int_0^xf(t)\;dt \) tend vers \( \int_0^{+\infty}f(t)\;dt \) et \( F''(x) = f'(x) = f'(0) +\int_0^xf''(t)\;dt \) tend vers \( f'(0) +\int_0^{+\infty}f''(t)\;dt \). Donc \( F \) et \( F'' \) ont des limites réelles en \( +\infty \). D'après a), \( f = F' \) tend vers \( 0 \) quand \( x \) tend vers \( +\infty \).
\end{enumerate}
\end{enumerate}

exercices.enonce:
\begin{enumerate}
		\item \emph{Le but de cette question est de montrer que \( \int_0^{+\infty} \frac{\sin t}{t}\, dt \) n'est pas absolument convergente.} Pour \( n\in\Nn \), on pose :
		\begin{eqnarray*}
			u_n = \int_{n\pi}^{(n+1)\pi} \frac{|\sin t|}{t} \, dt.
		\end{eqnarray*}
		Montrer que pour \( n\ge 0 \), \( \frac{2}{(n+1)\pi} \le u_n \). En déduire que \( \int_0^{+\infty} \frac{|\sin t|}{t}\, dt \) est divergente.

		\item \emph{Deuxième formule de la moyenne.}
		Soient \( f \) et \( g \) deux fonctions Riemann-intégrables sur \( [a, b] \), admettant des primitives notées \( F \) et \( G \) respectivement. Supposons que \( F \) est positive et décroissante. Montrer qu'il existe \( y\in [a,b] \) tel que :
		\begin{equation*}
			\int_a^bF(x)g(x)\,dx = F(a)\int_a^yg(x)\,dx.
		\end{equation*}

		\item En déduire que \( \int_0^{+\infty} \frac{\sin t}{t}\, dt \) est convergente.

		\item \emph{Le but de cette question est de calculer la valeur de cette intégrale.} Pour tout nombre réel \( \lambda\ge 0 \), on pose :
		\begin{equation*}
			\left\{
			\begin{array}{lll}
				f(t, \lambda) & = & e^{-\lambda t}\,\frac{\sin t}{t}\quad\quad
				\text{pour}\quad t> 0                                          \\
				f(0, \lambda) & = & 1.
			\end{array}\right.
		\end{equation*}

		\begin{enumerate}
			\item Pour \( 0< x \le y \), démontrer que l'on a :
			\begin{equation*}
				\left|\int_x^y f(t, \lambda)\, dt\right| \le \frac{2}{x}
				e^{-\lambda x}.
			\end{equation*}

			\item En déduire que les intégrales généralisées \( \int_0^{+\infty} f(t, \lambda)\, dt\ \), sont convergentes, uniformément pour \( \lambda\ge0 \). On pose, pour \( \lambda \ge 0 \),
			\begin{equation*}
				F(\lambda) = \int_0^{+\infty} e^{-\lambda t}\,\frac{\sin t}{t}\,dt.
			\end{equation*}
			Démontrer que la fonction \( F \) est continue pour \( \lambda \ge 0 \).

			\item Démontrer que la fonction \( F \) est dérivable pour \( \lambda > 0 \) et que sa dérivée est égale à l'intégrale généralisée convergente
			\begin{equation*}
				F'(\lambda) = - \int_0^{+\infty} e^{-\lambda t}\sin t \,dt.
			\end{equation*}

			\item Calculer cette dernière intégrale généralisée, par exemple en intégrant par parties sur \( [0, x] \) et en calculant la limite quand \( x\rightarrow +\infty \).

			\item En déduire la valeur de \( F(\lambda) \) pour \( \lambda\ge0 \) à une constante additive près. Démontrer que \( F(\lambda)\rightarrow 0 \) quand \( \lambda \rightarrow +\infty \). En déduire la valeur de la constante additive, puis la valeur de l'intégrale \( \int_0^{+\infty} \frac{\sin t}{t}\, dt \).

		\end{enumerate}
	\end{enumerate}

\begin{enumerate}
		\item Prouver l'existence pour \( x > 0 \) de \( I(x) = \int_{t = 0}^{+\infty} \frac{\sin t}{t+x}\,d t \).

		\item Déterminer \( \lim_{x\to+\infty} I(x) \).

	\end{enumerate}

