exercices.correction:
\begin{enumerate}
\item \( \sum u_n(t) \) converge pour \( |t|<1 \).

\item \( P_n(t) = t^{n+1}\sin(nx) - t^n\sin((n+1)x) + \sin(x) \), \( Q(t) = t^2 - 2t\cos(x) + 1 = (t-\cos x)^2 + \sin^2x\ge \sin^2x \).

\item Pour \( |t|<1 \) on a \( S_n(t)\to\frac{\sin t}{Q(t)} \) lorsque \( n\to\infty \) et il y a convergence dominée vu la minoration de \( Q \) donc l'intégrale suit : \( \int_{t = 0}^1 S_n(t)\,d t\to \int_{t = 0}^1 \frac{\sin x\,d t}{t^2-2t\cos x + 1} = (t-\cos x = u\sin x) = \int_{u = -\cotan x}^{\tan(x/2)}\frac{d u}{u^2+1} = \frac{\pi-x}2 \).

\item \( \frac{\sin(nx)}n = \int_{t = 0}^1 u_n(t)\,d t \) d'où \( \sum_{n = 1}^\infty \frac{\sin(nx)}n = \frac{\pi-x}2 \).
\end{enumerate}

