exercices.correction:
\begin{enumerate}
\item \( y = \int_{t = \alpha}^x b(t)e^{A(t)-A(x)}\,d t + y(\alpha)e^{-A(x)} \) avec \( A' = a \) et \( A(\alpha) = 0 \).\par Comme \( a \ge 1 \), on a \( A(x) \ge x-\alpha \) et \( A(t)-A(x) \le t-x \) pour \( t \le x \).\par Donc \( |y| \le \int_{t = \alpha}^z |b(t)|e^{t-x}\,d t +
\int_{t = z}^x |b(t)|e^{t-x}\,d t + |y(\alpha)|e^{\alpha-x}
\le \|b\|_{\infty} e^{z-x} +
\sup\limits_{[z,+\infty[}|b| + |y(\alpha)|e^{\alpha-x} \).\par On choisit \( z \) tel que \( z\to+\infty \) et \( x-z\to+\infty \Rightarrow \) cqfd.

\item Comme \( A(t)-A(x) \le t-x \) pour \( t \le x \), l'intégrale \( \int_{t = -\infty}^x b(t)e^{A(t)-A(x)}\,d t \) converge et fournit une solution nulle en \( -\infty \). Comme \( e^{-A(x)}\to +\infty \) lorsque \( x\to-\infty \), c'est la seule.
\end{enumerate}

