\begin{enumerate}
\item Raisonner à l'aide d'une fonction \( h \) des variables \( x \) et \( y \) telle que \( x+y+z = h(x,y) \) et \( \lim_{(x,y) \to (0,0)} h(x,y) = 0 \).

\item Montrer que, déjà sous la contrainte supplémentaire \( z = 0 \), la limite ne peut pas exister.
\end{enumerate}

exercices.enonce:
On considère une suite \( (u_n)_n \), de terme général \( u_n\in\Rr^2 \).
	\begin{enumerate}
		\item Donner la définition de convergence pour une telle suite. (Ceci est une question de cours!)

		\item Soit la suite de terme général \( u_n = (\tanh(n), \cos(n) \exp(-n^2)) \). Étudier sa convergence.
	\end{enumerate}

exercices.correction:
On note \( f \) la fonction considérée.
\begin{enumerate}
\item Pour \( x\neq0 \), \( f(x,-x+x^3) = \frac{x(-x+x^3)}{x-x+x^3}\underset{x\rightarrow0^+}{\sim}-\frac{1}{x} \). Quand \( x \) tend vers \( 0 \), \( -x+x^3 \) tend vers \( 0 \) puis \( \displaystyle\lim_{\substack{(x,y)\rightarrow(0,0)\\x>0,\;y = -x+x^3}}f(x,y) = -\infty \). \( f \) n'a de limite réelle en \( (0,0) \).

\item Pour \( x\neq0 \), \( f(x,0) = \frac{x\times0}{x^2+0^2} = 0 \) puis \( \displaystyle\lim_{\substack{(x,y)\rightarrow(0,0)\\y = 0}}f(x,y) = 0 \). Mais aussi, pour \( x\neq0 \), \( f(x,x) = \frac{x\times x}{x^2+x^2} = \frac{1}{2} \) puis \( \displaystyle\lim_{\substack{(x,y)\rightarrow(0,0)\\x = y}}f(x,y) = \frac{1}{2} \). Donc si \( f \) a une limite réelle, cette limite doit être égale à \( 0 \) et à \( \frac{1}{2} \) ce qui est impossible. \( f \) n'a pas de limite réelle en \( (0,0) \).

\item Pour tout \( (x,y)\in\Rr^2 \), \( x^2-2|xy|+y^2 = (|x|-|y|)^2\ge0 \) et donc \( |xy|\le\frac{1}{2}(x^2+y^2) \). Par suite, pour \( (x,y)\neq(0,0) \),

\begin{center}
	\( |f(x,y)| = \frac{x^2y^2}{x^2+y^2}\le\frac{(x^2+y^2)^2}{4(x^2+y^2)} = \frac{1}{4}(x^2+y^2) \).
\end{center}
Comme \( \lim_{(x,y)\rightarrow (0,0)}\frac{1}{4}(x^2+y^2) = 0 \), on a aussi \( \lim_{(x,y)\rightarrow (0,0)}f(x,y) = 0 \).

\item \( \lim_{(x,y)\rightarrow (0,0)}\frac{\sin y}{y} = 1 \) et \( \lim_{(x,y)\rightarrow (0,0)}(1+x^2+y^2) = 1 \). Donc \( \lim_{(x,y)\rightarrow (0,0)}f(x,y) = 1 \).

\item Pour \( (x,y)\in\Rr^2 \), \( |x^3+y^3| = |x+y|(x^2+xy+y^2)\le\frac{3}{2}|x+y|(x^2+y^2) \) et donc pour \( (x,y)\neq(0,0) \),

\begin{center}
	\( |f(x,y)| = \frac{|x^3+y^3|}{x^2+y^2}\le\frac{3}{2}|x+y| \).
\end{center}
Comme \( \lim_{(x,y)\rightarrow (0,0)}\frac{3}{2}|x+y| = 0 \), on a aussi \( \lim_{(x,y)\rightarrow (0,0)}f(x,y) = 0 \).

\item Pour \( (x,y)\in\Rr^2 \), \( |x^4+y^4| = (x^2+y^2)^2-2x^2y^2\le(x^2+y^2)^2+2\times\left(\frac{1}{2}(x^2+y^2)\right)^2 = \frac{3}{2}(x^2+y^2)^2 \) et donc pour \( (x,y)\neq(0,0) \),

\begin{center}
	\( |f(x,y)| = \frac{|x^4+y^4|}{x^2+y^2}\le\frac{3}{2}(x^2+y^2) \).
\end{center}
Comme \( \lim_{(x,y)\rightarrow (0,0)}\frac{3}{2}(x^2+y^2) = 0 \), on a aussi \( \lim_{(x,y)\rightarrow (0,0)}f(x,y) = 0 \).
\end{enumerate}

exercices.enonce:
Étudier la continuité sur \( \Rr^2 \) de la fonction suivante :

	\begin{enumerate}

		\item
		\[
		f(x,y) = \left\{
		\begin{array}{cc}
			\frac{x^2y^2}{x^2+y^2} & \mbox{ si }(x,y) \neq (0,0) \\
			0                      & \mbox{ sinon. }
		\end{array}
		\right .
		\]

		\item
		\[
		f(x,y) = \left\{
		\begin{array}{cc}
			\frac{x^2y}{x^2+y^2} & \mbox{ si }(x,y) \neq (0,0) \\
			0                    & \mbox{ sinon. }
		\end{array}
		\right .
		\]

		\item
		\[
		f(x,y) = \left\{
		\begin{array}{cc}
			\frac{x^4y}{x^4+y^6} & \mbox{ si }(x,y) \neq (0,0) \\
			0                    & \mbox{ sinon. }
		\end{array}
		\right .
		\]

		\item
		\[
		f(x,y) = \left\{
		\begin{array}{cc}
			\frac{xy^4}{x^4+y^6} & \mbox{ si }(x,y) \neq (0,0) \\
			0                    & \mbox{ sinon. }
		\end{array}
		\right .
		\]

		\item
		\[
		f(x,y) = \left\{
