	& \quad +y^2 \cos x \sin^2 (xy) \exp(y^2) +xy^3 \cos x \sin(xy) \cos(xy)\exp(y^2)
	\\&= y^2 \sin(xy) \exp(y^2) ( 2xy \cos x \cos(xy) - x \sin x\sin(xy) +
	\cos x \sin(xy) )
	\\
	\frac{\partial (g\circ f)}{\partial y}
	& = (xy^2 \sin(xy) \cos x \exp(y^2)) x\cos(xy)
	\\
	& \quad + (xy \sin^2 (xy) \exp(y^2))
	\cos x
	\\
	& \quad +(y \sin(xy) \cos x) x\exp(y^2)((1+2y^2)\sin(xy) +xy\cos(xy))
	\\
	& = x^2y^2 \cos x\sin(xy)
	\cos(xy)\exp(y^2) +xy \cos x\sin^2 (xy) \exp(y^2)
	\\
	& \quad +xy(1+2y^2) \cos x \sin^2 (xy)
	\exp(y^2) +x^2y^2 \cos x\sin(xy)\cos(xy)\exp(y^2)
	\\
	& = 2 x^2y^2 \cos x\sin(xy)
	\cos(xy)\exp(y^2) +2xy(1+y^2) \cos x\sin^2 (xy) \exp(y^2)
	\\
	& = 2xy \cos x \sin(xy)\exp(y^2) (xy \cos(xy) +(1+y^2) \sin(xy) ) .
\end{align*}
\end{enumerate}

