exercices.enonce:
En utilisant un changement de variables, calculer l'intégrale de \( f \) sur \( D \) avec
	\begin{enumerate}
		\item \( D = \{ (x,y)\in \Rr^2 \mid \pi^2 < x^2+y^2 \le 4\pi^2 \}\; ;\; f(x,y) = \sin \sqrt{x^2+y^2} \) ;

		\item \( D = \left\{ (x,y)\in \Rr^2 \mid \frac{x^2}{a^2}+\frac{y^2}{b^2} \le 1 \right\}\; \mbox{avec }a\, ,\, b>0\; ;\; f(x,y) = x^2+y^2 \) ;

		\item \( D = \{ (x,y,z)\in \Rr^3 \mid x^2+y^2 \le 1\, ,\, 0\le z\le h \}\; \mbox{avec }h>0 \; ;\; f(x,y,z) = z \) ;

		\item \( D = \{ (x,y)\in \Rr^2 \mid 0 < x^2\le y\le 2x^2\, ,\, 1/x\le y \le 2/x \}\; ;\; f(x,y) = x+y \) (changement de variable \( u = y/x^2\, ,\, v = xy \)) ;

		\item \( D = \{ (x,y,z)\in \Rr^3 \mid x\ge 0\, ,\, y\ge 0\, ,\, z\ge 0\, ,\, x^2+y^2+z^2 \le 1 \}\; ;\; f(x,y,z) = xyz \) ;

		\item \( D = \{ (x,y,z)\in \Rr^3 \mid 1\le x^2+y^2+z^2 \le 4 \}\; ;\; f(x,y,z) = (x^2+y^2+z^2)^\alpha \).
	\end{enumerate}

Identifier les ensembles suivants et calculer leur aire s'ils sont dans \( \Rr^2 \), leur volume s'ils sont dans \( \Rr^3 \).
	\begin{enumerate}
		\item \( D = \left\{ (x,y)\in \Rr^2 \mid \frac{x^2}{a^2}+\frac{y^2}{b^2} \le 1 \right\} \) avec \( a,b>0 \) ;

		\item \( D = \left\{ (x,y,z)\in \Rr^3 \mid \frac{x^2}{a^2}+\frac{y^2}{b^2}+\frac{z^2}{c^2} \le 1 \right\} \) avec \( a,b,c>0 \) ; qu'obtient-on dans le cas particulier où \( D \) est la boule unité de \( \Rr^3 \) ?

		\item \( D = \left\{ (x,y,z)\in \Rr^3 \mid x^2 +y^2 \le R\, ,\, 0\le z\le h \right\} \) avec \( R,h>0 \) ;

		\item \( D = \left\{ (x,y,z)\in \Rr^3 \mid x\ge 0\, ,\, y\ge 0\, ,\, z\ge 0\, ,\, x+y+z \le 1 \right\} \) ;

		\item \( D = \left\{ (x,y,z)\in \Rr^3 \mid x^2+y^2\le z^2/h^2 \, ,\, 0\le z\le h \right\} \) avec \( h>0 \).
	\end{enumerate}

Calculer les coordonnées du centre d'inertie (de gravité) du domaine \( D \) :
	\begin{enumerate}
		\item \( D = \left\{ (x,y)\in \Rr^2 \mid \frac{x^2}{a^2}+\frac{y^2}{b^2} \le 1\, ,\, x\ge 0\, ,\, y\ge 0 \right\} \) (le quart d'ellipse) ;

		\item \( D = \left\{ (x,y)\in \Rr^2 \mid x^2+y^2 \le 1\, ,\, x\ge 0 \, ,\, |y|\le ax \right\} \) ;

		\item \( D = \{ (x,y)\in \Rr^2 \mid x^2+y^2\le 9\, ,\, (x-1)^2+y^2\ge 1 \} \).
	\end{enumerate}

\begin{enumerate}
		\item {\bf{Théorème de Guldin}}
		Soit \( D_0 \) un domaine tracé dans le demi-plan \( \{ (x,0,z)\in \Rr^3 \mid x\ge 0 \} \). Si l'on fait tourner \( D_0 \) autour de l'axe \( Oz \), on obtient un domaine \( D \) de \( \Rr^3 \). En utilisant les coordonnées cylindriques, montrer que
		\[
		Vol\, (D) = 2\pi Aire\, (D_0)\cdot x_G\, ,
		\]
		où \( (x_G,z_G) \) sont les coordonnées du centre d'inertie du domaine \( D_0 \).

		\item Calculer les volumes des domaines suivants :
		\begin{enumerate}
			\item le tore obtenu en faisant tourner autour de \( Oz \) le domaine \( D_0 = \{ (x,0,z)\mid \frac{(x-c)^2}{a^2} +\frac{z^2}{b^2}\le 1 \} \), où \( a<c \) ;

			\item \( D = \left\{ (x,y,z)\in \Rr^3 \mid x^2 +y^2 +z^2 \le 4R^2\, ,\, x^2 +y^2 \le R^2 \right\} \), où \( R>0 \).
		\end{enumerate}
	\end{enumerate}

On note \( D \) le domaine délimité par les droites \( x = 0 \), \( y = x+2 \) et \( y = -x \).
	\begin{enumerate}
		\item Calculer (directement) \( I = \displaystyle{\int \! \! \! \int_D (x-y)dxdy. } \)

		\item Calculer \( I \) au moyen du changement de variable \( u = x+y \) et \( v = x-y \).
	\end{enumerate}

\begin{enumerate}
		\item Calculer \( \iiint_D \frac{d x\,d y\,d z}{(1+x^2z^2)(1+y^2z^2)} \) avec \( D = \{(x,y,z) \text{ tel que } 0\le x \le 1,\ 0\le y\le 1,\ 0\le z\} \).

		\item En déduire \( \int_{t = 0}^{+\infty} \Bigl(\frac{\arctan t}t\Bigr)^2d t \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Intégrer en \( z \) d'abord : \( \frac1{(1+x^2z^2)(1+y^2z^2)} = \frac 1{x^2-y^2}\Bigl(\frac{x^2}{1+x^2z^2} - \frac{y^2}{1+y^2z^2}\Bigr) \). On obtient \( I = \pi\ln 2 \).

