exercices.correction:
\begin{enumerate}
\item \( V = \frac{4\pi}3 (1-\sqrt{1-a^2}^3\,) \).

\item \( V = \frac{2\pi}3 (2-\sqrt{2}) \).

\item \( V = 2\pi^2Rr^2 \).
\end{enumerate}

Pour \( n\in\Nn^* \) et \( R\ge0 \), posons \( B_n(R) = \{(x_1,\ldots,x_n)\in\Rr^n/\;x_1^2+\ldots+x_n^2\le R^2\} \) et notons \( V_n(R) \) le volume de \( B_n(R) \). Par définition,

\begin{center}
\( V_n(R) = \displaystyle\int\ldots\iint_{x_1^2+\ldots+x_n^2\le R^2}dx_1\ldots dx_n \).
\end{center}

En posant \( x_1 = Ry_1 \), \ldots, \( x_n = Ry_n \), on a \( \frac{D(x_1,\ldots,x_n)}{D(y_1,\ldots,y_n)} = R^n \) (quand \( R>0 \)) puis

\begin{center}
\( V_n(R) = \displaystyle\int\ldots\iint_{x_1^2+\ldots+x_n^2\le R^2}dx_1\ldots dx_n = R^n\displaystyle\int\ldots\iint_{y_1^2+\ldots+y_n^2\le1}dy_1\ldots dy_n = R^nV_n(1) \).
\end{center}

ce qui reste vrai quand \( R = 0 \). Pour \( n\ge2 \), on peut alors écrire

\begin{align*}\ensuremath V_n(1) & =\displaystyle\int_{-1}^1\left(\displaystyle\int\ldots\iint_{x_1^2+\ldots+x_{n-1}^2\le 1-x_n^2}dx_1\ldots dx_{n-1}\right)dx_n=\int_{-1}^1V_{n-1}\left(\sqrt{1-x_n^2}\right)\;dx_n \\
& =\int_{-1}^1(1-x_n^2)^{(n-1)/2}V_{n-1}(1)\;dx_n=I_nV_{n-1}(1)
\end{align*}

où \( I_n = \int_{-1}^1(1-x^2)^{(n-1)/2}\;dx \). Pour calculer \( I_n \), on pose \( x = \cos\theta \). On obtient

\begin{center}
\( I_n = \int_{\pi}^0(1-\cos^2\theta)^{(n-1)/2}(-\sin\theta)\;d\theta = \int_0^{\pi}\sin^n\theta\;d\theta = 2\int_0^{\pi/2}\sin^n\theta\;d\theta = 2W_n \) (intégrales de \textsc{Wallis}).
\end{center}

Finalement,

\begin{center}
\( V_1(1) = 2 \) et \( \forall n\ge2 \), \( V_n(1) = 2W_nV_{n-1}(1) \).
\end{center}

On en déduit que pour \( n\ge2 \),

\begin{center}
\( V_n(1) = (2W_n)(2W_{n-1})\ldots(2W_2)V_1(1) = 2^n\prod_{k = 2}^nW_k = 2^n\prod_{k = 1}^nW_k \),
\end{center}

ce qui reste vrai pour \( n = 1 \). Maintenant, il est bien connu que la suite \( ((n+1)W_{n+1}W_n)_{n\in\Nn} \) est constante et plus précisément que \( \forall n\in\Nn \), \( (n+1)W_{n+1}W_n = W_1W_0 = \frac{\pi}{2} \). Donc, pour \( p\in\Nn^* \),

\begin{align*}\ensuremath V_{2p}(1) & =2^{2p}\prod_{k=1}^{2p}W_k=2^{2p}\prod_{k=1}^p(W_{2k-1}W_{2k})=2^{2p}\prod_{k=1}^p \frac{\pi}{2(2k)}= \frac{\pi^p}{p!},
\end{align*}

et de même

\begin{align*}\ensuremath V_{2p+1}(1) & =2^{2p+1}\prod_{k=2}^{2p+1}W_k=2^{2p+1}\prod_{k=1}^p(W_{2k}W_{2k+1})=2^{2p+1}\prod_{k=1}^p \frac{\pi}{2(2k+1)}                                             \\
& = \frac{\pi^p2^{p+1}}{3\times5\times\ldots\times(2p+1)}= \frac{\pi^p2^{p+1}(2p)\times(2p-2)\times\ldots\times2}{(2p+1)!}= \frac{\pi^p2^{2p+1}p!}{(2p+1)!}.
\end{align*}

\begin{center}
\shadowbox{ \( \forall p\in\Nn^* \), \( \forall R>0 \), \( V_{2p}(R) = \frac{\pi^pR^{2p}}{p!} \) et \( V_{2p-1}(R) = \frac{\pi^p2^{2p+1}p!R^{2p+1}}{(2p+1)!} \). }
\end{center}

En particulier, \( V_1(R) = 2R \), \( V_2(R) = \pi R^2 \) et \( V_3(R) = \frac{4}{3}\pi R^3 \).

\textbf{1ère solution.} \( V = \displaystyle\iiint_{x^2+ \frac{1}{2}y^2+ \frac{3}{4}z^2+xz\le1}dxdydz \). Or \( x^2+ \frac{1}{2}y^2+ \frac{3}{4}z^2+xz = \left(x+ \frac{z}{2}\right)^2+ \frac{y^2}{2}+ \frac{z^2}{2} \). On pose donc \( u = x+ \frac{z}{2} \), \( v = \frac{y}{\sqrt{2}} \) et \( w = \frac{z}{\sqrt{2}} \).

\begin{center}
\( \frac{D(u,v,w)}{D(x,y,z)} = \left|
\begin{array}{ccc}
	1 & 0                  & \frac{1}{2}        \\
	0 & \frac{1}{\sqrt{2}} & 0                  \\
	0 & 0                  & \frac{1}{\sqrt{2}}
\end{array}
\right| = \frac{1}{2} \).
\end{center}

On en déduit que \( \frac{D(x,y,z)}{D(u,v,w)} = 2 \) puis que

\begin{center}
\( V = \displaystyle\iiint_{x^2+ \frac{1}{2}y^2+ \frac{3}{4}z^2+xz\le1}dxdydz = \displaystyle\iiint_{u^2+v^2+w^2\le1}\left| \frac{D(x,y,z)}{D(u,v,w)}\right|dudvdw = 2\times \frac{4\pi}{3} = \frac{8\pi}{3} \).
\end{center}

\textbf{2ème solution.} Supposons savoir que le volume délimité par l'ellipsoïde d'équation \( \frac{X^2}{a^2}+ \frac{Y^2}{b^2}+ \frac{Z^2}{c^2} = 1 \) est \( \frac{4}{3}\pi abc \). La matrice de la forme quadratique \( (x,y,z)\mapsto x^2+ \frac{1}{2}y^2+ \frac{3}{4}z^2+xz \) dans la base canonique orthonormée de \( \Rr^3 \) est \( A = \left(
\begin{array}{ccc}
1           & 0           & \frac{1}{2} \\
0           & \frac{1}{2} & 0           \\
\frac{1}{2} & 0           & \frac{3}{4}
\end{array}
\right) \). On sait que cette matrice a \( 3 \) valeurs propres strictement positives \( \lambda = \frac{1}{a^2} \), \( \mu = \frac{1}{b^2} \) et \( \nu = \frac{1}{c^2} \) puis qu'il existe une base orthonormée dans laquelle l'ellipsoïde a pour équation \( \frac{X^2}{a^2}+ \frac{Y^2}{b^2}+ \frac{Z^2}{c^2} = 1 \). Le volume de l'ellipsoïde est alors

\begin{center}
\( V = \frac{4}{3}\pi abc = \frac{4}{3} \frac{\pi}{\sqrt{\lambda\mu\nu}} = \frac{4}{3} \frac{\pi}{\sqrt{\text{det}(A)}} = \frac{4}{3} \frac{\pi}{\sqrt{ \frac{1}{4}}} = \frac{8\pi}{3} \)
\end{center}

\begin{center}
\shadowbox{ \( V = \frac{8\pi}{3} \). }
\end{center}

On pose déjà \( x = ua \) et \( y = vb \) de sorte que \( \frac{D(u,v)}{D(x,y)} = ab \). On obtient

\begin{center}
\( I = \displaystyle\iint_{\frac{x^2}{a^2}+\frac{y^2}{b^2}\le1}(x^2-y^2)\;dxdy = ab\displaystyle\iint_{u^2+v^2\le1}(a^2u^2-b^2v^2)\;dudv \).
\end{center}

Ensuite,

\begin{align*}\ensuremath
\displaystyle\iint_{u^2+v^2\le1}u^2\;dudv & =\displaystyle\iint_{u^2+v^2\le1}v^2\;dudv= \frac{1}{2}\displaystyle\iint_{u^2+v^2\le1}(u^2+v^2)\;dudv= \frac{1}{2}\int_{r=0}^{r=1}\int_{\theta=0}^{2\pi}r^2\times rdrd\theta \\
& = \frac{1}{2}\int_0^1r^3dr\int_0^{2\pi}d\theta= \frac{1}{2}\times \frac{1}{4}\times2\pi= \frac{\pi}{4},
\end{align*}

et donc

\begin{center}
\shadowbox{ \( I = \frac{\pi ab(a^2-b^2)}{4} \). }
\end{center}

