\begin{enumerate}

\item \( a_0 = \pi \) et pour \( n\ne 0 \), \( a_n = \frac{2}{\pi n^2} ((-1)^n - 1) \) (nul quand \( n \) est pair), \( b_n = 0 \).

\item Par la formule de Parseval
\[
\frac{2 \pi^2}{3}
= \frac{1}{\pi} \int_{-\pi}^\pi |x|^2 \, dx = \frac{\pi^2}{2} + \frac{16}{\pi^2} \sum_{p = 0}^\infty \frac{1}{(2p+1)^4}
\]
donc \( \sum_{p = 0}^\infty \frac{1}{(2p+1)^4} = \frac{\pi^4}{96} \).

\item Comme
\[
\sum_{n = 1}^\infty \frac{1}{n^4} = \sum_{p = 1}^\infty \frac{1}{(2p)^4} + \sum_{p = 0}^\infty \frac{1}{(2p+1)^4}
= \frac{1}{16} \sum_{n = 1}^\infty \frac{1}{n^4} + \frac{\pi^4}{96}
\]
il vient \( \displaystyle \sum_{n = 1}^\infty \frac{1}{n^4} = \frac{15}{16} \frac{\pi^4}{96} = \frac{\pi^4}{90} \).

\item C'est le théorème de Dirichlet. Appliqué en \( x = 0 \), cela implique que \( \displaystyle \sum_{p = 0}^\infty \frac{1}{(2p+1)^2} = \frac{\pi}{4} \frac{\pi}{2} = \frac{\pi^2}{8} \). On en déduit que \( \sum_{n = 1}^\infty \frac{1}{n^2} = \frac{\pi^2}{6} \).

\end{enumerate}

