	\begin{enumerate}
		\item Soit \( F \) et \( G \) deux sous-espaces projectifs disjoints de \( P \). Montrer qu'il existe un unique sous-espace projectif \( \langle F,G\rangle \) de \( P \) de dimension \( \dim F+\dim G+1 \) contenant \( F \) et \( G \).

		\item Soit \( F \) et \( G \) deux sous-espaces projectifs disjoints de \( P \) tels que \( \dim F+\dim G = \dim P-1 \). Quel est le domaine de définition de l'application (appelée perspective) ?
		\[
		\begin{array}{ccccc}
			P(\vec{V}) & \to     & G           & \subset & P(\vec{V})                             \\
			M          & \mapsto & G\cap \langle M,F\rangle & =       & P (\vec{G}\cap (\vec{M}\oplus\vec{F}))
		\end{array}
		\]
		Montrer que c'est une application projective.
	\end{enumerate}

\begin{enumerate}
		\item Soit \( \vec{V} \) un espace vectoriel de dimension \( n+1 \) muni d'une base \( \mathcal{B}:=(\vec{v_i}) \) et \( (x_i) \) les coordonnées cartésiennes associées. Soit \( \mathcal{R} \) le repère projectif associé de \( P(\vec{V}) \). Soit \( \vec{v} \) un vecteur de \( \vec{V} \). Déterminer un système de coordonnées homogènes dans \( \mathcal{R} \) pour \( vect(\vec{v}) \) en fonction des coordonnées cartésiennes de \( \vec{v} \) dans \( \mathcal{B} \).

		\item Soit \( E \) un espace affine de dimension \( n \) et \( \widehat{E} \) son complété vectoriel. On identifie \( E \) à un ouvert affine de \( P(\widehat{E}) \) par l'application naturelle \( M\mapsto vect\left( (\!( 1,M )\!)\right) \). Soit \( \mathcal{A}:=(A_i)_{0\le i\le n} \) un repère affine de \( E \).
		\begin{enumerate}
			\item Considérons d'abord la base \( \mathcal{B}_1:=\left( (\!( 1,A_i)\!)\right) \) de \( \widehat{E} \) et \( \mathcal{R}_1 \) le repère projectif associé. Déterminer un système de coordonnées homogènes dans \( \mathcal{R}_1 \) de \( M\in E \) considéré dans \( P(\widehat{E}) \) en fonction de ses coordonnées barycentriques dans \( \mathcal{A} \). Donner une équation de l'hyperplan à l'infini.

			\item Considérons maintenant la base \( \mathcal{B}_2:=\left( (\!( 1,A_0)\!) , (\!( 0,\vec{A_0A_i})\!)\right) \) de \( \widehat{E} \) et \( \mathcal{R}_2 \) le repère projectif associé. Déterminer un système de coordonnées homogènes dans \( \mathcal{R}_2 \) de \( M\in E \) considéré dans \( P(\widehat{E}) \) en fonction de ses coordonnées cartésiennes dans \( \mathcal{A} \). Donner une équation de l'hyperplan à l'infini.
		\end{enumerate}
	\end{enumerate}

Soit \( E \) un plan affine muni d'un repère affine \( \mathcal{A}':=(A_0,A_1, A_3) \) et \( \mathcal{C} \) la conique d'équation cartésienne \( x^2+y^2 = 1 \). Soit \( \mathcal{A}:= (A_1,A_2 = s_{A_0}(A_1),A_3) \) un nouveau repère affine de \( E \).
	\begin{enumerate}
		\item Déterminer une équation barycentrique homogène dans \( \mathcal{A} \) de \( \mathcal{C} \).

		\item Soit \( B_1, B_2, B_3 \) trois points de \( \mathcal{C} \) distincts de \( A_1, A_2, A_3 \). Montrer à l'aide d'un calcul en coordonnées barycentriques que les points d'intersection \( P = (A_1B_2)\cap (A_2B_1) \), \( Q = (A_2B_3)\cap (A_3B_2) \) et \( R = (A_3B_1)\cap (A_1B_3) \) sont alignés.
	\end{enumerate}

Une quadrique d'un espace projectif \( P(V) \) est le lieu des zéros d'une forme quadratique \( f \) sur \( V \).
	\begin{enumerate}
		\item Montrer que toute quadrique qui contient trois points distincts d'une droite \( d \) contient toute la droite \( d \).

		\item Déterminer la dimension de l'espace des quadriques de \( P^3(K) \).

		\item Soit \( d_1, d_2, d_3 \) trois droites de \( P^3(K) \). Montrer qu'il existe une quadrique qui les contient.
	\end{enumerate}

En utilisant le théorème du cours selon lequel la somme d'angles intérieurs d'un polygone convexe à \( n \) sommets dans \( \mathbb{H}^2 \) est inférieure à \( (n-2)\pi \), démontrez que :
	\begin{enumerate}
		\item Soient \( \theta_1, \theta_2, ..., \theta_n \) une collection ordonnée de nombres tels que \( 0\le\theta_i < \pi\ (i = 1,...,n) \). Pour qu'il existe un polygone convexe d'angles intérieurs \( \theta_i \) il faut et il suffit que \( \theta_1 +\theta_2 +...+ \theta_n < (n-2)\pi \).

		\item Un polygone à \( n \) côtés et d'angles droits existe ssi \( n\ge 5 \).
	\end{enumerate}

\begin{enumerate}
		\item Démontrer que chaque homographie non-triviale \( g\in M^+(2)\setminus\{{\rm id}\} \) possède soit un point fixe soit deux. Un élément \( g\in M^+(2) \) est dit {\it parabolique} si son ensemble des points fixes : \( {\rm fix}(g) = \{x\in\overline\Cc\ \vert\ g(x) = x\} \) est un singleton. Montrer qu'un élément est parabolique {ssi}
		il est conjugué dans \( M^+(2) \) à la translation \( z\mapsto z+1 \).

		\item Un élément \( f\in M^+(2) \) est dit {\it elliptique}
		s'il est conjugué dans \( M^+(2) \) à une rotation \( z\mapsto k\cdot z \) où \( \vert k\vert = 1 \) , \( k\in\Cc\setminus \{1\} \).

		Un élément \( g\in M^+(2) \) est dit {\it loxodromique} s'il est conjugué dans \( M^+(2) \) à \( z\mapsto k\cdot z \) où \( \vert k\vert\not=1 \). De plus, un élément loxodromique est dit {\it hyperbolique} si \( k\in\Rr^*_+\setminus\{1\} \) ; un élément loxodromique est dit strictement loxodromique si \( k = \lambda\cdot e^{i\theta},\ \lambda > 0\ ,\
		\theta\not=2\pi m \). Pour un élément \( g\in M^+(2) \) on utilise la même lettre pour une de deux matrices dans \( SL_2\Cc \) qui le représentent (en fait c'est \( g \) ou \( -g \)). Montrer que pour tout élément \( g\in M^+(2) \) l'une des possibilités suivantes peut avoir lieu :

		\begin{enumerate}
			\item \( g \) est parabolique ssi \( {\rm tr}^2(g) = 4 \), où \( tr^2 \) est la trace carrée de la matrice \( g \).

			\item \( g \) est elliptique ssi \( {\rm tr}^2(g)\in [0,4[ \).

			\item \( g \) est hyperbolique ssi \( {\rm tr}^2(g)\in ]4, \infty[ \).

			\item \( g \) est strictement loxodromique {\bf ssi} \( {\rm tr}^2(g)\not\in[0,\infty[ \).
		\end{enumerate}

		\item En utilisant le modèle du demi-plan démontrer que les points fixes d'un élément parabolique ou hyperbolique se trouvent toujours sur le bord \( \overline\Rr \) de \( \mathbb{H}^2 \).

		En utilisant le modèle du disque démontrer qu'un élément elliptique a exactement un des deux points fixes dans \( \mathbb{H}^2 \).

	\end{enumerate}

\begin{enumerate}
		\item Soient \( \xi(t) \) et \( \eta(t) \) deux courbes paramétrées de \( \Rr^3 \) de classe \( C^1 \), montrer que \( \frac{d}{dt} [\xi, \eta] = [\frac{d\xi}{dt}, \eta] +[ {\xi, \frac{d\eta}{dt}}] \), où \( [, ] \) désigne le produit vectoriel.

		\item Montrer que \( \kappa = - \frac{<r', [r '', r ''']>}{k^2} \), où \( s\mapsto r(s) \) est une courbe de classe \( C^3 \) paramétrée par sa longueur, \( \kappa \) et \( k \) sont respectivement sa torsion et sa courbure.
	\end{enumerate}

\begin{enumerate}
		\item Montrer qu'une courbe \( s \mapsto r (s) \) est plane ssi \( <r', [r'', r''']>=0 \).

		\item Soit \( s \mapsto r (s) \) une courbe de classe \( C^2 \) paramétrée par sa longueur. On considère la nouvelle courbe \( s \mapsto n(s) \) où \( n \) est le vecteur normal unitaire. Notons \( s^* \) le paramètre naturel de cette courbe. Montrer que \( \frac{ds^{*}}{ds} = \sqrt{k^2+\kappa^2} \).
	\end{enumerate}

\begin{enumerate}
		\item Montrer que si une courbe \( s\mapsto r(s) \) est tracée sur une sphère de rayon \( R \) et si \( \kappa(s)\not=0, k(s)\not=0\ (\forall s) \) alors \( R^2 = <r ,r >  = \frac{1}{k^2}(1+ \frac{(k')^2}{(\kappa k)^2}) \).

		\item Soit \( s \mapsto r (s) \) une courbe à courbure constante qui est tracée sur la sphère \( S^2 \). Montrer que son image \( r \) est un arc de cercle. La propriété d'être à courbure constante dépend-t-elle de la paramétrisation de la courbe ?
	\end{enumerate}

\begin{enumerate}
		\item Montrez que \( d(x,y) = |x-y| \) est bien une distance sur l'ensemble des réels.

		\item Pour tout couple d'éléments \( X = (x_1,\dots,x_n) \) et \( Y = (y_1,\dots,y_n) \) de \( \Rr^n \), on définit \( d(X,Y) = \sup_{i = 1,\dots,n}|x_i-y_i| \). Montrez que \( d \) est bien une distance sur \( \Rr^n \).

		\item Faire de même avec \( d(X,Y) = |x_1-y_1|+|x_2-y_2|+...+|x_n-y_n| \).
	\end{enumerate}

Etudiez la continuité des applications suivantes:
	\begin{enumerate}
		\item \( f(x,y) = \frac{xy^2}{x^2+y^2} \). \item \( f(x,y) = \frac{xy}{x^2+y^2} \). \item \( f(x,y) = \frac{exp(\frac{-1}{x^2+y^2})}{|x|+|y|} \).
	\end{enumerate}

Soient \( ||.||_1 \) et \( ||.||_2 \) deux normes sur \( \Rr^2 \) et \( M = \left (
	\begin{array}{cc}
		a & b \\
		c & d
	\end{array}
	\right ) \) une matrice de \( {\cal M}_{n,n}(\Rr \mbox{ ou }
	\Cc) \). On définit la norme de \( M \) (ou de l'application linéaire associée) de la manière suivante:
	\[
	||M|| = \sup_{X \in S_1(0,1)}||M.X||_2
	\]
	où \( S_1(0,1) \) est la sphère unité pour la norme \( ||.||_1 \). Dans chacun des cas suivant, calculez la norme de \( M \).
	\begin{enumerate}
		\item \( ||(x,y)||_1 = ||(x,y)||_2 = \sup(|x|,|y|) \).

		\item \( ||(x,y)||_1 = ||(x,y)||_2 = \sqrt{x^2+y^2} \).

		\item \( ||(x,y)||_1 = \sqrt{x^2+y^2} \) et \( ||(x,y)||_2 = \sup(|x|,|y|) \).
	\end{enumerate}

Continuité sur \( \Rr^2 \) des fonctions suivantes:
	\begin{enumerate}
		\item \( f(x,y) = \frac{xy}{x^2+y^2} \)

		\item \( f(x,y) = \frac{x+y}{x^2+y^2} \)

		\item \( f(x,y) = \frac{x^3y^2}{x^2+y^2} \)
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f \) une application de \( E \) dans \( F \) espaces vectoriels normés et supposons \( f \) différentiable en \( a \); montrer que pour tout vecteur \( u\in E^* \), la dérivée de \( f \) en \( a \) dans la direction \( u \) existe, i.e. \( \lim_{h\to 0} {\frac 1 h}\big(f(a+hu)-f(a)\big) \) et l'exprimer à l'aide de \( f'(a) \).

		\item On considère \( f:{\Rr^2}\to\Rr \) définie par \( f(0,0) = 0 \) et, si \( (x,y)\neq(0,0) \),\ \( f(x,y) = {\frac{x^3y}{x^4+y^2}} \). Montrer que \( f \) est dérivable en \( (0,0) \) dans toutes les directions, mais que \( f \) n'est pas différentiable en \( (0,0) \).
	\end{enumerate}

Soit \( f \) une application différentiable de \( \Rr^2 \) dans lui-même, propre (i.e. \( ||f(x)|| \) tend vers \( \infty \) quand \( ||x||\to\infty \)), telle que pour tout \( x\in\Rr^2 \) \( Df(x) \) soit injective. On va montrer que \( f \) est surjective. Soit \( a\in\Rr^2 \) et \( g(x) = ||f(x)-a||^2 \);
	\begin{enumerate}
		\item Calculer \( Dg(x) \).

		\item Montrer que \( g \) atteint sa borne inférieure en un point \( x_0 \) de \( \Rr^2 \), et que \( Dg(x_0) = 0 \); en déduire le résultat.

	\end{enumerate}

Soit, dans \( {\Rr^n} \), \( F \) un sous-espace fermé, et soit \( f:{\Rr^n}\to\Rr \) définie par \( f(x) = d(x,F) \). On rappelle que \( f \) est \( 1 \)-lipschitzienne, et que pour chaque \( x \) il existe \( y\in F \) tel que \( f(x) = d(x,y) \).
	\begin{enumerate}
		\item On suppose que \( f \) est différentiable en \( x\notin F \). Montrer que \( ||Df(x)||_{{\cal L}(\Rr^n,\Rr)}\le 1 \).

		\item On considère la fonction \( \varphi : t\in[0,1]\to f((1-t)x+ty) \); en calculant \( \varphi'(0) \) de deux façons, montrer que \( Df(x)\cdot\frac{x-y}{||x-y||}=1 \) et \( ||Df(x)||_{{\cal L}(\Rr^n,\Rr)}=1 \).

		\item En déduire que \( y \) est unique.
	\end{enumerate}

Soit \( E \) un espace de Banach et \( {\cal L}(E) \) l'espace des endomorphismes linéaires continus de \( E \).
	\begin{enumerate}
		\item Soit \( A\in{\cal L}(E) \); montrer que l'application \( \varphi:t\in\Rr\to e^{tA} \) est dérivable et calculer sa dérivée.

		\item On suppose que la norme de \( E \) est associée au produit scalaire \( \langle \cdot,\cdot\rangle \). Soit \( x\in E \). Montrer que l'application \( \Phi:t\to \langle e^{tA}x,e^{tA}x\rangle \) est dérivable et calculer sa dérivée.

		\item On suppose que \( A \) est antisymétrique. Montrer que pour tout \( t \), \( e^{tA} \) est unitaire.
	\end{enumerate}

Soit \( {\cal F} \) l'algèbre des matrices carrées \( p\times p \) munie d'une norme.
	\begin{enumerate}

		\item Soit \( f:\mathcal{F} \to \Rr \) l'application qui associe à une matrice \( A \) son déterminant \( f(A) = \det (A) \). Montrer qu'elle est différentiable et déterminer \( Df \).

		\item Pour \( n\ge 1 \), on considère l'application \( \varphi_n (A) = A^n \) de \( {\cal F} \) dans \( {\cal F} \). Montrer qu'elle est différentiable en toute matrice \( A\in {\cal F} \).

		\item On désigne par \( U \) l'ensemble des matrices inversibles de \( {\cal F} \). Montrer que \( U \) est un ouvert de \( {\cal F} \) et calculer la différentielle de l'application \( A\mapsto A^{-1} \) de \( U \) dans \( U \).
	\end{enumerate}

\begin{enumerate}
		\item Que peut-on dire de la différentiabilité de l'application \( f:\Rr^2 \to \Rr \) définie par \( f(x_1,x_2) = \|x\|_\infty = \max{(|x_1|, |x_2|)} \)? \item Généraliser ceci à \( f:{\cal F} \to \Rr \), \( f(x) = \|x\|_\infty \), avec \( {\cal F} = \Rr^n \) ou \( {\cal F} \) l'ensemble des suites convergentes vers zéro.
	\end{enumerate}

\begin{enumerate}
		\item Soit \( f \) une application réelle continue et dérivable sur \( ]a,b[ \) telle que \( f'(x) \) ait une limite quand \( x\to b^- \); alors \( f \) se prolonge en une fonction continue et dérivable à gauche au point \( b \).

		\item Soit \( f \) une application continue et dérivable sur un intervalle \( I\subset\Rr \), et de dérivée croissante; montrer que \( f \) est convexe sur \( I \) i.e. \( f((1-t)x+ty)\le (1-t)f(x)+tf(y) \) pour tous \( x<y \) de \( I \) et \( t\in[0,1] \). (Poser \( z = (1-t)x+ty \) et appliquer les AF à \( [x,z] \) puis \( [z,y] \).)
	\end{enumerate}

