\begin{enumerate}
\item Montrons que \( [a, b] = \bigcap_{n = 1}^{\infty}
]a-\frac{1}{n}, b+\frac{1}{n}[ \).
\begin{itemize}
	\item Pour tout \( n\in\Nn \), on a \( [a, b] \subset\, ]a-\frac{1}{n}, b+\frac{1}{n}[ \). Donc \( [a, b]\subset\bigcap_{n = 1}^{\infty} ]a-\frac{1}{n}, b+\frac{1}{n}[ \).

	\item Soit \( x\in \bigcap_{n = 1}^{\infty} ]a-\frac{1}{n}, b+\frac{1}{n}[ \). Alors pour tout \( n\in\Nn \), on a :
	\[
	a-\frac{1}{n} < x < b+\frac{1}{n}.
	\]
	Ainsi
	\[
	\lim_{n\rightarrow+\infty}(a-\frac{1}{n})\le x \le
	\lim_{n\rightarrow+\infty}(b+\frac{1}{n}),
	\]
	c'est-à-dire \( x\in[a, b] \). Donc \( \bigcap_{n = 1}^{\infty}
	]a-\frac{1}{n}, b+\frac{1}{n}[ \subset [a, b] \) et on a démontré l'égalité entre ces deux ensembles.
\end{itemize}

\item Montrons que \( ]a, b[ = \bigcup_{n = 1}^{\infty} [a+
\frac{1}{n}, b-\frac{1}{n}] \).
\begin{itemize}
	\item Pour tout \( n\in\Nn \), on a \( [a+ \frac{1}{n}, b-\frac{1}{n}]\subset ]a,b[ \), donc \( \bigcup_{n = 1}^{\infty} [a+
	\frac{1}{n}, b-\frac{1}{n}]\subset]a,b[ \).

	\item Soit \( x\in\bigcup_{n = 1}^{\infty} [a+ \frac{1}{n}, b-\frac{1}{n}] \). Alors il existe \( n\in\Nn \) tel que \( x\in[a+ \frac{1}{n}, b-\frac{1}{n}] \). Ainsi \( x\in]a, b[ \) et \( \bigcup_{n = 1}^{\infty} [a+
	\frac{1}{n}, b-\frac{1}{n}] \subset ]a, b[ \), d'où l'égalité de ces deux ensembles.
\end{itemize}
\end{enumerate}

