exercices.correction:
Soit \( f :\Rr^n \rightarrow\Rr^+ \) la fonction définie par
\[
f(x) = |x|^{-p} \mathbf{1}_{\{|x|<1\}}(x).
\]
\begin{enumerate}
\item [(i)] On a :
\begin{eqnarray*} \int_{\Rr^n} f(x)\,dx & = &
	\int_{\Rr^n}|x|^{-p} \mathbf{1}_{\{|x|<1\}}(x) \,dx = \int_{|x|<1}
	|x|^{-p}\,dx = \int_{r=0}^1\int_{\sigma \in \mathcal{S}_{n-1}}
	r^{n-p-1} dr d\sigma\\
	& = & \frac{2\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}\right)}
	\int_0^1 r^{n-p-1}\,dr.
\end{eqnarray*}
Pour \( n \le p \), il vient
\begin{eqnarray*}
	\int_{\Rr^n} f(x)\,dx &=& +\infty.
\end{eqnarray*}
Pour \( p < n \), il vient
\begin{eqnarray*}
	\int_{\Rr^n} f(x)\,dx &=&
	\frac{2\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}\right)}
	\left[\frac{r^{n-p}}{(n-p)}\right]_0^1 =
	\frac{2\pi^{\frac{n}{2}}}{(n - p)\Gamma\left(\frac{n}{2}\right)}
\end{eqnarray*}

\item[(ii)] Pour \( a\in[0,+\infty[ \),
\begin{eqnarray*}
	S_f(a) = \{ x\in\Rr^n, |x|^{-p} \mathbf{1}_{|x|<1} > a\} =
	\{x\in\Rr^n, |x|^{-p} > a\}\cap \mathcal{B}(0, 1),
\end{eqnarray*}
où \( \mathcal{B}(0, 1) \) est la boule de centre 0 et de rayon 1. Ainsi
\begin{eqnarray*}
	S_f(a) = \{ x\in\Rr^n, a^{-\frac{1}{p}} > |x|\}\cap
	\mathcal{B}(0, 1).
\end{eqnarray*}
On en déduit que \( S_f(a) = \mathcal{B}(0, 1) \) si \( a^{-\frac{1}{p}}>1 \), i.e. si \( a<1 \) et que \( S_f(a) \) est égale à la boule \( \mathcal{B}(0, a^{-\frac{1}{p}}) \) de centre 0 et de rayon \( a^{-\frac{1}{p}} \) lorsque \( a\ge 1 \). Il vient alors :
\begin{eqnarray*}
	\int_{\Rr^n} f(x)\,dx &=& \int_0^{+\infty}
	\mu\left(S_f(a)\right)\,da = \int_0^1
	\mu\left(\mathcal{B}(0,1) \right)\,da + \int_1^{+\infty}
	\mu\left(\mathcal{B}(0, a^{-\frac{1}{p}})\right)\,da\\
	& = & \frac{\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}+1\right)} +
	\frac{\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}+1\right)}\int_1^{+\infty}
	a^{-\frac{n}{p}}\,da.
\end{eqnarray*}
Si \( p\ge n \), on obtient \( \int_{\Rr^n} f(x)\,dx = +\infty \) et pour \( p<n \), on a :
\begin{eqnarray*}
	\int_{\Rr^n} f(x)\,dx & = &\frac{\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}+1\right)} +
	\frac{\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}+1\right)}\left[\frac{a^{-\frac{n}{p}+1}}{-\frac{n}{p}+1}\right]_1^{+\infty}\\
	&=&\frac{\pi^{\frac{n}{2}}}{\Gamma\left(\frac{n}{2}+1\right)}\left(1 + \frac{p}{n-p} \right) = \frac{2\pi^{\frac{n}{2}}}{(n - p)\Gamma\left(\frac{n}{2}\right)}.
\end{eqnarray*}
\end{enumerate}

\begin{enumerate}
\item Montrons que pour tout \( x\in \Rr_+ \), \( (1+\frac{x}{n})^n \) est une suite croissante et que \( \lim\limits_{n\rightarrow\infty}(1+\frac{x}{n})^n = e^x \). Pour \( n\in \Nn \) on a
\[
\left(1+\frac{x}{n}\right)^n = \sum\limits_{k = 0}^n {\binom{n}{k}}\left(\frac{x}{n}\right)^k = \sum\limits_{k = 0}^n a_{n,k}\,\frac{x^k}{k!},
\]
où \; \( \displaystyle a_{n,k} = \frac{n!}{(n-k)!n^k} = \frac{n(n-1)\cdots(n-k+1)}{n^k} \).

\bigskip

Les assertions suivantes sont vraies:
\begin{enumerate}
	\item[{i)}] \( a_{n+1,k}\ge a_{n,k} \). En effet, \( \frac{n+1-l}{n+1}\ge \frac{n-l}{n} \) \, pour \, \( l\in \Nn \)
	\, car \, \( n^2+n-l\cdot n\ge n^2+n-l\cdot n-l \),

	\item[{ii)}] \( a_{n,k}<1 \) \; (évident);

	\item[{iii)}] Pour tout \( k\in \Nn \), \; \( \lim\limits_{n\rightarrow\infty}a_{n,k} = 1 \).

\end{enumerate}

Comme \( a_{n+1,n+1}>0 \), \( \displaystyle\left(1+\frac{x}{n+1}\right)^{n+1} = \sum\limits_{k = 0}^{n+1}
a_{n+1,k}\,\frac{x^k}{k!}>\sum\limits_{k = 0}^n a_{n+1,k}\,\frac{x^k}{k!} \). Il s'ensuit donc de (i) que la suite \( \displaystyle\left\{\left(1+\frac{x}{n}\right)^n\right\} \) est croissante. Les assertions (ii) et (iii) impliquent que
\[
\left(1+\frac{x}{n}\right)^n = \sum\limits_{k = 0}^n a_{n,k}\,\frac{x^k}{k!}\le \sum\limits_{k = 0}^n \frac{x^k}{k!}\le
\sum\limits_{k = 0}^\infty \frac{x^k}{k!} = e^x
\]
et que, pour tout \( m\in\Nn \),\; \( \displaystyle\lim\limits_{n\rightarrow\infty}\left(1+\frac{x}{n}\right)^n\ge
\sum\limits_{k = 0}^m \frac{x^k}{k!} \). \; \; Ainsi, \; \( \displaystyle\lim\limits_{n\rightarrow\infty}\left(1+\frac{x}{n}\right)^n = e^x \).

\item Par le théorème de convergence monotone, on a pour \( b>1 \),
\begin{eqnarray*}
	\lim\limits_{n\rightarrow\infty}\int_{\Rr_+}\left(1+\frac{x}{n}\right)^n e^{-bx} d\lambda(x) &=
	\int_{\Rr_+}\lim\limits_{n\rightarrow\infty}\left(1+\frac{x}{n}\right)^n e^{-bx} d\lambda(x)\\ &=\int_0^\infty e^{(1-b)x}
	d\lambda(x)=\frac{1}{b-1}.
\end{eqnarray*}
\end{enumerate}

exercices.enonce:
Montrer que

\begin{enumerate}
\item \( \displaystyle \lim_{n \to \infty} \int_0^n \left(1-\frac{x}{n}\right)^n x^mdx = m ! \) \ (pour tout \( m\in \Nn \)).

\item \( \displaystyle \lim_{n \to \infty} \int_0^n \left(1+\frac{x}{n}\right)^n e^{-2x}dx = 1 \).
\end{enumerate}

\label{derivation}
Montrer le théorème suivant, \( \Omega \) étant un espace mesurable. (On pourra utiliser le théorème des accroissements finis.) \\
\textbf{Théorème.}(Dérivation sous le signe \( \int \)) \\
Soit \( f :\Omega \times \Rr \rightarrow \Cc \) une fonction telle que
\begin{enumerate}
\item[(i)] Pour tout \( s\in[s_1, s_2] \), la fonction \( x\mapsto f(x, s) \) est intégrable ;

\item[(ii)] pour presque tout \( x \), la fonction \( s\mapsto f(x, s) \) est dérivable sur \( (s_1, s_2) \);

\item[(iii)] il existe \( g\in \mathcal{L}^1(\Omega, \Rr^{+}) \) tel que pour tout \( s \in [s_1, s_2] \) et pour presque tout \( x\in\Omega \) on ait \( |\frac{\partial f(x,s)}{\partial s}| \le g(x) \).
\end{enumerate}
Alors la fonction \( I(s):= \int_{\Omega} f(x, s)\,d\mu(x) \) est dérivable sur \( (s_1, s_2) \) et
\[
\frac{dI}{ds} = \int_{\Omega} \frac{\partial f(x,s)}{\partial s}
\,d\mu(x).
\]

exercices.correction:
\begin{enumerate}
\item Notons \( g(x,y) = e^{-ixy} f(x) \). Alors,
\begin{enumerate}
	\item[{i.)}] pour tout \( y\in \Rr \), la fonction \( x\mapsto g(x,y) \) est mesurable; \item[{ii.)}] pour presque tout \( x\in
	\Rr \) (pour tout les \( x\in \Rr \) tels que \( f(x) \) est finie) la fonction \( y\mapsto g(x,y) \) est continue pour tout \( y\in
	\Rr \); \item[{iii.)}] \( |g(x,y)| = |e^{-ixy} f(x)|\le |f(x)| \) et \( |f|\in \mathcal{L}^1(\Rr,\Rr_+) \).
\end{enumerate}
On doit montrer que pour tout suite \( \{y_n\}_{n\in\Nn} \) convergeant vers \( y \), on a \( \lim_{n\rightarrow +\infty}
\hat{f}(y_n) = \hat{f}(y) \). Posons \( g_n(x) = g(x, y_n) \). D'après le théorème de convergence dominée,
\[
\lim_{n\rightarrow +\infty} \hat{f}(y_n)  :=  \lim_{n\rightarrow +\infty} \int_\Rr g_n(x)\,dx = \int_\Rr g(x,y) dx = : \hat{f}(y).
\]
Ainsi \( \hat{f} \) est continue.

\item Pour tout \( y\in \Rr \), \( |\hat{f}(y)|\le
\displaystyle\int_\Rr|e^{-ixy} f(x)|dx\le
\displaystyle\int_\Rr| f(x)|dx = \|f\|_{L_1} \) et donc
\[
\sup|\hat{f}|\le\|f\|_{L_1}.
\]

\item Soit \( g(x,y) = e^{-ixy} f(x) \). Alors, on a
\begin{enumerate}
	\item[{i.)}] pour tout \( y\in \Rr \), la fonction \( x\mapsto g(x,y) \) est intégrable;

	\item[{ii.)}] pour presque tout \( x\in \Rr \) la fonction \( y\mapsto g(x,y) \) est dérivable pour tout \( y\in \Rr \);

	\item[{iii.)}] \( |\frac{\partial g(x,y)}{\partial y}| = |-ix e^{-ixy}
	f(x)|\le |x f(x)| \) avec \( x\mapsto xf(x) \) intégrable.
\end{enumerate}
Ainsi, d'après l'exercice \ref{derivation} (le théorème de dérivation sous le signe \( \int \)), on a
\[
\frac{d}{dy}\hat{f} = \int_\Rr e^{-ixy}(-ix f(x))dx = \widehat{-iyf(y)}.
\]
\end{enumerate}

Soient \( a, b>0 \), et \( f \) et \( g \) les fonctions définies sur \( \Rr^n \) par \( f(x) = e^{-\frac{a |x|^2}{2}} \) et \( g(x) = e^{-\frac{b |x|^2}{2}} \). On a
\begin{eqnarray*}
f*g(x) = \int_{\Rr^n} f(x-y)\,g(y)\,dy =
\int_{\Rr^n} e^{-\left(\frac{a|x-y|^2 + b|y|^2}{2}\right)}\, dy
\end{eqnarray*}
Or
\begin{eqnarray*}
a|x-y|^2 + b|y|^2 &=& \sum_{i=1}^n a x_i^2 + (a + b) y_i^2 -2a x_i y_i\\
& = & \sum_{i=1}^n a x_i^2 + (a + b)\left(y_i - \frac{a}{a+b} x_i
\right)^2 - (a+b) \left(\frac{a x_i}{a+b} \right)^2\\
& = & \sum_{i=1}^n \left(a - \frac{a^2}{a+b}\right) x_i^2 + (a + b)\left(y_i - \frac{a}{a+b} x_i \right)^2\\
& = & \frac{ab}{a + b}|x|^2 + (a+b)\left|y-\frac{a}{a+b}x\right|^2.
\end{eqnarray*}
Ainsi
\begin{eqnarray*}
f*g(x) & = & e^{-\frac{ab}{a + b}\frac{|x|^2}{2}}\int_{\Rr^n}
e^{-\frac{(a+b)}{2}\left|y-\frac{a}{a+b}x\right|^2}\,dy = e^{-\frac{ab}{a + b}\frac{|x|^2}{2}}
\int_{\Rr^n} e^{-\frac{(a + b)}{2} |z|^2}\,dz
\end{eqnarray*}
car la mesure de Lebesgue est invariante par translation. En utilisant \( \int_\Rr e^{-t^2} \,dt = \sqrt{\pi} \), on obtient alors :
\[
f*g(x) = \left(\frac{2\pi}{a + b}\right)^{\frac{n}{2}}
e^{-\frac{ab}{a + b}\frac{|x|^2}{2}}.
\]

