\item On considère \( f \) définie par \( f(z) = \displaystyle\frac{z^n}{(z-\lambda)(z-\lambda^{-1})} \); en calculant l'intégrale de \( f \) sur le cercle unité, trouver la valeur de \( I \) (distinguer les deux cas \( |\lambda|>1, |\lambda|<1 \)).
\end{enumerate}

Soit \( U \) un ouvert de \( \Cc \) contenant \( \bar D \) et \( f\in H(U) \). On note \( \gamma \) le paramétrage de \( \partial D \) par \( t\in [0,2\pi]\to e^{it} \).
\begin{enumerate}
\item Calculer \( I_1 = \displaystyle\int_{\gamma} (2+z+\frac{1}{z})\frac{f(z)}{z}\ dz \) et \( I_2 = \displaystyle\int_{\gamma} (2-z-\frac{1}{z})\frac{f(z)}{z}\ dz \).

\item En déduire la valeur de \( \displaystyle\int_0^{2\pi}
f(e^{i\theta})\cos^2(\frac{\theta}{2})\ d\theta \) et \( \displaystyle\int_0^{2\pi}
f(e^{i\theta})\sin^2(\frac{\theta}{2})\ d\theta \).

\item Pour \( |a|\not=1 \), évaluer \( I(a) = \displaystyle\frac{1}{2i\pi}\int_{\gamma}
\frac{\overline{f(z)}}{z-a}\ dz \).
\end{enumerate}

\begin{enumerate}
\item Montrer que \( \int_0^{2\pi} e^{re^{it}}\ dt \) est indépendant de \( r>0 \).

\item Montrer que \( \int_0^{2\pi} \mathrm{Log}{(1-re^{it})}\ dt \) est indépendant de \( r\in \mathopen]0,1\mathclose[ \) (\( \mathrm{Log} \) désigne la branche principale du logarithme sur \( \Cc\setminus \mathopen]-\infty,0] \)).
\end{enumerate}

\begin{enumerate}
\item Montrer qu'il existe sur \( \Cc\setminus [-1,1] \) une détermination holomorphe de \( (z^2-1)^{-1/2} \) qui prend la valeur 1 pour \( z = \sqrt 2 \). Unicité ? On désignera par \( f \) cette détermination.

\item Pour \( z\in \Cc\setminus\Rr \), on désigne par \( \gamma_z \) le segment \( \mathopen] 0,z] \) orienté de 0 vers \( z \) et on pose
\[
F(z) = \int_{\gamma_z}f(\zeta)\ d\zeta .
\]
\begin{enumerate}
	\item Montrer que \( F \) est holomorphe sur \( \Cc\setminus \Rr \) (quelle en est la dérivée \( F' \) ?).

	\item Étudier \( \lim_{z'\to z}F(z') \) lorsque \( z\in \Rr\setminus [-1,1] \).

	\item En déduire que \( f \) n'a pas de primitive sur \( \Cc\setminus [-1,1] \).
\end{enumerate}
\end{enumerate}

\begin{enumerate}
\item Soit \( f \) une fonction entière telle que \( |f(z)|\le 1+e^{|z|}\sin|z| \) pour tout \( z \). Montrer que \( f \) est une constante.

\item Soit \( f\in H(D) \) telle que \( |f(z)|(1-|z|)\le 1 \) pour \( z\in D \). Montrer que pour tout \( n \) \( |a_n|< e(n+1) \).
\end{enumerate}

Soit \( f \) une fonction entière telle que \( |f(z)|\to+\infty \) quand \( |z|\to+\infty \).
\begin{enumerate}
\item Montrer que \( f \) n'a qu'un nombre fini de zéros dans \( \Cc \) notés \( z_1,\ldots z_k \).

\item En déduire que \( f \) est un polynôme. (Pour cela considérer \( f(z)/P(z) = g(z) \) où \( P(z) = (z-z_1)\cdots (z-z_k) \) et montrer que \( 1/g \) est entière) .
\end{enumerate}

On considère la série entière \( f(z) = \sum_{n\ge 1} \frac{z^n}{n} \).

\begin{enumerate}
\item Montrer que \( f \) admet un prolongement analytique sur un ouvert que l'on déterminera.

\item Déterminer le développement en série entière de ce prolongement en \( i \). Quel est son rayon de convergence ?
\end{enumerate}

Soit \( F_1(z) = \int_0^{+\infty}e^{-(z+1)^2t}dt \).

\begin{enumerate}
\item Déterminer l'ouvert \( E \) sur lequel \( F_1 \) définit une fonction holomorphe.

\item Montrer que \( F_1 \) se prolonge analytiquement en une fonction \( F \) sur un ouvert que l'on déterminera. Calculer \( F(2-4i) \).
\end{enumerate}

Existe-t-il des fonctions \( f \) holomorphes sur \( D(0,1) \) telles que pour tout entier \( n>0 \) ?

\begin{enumerate}
\item \( f\left( \frac{1}{2n}\right) = f\left( \frac{1}{2n+1}\right) = \frac{1}{n} \) ?

\item \( f\left( \frac{1}{n}\right) = f\left( -\frac{1}{n}\right) = \frac{1}{n^2} \) ?

\item \( f\left( \frac{1}{n}\right) = f\left( -\frac{1}{n}\right) = -\frac{1}{n^3} \) ?
\end{enumerate}

Soit \( f \) une fonction entière telle que \( \vert f(z)\vert = 1 \) si \( \vert z\vert = 1 \). Soit \( D \) le disque unité fermé.

\begin{enumerate}
\item Supposons que \( f \) n'a pas de zéros dans \( D \). Montrer qu'il existe \( k\in\Cc \) tel que \( f(z) = k \) pour tout \( z\in\Cc \).

\item Soit \( a_1,\dots,a_n \) (pourquoi un nombre fini ?) les zéros de \( f \) dans \( D \) , chacun étant compté avec son ordre de multiplicité. En étudiant la fonction
\[
g(z) = f(z)\prod_{j = 1}^n\frac{1-\overline{a_j}z}{z-a_j}
\]
montrer qu'il existe \( k\in\Cc \), \( \vert k\vert = 1 \), et \( n\in \Nn \) tels que \( f(z) = kz^n \).
\end{enumerate}

Soit \( f \) une fonction holomorphe dans un domaine contenant la couronne fermée constituée par les \( z\in\Cc \) tels que \( r_1\le\vert z\vert \le r_2 \) (où \( 0<r_1<r_2 \)). On pose \( M(r) = \max_{\vert z\vert = r}\vert f(z)\vert \) pour \( r_1\le r\le r_2 \).

\begin{enumerate}
\item Montrer qu'il existe un nombre réel \( \alpha \) tel que \( r_1^\alpha M(r_1) = r_2^\alpha M(r_2) \).

\item Montrer que
\[
M(r)\le M(r_1)^\frac{\ln{r_2}-\ln{r}}{\ln{r_2}-\ln{r_1}}
M(r_2)^\frac{\ln{r}-\ln{r_1}}{\ln{r_2}-\ln{r_1}}
\]
(on appliquera le principe du maximum à la fonction \( z^pf(z)^q \) où \( p\in\Zz \) et \( q\in \Nn^* \), puis on considérera une suite \( (p_n,q_n) \), \( p_n\in\Zz \) et \( q_n\in \Nn^* \), telle que \( \lim_{n\to\infty}p_n/q_n = \alpha \)).
\end{enumerate}

Soit \( \gamma \) un chemin \( \mathcal{C}^1 \) par morceaux de \( \Cc \) allant de \( 0 \) à \( i \). Calculer \( \int_\gamma f(z)dz \) avec :
\begin{enumerate}
\item \( f(z) = z^2\sin z \)

\item \( f(z) = ze^{iz} \).
\end{enumerate}

[Principe de réflexion de Schwarz] Soit \( U\subset \Cc \) un ouvert symétrique par rapport à l'axe réel. Notons \( U_+:=U\cap\{\Im(z)>0\} \) et \( U_-:=U\cap \{\Im(z)<0\} \). Soit \( f:\overline{U_+}\to \Cc \) une fonction continue telle que \( f|_{U_+} \) est holomorphe et telle que \( f(x)\in\Rr \) pour tout \( x\in \overline{U_+}\cap \Rr \).
\begin{enumerate}
\item Montrer que la fonction \( g:\overline{U_-}\to \Cc \) définie par \( g(z):=\overline{f(\bar z)} \) est continue sur \( \overline{U_-} \) et holomorphe sur \( U_- \).

\item Montrer que l'on peut étendre la fonction \( f \) en une fonction continue \( h:\overline{U}\to \Cc \) en posant \( h(z) = f(z) \) si \( z\in \overline{U_+} \) et \( h(z) = g(z) \) si \( z\in \overline{U_-} \).

\item Montrer que \( h|_U \) est holomorphe.
\end{enumerate}

\begin{enumerate}
\item Déterminer les développements en série de Laurent de \( f(z) = \frac{1}{1-z^2}+\frac{1}{3-z} \) dans les domaines \( D = D(0,1) \), \( C_1 = \{1<|z|<3\} \) puis \( C_2 = \{|z|>3\} \).

\item Déterminer les développements en série de Laurent de \( f(z) = \frac{z}{z-1}e^z \) dans les domaines \( C_1 = \{|z|<1\} \) puis \( C_2 = \{|z|>1\} \).
\end{enumerate}

Développer les fonctions suivantes en série de Laurent dans chacun des ouverts donnés

\begin{enumerate}
\item \( \displaystyle f(z) = \frac{1}{(z-1)(z-2)} \) dans \( \vert z\vert <1 \) ; \( 1<\vert z\vert <2 \) ; \( 2<\vert z\vert \) ;

\item \( \displaystyle f(z) = \frac{1}{(z-a)^k} \) (\( k\in \Nn^* \)) dans \( \vert z\vert <\vert a\vert \) et dans \( \vert z\vert >\vert a\vert \) ;

\item \( \displaystyle f(z) = \frac{1}{z(z-a)} \) dans \( 0<\vert z\vert <\vert a\vert \) et dans \( \vert a\vert <\vert z\vert \) ;

\item \( \displaystyle f(z) = \frac{1}{(z-a)(z-b)} \) (\( 0<\vert a\vert <\vert b\vert \)) dans \( 0<\vert z\vert <\vert a\vert \) ; \( \vert a\vert<\vert z\vert <\vert b\vert \) ; \( \vert b\vert <\vert z\vert \) ;

\item une détermination holomorphe \( f \) de \( [(z-a)(z-b)]^\frac{1}{2} \) (\( 0<\vert a\vert = \vert b\vert \)) dans \( 0<\vert z\vert <\vert a\vert \) ; \( \vert b\vert <\vert z\vert \) ;

\item \( f(z) = z^2\exp{(z^{-1})} \) dans \( 0<\vert z\vert \).

\item \( f(z) = \exp{(z+z^{-1})} \) dans \( 0<\vert z\vert \).

\item \( f(z) = \sin z\cdot\sin{\left(z^{-1}\right)} \) dans \( 0<\vert z\vert \).

\item \( f(z) = \cotan z \) dans \( k\pi<\vert z\vert<(k+1)\pi \) (\( k\in \Nn \)) on pourra exprimer le résultat en fonction des nombres \( B_n \) de Bernoulli, définis par :
\[
\frac{z}{\exp{(z)}-1} = \sum_{n\ge 0}B_n\frac{z^n}{n!}
\]
(\( B_0 = 1 \), \( B_1 = -1/2 \), et \( B_{2n+1} = 0 \) pour \( n\ge 1 \)).
\end{enumerate}

Exhiber des fonctions n'ayant dans le plan complexe que les singularités suivantes:

\begin{enumerate}
\item un pôle triple en 0, un pôle simple en 1 et un point singulier essentiel en \( i \) et \( -i \).

\item un point singulier essentiel en tout entier.
\end{enumerate}

Déterminer les singularités isolées \( a \) des fonctions \( f \) suivantes et calculer \( \mathrm{Res} (f,a) \).

\[
\begin{array}{lll}
1. \displaystyle z\mapsto \frac{1}{z^3-z^5}\            & 2.\ \displaystyle z\mapsto \frac{z^2}{(z^2+1)^2}\                      & 3.\ \displaystyle z\mapsto \exp{(z+z^{-1})}       \\
4.\ \displaystyle z\mapsto \frac{\sin{(2z)}}{(z+1)^3}\  & 5.\ \displaystyle z\mapsto \cos{\left( \frac{z^2+4z-1}{z-3}\right) }\  & 6.\ \displaystyle z\mapsto z^n\sin{(\frac{1}{z})}
\end{array}
\]

Calculer les intégrales suivantes, où les chemins fermés simples \( \gamma \) sont parcourus dans le sens direct.

\begin{enumerate}
\item \( \displaystyle \int_\gamma \frac{z}{(z-1)(z-2)^2}dz \) où \( \gamma \) est le cercle \( \vert z-2\vert = \frac{1}{2} \) ;

\item \( \displaystyle \int_\gamma \frac{\exp z}{z^2(z-9)^2}dz \) où \( \gamma \) est le cercle \( \vert z\vert = 1 \) ;

\item \( \displaystyle \int_\gamma \exp{\left( \frac{1}{z}\right) }\ dz \) où \( \gamma \) est le cercle \( \vert z\vert = 1 \) ;

\item \( \displaystyle \int_\gamma \sin^2{\left( \frac{1}{z}\right) }\ dz \) où \( \gamma \) est le cercle \( \vert z\vert = r \) ;

\item \( \displaystyle \int_\gamma (z^2+z+1)^{-1/2}\ dz \) où \( \gamma \) est le cercle \( \vert z\vert = r\ne 1 \).
\end{enumerate}

Si \( f \) est une fonction méromorphe sur un ouvert \( D \) de \( \Cc \), on notera \( P(f) \) le lieu de ses pôles.
\begin{enumerate}
\item Soit \( D \) un ouvert de \( \Cc \) et \( f,g \) deux applications méromorphes sur \( D \). Montrer qu'on a équivalence entre
\begin{enumerate}
	\item \( f = g \)

	\item \( \{z\in D-P(f)-P(g), f(z) = g(z)\} \) a un point d'accumulation dans \( D \).
\end{enumerate}

\item Peut-on construire une application méromorphe sur \( \Cc^\star \) non nulle mais nulle en tous les réels de la forme \( \frac{1}{n} \) avec \( n\in\Nn \) ?
\end{enumerate}

exercices.correction:
On intègre \( f(z) = e^{2iaz -z^2} \) sur le rectangle. Il n'y a aucun pôle, donc l'intégrale sur le rectangle est nulle; l'intégrale sur le côté \( [R, R+ia] \) tend vers zéro. On a donc
\[
\begin{array}{ccc}
\int_0^{+\infty } e^{2iax-x^2} \,dx & = \int_{[0,ia]} f(z)\,dz + \int_{[ia, ia+\infty ]}f(z)\,dz            \\
& = \int_0^a e^{-2ay+y^2}\,idy + \int_0^{+\infty } e^{(ia-x)(ia+x)}\,dx \\
& = i\int_0^a e^{y^2-2ay}\, dy + e^{-a^2}\frac{\sqrt \pi}{2}
\end{array}
\]
d'où le résultat en ne conservant que la partie réelle.

exercices.enonce:
\begin{enumerate}
\item Soit \( f \) une fonction continue sur \( \overline{D(0,1)} \), holomorphe sur \( D(0,1) \), nulle sur le cercle de rayon \( 1 \). Montrer que \( f \) est identiquement nulle.

\item Plus fort: on ne suppose plus que \( f(e^{i\theta}) \) est nulle pour tout \( \theta \) mais seulement pour \( 0\le\theta\le\pi \). Montrer que \( f \) est identiquement nulle.
\emph{Indication :} \( f(z)f(-z) \).
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item C'est le principe du maximum.

\item La fonction \( g(z) = f(z) f(-z) \) est nulle sur le cercle de rayon \( 1 \).
\end{enumerate}

exercices.enonce:
\begin{enumerate}
\item Soit \( f \) analytique sur un disque \( |z - z_0|\le R \) et telle qu'il existe un certain \( z_1 \) avec \( |z_1 - z_0|<R \) tel que \( |f(z)|>|f(z_1)| \) pour \( |z-z_0| = R \). Montrer que \( f \) s'annule au moins une fois dans le disque ouvert \( D(z_0,R) \).
\emph{Indication :} considérer sinon ce que dit le principe du maximum pour la fonction \( \frac1f \).

\item \emph{Théorème de Hurwitz.} Soit \( f_n \) des fonctions holomorphes sur un voisinage commun \( U \) de \( \overline{D(0,1)} \) qui convergent uniformément sur \( U \). Soit \( F \) la fonction limite. On suppose que \( F \) n'a aucun zéro sur le cercle \( |z| = 1 \), et qu'elle a au moins un zéro dans le disque ouvert \( D(0,1) \). Montrer en appliquant la question précédente à \( f_n \) que pour \( n\gg1 \) la fonction \( f_n \) a au moins un zéro dans \( D(0,1) \).\footnote{On verra plus tard en cours ou en exercice que pour \( n\gg1 \) chaque \( f_n \) a, comptés avec leurs multiplicités, exactement le même nombre de zéros que \( F \) dans \( D(0,1) \).}
Ce résultat est souvent appliqué sous sa forme réciproque: \emph{si des fonctions holomorphes \( f_n \) sans zéro convergent uniformément sur un ouvert connexe vers \( F \) alors soit \( F \) est identiquement nulle soit \( F \) n'a aucun zéro.} Justifier cette dernière reformulation.
\end{enumerate}

Soit \( f \) une fonction entière telle que \( |f(z)|\le M\,(1+ |z|)^n \) pour un certain \( M \) et un certain \( n\in\Nn \). Donner plusieurs démonstrations que \( f \) est un polynôme de degré au plus \( n \):
\begin{itemize}
\item en utilisant une formule intégrale de Cauchy pour \( f^{(n+1)}(z) \), avec comme contour les cercles de rayon \( R \) centrés en l'origine, ou en \( z \) si l'on veut,

\item en utilisant les formules de Cauchy pour \( f^{(m)}(0) \), avec \( m\ge n+1 \),

\item en appliquant le théorème de Liouville à \( (f(z) - P(z))/z^{n+1} \) avec \( P \) le polynôme de McLaurin-Taylor à l'origine à l'ordre \( n \).
\end{itemize}

Soit \( f \) une fonction entière vérifiant \( \lim_{|z|\to\infty}
|f(z)| = +\infty \). Donner plusieurs démonstrations que \( f \) est un polynôme:
\begin{itemize}
\item en montrant, par un théorème du cours, que \( w = 0 \) est une singularité polaire de \( g(w) = f(\frac1w) \), et en en déduisant qu'il existe un polynôme \( P \) tel que \( f(z) - P(z) \) tende vers \( 0 \) pour \( |z|\to\infty \), puis Liouville,

\item ou en montrant que \( f \) n'a qu'un nombre fini de zéros \( z_j \), \( 1\le j\le n \), et en appliquant à \( (z-z_1)\dots (z- z_n)/f(z) \) le résultat de l'exercice précédent, plus quelques réflexions de conclusion pour achever la preuve.
\end{itemize}
Montrer que la fonction entière \( z+e^z \) tend vers l'infini le long de tout rayon partant de l'origine. D'après ce qui précède \( z+e^z \) est donc un polynôme. Commentaires?

Déterminer les séries de Laurent et les résidus à l'origine des fonctions suivantes:
\begin{enumerate}
\item \( f(z) = \frac1z \)

\item \( f(z) = \frac1{z^2+1} \)

\item \( f(z) = \frac1{z(z^2+1)} \)
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Le résidu est \( a_{-1} = 1 \).

\item \( f(z) = \frac{1}{1+z^2} = \sum_{k = 0}^\infty (-1)^k z^{2k} \) pour \( |z|< 1 \). C'est une série entière car \( f \) est holomorphe dans le disque unité et \( \mathrm{Res} (f ,0) = 0 \).

\item \( f(z) = \frac{1}{z}\frac{1}{1+z^2} = \sum_{k = 0}^\infty (-1)^k z^{2k-1} = \frac{1}{z}-z +z^3 .. \)...et \( \mathrm{Res} (f ,0) = 0 \)
\end{enumerate}

exercices.enonce:
Déterminer la partie singulière, le résidu, et le terme constant des séries de Laurent à l'origine pour les fonctions:
\begin{enumerate}
\item \( f(z) = \frac1{\sin z} \)

\item \( f(z) = \frac1{\sin z - \sh z} \)

\item \( f(z) = \frac1{z\sin(z)\sh(z)} \)
\end{enumerate}

\begin{enumerate}
\item Soit \( \gamma:[0,1]\to\Cc\setminus\{0\} \) un lacet et soit \( N\in \Zz \) son indice par rapport à \( 0 \). En utilisant la notion de variation de l'argument, montrer qu'il existe une fonction continue \( g:[0,1]\to\Cc \) telle que \( \forall t\quad \gamma(t) = e^{g(t)} \) et \( g(1) - g(0) = 2\pi i N \). Montrer que toute autre fonction continue \( G \) avec \( \forall t\quad \gamma(t) = e^{G(t)} \) est de la forme \( g+2\pi i k \) pour un certain \( k\in\Zz \). On pose \( h(t,u) = (1-u)\;2\pi i N\,t + ug(t) \) puis \( H(t,u) = e^{h(t,u)} \). Montrer que pour chaque \( u\in[0,1] \) l'application \( t\mapsto H(t,u) \) est un lacet. En déduire que le lacet \( c_N(t) = e^{2\pi i\; Nt} \) et \( \gamma \) sont homotopes dans \( \Cc\setminus\{0\} \).

\item On considère le lacet obtenu en suivant d'abord \( c_N \) puis \( c_M \). Montrer que ce lacet est homotope dans \( \Cc\setminus\{0\} \) au lacet \( c_{N+M} \) (il suffit de calculer son indice!).
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Le calcul de l'indice de \( c_N \) est évident. L'affirmation sur l'existence de \( g \) continue telle que \( \gamma = e^g \) et \( g(1)-g(0) = 2\pi i N \) est le contenu du polycopié de J.-F. Burnol 2005/2006, chapitre 30. Le reste est laissé au lecteur.
\end{enumerate}

exercices.enonce:
\label{ex:burnol6.4}
Soit \( 0<a<b<c \) et soit \( C \) le cercle de rayon \( r \) centré en l'origine, parcouru dans le sens direct. Calculer \( \int_C
\frac1{(z-a)(z-b)(z-c)}dz \) selon la valeur de \( r \). On donnera deux preuves, soit en utilisant le théorème des résidus, soit en décomposant en éléments simples.

\label{ex:burnol2.2}
Soit \( f \) une fonction définie et continue sur le domaine \( \{\Im(z)>0, |z|>R\} \), ou seulement sur une suite de demi-cercles \( \{\Im(z)>0, |z| = R_n\} \) de rayons tendant vers l'infini. On suppose \( \lim_{\substack{|z|\to\infty \\ \Im(z)>0}} |f(z)| = 0 \) (ou \( \displaystyle\lim_{n\to\infty}
\sup_{\Im(z)>0,\,|z| = R_n} |f(z)| = 0 \).) Montrer (on utilisera \( \sin(\theta)\ge \frac2\pi \theta \) pour \( 0\le\theta\le\frac\pi2 \)):
\[
\lim_{R\to\infty} \int_{z = R e^{i\theta},\, 0<\theta<\pi} f(z)e^{iz}\,dz = 0\qquad (\text{ou l'analogue avec les\ }R_n)
\]

\begin{enumerate}
\item Déterminer
\[
\int_0^{+\infty} \frac{dx}{1 + x^3}
\]
Pour ce calcul, on considérera le contour allant le long de l'axe réel de \( 0 \) à \( R \) puis de \( R \) à \( j R \) le long d'un cercle puis de \( jR \) à \( 0 \) par un segment (\( j = \exp(i\frac{2\pi}3) \)). On écrira d'une part chacune des trois contributions à l'intégrale de contour, en faisant attention au sens de parcours, et l'on utilisera d'autre part le théorème des résidus.

\item On note, pour \( |w| = 1 \) et certaines valeurs spéciales de \( w \) (que l'on précisera) étant exclues, \( J(w) \) l'intégrale \( \int \frac{dz}{1+z^3} \) le long du segment infini \( w\Rr^+ \). Déterminer \( J(w) \) en fonction de \( w \).
\end{enumerate}

\begin{enumerate}
\item Démontrer que
\[
\int_{\gamma} \frac{dz}{(z-a)^n} = \begin{cases}
	2\pi i \quad & n = 1,          \\
	0            & n = 2,3,4,\dots\end{cases}
\]
\( \gamma \) étant une courbe fermée simple ayant \( a \) dans son intérieur et orientée positivement.

\item Quelle est la valeur de l'intégrale si \( n = 0,-1,-2, \dots \)?
\end{enumerate}

\begin{enumerate}
\item Calculer les résidus aux différents pôles de la fonction \( f(z) = \frac{z^2+z+1}{z(z^2+1)^2};\ f(z) = \displaystyle\frac{1}{1+z+\cdots+z^{n-1}};\ f(z) = \frac{1}{e^z-1}-\frac{1}{z} \).

\item Montrer que si \( f(z) = (z-a)^{-n} g(z) \) où \( g \) est holomorphe dans \( \Omega \) ouvert contenant \( a \), alors Res\( (f,a) = \displaystyle\frac{g^{(n-1)}(a)}{(n-1)!} \). Trouver les pôles et résidus des fonctions suivantes : \( \displaystyle\frac{1-\cos z}{z^3},\ \displaystyle\frac{e^{2z}}{(z-1)^3},\
