exercices.correction:
\begin{enumerate}
\item On note \( R \) le rayon de convergence de la série entière \( \sum_{n\ge 1}a_nz^n \) et \( r\in]0,R[ \). On sait alors que \( (a_n r^n)_{n\in\Nn} \) est une suite bornée en module. Soit \( z\in\Cc \)
\[
\left|\frac{a_n}{n!}z^n\right|\le \left|a_n r^n\right| \frac{\left|\frac{z}{r}\right|^n}{n!}
\]
est le terme général d'une suite bornée en module car \( \frac{\left|\frac{z}{r}\right|^n}{n!} \) est borné. Par conséquent, \( \sum_{n\ge 1}\frac{a_n}{n!}z^n \) a un rayon de convergence infini.

\item L'application \( f-g \) est somme sur \( \Delta_r \) connexe d'une série entière centrée en \( 0 \) et s'annule sur l'ensemble non discret \( ]-R,R[ \). Par le principe des zéros isolés, \( f = g \) sur \( \Delta_r \).

\item Soit \( a\in\Rr \). Les deux applications \( z\mapsto \sin(a+z) \) et \( z\mapsto \sin(a)\cos(z)+\cos(a)\sin(z) \) sont développables en séries entières sur \( \Cc \) et coïncident sur \( \Rr \) par la formule d'addition des sinus sur \( \Rr \). Par la question précédente, elles coïncident sur \( \Cc \).
\end{enumerate}

\begin{enumerate}
\item Soit \( z\in\Cc \).

\begin{eqnarray*}
	\sin z=c&\iff& \frac{e^{iz}-e^{-iz}}{2i}=c\iff e^{iz}-2ic-e^{-iz}=0\\
	&\iff& (e^{iz})^2-2ic e^{iz}-1=0 \textrm{ car } e^{iz}\not=0.
\end{eqnarray*}

\item Soit \( c\in [-1,1] \). Soit \( z\in\Cc \) une solution de \( \sin z = c \). Alors \( e^{iz} \) est solution de \( X^2-2icX-1 = 0 \). Comme \( c\in [-1,1] \), les solutions de cette équation sont \( ic+\sqrt{1-c^2} \) et \( ic-\sqrt{1-c^2} \), toutes les deux de module \( 1 \),
\[
|e^{iz}| = e^{-y} = 1
\]
et donc \( y = 0 \), et \( z \) est donc réel.

\item \begin{eqnarray*}
	e^{i(a+b)}&=&e^{ia}e^{ib}=(\cos a+i\sin a)(\cos b+i\sin b)\\
	&=&(\cos a\cos b -\sin a\sin b)+i(\sin a\cos b+\cos a\sin b).
\end{eqnarray*}
\begin{eqnarray*}
	e^{-i(a+b)}&=&e^{-ia}e^{-ib}=(\cos a-i\sin a)(\cos b-i\sin b)\\
	&=&(\cos a\cos b -\sin a\sin b)-i(\sin a\cos b+\cos a\sin b).
\end{eqnarray*}

\item \begin{eqnarray*}
	\sin(a+b)&=&\frac{e^{i(a+b)}-e^{-i(a+b)}}{2i}=\sin a\cos b+\cos a\sin b
\end{eqnarray*}
d'après la question précédente.

\item Soit \( z\in\Cc \).
\begin{eqnarray*}
	\cos z+\sin z=2&\iff& \frac{1}{\sqrt{2}}\cos z+\frac{1}{\sqrt{2}}\sin z=\sqrt{2}\\
	&\iff& \sin(\frac{\pi}{4}+z)=\sqrt{2}\\
	&\iff& (e^{iz}) \textrm{ est solution de }X^2-2i\sqrt{2}X-1=0\\
	&\iff& e^{iz}=i\sqrt{2}+i \textrm { ou } e^{iz}=i\sqrt{2}-i\\
	&\iff& e^{iz}=(\sqrt{2}+1)e^{\frac{\pi}{2}} \textrm { ou } e^{iz}=(\sqrt{2}-1)e^{\frac{\pi}{2}}\\
	&\iff&\exists k\in\Zz, iz=\log_\Rr(\sqrt{2}+1)+i(\frac{\pi}{2}+2k\pi) \\&& \textrm { ou } iz=\log_\Rr(\sqrt{2}-1)+i(\frac{\pi}{2}+2k\pi)\\
	&\iff&\exists k\in\Zz, z=(\frac{pi}{2}+2k\pi)-i\log_\Rr(\sqrt{2}+1) \\&& \textrm { ou } z=(\frac{\pi}{2}+2k\pi)-i\log_\Rr(\sqrt{2}-1)
\end{eqnarray*}
Les soultions de l'équation \( \cos z+\sin z = 2 \) dans \( \Cc \) sont les nombres complexes de la forme \( (\frac{pi}{2}+2k\pi)-i\log_\Rr(\sqrt{2}+1) \) ou \( z = (\frac{pi}{2}+2k\pi)-i\log_\Rr(\sqrt{2}-1) \) avec \( k \) entier.
\end{enumerate}

