exercices.correction:
\begin{enumerate}
\item On note d'abord que les indices de \( w_1,w_2,w_3 \) par rapport à \( \Gamma \) sont respectivement \( -1,1 \) et \( 0 \). L'application \( \Cc-\{w_1,w_2,w_3\}\to\Cc \), \( z\mapsto \frac{1}{(z-w_1)(z-w_2)(z-w_3)} \) est méromorphe sur \( \Cc \) avec des pôles simples en \( w_1,w_2,w_3 \) de résidu respectif \( \lim_{z\to w_1}(z-w_1)\frac{1}{(z-w_1)(z-w_2)(z-w_3)} = \frac{1}{(w_1-w_2)(w_1-w_3)} \), \( \frac{1}{(w_2-w_1)(w_2-w_3)} \), \( \frac{1}{(w_3-w_1)(w_3-w_2)} \). Par le théorème de Cauchy,
\begin{eqnarray*}
	A&=&2i\pi\left(Ind_\Gamma(w_1)Res_{w_1}(f)+Ind_\Gamma(w_2)Res_{w_2}(f)+Ind_\Gamma(w_2)Res_{w_3}(f)\right)\\
	&=&2i\pi\left(-\frac{1}{(w_1-w_2)(w_1-w_3)}+\frac{1}{(w_2-w_1)(w_2-w_3)}+0\right)\\
	&=&\frac{2i\pi(w_1+w_2-2w_3)}{(w_2-w_1)(w_1-w_3)(w_2-w_3)}
\end{eqnarray*}

\item L'application \( \Cc\to\Cc \), \( z\mapsto \sin z \) est holomorphe sur \( \Cc \) étoilé : son intégrale sur le chemin fermé \( \Gamma \) est donc nulle.

\item Par le théorème de Cauchy pour les dérivées,
\[
C = 2i\pi Ind_\Gamma(w_1)\sin'(w_1) = -2i\pi\cos(w_1).
\]
\end{enumerate}

